--
-- Name: activate_prepared_training_battle("uuid", "uuid", bigint, "uuid", bigint, "uuid", integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."activate_prepared_training_battle"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_active_slot" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare
  v_battle public.authoritative_battle%rowtype;
  v_receipt public.player_command_receipt%rowtype;
  v_revision bigint;
  v_request jsonb;
  v_hash text;
  v_active_index integer;
  v_snapshot jsonb;
  v_snapshot_hash text;
  v_result jsonb;
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'service role required' using errcode = '42501'; end if;
  if p_auth_user_id is null or p_command_id is null or p_battle_id is null or p_runtime_owner_id is null
    or p_expected_player_revision is null or p_expected_player_revision < 0
    or p_expected_battle_version is null or p_expected_battle_version < 1
    or p_active_slot not between 0 and 5 then
    raise exception 'training activation envelope is invalid' using errcode = '22023';
  end if;
  v_request := jsonb_build_object('command_type', 'authoritative_training_activate',
    'expected_player_revision', p_expected_player_revision, 'battle_id', p_battle_id,
    'expected_battle_version', p_expected_battle_version, 'runtime_owner_id', p_runtime_owner_id,
    'active_slot', p_active_slot);
  v_hash := encode(digest(convert_to(v_request::text, 'UTF8'), 'sha256'), 'hex');
  perform pg_advisory_xact_lock(hashtextextended(p_auth_user_id::text || ':' || p_command_id::text, 0));
  select * into v_receipt from public.player_command_receipt
  where auth_user_id = p_auth_user_id and command_id = p_command_id;
  if found then
    if v_receipt.command_type <> 'authoritative_training_activate' or v_receipt.request_hash <> v_hash then
      raise exception 'command id was already used with a different payload' using errcode = '22023';
    end if;
    return v_receipt.result;
  end if;
  select revision into v_revision from public.player_state_revision
  where auth_user_id = p_auth_user_id for update;
  if not found then raise exception 'player state does not exist' using errcode = 'P0002'; end if;
  if v_revision <> p_expected_player_revision then raise exception 'player revision conflict' using errcode = '40001'; end if;
  select * into v_battle from public.authoritative_battle
  where id = p_battle_id and auth_user_id = p_auth_user_id for update;
  if not found then raise exception 'authoritative battle was not found' using errcode = 'P0002'; end if;
  if v_battle.contract_key <> 'training' or v_battle.status <> 'prepared'
    or v_battle.engine_runtime_state <> 'ready' or v_battle.engine_snapshot is null
    or v_battle.battle_version <> p_expected_battle_version
    or v_battle.runtime_owner_id <> p_runtime_owner_id then
    raise exception 'prepared training battle changed' using errcode = '40001';
  end if;
  select ordinal - 1 into v_active_index
  from jsonb_array_elements(v_battle.engine_snapshot #> '{playerTeam,pokemon}') with ordinality entry(value, ordinal)
  where server_authority_private.edge_jsonb_bigint(entry.value #> '{state,authoritativeSlot}') = p_active_slot;
  if v_active_index is null then raise exception 'active team slot does not exist' using errcode = '22023'; end if;
  v_snapshot := jsonb_set(v_battle.engine_snapshot, '{playerTeam,state,activeIndex}', to_jsonb(v_active_index), false);
  v_snapshot_hash := encode(digest(convert_to(v_snapshot::text, 'UTF8'), 'sha256'), 'hex');
  update public.authoritative_battle
  set status = 'active', player_active_slot = p_active_slot, engine_snapshot = v_snapshot,
      engine_snapshot_hash = v_snapshot_hash, battle_version = battle_version + 1, updated_at = now()
  where id = p_battle_id;
  perform server_authority_private.authoritative_battle_append_event(p_battle_id, 'training_activated',
    jsonb_build_object('active_slot', p_active_slot), p_command_id, '[]'::jsonb);
  update public.player_state_revision set revision = revision + 1, updated_at = now()
  where auth_user_id = p_auth_user_id returning revision into v_revision;
  v_result := jsonb_build_object('player_revision', v_revision, 'battle_id', p_battle_id);
  insert into public.player_command_receipt(auth_user_id, command_id, command_type, request_hash, result, resulting_revision)
  values (p_auth_user_id, p_command_id, 'authoritative_training_activate', v_hash, v_result, v_revision);
  return v_result;
end;
$$;


