--
-- Name: cancel_wild_encounter_authoritative("uuid", bigint, "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."cancel_wild_encounter_authoritative"("p_command_id" "uuid", "p_expected_revision" bigint, "p_encounter_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare
  v_auth_user_id uuid := auth.uid();
  v_revision bigint;
  v_request jsonb;
  v_request_hash text;
  v_receipt record;
  v_result jsonb;
begin
  if v_auth_user_id is null then raise exception 'authentication required' using errcode = '28000'; end if;
  if p_command_id is null or p_expected_revision is null or p_expected_revision < 0 or p_encounter_id is null then
    raise exception 'cancel command inputs are invalid' using errcode = '22023';
  end if;
  v_request := jsonb_build_object('command_type', 'wild_encounter_cancel', 'expected_revision', p_expected_revision, 'encounter_id', p_encounter_id);
  v_request_hash := encode(digest(convert_to(v_request::text, 'UTF8'), 'sha256'), 'hex');
  perform pg_advisory_xact_lock(hashtextextended(v_auth_user_id::text || ':' || p_command_id::text, 0));
  select command_type, request_hash, result into v_receipt from public.player_command_receipt
  where auth_user_id = v_auth_user_id and command_id = p_command_id;
  if found then
    if v_receipt.command_type <> 'wild_encounter_cancel' or v_receipt.request_hash <> v_request_hash then
      raise exception 'command id was already used with a different payload' using errcode = '22023';
    end if;
    return v_receipt.result;
  end if;
  select revision into v_revision from public.player_state_revision where auth_user_id = v_auth_user_id for update;
  if v_revision is null or v_revision <> p_expected_revision then
    raise exception 'revision conflict: expected %, current %', p_expected_revision, coalesce(v_revision, 0) using errcode = '40001';
  end if;
  update public.player_encounter
  set status = case when expires_at <= now() then 'expired' else 'cancelled' end
  where id = p_encounter_id and auth_user_id = v_auth_user_id and status = 'active';
  if not found then raise exception 'active encounter was not found' using errcode = 'P0002'; end if;
  update public.player_state_revision set revision = revision + 1, updated_at = now()
  where auth_user_id = v_auth_user_id returning revision into v_revision;
  v_result := server_authority_private.player_state_projection(v_auth_user_id)
    || jsonb_build_object('command_id', p_command_id, 'command_type', 'wild_encounter_cancel');
  insert into public.player_command_receipt(auth_user_id, command_id, command_type, request_hash, result, resulting_revision)
  values (v_auth_user_id, p_command_id, 'wild_encounter_cancel', v_request_hash, v_result, v_revision);
  return v_result;
end;
$$;


ALTER FUNCTION "public"."cancel_wild_encounter_authoritative"("p_command_id" "uuid", "p_expected_revision" bigint, "p_encounter_id" "uuid") OWNER TO "postgres";

--
-- Name: choose_starter_authoritative("uuid", bigint, integer, "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."choose_starter_authoritative"("p_command_id" "uuid", "p_expected_revision" bigint, "p_trainer_index" integer, "p_starter_species" "text", "p_gender" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare
  v_auth_user_id uuid := auth.uid();
  v_catalog_release_id uuid;
  v_catalog_status text;
  v_allow_draft boolean;
  v_engine_contract text;
  v_species_key text;
  v_species_name text;
  v_dex_number integer;
  v_gender_options text[];
  v_gender text := nullif(btrim(p_gender), '');
  v_gender_code text;
  v_request jsonb;
  v_request_hash text;
  v_receipt_type text;
  v_receipt_hash text;
  v_receipt_result jsonb;
  v_current_revision bigint;
  v_pokemon_instance_id uuid := gen_random_uuid();
  v_pokemon_state jsonb;
  v_result jsonb;
begin
  if v_auth_user_id is null then
    raise exception 'authentication required' using errcode = '28000';
  end if;
  if p_command_id is null then
    raise exception 'command id is required' using errcode = '22023';
  end if;
  if p_expected_revision is null or p_expected_revision < 0 then
    raise exception 'expected revision must be non-negative' using errcode = '22023';
  end if;
  if p_trainer_index is null or p_trainer_index < 1 or p_trainer_index > 38 then
    raise exception 'trainer index is not allowed' using errcode = '22023';
  end if;
  if nullif(btrim(p_starter_species), '') is null then
    raise exception 'starter species is required' using errcode = '22023';
  end if;

  v_request := jsonb_build_object(
    'command_type', 'choose_starter',
    'expected_revision', p_expected_revision,
    'trainer_index', p_trainer_index,
    'starter_species', btrim(p_starter_species),
    'gender', v_gender
  );
  v_request_hash := encode(digest(convert_to(v_request::text, 'UTF8'), 'sha256'), 'hex');

  perform pg_advisory_xact_lock(
    hashtextextended(v_auth_user_id::text || ':' || p_command_id::text, 0)
  );

  select command_type, request_hash, result
  into v_receipt_type, v_receipt_hash, v_receipt_result
  from public.player_command_receipt
  where auth_user_id = v_auth_user_id
    and command_id = p_command_id;

  if found then
    if v_receipt_type <> 'choose_starter' or v_receipt_hash <> v_request_hash then
      raise exception 'command id was already used with a different payload' using errcode = '22023';
    end if;
    return v_receipt_result;
  end if;

  insert into public.player_state_revision (auth_user_id, revision, updated_at)
  values (v_auth_user_id, 0, now())
  on conflict (auth_user_id) do nothing;

  select revision into v_current_revision
  from public.player_state_revision
  where auth_user_id = v_auth_user_id
  for update;

  if v_current_revision <> p_expected_revision then
    raise exception 'revision conflict: expected %, current %', p_expected_revision, v_current_revision
      using errcode = '40001';
  end if;
  if exists (
    select 1 from public.player_starter_selection
    where auth_user_id = v_auth_user_id
  ) or exists (
    select 1 from public.player_profile_state
    where auth_user_id = v_auth_user_id
      and starter_status = 'selected'
  ) then
    raise exception 'starter was already selected' using errcode = '23505';
  end if;

  select config.catalog_release_id, release.status, config.allow_draft, config.engine_contract
  into v_catalog_release_id, v_catalog_status, v_allow_draft, v_engine_contract
  from server_authority_private.runtime_catalog_config config
  join public.catalog_release release on release.id = config.catalog_release_id
  where config.runtime_key = 'starter';

  if v_catalog_release_id is null then
    raise exception 'starter runtime catalog is not configured';
  end if;
  if v_engine_contract <> 'starter' then
    raise exception 'starter engine contract is not ready';
  end if;
  if v_catalog_status <> 'published' and not (v_catalog_status = 'draft' and v_allow_draft) then
    raise exception 'starter runtime catalog is not ready: %', v_catalog_status;
  end if;
  if (
    select count(*) from public.catalog_item
    where catalog_release_id = v_catalog_release_id
      and item_index in (100, 103)
  ) <> 2 or not exists (
    select 1 from public.catalog_move
    where catalog_release_id = v_catalog_release_id
      and move_index = 25
      and move_key = 'Azione'
      and display_name = 'Azione'
  ) then
    raise exception 'starter runtime catalog is incomplete';
  end if;

  select species.species_key, species.display_name, species.dex_number
  into v_species_key, v_species_name, v_dex_number
  from public.catalog_species species
  where species.catalog_release_id = v_catalog_release_id
    and species.species_key = btrim(p_starter_species);

  if v_species_key is null then
    if (
      select count(*) from public.catalog_species species
      where species.catalog_release_id = v_catalog_release_id
        and lower(species.display_name) = lower(btrim(p_starter_species))
    ) <> 1 then
      raise exception 'starter species was not found or is ambiguous' using errcode = '22023';
    end if;

    select species.species_key, species.display_name, species.dex_number
    into v_species_key, v_species_name, v_dex_number
    from public.catalog_species species
    where species.catalog_release_id = v_catalog_release_id
      and lower(species.display_name) = lower(btrim(p_starter_species));
  end if;

  if not exists (
    select 1 from public.catalog_species species
    where species.catalog_release_id = v_catalog_release_id
      and species.species_key = v_species_key
      and species.rules ->> 'evolutionStage' = 'base'
      and coalesce(species.encounter_rarity_key, '') not in ('s', 'f', 'm', 'l')
  ) then
    raise exception 'species is not an allowed starter' using errcode = '22023';
  end if;

  select coalesce(array_agg(gender.gender_key order by gender.gender_order), array[]::text[])
  into v_gender_options
  from public.catalog_species_gender gender
  where gender.catalog_release_id = v_catalog_release_id
    and gender.species_key = v_species_key;

  if cardinality(v_gender_options) = 0 then
    if v_gender is not null then
      raise exception 'gender is not valid for this species' using errcode = '22023';
    end if;
  elsif cardinality(v_gender_options) = 1 then
    if v_gender is not null and v_gender <> v_gender_options[1] then
      raise exception 'gender is not valid for this species' using errcode = '22023';
    end if;
    v_gender := v_gender_options[1];
  elsif v_gender is null or not (v_gender = any(v_gender_options)) then
    raise exception 'gender must be one of the species gender options' using errcode = '22023';
  end if;

  if v_gender is null then
    v_gender_code := null;
  elsif v_gender = 'Maschio' then
    v_gender_code := 'M';
  elsif v_gender = 'Femmina' then
    v_gender_code := 'F';
  else
    raise exception 'starter cannot project catalog gender: %', v_gender;
  end if;

  v_pokemon_state := jsonb_build_object(
    's', v_species_key,
    'g', v_gender_code,
    'l', 5,
    'hp', 23,
    'm', jsonb_build_array(jsonb_build_array(25, 4, 0)),
    'xp', 0
  );

  insert into public.player_profile_state (
    auth_user_id,
    catalog_release_id,
    trainer_index,
    pokedollars,
    badges,
    starter_status
  ) values (
    v_auth_user_id,
    v_catalog_release_id,
    p_trainer_index,
    5000,
    0,
    'selected'
  );

  insert into public.player_inventory_item (
    auth_user_id,
    catalog_release_id,
    item_index,
    quantity
  ) values
    (v_auth_user_id, v_catalog_release_id, 103, 3),
    (v_auth_user_id, v_catalog_release_id, 100, 5);

  insert into public.player_pokemon_instance (
    id,
    auth_user_id,
    catalog_release_id,
    species_key,
    state_version,
    state,
    revision
  ) values (
    v_pokemon_instance_id,
    v_auth_user_id,
    v_catalog_release_id,
    v_species_key,
    1,
    v_pokemon_state,
    1
  );

  insert into public.player_pokemon_placement (
    pokemon_instance_id,
    auth_user_id,
    placement_type,
    slot_index,
    box_index
  ) values (
    v_pokemon_instance_id,
    v_auth_user_id,
    'team',
    0,
    null
  );

  insert into public.player_dex_entry (
    auth_user_id,
    catalog_release_id,
    species_key
  ) values (
    v_auth_user_id,
    v_catalog_release_id,
    v_species_key
  );

  insert into public.player_starter_selection (
    auth_user_id,
    pokemon_instance_id,
    catalog_release_id,
    species_key,
    gender_key,
    command_id
  ) values (
    v_auth_user_id,
    v_pokemon_instance_id,
    v_catalog_release_id,
    v_species_key,
    v_gender,
    p_command_id
  );

  update public.player_state_revision
  set revision = revision + 1,
      updated_at = now()
  where auth_user_id = v_auth_user_id
  returning revision into v_current_revision;

  v_result := server_authority_private.player_state_projection(v_auth_user_id) || jsonb_build_object(
    'command_id', p_command_id,
    'command_type', 'choose_starter',
    'starter_species_name', v_species_name,
    'starter_dex_number', v_dex_number
  );

  insert into public.player_command_receipt (
    auth_user_id,
    command_id,
    command_type,
    request_hash,
    result,
    resulting_revision
  ) values (
    v_auth_user_id,
    p_command_id,
    'choose_starter',
    v_request_hash,
    v_result,
    v_current_revision
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."choose_starter_authoritative"("p_command_id" "uuid", "p_expected_revision" bigint, "p_trainer_index" integer, "p_starter_species" "text", "p_gender" "text") OWNER TO "postgres";

--
-- Name: claim_authoritative_battle_runtime("uuid", bigint, bigint, "uuid", boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."claim_authoritative_battle_runtime"("p_battle_id" "uuid", "p_expected_player_revision" bigint, "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_takeover" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare
  v_auth_user_id uuid := auth.uid();
  v_revision bigint;
  v_battle public.authoritative_battle%rowtype;
begin
  if v_auth_user_id is null then raise exception 'authentication required' using errcode = '28000'; end if;
  if p_runtime_owner_id is null then raise exception 'runtime owner id is required' using errcode = '22023'; end if;
  select revision into v_revision from public.player_state_revision
  where auth_user_id = v_auth_user_id for update;
  if not found then raise exception 'player state does not exist' using errcode = 'P0002'; end if;
  select * into v_battle from public.authoritative_battle
  where id = p_battle_id and auth_user_id = v_auth_user_id for update;
  if not found then raise exception 'authoritative battle was not found' using errcode = 'P0002'; end if;
  if v_revision <> p_expected_player_revision or v_battle.battle_version <> p_expected_battle_version then
    raise exception 'runtime claim version conflict' using errcode = '40001';
  end if;
  if v_battle.status not in ('active', 'needs_player_switch') then
    raise exception 'battle no longer accepts a runtime owner' using errcode = '22023';
  end if;
  if v_battle.runtime_owner_id <> p_runtime_owner_id and not coalesce(p_takeover, false) then
    raise exception 'runtime is already owned; explicit takeover is required' using errcode = '55P03';
  end if;
  update public.authoritative_battle set runtime_owner_id = p_runtime_owner_id,
    runtime_lock_version = runtime_lock_version + 1, battle_version = battle_version + 1,
    updated_at = now() where id = p_battle_id;
  perform server_authority_private.authoritative_battle_append_event(p_battle_id,
    case when v_battle.runtime_owner_id = p_runtime_owner_id then 'runtime_reclaimed' else 'runtime_taken_over' end,
    jsonb_build_object('previous_owner_id', v_battle.runtime_owner_id,
      'runtime_owner_id', p_runtime_owner_id, 'explicit_takeover', coalesce(p_takeover, false)));
  update public.player_state_revision set revision = revision + 1, updated_at = now()
  where auth_user_id = v_auth_user_id returning revision into v_revision;
  return jsonb_build_object('player_revision', v_revision,
    'battle', server_authority_private.authoritative_battle_projection(v_auth_user_id, p_battle_id));
end;
$$;


ALTER FUNCTION "public"."claim_authoritative_battle_runtime"("p_battle_id" "uuid", "p_expected_player_revision" bigint, "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_takeover" boolean) OWNER TO "postgres";

--
-- Name: claim_daily_berry_authoritative("uuid", bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."claim_daily_berry_authoritative"("p_command_id" "uuid", "p_expected_revision" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_conflict jsonb;
begin
  v_conflict:=server_authority_private.player_command_revision_conflict(p_command_id,p_expected_revision);
  if v_conflict is not null then return v_conflict; end if;
  begin
    return public.claim_daily_berry_before_revision_guard(p_command_id,p_expected_revision);
  exception when serialization_failure then
    v_conflict:=server_authority_private.player_command_revision_conflict(p_command_id,p_expected_revision);
    if v_conflict is not null then return v_conflict; end if;
    raise;
  end;
end;
$$;


