-- Name: claim_player_mission_authoritative("uuid", bigint, integer, integer, "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."claim_player_mission_authoritative"("p_command_id" "uuid", "p_expected_revision" bigint, "p_mission_index" integer, "p_selected_reward_item_index" integer, "p_selected_reward_species_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_conflict jsonb;
begin
  v_conflict:=server_authority_private.player_command_revision_conflict(p_command_id,p_expected_revision);
  if v_conflict is not null then return v_conflict; end if;
  begin
    return public.claim_player_mission_before_revision_guard(
      p_command_id,p_expected_revision,p_mission_index,p_selected_reward_item_index,p_selected_reward_species_key
    );
  exception when serialization_failure then
    v_conflict:=server_authority_private.player_command_revision_conflict(p_command_id,p_expected_revision);
    if v_conflict is not null then return v_conflict; end if;
    raise;
  end;
end;
$$;


ALTER FUNCTION "public"."claim_player_mission_authoritative"("p_command_id" "uuid", "p_expected_revision" bigint, "p_mission_index" integer, "p_selected_reward_item_index" integer, "p_selected_reward_species_key" "text") OWNER TO "postgres";

--
-- Name: claim_player_mission_before_revision_guard("uuid", bigint, integer, integer, "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."claim_player_mission_before_revision_guard"("p_command_id" "uuid", "p_expected_revision" bigint, "p_mission_index" integer, "p_selected_reward_item_index" integer, "p_selected_reward_species_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $_$
declare
  v_auth_user_id uuid:=auth.uid(); v_request jsonb; v_request_hash text;
  v_receipt public.player_command_receipt%rowtype; v_revision bigint;
  v_profile public.player_profile_state%rowtype; v_state public.player_mission_state%rowtype;
  v_mission public.catalog_mission%rowtype; v_reward jsonb; v_reward_kind text;
  v_reward_quantity bigint; v_reward_item_index integer; v_matching_choices integer;
  v_inventory_quantity integer:=0; v_reward_badges integer;
  v_species_key text; v_level integer; v_gender text; v_rule public.catalog_level_rule%rowtype;
  v_rule_60 public.catalog_level_rule%rowtype; v_base_hp integer; v_base_power integer;
  v_base_stats integer; v_max_hp integer; v_moves jsonb; v_instance_id uuid; v_box_index bigint;
  v_result jsonb;
begin
  if v_auth_user_id is null then raise exception 'Autenticazione richiesta' using errcode='28000'; end if;
  if p_command_id is null or p_expected_revision is null or p_expected_revision<0
    or p_mission_index is null or p_mission_index<=0 then
    raise exception 'Comando missione non valido' using errcode='22023'; end if;
  v_request:=jsonb_build_object('command_type','mission_claim','expected_revision',p_expected_revision,
    'mission_index',p_mission_index,'selected_reward_item_index',p_selected_reward_item_index,
    'selected_reward_species_key',p_selected_reward_species_key);
  v_request_hash:=encode(digest(convert_to(v_request::text,'UTF8'),'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended(v_auth_user_id::text||':'||p_command_id::text,0));
  select * into v_receipt from public.player_command_receipt
  where auth_user_id=v_auth_user_id and command_id=p_command_id;
  if found then
    if v_receipt.command_type<>'mission_claim' or v_receipt.request_hash<>v_request_hash then
      raise exception 'Identificativo comando giÃ  usato con un altro premio' using errcode='22023'; end if;
    return v_receipt.result;
  end if;
  select revision into v_revision from public.player_state_revision
  where auth_user_id=v_auth_user_id for update;
  if v_revision is null then raise exception 'Stato giocatore non trovato' using errcode='P0002'; end if;
  if v_revision<>p_expected_revision then
    raise exception 'Lo stato del giocatore Ã¨ cambiato. Aggiorna e riprova' using errcode='40001'; end if;
  select * into strict v_profile from public.player_profile_state
  where auth_user_id=v_auth_user_id for update;
  perform server_authority_private.sync_player_missions(v_auth_user_id);
  select * into v_state from public.player_mission_state
  where auth_user_id=v_auth_user_id and mission_index=p_mission_index for update;
  if not found then raise exception 'Missione non trovata' using errcode='P0002'; end if;
  select * into strict v_mission from public.catalog_mission
  where catalog_release_id=v_state.catalog_release_id and mission_index=v_state.mission_index;
  if v_state.claim_status<>'unclaimed' or v_state.counter<v_mission.target
    or not server_authority_private.mission_is_active(v_auth_user_id,p_mission_index) then
    raise exception 'La missione non Ã¨ completata e riscuotibile' using errcode='22023'; end if;

  v_reward:=v_mission.reward_rules; v_reward_kind:=v_reward->>'kind';
  if v_reward_kind='choice' then
    if p_selected_reward_species_key is not null or coalesce(p_selected_reward_item_index,0)<=0 then
      raise exception 'Scegli uno degli strumenti premio' using errcode='22023'; end if;
    select count(*)::integer into v_matching_choices
    from jsonb_array_elements(case when jsonb_typeof(v_reward->'choices')='array'
      then v_reward->'choices' else '[]'::jsonb end) choices(choice)
    where coalesce(choice->>'itemIndex','')~'^[1-9][0-9]*$'
      and choice->>'itemIndex'=p_selected_reward_item_index::text;
    if v_matching_choices<>1 then raise exception 'Lo strumento scelto non Ã¨ offerto' using errcode='22023'; end if;
    select choice into v_reward from jsonb_array_elements(v_reward->'choices') choices(choice)
    where choice->>'itemIndex'=p_selected_reward_item_index::text;
    v_reward_kind:=v_reward->>'kind';
  elsif v_reward_kind='pokemon-choice' then
    if p_selected_reward_item_index is not null or coalesce(p_selected_reward_species_key,'')!~'^[1-9][0-9]*$' then
      raise exception 'Scegli un PokÃ©mon premio' using errcode='22023'; end if;
    v_species_key:=p_selected_reward_species_key;
  elsif p_selected_reward_item_index is not null or p_selected_reward_species_key is not null then
    raise exception 'Questa ricompensa non richiede una scelta' using errcode='22023';
  end if;

  if v_reward_kind in ('dynamic-money','dynamic-item') then
    if v_mission.mission_type='daily-login' then
      select substring(key from '^reward-badges:([0-8])$')::integer into v_reward_badges
      from unnest(v_state.tracked_keys) key where key~'^reward-badges:[0-8]$' limit 1;
      if v_reward_badges is null then raise exception 'Livello premio Login non congelato' using errcode='55000'; end if;
    else v_reward_badges:=least(8,greatest(0,v_profile.badges)); end if;
    v_reward_quantity:=coalesce((v_reward->>'baseQuantity')::bigint,0)
      +v_reward_badges*coalesce((v_reward->>'perBadge')::bigint,0);
    if v_reward_quantity<=0 then raise exception 'Ricompensa dinamica non valida' using errcode='22023'; end if;
    if v_reward_kind='dynamic-money' then
      v_reward:=jsonb_build_object('kind','money','quantity',v_reward_quantity,'badgeCount',v_reward_badges);
      v_reward_kind:='money';
    else
      v_reward:=jsonb_build_object('kind','item','itemIndex',v_reward->'itemIndex',
        'quantity',v_reward_quantity,'badgeCount',v_reward_badges);
      v_reward_kind:='item';
    end if;
  end if;

  if v_reward_kind='money' then
    if coalesce(v_reward->>'quantity','')!~'^[1-9][0-9]*$' then raise exception 'Premio in denaro non valido'; end if;
    v_reward_quantity:=(v_reward->>'quantity')::bigint;
    if v_reward_quantity>9223372036854775807-v_profile.pokedollars then
      raise exception 'Limite PokÃ©dollari superato' using errcode='22003'; end if;
    update public.player_profile_state set pokedollars=pokedollars+v_reward_quantity,updated_at=now()
    where auth_user_id=v_auth_user_id;
  elsif v_reward_kind='item' then
    if coalesce(v_reward->>'itemIndex','')!~'^[1-9][0-9]*$'
      or coalesce(v_reward->>'quantity','')!~'^[1-9][0-9]*$' then
      raise exception 'Strumento premio non valido' using errcode='22023'; end if;
    v_reward_item_index:=(v_reward->>'itemIndex')::integer;
    v_reward_quantity:=(v_reward->>'quantity')::bigint;
    if not exists(select 1 from public.catalog_item where catalog_release_id=v_state.catalog_release_id
      and item_index=v_reward_item_index) then raise exception 'Strumento premio fuori catalogo'; end if;
    if coalesce((v_mission.reward_rules->>'purchasableNow')::boolean,false)
      and exists(select 1 from public.catalog_item item where item.catalog_release_id=v_state.catalog_release_id
        and item.item_index=v_reward_item_index and item.category_key='Mt'
        and v_profile.badges<case coalesce((item.rules->>'tier')::integer,3)
          when 0 then 7 when 1 then 6 when 2 then 4 else 0 end) then
      raise exception 'Questa MT non Ã¨ ancora acquistabile' using errcode='22023'; end if;
    select coalesce((select quantity from public.player_inventory_item
      where auth_user_id=v_auth_user_id and item_index=v_reward_item_index for update),0)
    into v_inventory_quantity;
    if v_reward_quantity>2147483647-v_inventory_quantity then
      raise exception 'Limite inventario superato' using errcode='22003'; end if;
    insert into public.player_inventory_item(auth_user_id,catalog_release_id,item_index,quantity,updated_at)
    values(v_auth_user_id,v_state.catalog_release_id,v_reward_item_index,v_reward_quantity::integer,now())
    on conflict(auth_user_id,item_index) do update
      set quantity=player_inventory_item.quantity+excluded.quantity,updated_at=now();
  elsif v_reward_kind='pokemon-choice' then
    if exists(select 1 from public.player_ordinary_progression
      where auth_user_id=v_auth_user_id and status<>'completed') then
      raise exception 'Completa prima la progressione PokÃ©mon in sospeso' using errcode='55000'; end if;
    if v_reward->>'levelMode'='fixed-5' and (v_reward->>'level')::integer=5 then v_level:=5;
    elsif v_reward->>'levelMode'='badge-cap' then
      select (rules->>'level')::integer into v_level from public.catalog_progression_rule
      where catalog_release_id=v_profile.catalog_release_id and rule_family='badge-level-limit'
        and rule_key=least(8,greatest(0,v_profile.badges))::text;
    else raise exception 'Livello PokÃ©mon premio non valido' using errcode='22023'; end if;
    if not exists(select 1 from server_authority_private.mission_pokemon_reward_candidates(
      v_profile.catalog_release_id,v_level,coalesce((v_reward->>'excludeFossils')::boolean,false)) candidate
      where candidate.species_key=v_species_key) then
      raise exception 'Questo PokÃ©mon non Ã¨ disponibile per la missione' using errcode='22023'; end if;
    select gender_key into v_gender from public.catalog_species_gender
    where catalog_release_id=v_profile.catalog_release_id and species_key=v_species_key order by random() limit 1;
    select * into strict v_rule from public.catalog_level_rule
    where catalog_release_id=v_profile.catalog_release_id and level=v_level;
    select * into strict v_rule_60 from public.catalog_level_rule
    where catalog_release_id=v_profile.catalog_release_id and level=60;
    v_base_hp:=coalesce(v_rule.base_hp,v_rule_60.base_hp+greatest(0,v_level-60)*3);
    v_base_power:=coalesce(v_rule.base_power,v_rule_60.base_power+greatest(0,v_level-60)*2);
    v_base_stats:=coalesce(v_rule.base_stats,v_rule_60.base_stats+greatest(0,v_level-60)*2);
    v_max_hp:=v_base_hp-floor(random()*(case when v_level>=35 then 5 when v_level>=15 then 3 else 1 end))::integer;
    select jsonb_agg(jsonb_build_array(move_index,
      v_base_power-floor(random()*(case when v_level>=50 then 5 when v_level>=20 then 4 when v_level>=10 then 3 else 1 end))::integer,
      v_base_stats-floor(random()*(case when v_level>=40 then 3 else 1 end))::integer) order by random_order)
    into v_moves from (
      select candidate.move_index,random() random_order from (
        select distinct move_index from public.catalog_species_level_move
        where catalog_release_id=v_profile.catalog_release_id and species_key=v_species_key and level<=v_level
      ) candidate order by random() limit 4
    ) moves;
    if v_moves is null or jsonb_array_length(v_moves)=0 then
      raise exception 'Il PokÃ©mon non ha mosse selvatiche valide a questo livello' using errcode='22023'; end if;
    v_instance_id:=gen_random_uuid();
    insert into public.player_pokemon_instance(id,auth_user_id,catalog_release_id,species_key,state_version,state,revision)
    values(v_instance_id,v_auth_user_id,v_profile.catalog_release_id,v_species_key,1,
      jsonb_build_object('s',v_species_key,'g',case v_gender when 'Maschio' then 'M' when 'Femmina' then 'F' else null end,
        'l',v_level,'hp',v_max_hp,'m',v_moves,'xp',0),1);
    insert into public.player_box_index_state(auth_user_id,next_box_index)
    select v_auth_user_id,coalesce(max(box_index),-1)::bigint+1 from public.player_pokemon_placement
    where auth_user_id=v_auth_user_id and placement_type='box' on conflict(auth_user_id) do nothing;
    select next_box_index into v_box_index from public.player_box_index_state
    where auth_user_id=v_auth_user_id for update;
    select greatest(v_box_index,coalesce(max(box_index),-1)::bigint+1) into v_box_index
    from public.player_pokemon_placement where auth_user_id=v_auth_user_id and placement_type='box';
    if v_box_index>2147483647 then raise exception 'Il Box ha raggiunto il limite massimo' using errcode='22003'; end if;
    update public.player_box_index_state set next_box_index=v_box_index+1,updated_at=now()
    where auth_user_id=v_auth_user_id;
    insert into public.player_pokemon_placement(pokemon_instance_id,auth_user_id,placement_type,slot_index,box_index)
    values(v_instance_id,v_auth_user_id,'box',null,v_box_index::integer);
    insert into public.player_dex_entry(auth_user_id,catalog_release_id,species_key)
    values(v_auth_user_id,v_profile.catalog_release_id,v_species_key) on conflict do nothing;
    v_reward:=jsonb_build_object('kind','pokemon','speciesKey',v_species_key,'level',v_level,
      'pokemonInstanceId',v_instance_id,'boxIndex',v_box_index);
  else raise exception 'Tipo ricompensa missione non supportato: %',coalesce(v_reward_kind,'<null>'); end if;

  update public.player_mission_state set counter=case when v_mission.repeatable
      and not coalesce((v_mission.rules->>'daily')::boolean,false) then 0 else counter end,
    claim_status=case when v_mission.repeatable and not coalesce((v_mission.rules->>'daily')::boolean,false)
      then 'unclaimed' else 'claimed' end,
    tracked_keys=case when v_mission.repeatable and not coalesce((v_mission.rules->>'daily')::boolean,false)
      then array[]::text[] else tracked_keys end,
    last_counted_day=case when v_mission.repeatable and not coalesce((v_mission.rules->>'daily')::boolean,false)
      then null else last_counted_day end,claim_count=claim_count+1,last_claimed_at=now(),updated_at=now()
  where auth_user_id=v_auth_user_id and mission_index=p_mission_index;
  perform server_authority_private.sync_player_missions(v_auth_user_id);
  update public.player_state_revision set revision=revision+1,updated_at=now()
  where auth_user_id=v_auth_user_id returning revision into v_revision;
  v_result:=server_authority_private.player_state_projection(v_auth_user_id)||jsonb_build_object(
    'command_id',p_command_id,'command_type','mission_claim','mission_index',p_mission_index,
    'selected_reward_item_index',p_selected_reward_item_index,
    'selected_reward_species_key',p_selected_reward_species_key,'reward',v_reward,
    'pokemon_instance_id',v_instance_id);
  insert into public.player_command_receipt(auth_user_id,command_id,command_type,request_hash,result,resulting_revision)
  values(v_auth_user_id,p_command_id,'mission_claim',v_request_hash,v_result,v_revision);
  v_result:=server_authority_private.player_state_projection(v_auth_user_id)||jsonb_build_object(
    'command_id',p_command_id,'command_type','mission_claim','mission_index',p_mission_index,
    'selected_reward_item_index',p_selected_reward_item_index,
    'selected_reward_species_key',p_selected_reward_species_key,'reward',v_reward,
    'pokemon_instance_id',v_instance_id);
  update public.player_command_receipt set result=v_result
  where auth_user_id=v_auth_user_id and command_id=p_command_id;
  return v_result;
end;
$_$;


ALTER FUNCTION "public"."claim_player_mission_before_revision_guard"("p_command_id" "uuid", "p_expected_revision" bigint, "p_mission_index" integer, "p_selected_reward_item_index" integer, "p_selected_reward_species_key" "text") OWNER TO "postgres";

--
-- Name: commit_edge_admin_debug_training_command("uuid", "uuid", "text", "text", "uuid", bigint, "text", "text", "text", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."commit_edge_admin_debug_training_command"("p_admin_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $_$
declare v_battle public.authoritative_battle%rowtype; v_receipt public.authoritative_admin_gym_command_receipt%rowtype;
  v_revision bigint; v_internal uuid:=gen_random_uuid(); v_result jsonb; v_owner uuid;
begin
  if coalesce(auth.role(),'')<>'service_role' or not server_authority_private.user_has_server_role(p_admin_user_id,'admin') then
    raise exception 'admin service authority required' using errcode='42501'; end if;
  if p_command_type not in ('move','switch','item') or p_command_hash!~'^[0-9a-f]{64}$' then
    raise exception 'admin debug training command metadata is invalid' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_admin_user_id::text||':'||p_command_id::text,0));
  select * into v_receipt from public.authoritative_admin_gym_command_receipt where admin_auth_user_id=p_admin_user_id and command_id=p_command_id;
  if found then
    if v_receipt.battle_id<>p_battle_id or v_receipt.command_type<>p_command_type or v_receipt.command_hash<>p_command_hash then
      raise exception 'admin command id was reused with a different payload' using errcode='22023'; end if;
    return v_receipt.result;
  end if;
  select * into strict v_battle from public.authoritative_battle where id=p_battle_id;
  if v_battle.contract_key<>'debug_training' or v_battle.waiting_for<>'admin'
    or v_battle.status not in ('active','needs_player_switch') then
    raise exception 'debug training is not waiting for an admin command' using errcode='40001'; end if;
  if v_battle.battle_version<>p_expected_battle_version then raise exception 'battle version conflict' using errcode='40001'; end if;
  v_owner:=v_battle.runtime_owner_id;
  if p_next_snapshot#>>'{manager,adminControlled}'<>'true' or p_projection->>'admin_controlled'<>'true'
    or (p_projection->>'status' not in ('concluded','abandoned') and p_projection->>'waiting_for' is distinct from p_next_snapshot#>>'{manager,waitingFor}')
    or (p_command_type<>'switch' and coalesce((v_battle.engine_snapshot#>>'{manager,npcNeedsSwitch}')::boolean,false)) then
    raise exception 'admin debug training transition ownership is invalid' using errcode='22023'; end if;
  select revision into strict v_revision from public.player_state_revision where auth_user_id=v_battle.auth_user_id;
  if p_command_type='item' then
    v_result:=server_authority_private.commit_edge_battle_command_without_items(v_battle.auth_user_id,v_internal,p_command_type,p_command_hash,
      v_revision,p_battle_id,p_expected_battle_version,v_owner,p_engine_version,p_engine_checksum,p_input_snapshot_hash,p_next_snapshot,
      p_events,p_projection,jsonb_build_object('reward','none','inventory','unchanged','team','unchanged'));
  else
    v_result:=server_authority_private.commit_edge_battle_command_before_admin_gyms(v_battle.auth_user_id,v_internal,p_command_type,p_command_hash,
      v_revision,p_battle_id,p_expected_battle_version,v_owner,p_engine_version,p_engine_checksum,p_input_snapshot_hash,p_next_snapshot,
      p_events,p_projection,jsonb_build_object('reward','none','inventory','unchanged','team','unchanged'));
  end if;
  if (select runtime_owner_id from public.authoritative_battle where id=p_battle_id) is distinct from v_owner then
    raise exception 'admin command changed the player runtime owner' using errcode='40001'; end if;
  update public.authoritative_battle set waiting_for=case when status in ('concluded','abandoned') then null else p_projection->>'waiting_for' end,
    admin_items=coalesce(p_projection->'admin_items',admin_items) where id=p_battle_id;
  insert into public.authoritative_admin_gym_command_receipt(admin_auth_user_id,command_id,battle_id,command_type,command_hash,result,resulting_battle_version)
    values(p_admin_user_id,p_command_id,p_battle_id,p_command_type,p_command_hash,v_result,(v_result->>'battle_version')::bigint);
  return v_result;
end;
$_$;


ALTER FUNCTION "public"."commit_edge_admin_debug_training_command"("p_admin_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb") OWNER TO "postgres";

--
-- Name: commit_edge_admin_gym_command("uuid", "uuid", "text", "text", "uuid", bigint, "text", "text", "text", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."commit_edge_admin_gym_command"("p_admin_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare v_battle public.authoritative_battle%rowtype; v_receipt public.authoritative_admin_gym_command_receipt%rowtype;
  v_revision bigint; v_internal uuid:=gen_random_uuid(); v_result jsonb; v_owner uuid;
begin
  if p_command_type<>'entry_choice' then
    return public.commit_edge_admin_gym_command_before_snapshot(
      p_admin_user_id,p_command_id,p_command_type,p_command_hash,p_battle_id,p_expected_battle_version,p_engine_version,p_engine_checksum,
      p_input_snapshot_hash,p_next_snapshot,p_events,p_projection
    );
  end if;
  if coalesce(auth.role(),'')<>'service_role' or not server_authority_private.user_has_server_role(p_admin_user_id,'admin') then
    raise exception 'admin service authority required' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_admin_user_id::text||':'||p_command_id::text,0));
  select * into v_receipt from public.authoritative_admin_gym_command_receipt where admin_auth_user_id=p_admin_user_id and command_id=p_command_id;
  if found then return v_receipt.result; end if;
  select * into strict v_battle from public.authoritative_battle where id=p_battle_id;
  if v_battle.contract_key not in ('admin_gym','league','debug_training') or v_battle.waiting_for<>'admin'
    or v_battle.battle_version<>p_expected_battle_version then raise exception 'admin initial entry choice is invalid' using errcode='22023'; end if;
  select revision into strict v_revision from public.player_state_revision where auth_user_id=v_battle.auth_user_id;
  v_owner:=v_battle.runtime_owner_id;
  v_result:=public.commit_edge_battle_command(v_battle.auth_user_id,v_internal,p_command_type,p_command_hash,v_revision,p_battle_id,
    p_expected_battle_version,v_owner,p_engine_version,p_engine_checksum,p_input_snapshot_hash,p_next_snapshot,p_events,p_projection,
    jsonb_build_object('reward','none','inventory','unchanged','team','unchanged'));
  update public.authoritative_battle set waiting_for=p_projection->>'waiting_for',admin_items=coalesce(p_projection->'admin_items',admin_items)
    where id=p_battle_id and runtime_owner_id=v_owner;
  insert into public.authoritative_admin_gym_command_receipt(admin_auth_user_id,command_id,battle_id,command_type,command_hash,result,resulting_battle_version)
    values(p_admin_user_id,p_command_id,p_battle_id,p_command_type,p_command_hash,v_result,(v_result->>'battle_version')::bigint);
  return v_result;
end;
$$;


ALTER FUNCTION "public"."commit_edge_admin_gym_command"("p_admin_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb") OWNER TO "postgres";

--
-- Name: commit_edge_admin_gym_command_before_initial_entry("uuid", "uuid", "text", "text", "uuid", bigint, "text", "text", "text", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."commit_edge_admin_gym_command_before_initial_entry"("p_admin_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_result jsonb; v_owner uuid; v_player jsonb; v_penalty jsonb; v_internal uuid;
  v_receipt public.authoritative_admin_gym_command_receipt%rowtype;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_admin_user_id::text||':'||p_command_id::text,0));
  select * into v_receipt from public.authoritative_admin_gym_command_receipt
    where admin_auth_user_id=p_admin_user_id and command_id=p_command_id;
  if found then
    if v_receipt.battle_id<>p_battle_id or v_receipt.command_type<>p_command_type or v_receipt.command_hash<>p_command_hash then
      raise exception 'admin command id was reused with a different battle or payload' using errcode='22023'; end if;
    return v_receipt.result;
  end if;
  select auth_user_id into strict v_owner from public.authoritative_battle where id=p_battle_id;
  v_result:=public.commit_edge_admin_gym_command_before_ordinary_progression(p_admin_user_id,p_command_id,p_command_type,p_command_hash,
    p_battle_id,p_expected_battle_version,p_engine_version,p_engine_checksum,p_input_snapshot_hash,p_next_snapshot,p_events,p_projection);
  if p_projection->>'status' in ('concluded','abandoned') then
    select command_id into v_internal from public.authoritative_battle_command_receipt where battle_id=p_battle_id
      and resulting_battle_version=(v_result->>'battle_version')::bigint order by created_at desc limit 1;
    v_internal:=coalesce(v_internal,p_command_id);
    v_penalty:=server_authority_private.apply_ordinary_money_penalty(v_owner,p_battle_id,v_internal);
    if v_penalty is not null then v_player:=v_penalty->'player_state'; end if;
    if p_projection->>'status'='concluded' and p_projection->>'result_key'='player_win_no_reward' then
      v_player:=server_authority_private.create_terminal_ordinary_progression(v_owner,p_battle_id,v_internal,p_projection->'ordinary_exp_awards');
    end if;
    if v_player is not null then v_result:=jsonb_set(v_result,'{player_revision}',v_player->'revision',true)
      ||jsonb_build_object('player_state',v_player,'ordinary_progression',v_player->'ordinary_progression',
        'money_penalty',case when v_penalty is null then null else v_penalty->'amount' end); end if;
    update public.authoritative_admin_gym_command_receipt set result=v_result where admin_auth_user_id=p_admin_user_id and command_id=p_command_id;
    update public.authoritative_battle_command_receipt set result=v_result,resulting_player_revision=coalesce((v_player->>'revision')::bigint,resulting_player_revision)
      where command_id=v_internal and battle_id=p_battle_id;
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."commit_edge_admin_gym_command_before_initial_entry"("p_admin_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb") OWNER TO "postgres";

--
-- Name: commit_edge_admin_gym_command_before_league("uuid", "uuid", "text", "text", "uuid", bigint, "text", "text", "text", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."commit_edge_admin_gym_command_before_league"("p_admin_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $_$
declare v_battle public.authoritative_battle%rowtype; v_receipt public.authoritative_admin_gym_command_receipt%rowtype;
  v_revision bigint; v_internal_command_id uuid := gen_random_uuid(); v_result jsonb; v_reward jsonb;
  v_runtime_owner uuid;
begin
  if coalesce(auth.role(), '') <> 'service_role'
    or not server_authority_private.user_has_server_role(p_admin_user_id, 'admin') then
    raise exception 'admin service authority required' using errcode = '42501';
  end if;
  if p_command_type not in ('move','switch','item') or p_command_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'admin command metadata is invalid' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_admin_user_id::text || ':' || p_command_id::text, 0));
  select * into v_receipt from public.authoritative_admin_gym_command_receipt
    where admin_auth_user_id = p_admin_user_id and command_id = p_command_id;
  if found then
    if v_receipt.battle_id <> p_battle_id or v_receipt.command_type <> p_command_type
      or v_receipt.command_hash <> p_command_hash then
      raise exception 'admin command id was reused with a different payload' using errcode = '22023';
    end if;
    return v_receipt.result;
  end if;
  select * into strict v_battle from public.authoritative_battle where id = p_battle_id;
  if v_battle.contract_key <> 'admin_gym' or v_battle.waiting_for <> 'admin'
    or v_battle.status not in ('active','needs_player_switch') then
    raise exception 'admin gym is not waiting for an admin command' using errcode = '40001';
  end if;
  if v_battle.battle_version <> p_expected_battle_version then
    raise exception 'battle version conflict' using errcode = '40001';
  end if;
  v_runtime_owner := v_battle.runtime_owner_id;
  if p_next_snapshot #>> '{manager,adminControlled}' <> 'true'
    or p_projection ->> 'admin_controlled' <> 'true'
    or (p_projection ->> 'status' not in ('concluded','abandoned')
      and p_projection ->> 'waiting_for' is distinct from p_next_snapshot #>> '{manager,waitingFor}')
    or p_command_type <> 'switch' and coalesce((v_battle.engine_snapshot #>> '{manager,npcNeedsSwitch}')::boolean, false) then
    raise exception 'admin gym transition ownership is invalid' using errcode = '22023';
  end if;
  select revision into strict v_revision from public.player_state_revision where auth_user_id = v_battle.auth_user_id;
  if p_command_type = 'item' then
    -- The training item wrapper intentionally rejects every non-training item.
    -- Admin inventory is snapshot-local, so commit through its wrapped generic
    -- transition and persist no player inventory effect.
    v_result := server_authority_private.commit_edge_battle_command_without_items(
      v_battle.auth_user_id,v_internal_command_id,p_command_type,p_command_hash,v_revision,
      p_battle_id,p_expected_battle_version,v_runtime_owner,p_engine_version,p_engine_checksum,
      p_input_snapshot_hash,p_next_snapshot,p_events,p_projection,
      jsonb_build_object('reward','none','inventory','unchanged','team','unchanged'));
  else
    v_result := server_authority_private.commit_edge_battle_command_before_admin_gyms(
      v_battle.auth_user_id,v_internal_command_id,p_command_type,p_command_hash,v_revision,
      p_battle_id,p_expected_battle_version,v_runtime_owner,p_engine_version,p_engine_checksum,
      p_input_snapshot_hash,p_next_snapshot,p_events,p_projection,
      jsonb_build_object('reward','none','inventory','unchanged','team','unchanged'));
  end if;
  if (select runtime_owner_id from public.authoritative_battle where id = p_battle_id)
    is distinct from v_runtime_owner then
    raise exception 'admin command changed the player runtime owner' using errcode = '40001';
  end if;
  update public.authoritative_battle set waiting_for = case when status in ('concluded','abandoned') then null
      else p_projection ->> 'waiting_for' end,
    admin_items = coalesce(p_projection -> 'admin_items', admin_items) where id = p_battle_id;
  if p_projection ->> 'status' = 'concluded' and p_projection ->> 'result_key' = 'player_win_no_reward' then
    v_reward := server_authority_private.award_terminal_admin_gym_victory(v_battle.auth_user_id,p_battle_id,v_internal_command_id);
    if v_reward is not null then
      v_result := jsonb_set(v_result, '{player_revision}', v_reward #> '{player_state,revision}', true) || v_reward;
    end if;
  end if;
  insert into public.authoritative_admin_gym_command_receipt(admin_auth_user_id,command_id,battle_id,
    command_type,command_hash,result,resulting_battle_version)
  values(p_admin_user_id,p_command_id,p_battle_id,p_command_type,p_command_hash,v_result,
    (v_result ->> 'battle_version')::bigint);
  return v_result;
end;
$_$;


ALTER FUNCTION "public"."commit_edge_admin_gym_command_before_league"("p_admin_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb") OWNER TO "postgres";

--
-- Name: commit_edge_admin_gym_command_before_ordinary_progression("uuid", "uuid", "text", "text", "uuid", bigint, "text", "text", "text", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."commit_edge_admin_gym_command_before_ordinary_progression"("p_admin_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_contract text; v_expected_status text; v_legacy_projection jsonb; v_result jsonb; v_version bigint;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'service role required' using errcode='42501'; end if;
  select contract_key into strict v_contract from public.authoritative_battle where id=p_battle_id;
  v_expected_status:=server_authority_private.authoritative_battle_reward_status(v_contract);
  if v_contract not in ('admin_gym','league')
    or p_projection->>'reward_status' is distinct from v_expected_status then
    raise exception 'admin battle reward status does not match canonical contract' using errcode='22023';
  end if;
  v_legacy_projection:=jsonb_set(p_projection,'{reward_status}',to_jsonb('disabled_edge_first_slice'::text),true);
  v_result:=public.commit_edge_admin_gym_command_before_reward_status(
    p_admin_user_id,p_command_id,p_command_type,p_command_hash,p_battle_id,p_expected_battle_version,
    p_engine_version,p_engine_checksum,p_input_snapshot_hash,p_next_snapshot,p_events,v_legacy_projection);
  if jsonb_typeof(v_result->'battle')='object' then
    v_result:=jsonb_set(v_result,'{battle,reward_status}',to_jsonb(v_expected_status),true);
    v_version:=(v_result->>'battle_version')::bigint;
    update public.authoritative_battle_command_receipt
      set result=jsonb_set(result,'{battle,reward_status}',to_jsonb(v_expected_status),true)
      where battle_id=p_battle_id and resulting_battle_version=v_version;
  end if;
  update public.authoritative_admin_gym_command_receipt set result=v_result
    where admin_auth_user_id=p_admin_user_id and command_id=p_command_id;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."commit_edge_admin_gym_command_before_ordinary_progression"("p_admin_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb") OWNER TO "postgres";

--
-- Name: commit_edge_admin_gym_command_before_reward_status("uuid", "uuid", "text", "text", "uuid", bigint, "text", "text", "text", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."commit_edge_admin_gym_command_before_reward_status"("p_admin_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $_$
declare v_battle public.authoritative_battle%rowtype; v_receipt public.authoritative_admin_gym_command_receipt%rowtype;
  v_revision bigint; v_internal uuid:=gen_random_uuid(); v_result jsonb; v_terminal jsonb; v_owner uuid;
begin
  if coalesce(auth.role(),'')<>'service_role' or not server_authority_private.user_has_server_role(p_admin_user_id,'admin') then
    raise exception 'admin service authority required' using errcode='42501'; end if;
  select * into strict v_battle from public.authoritative_battle where id=p_battle_id;
  if v_battle.contract_key='admin_gym' then
    return public.commit_edge_admin_gym_command_before_league(p_admin_user_id,p_command_id,p_command_type,p_command_hash,p_battle_id,
      p_expected_battle_version,p_engine_version,p_engine_checksum,p_input_snapshot_hash,p_next_snapshot,p_events,p_projection);
  end if;
  if v_battle.contract_key<>'league' or p_command_type not in ('move','switch','item') or p_command_hash!~'^[0-9a-f]{64}$' then
    raise exception 'admin League command metadata is invalid' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_admin_user_id::text||':'||p_command_id::text,0));
  select * into v_receipt from public.authoritative_admin_gym_command_receipt where admin_auth_user_id=p_admin_user_id and command_id=p_command_id;
  if found then
    if v_receipt.battle_id<>p_battle_id or v_receipt.command_type<>p_command_type or v_receipt.command_hash<>p_command_hash then
      raise exception 'admin command id was reused with a different payload' using errcode='22023'; end if;
    return v_receipt.result;
  end if;
  if v_battle.waiting_for<>'admin' or v_battle.status not in ('active','needs_player_switch') then
    raise exception 'admin League is not waiting for an admin command' using errcode='40001'; end if;
  if v_battle.battle_version<>p_expected_battle_version then raise exception 'battle version conflict' using errcode='40001'; end if;
  v_owner:=v_battle.runtime_owner_id;
  if p_next_snapshot#>>'{manager,adminControlled}'<>'true' or p_projection->>'admin_controlled'<>'true'
    or (p_projection->>'status' not in ('concluded','abandoned') and p_projection->>'waiting_for' is distinct from p_next_snapshot#>>'{manager,waitingFor}')
    or (p_command_type<>'switch' and coalesce((v_battle.engine_snapshot#>>'{manager,npcNeedsSwitch}')::boolean,false)) then
    raise exception 'admin League transition ownership is invalid' using errcode='22023'; end if;
  select revision into strict v_revision from public.player_state_revision where auth_user_id=v_battle.auth_user_id;
  if p_command_type='item' then
    v_result:=server_authority_private.commit_edge_battle_command_without_items(v_battle.auth_user_id,v_internal,p_command_type,p_command_hash,
      v_revision,p_battle_id,p_expected_battle_version,v_owner,p_engine_version,p_engine_checksum,p_input_snapshot_hash,p_next_snapshot,
      p_events,p_projection,jsonb_build_object('reward','none','inventory','unchanged','team','unchanged'));
  else
    v_result:=server_authority_private.commit_edge_battle_command_before_admin_gyms(v_battle.auth_user_id,v_internal,p_command_type,p_command_hash,
      v_revision,p_battle_id,p_expected_battle_version,v_owner,p_engine_version,p_engine_checksum,p_input_snapshot_hash,p_next_snapshot,
      p_events,p_projection,jsonb_build_object('reward','none','inventory','unchanged','team','unchanged'));
  end if;
  if (select runtime_owner_id from public.authoritative_battle where id=p_battle_id) is distinct from v_owner then
    raise exception 'admin command changed the player runtime owner' using errcode='40001'; end if;
  update public.authoritative_battle set waiting_for=case when status in ('concluded','abandoned') then null else p_projection->>'waiting_for' end,
    admin_items=coalesce(p_projection->'admin_items',admin_items) where id=p_battle_id;
  if p_projection->>'status' in ('concluded','abandoned') then
    v_terminal:=server_authority_private.finalize_terminal_admin_league(v_battle.auth_user_id,p_battle_id,v_internal,p_projection);
    if v_terminal is not null then v_result:=jsonb_set(v_result,'{player_revision}',v_terminal#>'{player_state,revision}',true)||v_terminal; end if;
  end if;
  insert into public.authoritative_admin_gym_command_receipt(admin_auth_user_id,command_id,battle_id,command_type,command_hash,result,resulting_battle_version)
    values(p_admin_user_id,p_command_id,p_battle_id,p_command_type,p_command_hash,v_result,(v_result->>'battle_version')::bigint);
  return v_result;
end;
$_$;


ALTER FUNCTION "public"."commit_edge_admin_gym_command_before_reward_status"("p_admin_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb") OWNER TO "postgres";

--
-- Name: commit_edge_admin_gym_command_before_snapshot("uuid", "uuid", "text", "text", "uuid", bigint, "text", "text", "text", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."commit_edge_admin_gym_command_before_snapshot"("p_admin_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $_$
declare v_battle public.authoritative_battle%rowtype; v_receipt public.authoritative_admin_gym_command_receipt%rowtype;
  v_revision bigint; v_internal uuid:=gen_random_uuid(); v_result jsonb; v_owner uuid;
begin
  if p_command_type<>'entry_choice' then
    return public.commit_edge_admin_gym_command_before_initial_entry(
      p_admin_user_id,p_command_id,p_command_type,p_command_hash,p_battle_id,p_expected_battle_version,p_engine_version,p_engine_checksum,
      p_input_snapshot_hash,p_next_snapshot,p_events,p_projection
    );
  end if;
  if coalesce(auth.role(),'')<>'service_role' or not server_authority_private.user_has_server_role(p_admin_user_id,'admin') then
    raise exception 'admin service authority required' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_admin_user_id::text||':'||p_command_id::text,0));
  select * into v_receipt from public.authoritative_admin_gym_command_receipt
    where admin_auth_user_id=p_admin_user_id and command_id=p_command_id;
  if found then
    if v_receipt.battle_id<>p_battle_id or v_receipt.command_type<>p_command_type or v_receipt.command_hash<>p_command_hash then
      raise exception 'admin command id was reused with a different battle or payload' using errcode='22023'; end if;
    return v_receipt.result;
  end if;
  select * into strict v_battle from public.authoritative_battle where id=p_battle_id;
  if v_battle.contract_key not in ('admin_gym','league','debug_training')
    or v_battle.waiting_for<>'admin' or v_battle.status not in ('active','needs_player_switch')
    or v_battle.battle_version<>p_expected_battle_version or p_command_hash!~'^[0-9a-f]{64}$' then
    raise exception 'admin initial entry choice is invalid' using errcode='22023'; end if;
  if p_next_snapshot#>>'{manager,adminControlled}'<>'true' or p_projection->>'admin_controlled'<>'true'
    or p_next_snapshot#>>'{manager,initialEntry,phase}' not in ('awaiting_player_entry_choice','ready')
    or (p_projection->>'status' not in ('concluded','abandoned')
      and p_projection->>'waiting_for' is distinct from p_next_snapshot#>>'{manager,waitingFor}') then
    raise exception 'admin initial entry transition is invalid' using errcode='22023'; end if;
  select revision into strict v_revision from public.player_state_revision where auth_user_id=v_battle.auth_user_id;
  v_owner:=v_battle.runtime_owner_id;
  v_result:=server_authority_private.commit_edge_battle_command_before_admin_gyms(
    v_battle.auth_user_id,v_internal,p_command_type,p_command_hash,v_revision,p_battle_id,p_expected_battle_version,v_owner,
    p_engine_version,p_engine_checksum,p_input_snapshot_hash,p_next_snapshot,p_events,p_projection,
    jsonb_build_object('reward','none','inventory','unchanged','team','unchanged')
  );
  if (select runtime_owner_id from public.authoritative_battle where id=p_battle_id) is distinct from v_owner then
    raise exception 'admin command changed the player runtime owner' using errcode='40001'; end if;
  update public.authoritative_battle set waiting_for=case when status in ('concluded','abandoned') then null else p_projection->>'waiting_for' end,
    admin_items=coalesce(p_projection->'admin_items',admin_items) where id=p_battle_id;
  insert into public.authoritative_admin_gym_command_receipt(admin_auth_user_id,command_id,battle_id,command_type,command_hash,result,resulting_battle_version)
    values(p_admin_user_id,p_command_id,p_battle_id,p_command_type,p_command_hash,v_result,(v_result->>'battle_version')::bigint);
  return v_result;
end;
$_$;


