CREATE FUNCTION "public"."commit_edge_battle_command_before_ordinary_progression"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_contract text; v_expected_status text; v_legacy_projection jsonb; v_result jsonb;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'service role required' using errcode='42501'; end if;
  select contract_key into strict v_contract from public.authoritative_battle
    where id=p_battle_id and auth_user_id=p_auth_user_id;
  v_expected_status:=server_authority_private.authoritative_battle_reward_status(v_contract);
  if p_projection->>'reward_status' is distinct from v_expected_status then
    raise exception 'battle reward status does not match canonical contract' using errcode='22023';
  end if;
  v_legacy_projection:=jsonb_set(p_projection,'{reward_status}',to_jsonb('disabled_edge_first_slice'::text),true);
  v_result:=public.commit_edge_battle_command_before_reward_status(
    p_auth_user_id,p_command_id,p_command_type,p_command_hash,p_expected_player_revision,p_battle_id,
    p_expected_battle_version,p_runtime_owner_id,p_engine_version,p_engine_checksum,p_input_snapshot_hash,
    p_next_snapshot,p_events,v_legacy_projection,p_terminal_effects);
  if jsonb_typeof(v_result->'battle')='object' then
    v_result:=jsonb_set(v_result,'{battle,reward_status}',to_jsonb(v_expected_status),true);
  end if;
  update public.authoritative_battle_command_receipt set result=v_result
    where auth_user_id=p_auth_user_id and command_id=p_command_id;
  return v_result;
end;
$$;


