--
-- Name: complete_debug_mission("uuid", "uuid", bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."complete_debug_mission"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_expected_player_revision" bigint, "p_mission_index" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare
  v_request jsonb;
  v_request_hash text;
  v_receipt public.player_command_receipt%rowtype;
  v_revision bigint;
  v_profile public.player_profile_state%rowtype;
  v_state public.player_mission_state%rowtype;
  v_mission public.catalog_mission%rowtype;
  v_result jsonb;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Ãˆ richiesto il ruolo di servizio.' using errcode = '42501';
  end if;
  if not server_authority_private.user_has_server_role(p_auth_user_id, 'debug') then
    raise exception 'Ãˆ richiesto il ruolo debug.' using errcode = '42501';
  end if;
  if p_auth_user_id is null or p_command_id is null or p_expected_player_revision is null
    or p_expected_player_revision < 0 or p_mission_index is null or p_mission_index <= 0 then
    raise exception 'I dati del comando debug missione non sono validi.' using errcode = '22023';
  end if;

  v_request := jsonb_build_object(
    'command_type', 'debug_complete_mission',
    'expected_player_revision', p_expected_player_revision,
    'mission_index', p_mission_index
  );
  v_request_hash := encode(digest(convert_to(v_request::text, 'UTF8'), 'sha256'), 'hex');
  perform pg_advisory_xact_lock(hashtextextended(p_auth_user_id::text || ':' || p_command_id::text, 0));
  select * into v_receipt from public.player_command_receipt
  where auth_user_id = p_auth_user_id and command_id = p_command_id;
  if found then
    if v_receipt.command_type <> 'debug_complete_mission' or v_receipt.request_hash <> v_request_hash then
      raise exception 'Lâ€™identificativo del comando Ã¨ giÃ  stato usato con dati diversi.' using errcode = '22023';
    end if;
    return v_receipt.result;
  end if;

  perform server_authority_private.assert_no_pending_ordinary_progression(p_auth_user_id, p_command_id);
  select revision into v_revision from public.player_state_revision
  where auth_user_id = p_auth_user_id for update;
  if not found then raise exception 'Lo stato del giocatore non esiste.' using errcode = 'P0002'; end if;
  select * into v_profile from public.player_profile_state
  where auth_user_id = p_auth_user_id for update;
  if not found then raise exception 'Il profilo del giocatore non esiste.' using errcode = 'P0002'; end if;
  if v_revision <> p_expected_player_revision then
    raise exception 'Conflitto di revisione dello stato del giocatore.' using errcode = '40001';
  end if;
  if exists (
    select 1 from public.authoritative_battle
    where auth_user_id = p_auth_user_id and status in ('active', 'needs_player_switch')
  ) then
    raise exception 'Il comando debug missione non Ã¨ disponibile durante una battaglia attiva.' using errcode = '55000';
  end if;

  perform server_authority_private.sync_player_missions(p_auth_user_id);
  perform server_authority_private.apply_daily_mission_resets(p_auth_user_id);
  select * into v_state from public.player_mission_state
  where auth_user_id = p_auth_user_id and mission_index = p_mission_index for update;
  if not found then raise exception 'La missione non Ã¨ presente nello stato del giocatore.' using errcode = 'P0002'; end if;
  select * into v_mission from public.catalog_mission
  where catalog_release_id = v_state.catalog_release_id and mission_index = v_state.mission_index for share;
  if not found then raise exception 'La missione non Ã¨ presente nel catalogo attivo.' using errcode = 'P0002'; end if;
  if v_state.claim_status <> 'unclaimed' or v_state.counter >= v_mission.target
    or not server_authority_private.mission_is_active(p_auth_user_id, p_mission_index) then
    raise exception 'La missione deve essere attiva, non riscossa e incompleta.' using errcode = '22023';
  end if;

  update public.player_mission_state
  set counter = v_mission.target, updated_at = now()
  where auth_user_id = p_auth_user_id and mission_index = p_mission_index;
  update public.player_state_revision set revision = revision + 1, updated_at = now()
  where auth_user_id = p_auth_user_id returning revision into v_revision;
  v_result := jsonb_build_object(
    'ok', true,
    'player_revision', v_revision,
    'player_state', server_authority_private.player_state_projection(p_auth_user_id)
  );
  insert into public.player_command_receipt(auth_user_id, command_id, command_type, request_hash, result, resulting_revision)
  values(p_auth_user_id, p_command_id, 'debug_complete_mission', v_request_hash, v_result, v_revision);
  return v_result;
end;
$$;


ALTER FUNCTION "public"."complete_debug_mission"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_expected_player_revision" bigint, "p_mission_index" integer) OWNER TO "postgres";

--
-- Name: consume_edge_request_rate_limit("text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."consume_edge_request_rate_limit"("category" "text", "subject_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'server_authority_private', 'pg_temp'
    AS $_$
declare
  v_category text := category;
  v_subject_hash text := subject_hash;
  v_quota integer;
  v_window_seconds integer;
  v_now timestamptz := statement_timestamp();
  v_bucket server_authority_private.edge_request_rate_bucket%rowtype;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service role required' using errcode = '42501';
  end if;
  if v_subject_hash is null or v_subject_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid rate-limit subject hash' using errcode = '22023';
  end if;

  select limits.quota, limits.window_seconds
  into v_quota, v_window_seconds
  from (values
    ('battle_user', 120, 60),
    ('auth_login_global', 300, 60),
    ('auth_register_global', 60, 60),
    ('auth_recovery_global', 60, 60),
    ('auth_delete_user', 5, 3600)
  ) limits(category, quota, window_seconds)
  where limits.category = v_category;

  if v_quota is null then
    raise exception 'invalid rate-limit category' using errcode = '22023';
  end if;

  insert into server_authority_private.edge_request_rate_bucket as bucket (
    category, subject_hash, window_started_at, request_count, updated_at
  ) values (
    v_category, v_subject_hash, v_now, 1, v_now
  )
  on conflict on constraint edge_request_rate_bucket_pkey do update
  set window_started_at = case
        when bucket.window_started_at <= v_now - make_interval(secs => v_window_seconds) then v_now
        else bucket.window_started_at
      end,
      request_count = case
        when bucket.window_started_at <= v_now - make_interval(secs => v_window_seconds) then 1
        else bucket.request_count + 1
      end,
      updated_at = v_now
  where bucket.window_started_at <= v_now - make_interval(secs => v_window_seconds)
     or bucket.request_count < v_quota
  returning * into v_bucket;

  if found then
    return jsonb_build_object(
      'allowed', true,
      'remaining', greatest(v_quota - v_bucket.request_count, 0),
      'retry_after', 0
    );
  end if;

  select * into strict v_bucket
  from server_authority_private.edge_request_rate_bucket bucket
  where bucket.category = v_category
    and bucket.subject_hash = v_subject_hash;
  return jsonb_build_object(
    'allowed', false,
    'remaining', 0,
    'retry_after', greatest(1, ceil(extract(epoch from
      (v_bucket.window_started_at + make_interval(secs => v_window_seconds) - v_now)))::integer)
  );
end;
$_$;


ALTER FUNCTION "public"."consume_edge_request_rate_limit"("category" "text", "subject_hash" "text") OWNER TO "postgres";

