-- Name: deposit_daycare_pokemon_authoritative("uuid", bigint, "uuid", integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."deposit_daycare_pokemon_authoritative"("p_command_id" "uuid", "p_expected_revision" bigint, "p_pokemon_instance_id" "uuid", "p_slot_index" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_conflict jsonb;
begin
  v_conflict:=server_authority_private.player_command_revision_conflict(p_command_id,p_expected_revision);
  if v_conflict is not null then return v_conflict; end if;
  begin
    return public.deposit_daycare_pokemon_before_revision_guard(
      p_command_id,p_expected_revision,p_pokemon_instance_id,p_slot_index
    );
  exception when serialization_failure then
    v_conflict:=server_authority_private.player_command_revision_conflict(p_command_id,p_expected_revision);
    if v_conflict is not null then return v_conflict; end if;
    raise;
  end;
end;
$$;


