--
-- Name: discard_prepared_training_battle("uuid", "uuid", bigint, "uuid", bigint, "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."discard_prepared_training_battle"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare
  v_battle public.authoritative_battle%rowtype;
  v_receipt public.player_command_receipt%rowtype;
  v_revision bigint;
  v_request jsonb;
  v_hash text;
  v_result jsonb;
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'service role required' using errcode = '42501'; end if;
  if p_auth_user_id is null or p_command_id is null or p_battle_id is null or p_runtime_owner_id is null
    or p_expected_player_revision is null or p_expected_player_revision < 0
    or p_expected_battle_version is null or p_expected_battle_version < 1 then
    raise exception 'training preview discard envelope is invalid' using errcode = '22023';
  end if;
  v_request := jsonb_build_object('command_type', 'authoritative_training_preview_discard',
    'expected_player_revision', p_expected_player_revision, 'battle_id', p_battle_id,
    'expected_battle_version', p_expected_battle_version, 'runtime_owner_id', p_runtime_owner_id);
  v_hash := encode(digest(convert_to(v_request::text, 'UTF8'), 'sha256'), 'hex');
  perform pg_advisory_xact_lock(hashtextextended(p_auth_user_id::text || ':' || p_command_id::text, 0));
  select * into v_receipt from public.player_command_receipt
  where auth_user_id = p_auth_user_id and command_id = p_command_id;
  if found then
    if v_receipt.command_type <> 'authoritative_training_preview_discard' or v_receipt.request_hash <> v_hash then
      raise exception 'command id was already used with a different payload' using errcode = '22023';
    end if;
    return v_receipt.result;
  end if;
  select revision into v_revision from public.player_state_revision
  where auth_user_id = p_auth_user_id for update;
  if not found then raise exception 'player state does not exist' using errcode = 'P0002'; end if;
  if v_revision <> p_expected_player_revision then raise exception 'player revision conflict' using errcode = '40001'; end if;
  select * into v_battle from public.authoritative_battle
  where id = p_battle_id and auth_user_id = p_auth_user_id for update;
  if not found then raise exception 'authoritative battle was not found' using errcode = 'P0002'; end if;
  if v_battle.contract_key <> 'training' or v_battle.status <> 'prepared'
    or v_battle.battle_version <> p_expected_battle_version
    or v_battle.runtime_owner_id <> p_runtime_owner_id then
    raise exception 'prepared training battle changed' using errcode = '40001';
  end if;
  delete from public.authoritative_battle where id = p_battle_id;
  update public.player_state_revision set revision = revision + 1, updated_at = now()
  where auth_user_id = p_auth_user_id returning revision into v_revision;
  v_result := jsonb_build_object('player_revision', v_revision, 'battle_id', p_battle_id, 'discarded', true);
  insert into public.player_command_receipt(auth_user_id, command_id, command_type, request_hash, result, resulting_revision)
  values (p_auth_user_id, p_command_id, 'authoritative_training_preview_discard', v_hash, v_result, v_revision);
  return v_result;
end;
$$;


ALTER FUNCTION "public"."discard_prepared_training_battle"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid") OWNER TO "postgres";

--
-- Name: execute_debug_command("uuid", "uuid", bigint, "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."execute_debug_command"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_expected_player_revision" bigint, "p_command_type" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare
  v_request jsonb;
  v_request_hash text;
  v_receipt public.player_command_receipt%rowtype;
  v_revision bigint;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'service role required' using errcode = '42501';
  end if;
  if p_auth_user_id is null or p_command_id is null or p_expected_player_revision is null
    or p_expected_player_revision < 0
    or p_command_type not in ('debug_money', 'debug_badges', 'debug_battle_points', 'debug_create_pokemon', 'inventory_adjust')
    or jsonb_typeof(p_payload) is distinct from 'object' then
    raise exception 'invalid debug command envelope' using errcode = '22023';
  end if;
  if not server_authority_private.user_has_server_role(p_auth_user_id, 'debug') then
    raise exception 'debug role required' using errcode = '42501';
  end if;

  v_request := jsonb_build_object(
    'command_type', p_command_type,
    'expected_player_revision', p_expected_player_revision,
    'payload', p_payload
  );
  v_request_hash := encode(digest(convert_to(v_request::text, 'UTF8'), 'sha256'), 'hex');
  perform pg_advisory_xact_lock(hashtextextended(p_auth_user_id::text || ':' || p_command_id::text, 0));

  select * into v_receipt
  from public.player_command_receipt
  where auth_user_id = p_auth_user_id and command_id = p_command_id;
  if found then
    if v_receipt.command_type <> p_command_type or v_receipt.request_hash <> v_request_hash then
      raise exception 'command id was already used with a different payload' using errcode = '22023';
    end if;
    return v_receipt.result;
  end if;

  perform server_authority_private.assert_no_pending_ordinary_progression(p_auth_user_id, p_command_id);
  select revision into strict v_revision
  from public.player_state_revision
  where auth_user_id = p_auth_user_id
  for update;

  if v_revision <> p_expected_player_revision then
    return jsonb_build_object(
      'ok', true,
      'applied', false,
      'conflict', 'player_revision',
      'player_revision', v_revision,
      'player_state', server_authority_private.player_state_projection(p_auth_user_id)
    );
  end if;

  return public.execute_debug_command_before_revision_conflict(
    p_auth_user_id,
    p_command_id,
    p_expected_player_revision,
    p_command_type,
    p_payload
  );
end;
$$;


ALTER FUNCTION "public"."execute_debug_command"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_expected_player_revision" bigint, "p_command_type" "text", "p_payload" "jsonb") OWNER TO "postgres";

--
-- Name: execute_debug_command_before_battle_points("uuid", "uuid", bigint, "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."execute_debug_command_before_battle_points"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_expected_player_revision" bigint, "p_command_type" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
begin
  perform server_authority_private.assert_no_pending_ordinary_progression(p_auth_user_id,p_command_id);
  return public.execute_debug_command_before_ordinary_guard(
    p_auth_user_id,p_command_id,p_expected_player_revision,p_command_type,p_payload);
end;
$$;


ALTER FUNCTION "public"."execute_debug_command_before_battle_points"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_expected_player_revision" bigint, "p_command_type" "text", "p_payload" "jsonb") OWNER TO "postgres";

--
-- Name: execute_debug_command_before_ordinary_guard("uuid", "uuid", bigint, "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."execute_debug_command_before_ordinary_guard"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_expected_player_revision" bigint, "p_command_type" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $_$
declare
  v_request jsonb;
  v_request_hash text;
  v_receipt public.player_command_receipt%rowtype;
  v_profile public.player_profile_state%rowtype;
  v_revision bigint;
  v_delta integer;
  v_level integer;
  v_max_hp integer;
  v_held_item integer;
  v_species_key text;
  v_moves jsonb;
  v_move jsonb;
  v_move_index integer;
  v_power integer;
  v_stats integer;
  v_move_indexes integer[] := array[]::integer[];
  v_level_rule public.catalog_level_rule%rowtype;
  v_team_count integer;
  v_species_count integer;
  v_item_count integer;
  v_inventory_quantity integer;
  v_next_inventory_quantity bigint;
  v_slot integer;
  v_instance_id uuid;
  v_state jsonb;
  v_result jsonb;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'service role required' using errcode = '42501';
  end if;
  if p_auth_user_id is null or p_command_id is null or p_expected_player_revision is null
    or p_expected_player_revision < 0 or p_command_type not in ('debug_money', 'debug_badges', 'debug_create_pokemon', 'inventory_adjust')
    or jsonb_typeof(p_payload) is distinct from 'object' then
    raise exception 'invalid debug command envelope' using errcode = '22023';
  end if;
  if not server_authority_private.user_has_server_role(p_auth_user_id, 'debug') then
    raise exception 'debug role required' using errcode = '42501';
  end if;

  v_request := jsonb_build_object(
    'command_type', p_command_type,
    'expected_player_revision', p_expected_player_revision,
    'payload', p_payload
  );
  v_request_hash := encode(digest(convert_to(v_request::text, 'UTF8'), 'sha256'), 'hex');
  perform pg_advisory_xact_lock(hashtextextended(p_auth_user_id::text || ':' || p_command_id::text, 0));

  select * into v_receipt from public.player_command_receipt
  where auth_user_id = p_auth_user_id and command_id = p_command_id;
  if found then
    if v_receipt.command_type <> p_command_type or v_receipt.request_hash <> v_request_hash then
      raise exception 'command id was already used with a different payload' using errcode = '22023';
    end if;
    return v_receipt.result;
  end if;

  select revision into strict v_revision from public.player_state_revision
  where auth_user_id = p_auth_user_id for update;
  if v_revision <> p_expected_player_revision then
    raise exception 'player revision conflict' using errcode = '40001';
  end if;
  select * into strict v_profile from public.player_profile_state
  where auth_user_id = p_auth_user_id for update;

  if exists (
    select 1 from public.authoritative_battle
    where auth_user_id = p_auth_user_id and status in ('active', 'needs_player_switch')
  ) then
    raise exception 'debug commands are blocked during an active battle' using errcode = '55000';
  end if;

  if p_command_type = 'debug_money' then
    if p_payload <> jsonb_build_object('delta', p_payload -> 'delta') then
      raise exception 'invalid money payload' using errcode = '22023';
    end if;
    v_delta := server_authority_private.edge_jsonb_bigint(p_payload -> 'delta');
    if v_delta is null or v_delta = 0 or v_delta not between -1000000 and 1000000
      or v_profile.pokedollars + v_delta < 0 then
      raise exception 'money delta is outside its allowed range' using errcode = '22023';
    end if;
    update public.player_profile_state set pokedollars = pokedollars + v_delta, updated_at = now()
    where auth_user_id = p_auth_user_id;

  elsif p_command_type = 'debug_badges' then
    if p_payload <> jsonb_build_object('delta', p_payload -> 'delta') then
      raise exception 'invalid badge payload' using errcode = '22023';
    end if;
    v_delta := server_authority_private.edge_jsonb_bigint(p_payload -> 'delta');
    if v_delta is null or v_delta not in (-1, 1) then
      raise exception 'badge delta must be -1 or 1' using errcode = '22023';
    end if;
    update public.player_profile_state set badges = greatest(0, least(8, badges + v_delta)), updated_at = now()
    where auth_user_id = p_auth_user_id;

  elsif p_command_type = 'inventory_adjust' then
    if (select count(*) from jsonb_object_keys(p_payload)) <> 2
      or not (p_payload ?& array['itemIndex', 'delta']) then
      raise exception 'invalid inventory payload' using errcode = '22023';
    end if;
    v_held_item := server_authority_private.edge_jsonb_bigint(p_payload -> 'itemIndex');
    v_delta := server_authority_private.edge_jsonb_bigint(p_payload -> 'delta');
    if v_held_item is null or v_held_item <= 0 or v_delta is null or v_delta = 0
      or v_delta not between -999 and 999 or not exists (
        select 1 from public.catalog_item where catalog_release_id = v_profile.catalog_release_id
          and item_index = v_held_item
      ) then
      raise exception 'inventory item or delta is invalid' using errcode = '22023';
    end if;
    select quantity into v_inventory_quantity from public.player_inventory_item
    where auth_user_id = p_auth_user_id and item_index = v_held_item for update;
    v_inventory_quantity := coalesce(v_inventory_quantity, 0);
    v_next_inventory_quantity := v_inventory_quantity::bigint + v_delta;
    if v_next_inventory_quantity < 0 or v_next_inventory_quantity > 2147483647 then
      raise exception 'inventory quantity is outside its allowed range' using errcode = '22023';
    elsif v_next_inventory_quantity = 0 then
      delete from public.player_inventory_item
      where auth_user_id = p_auth_user_id and item_index = v_held_item;
    else
      insert into public.player_inventory_item(auth_user_id, catalog_release_id, item_index, quantity, updated_at)
      values(p_auth_user_id, v_profile.catalog_release_id, v_held_item, v_next_inventory_quantity::integer, now())
      on conflict(auth_user_id, item_index) do update set
        catalog_release_id = excluded.catalog_release_id,
        quantity = excluded.quantity,
        updated_at = excluded.updated_at;
    end if;

  else
    if (select count(*) from jsonb_object_keys(p_payload)) <> 5
      or not (p_payload ?& array['speciesKey', 'level', 'maxHp', 'heldItemIndex', 'moves']) then
      raise exception 'invalid Pokemon payload' using errcode = '22023';
    end if;
    v_species_key := p_payload ->> 'speciesKey';
    v_level := server_authority_private.edge_jsonb_bigint(p_payload -> 'level');
    v_max_hp := server_authority_private.edge_jsonb_bigint(p_payload -> 'maxHp');
    v_held_item := server_authority_private.edge_jsonb_bigint(p_payload -> 'heldItemIndex');
    v_moves := p_payload -> 'moves';
    if v_species_key is null or v_species_key !~ '^[A-Za-z0-9_-]{1,80}$' or v_level not between 5 and 100
      or v_max_hp is null or v_max_hp not between 1 and 999 or v_held_item is null or v_held_item < 0
      or jsonb_typeof(v_moves) is distinct from 'array' or jsonb_array_length(v_moves) not between 1 and 4
      or not exists (select 1 from public.catalog_species where catalog_release_id = v_profile.catalog_release_id
        and species_key = v_species_key) then
      raise exception 'Pokemon species or base state is invalid' using errcode = '22023';
    end if;
    select * into v_level_rule from public.catalog_level_rule
    where catalog_release_id = v_profile.catalog_release_id and level = v_level;
    if not found then
      raise exception 'Pokemon HP exceeds the catalog level cap' using errcode = '22023';
    end if;
    if v_held_item > 0 and not exists (
      select 1 from public.catalog_item where catalog_release_id = v_profile.catalog_release_id and item_index = v_held_item
    ) then
      raise exception 'held item is not cataloged' using errcode = '22023';
    end if;
    for v_move in select value from jsonb_array_elements(v_moves) loop
      if jsonb_typeof(v_move) is distinct from 'object' or (select count(*) from jsonb_object_keys(v_move)) <> 3
        or not (v_move ?& array['moveIndex', 'power', 'stats']) then
        raise exception 'move state is invalid' using errcode = '22023';
      end if;
      v_move_index := server_authority_private.edge_jsonb_bigint(v_move -> 'moveIndex');
      v_power := server_authority_private.edge_jsonb_bigint(v_move -> 'power');
      v_stats := server_authority_private.edge_jsonb_bigint(v_move -> 'stats');
      if v_move_index is null or v_power is null or v_stats is null
        or v_power not between 0 and 999
        or v_stats not between 0 and 999 or v_move_index = any(v_move_indexes)
        or not exists (select 1 from public.catalog_move where catalog_release_id = v_profile.catalog_release_id
          and move_index = v_move_index) then
        raise exception 'move reference or values are invalid' using errcode = '22023';
      end if;
      v_move_indexes := array_append(v_move_indexes, v_move_index);
    end loop;

    perform 1 from public.player_pokemon_placement
    where auth_user_id = p_auth_user_id and placement_type = 'team'
    order by pokemon_instance_id for update;
    select count(*) into v_team_count from public.player_pokemon_placement
    where auth_user_id = p_auth_user_id and placement_type = 'team';
    if v_team_count >= 6 then raise exception 'team is full' using errcode = '22023'; end if;
    select count(*) into v_species_count from public.player_pokemon_placement placement
    join public.player_pokemon_instance pokemon on pokemon.id = placement.pokemon_instance_id
    where placement.auth_user_id = p_auth_user_id and placement.placement_type = 'team'
      and pokemon.species_key = v_species_key;
    if v_species_count >= 2 then raise exception 'team already has two Pokemon of this species' using errcode = '22023'; end if;
    if v_held_item > 0 then
      select count(*) into v_item_count from public.player_pokemon_placement placement
      join public.player_pokemon_instance pokemon on pokemon.id = placement.pokemon_instance_id
      where placement.auth_user_id = p_auth_user_id and placement.placement_type = 'team'
        and server_authority_private.edge_jsonb_bigint(pokemon.state -> 'i') = v_held_item;
      if v_item_count >= 2 then raise exception 'team already has two equal held items' using errcode = '22023'; end if;
    end if;
    select slot into v_slot from generate_series(0, 5) slot
    where not exists (select 1 from public.player_pokemon_placement where auth_user_id = p_auth_user_id
      and placement_type = 'team' and slot_index = slot) order by slot limit 1;
    if v_slot is null then raise exception 'no valid team slot is available' using errcode = '22023'; end if;

    v_instance_id := gen_random_uuid();
    select jsonb_agg(jsonb_build_array(
      server_authority_private.edge_jsonb_bigint(value -> 'moveIndex'),
      server_authority_private.edge_jsonb_bigint(value -> 'power'),
      server_authority_private.edge_jsonb_bigint(value -> 'stats')
    ) order by ordinality) into v_moves from jsonb_array_elements(v_moves) with ordinality;
    v_state := jsonb_build_object('s', v_species_key, 'g', null, 'l', v_level, 'hp', v_max_hp, 'm', v_moves, 'xp', 0);
    if v_held_item > 0 then v_state := v_state || jsonb_build_object('i', v_held_item); end if;
    insert into public.player_pokemon_instance(id, auth_user_id, catalog_release_id, species_key, state_version, state, revision, debug_created)
    values(v_instance_id, p_auth_user_id, v_profile.catalog_release_id, v_species_key, 1, v_state, 1, true);
    insert into public.player_pokemon_placement(pokemon_instance_id, auth_user_id, placement_type, slot_index, box_index)
    values(v_instance_id, p_auth_user_id, 'team', v_slot, null);
    insert into public.player_dex_entry(auth_user_id, catalog_release_id, species_key)
    values(p_auth_user_id, v_profile.catalog_release_id, v_species_key) on conflict do nothing;
  end if;

  update public.player_state_revision set revision = revision + 1, updated_at = now()
  where auth_user_id = p_auth_user_id returning revision into v_revision;
  v_result := jsonb_build_object(
    'ok', true,
    'player_revision', v_revision,
    'player_state', server_authority_private.player_state_projection(p_auth_user_id)
  );
  insert into public.player_command_receipt(auth_user_id, command_id, command_type, request_hash, result, resulting_revision)
  values(p_auth_user_id, p_command_id, p_command_type, v_request_hash, v_result, v_revision);
  return v_result;
end;
$_$;


ALTER FUNCTION "public"."execute_debug_command_before_ordinary_guard"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_expected_player_revision" bigint, "p_command_type" "text", "p_payload" "jsonb") OWNER TO "postgres";

--
-- Name: execute_debug_command_before_revision_conflict("uuid", "uuid", bigint, "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."execute_debug_command_before_revision_conflict"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_expected_player_revision" bigint, "p_command_type" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare
  v_request jsonb;
  v_request_hash text;
  v_receipt public.player_command_receipt%rowtype;
  v_profile public.player_profile_state%rowtype;
  v_revision bigint;
  v_result jsonb;
begin
  if p_command_type <> 'debug_battle_points' then
    return public.execute_debug_command_before_battle_points(
      p_auth_user_id,p_command_id,p_expected_player_revision,p_command_type,p_payload);
  end if;
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'service role required' using errcode = '42501';
  end if;
  if p_auth_user_id is null or p_command_id is null or p_expected_player_revision is null
    or p_expected_player_revision < 0 or p_payload <> '{}'::jsonb then
    raise exception 'invalid debug battle points command envelope' using errcode = '22023';
  end if;
  if not server_authority_private.user_has_server_role(p_auth_user_id, 'debug') then
    raise exception 'debug role required' using errcode = '42501';
  end if;

  v_request := jsonb_build_object(
    'command_type', p_command_type,
    'expected_player_revision', p_expected_player_revision,
    'payload', p_payload
  );
  v_request_hash := encode(digest(convert_to(v_request::text, 'UTF8'), 'sha256'), 'hex');
  perform pg_advisory_xact_lock(hashtextextended(p_auth_user_id::text || ':' || p_command_id::text, 0));
  select * into v_receipt from public.player_command_receipt
  where auth_user_id = p_auth_user_id and command_id = p_command_id;
  if found then
    if v_receipt.command_type <> p_command_type or v_receipt.request_hash <> v_request_hash then
      raise exception 'command id was already used with a different payload' using errcode = '22023';
    end if;
    return v_receipt.result;
  end if;

  perform server_authority_private.assert_no_pending_ordinary_progression(p_auth_user_id,p_command_id);
  select revision into strict v_revision from public.player_state_revision
  where auth_user_id = p_auth_user_id for update;
  if v_revision <> p_expected_player_revision then
    raise exception 'player revision conflict' using errcode = '40001';
  end if;
  select * into strict v_profile from public.player_profile_state
  where auth_user_id = p_auth_user_id for update;
  if exists (
    select 1 from public.authoritative_battle
    where auth_user_id = p_auth_user_id and status in ('active', 'needs_player_switch')
  ) then
    raise exception 'debug commands are blocked during an active battle' using errcode = '55000';
  end if;
  if v_profile.battle_points > 9223372036854775307 then
    raise exception 'battle points exceed the supported range' using errcode = '22023';
  end if;

  update public.player_profile_state set battle_points = battle_points + 500, updated_at = now()
  where auth_user_id = p_auth_user_id;
  update public.player_state_revision set revision = revision + 1, updated_at = now()
  where auth_user_id = p_auth_user_id returning revision into v_revision;
  v_result := jsonb_build_object(
    'ok', true,
    'player_revision', v_revision,
    'player_state', server_authority_private.player_state_projection(p_auth_user_id)
  );
  insert into public.player_command_receipt(auth_user_id,command_id,command_type,request_hash,result,resulting_revision)
  values(p_auth_user_id,p_command_id,p_command_type,v_request_hash,v_result,v_revision);
  return v_result;
end;
$$;


ALTER FUNCTION "public"."execute_debug_command_before_revision_conflict"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_expected_player_revision" bigint, "p_command_type" "text", "p_payload" "jsonb") OWNER TO "postgres";

--
-- Name: execute_pokemon_center_command_authoritative("uuid", bigint, "uuid", "text", integer, integer, "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."execute_pokemon_center_command_authoritative"("p_command_id" "uuid", "p_expected_revision" bigint, "p_pokemon_instance_id" "uuid", "p_operation" "text", "p_item_index" integer, "p_replacement_slot" integer DEFAULT NULL::integer, "p_evolution_target_species_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_conflict jsonb;
begin
  v_conflict:=server_authority_private.player_command_revision_conflict(p_command_id,p_expected_revision);
  if v_conflict is not null then return v_conflict; end if;
  begin
    return public.execute_pokemon_center_command_before_revision_guard(
      p_command_id,p_expected_revision,p_pokemon_instance_id,p_operation,p_item_index,
      p_replacement_slot,p_evolution_target_species_key
    );
  exception when serialization_failure then
    v_conflict:=server_authority_private.player_command_revision_conflict(p_command_id,p_expected_revision);
    if v_conflict is not null then return v_conflict; end if;
    raise;
  end;
end;
$$;


ALTER FUNCTION "public"."execute_pokemon_center_command_authoritative"("p_command_id" "uuid", "p_expected_revision" bigint, "p_pokemon_instance_id" "uuid", "p_operation" "text", "p_item_index" integer, "p_replacement_slot" integer, "p_evolution_target_species_key" "text") OWNER TO "postgres";

--
-- Name: execute_pokemon_center_command_before_ordinary_guard("uuid", bigint, "uuid", "text", integer, integer, "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."execute_pokemon_center_command_before_ordinary_guard"("p_command_id" "uuid", "p_expected_revision" bigint, "p_pokemon_instance_id" "uuid", "p_operation" "text", "p_item_index" integer, "p_replacement_slot" integer DEFAULT NULL::integer, "p_evolution_target_species_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $_$
declare
  v_auth_user_id uuid := auth.uid();
  v_request jsonb;
  v_request_hash text;
  v_receipt_type text;
  v_receipt_hash text;
  v_receipt_result jsonb;
  v_current_revision bigint;
  v_profile public.player_profile_state%rowtype;
  v_instance public.player_pokemon_instance%rowtype;
  v_placement public.player_pokemon_placement%rowtype;
  v_item public.catalog_item%rowtype;
  v_inventory public.player_inventory_item%rowtype;
  v_level_rule public.catalog_level_rule%rowtype;
  v_old_item_index integer;
  v_move_count integer;
  v_move_power integer;
  v_move_stats integer;
  v_item_value integer;  v_mt_tier integer;
  v_target_species_key text := nullif(btrim(p_evolution_target_species_key), '');
  v_types text[];
  v_moves jsonb;
  v_result jsonb;
begin
  if v_auth_user_id is null then
    raise exception 'authentication required' using errcode = '28000';
  end if;
  if p_command_id is null or p_pokemon_instance_id is null then
    raise exception 'command id and Pokemon instance id are required' using errcode = '22023';
  end if;
  if p_expected_revision is null or p_expected_revision < 0 then
    raise exception 'expected revision must be non-negative' using errcode = '22023';
  end if;
  if p_operation is null or p_operation not in ('assign_held', 'remove_held', 'use_vitamin', 'teach_mt', 'evolve') then
    raise exception 'Pokemon Center operation is not allowed' using errcode = '22023';
  end if;
  if p_item_index is null or p_item_index <= 0 then
    raise exception 'item index must be positive' using errcode = '22023';
  end if;
  if p_operation not in ('teach_mt', 'use_vitamin') and p_replacement_slot is not null then
    raise exception 'move slot is only allowed for MTs and move vitamins' using errcode = '22023';
  end if;
  if p_operation <> 'evolve' and v_target_species_key is not null then
    raise exception 'evolution target is only allowed for evolution' using errcode = '22023';
  end if;
  if p_operation = 'evolve' and v_target_species_key is null then
    raise exception 'evolution target is required' using errcode = '22023';
  end if;

  v_request := jsonb_build_object(
    'command_type', 'pokemon_center_' || p_operation,
    'expected_revision', p_expected_revision,
    'pokemon_instance_id', p_pokemon_instance_id,
    'item_index', p_item_index,
    'replacement_slot', p_replacement_slot,
    'evolution_target_species_key', v_target_species_key
  );
  v_request_hash := encode(digest(convert_to(v_request::text, 'UTF8'), 'sha256'), 'hex');
  perform pg_advisory_xact_lock(hashtextextended(v_auth_user_id::text || ':' || p_command_id::text, 0));

  select command_type, request_hash, result
  into v_receipt_type, v_receipt_hash, v_receipt_result
  from public.player_command_receipt
  where auth_user_id = v_auth_user_id and command_id = p_command_id;
  if found then
    if v_receipt_type <> ('pokemon_center_' || p_operation) or v_receipt_hash <> v_request_hash then
      raise exception 'command id was already used with a different payload' using errcode = '22023';
    end if;
    return v_receipt_result;
  end if;

  select revision into v_current_revision
  from public.player_state_revision
  where auth_user_id = v_auth_user_id
  for update;
  if not found then
    raise exception 'player state does not exist' using errcode = 'P0002';
  end if;
  if v_current_revision <> p_expected_revision then
    raise exception 'revision conflict: expected %, current %', p_expected_revision, v_current_revision using errcode = '40001';
  end if;

  select * into v_profile
  from public.player_profile_state
  where auth_user_id = v_auth_user_id
  for update;
  if not found then
    raise exception 'player profile does not exist' using errcode = 'P0002';
  end if;

  -- Use the team-wide UUID lock order shared by placement commands because held
  -- item limits depend on every team member.
  perform 1
  from public.player_pokemon_placement placement
  join public.player_pokemon_instance pokemon
    on pokemon.id = placement.pokemon_instance_id and pokemon.auth_user_id = placement.auth_user_id
  where placement.auth_user_id = v_auth_user_id and placement.placement_type = 'team'
  order by placement.pokemon_instance_id
  for update of placement, pokemon;

  select * into v_instance
  from public.player_pokemon_instance
  where id = p_pokemon_instance_id and auth_user_id = v_auth_user_id;
  if not found then
    raise exception 'Pokemon instance is not owned by the current player' using errcode = '22023';
  end if;
  select * into v_placement
  from public.player_pokemon_placement
  where pokemon_instance_id = p_pokemon_instance_id and auth_user_id = v_auth_user_id;
  if not found or v_placement.placement_type <> 'team' then
    raise exception 'Pokemon must be in the current team' using errcode = '22023';
  end if;
  if p_operation <> 'remove_held' and exists (
    select 1 from public.player_pending_resolution
    where auth_user_id = v_auth_user_id and pokemon_instance_id = p_pokemon_instance_id and status = 'pending'
  ) then
    raise exception 'Pokemon has a pending resolution' using errcode = '55000';
  end if;
  if v_instance.catalog_release_id <> v_profile.catalog_release_id
    or v_instance.state ->> 's' is distinct from v_instance.species_key then
    raise exception 'canonical Pokemon catalog identity is inconsistent' using errcode = '22023';
  end if;
  if coalesce(v_instance.state ->> 'l', '') !~ '^[1-9][0-9]*$'
    or coalesce(v_instance.state ->> 'hp', '') !~ '^[1-9][0-9]*$'
    or jsonb_typeof(coalesce(v_instance.state -> 'm', 'null'::jsonb)) <> 'array' then
    raise exception 'canonical Pokemon state is invalid' using errcode = '22023';
  end if;

  select * into v_level_rule
  from public.catalog_level_rule
  where catalog_release_id = v_instance.catalog_release_id
    and level = (v_instance.state ->> 'l')::integer;
  if not found then
    raise exception 'level/stat rule is missing for the Pokemon level' using errcode = 'P0002';
  end if;
  if (v_instance.state ->> 'hp')::integer > (case when v_instance.debug_created then 999 else v_level_rule.max_hp end) then
    raise exception 'canonical Pokemon HP exceeds its catalog cap' using errcode = '22023';
  end if;

  select coalesce(jsonb_agg(move order by ordinality), '[]'::jsonb), count(*)::integer
  into v_moves, v_move_count
  from jsonb_array_elements(v_instance.state -> 'm') with ordinality as moves(move, ordinality)
  where jsonb_typeof(move) = 'array' and jsonb_array_length(move) = 3
    and coalesce(move ->> 0, '') ~ '^[1-9][0-9]*$'
    and coalesce(move ->> 1, '') ~ '^[0-9]+$'
    and coalesce(move ->> 2, '') ~ '^[0-9]+$'
    and (move ->> 1)::integer <= (case when v_instance.debug_created then 999 else v_level_rule.max_power end)
    and (move ->> 2)::integer <= (case when v_instance.debug_created then 999 else v_level_rule.max_stats end)
    and exists (
      select 1 from public.catalog_move catalog_move
      where catalog_move.catalog_release_id = v_instance.catalog_release_id
        and catalog_move.move_index = (move ->> 0)::integer
    );
  if v_move_count <> jsonb_array_length(v_instance.state -> 'm') or v_move_count > 4
    or (select count(distinct (move ->> 0)::integer) from jsonb_array_elements(v_moves) move) <> v_move_count then
    raise exception 'canonical Pokemon moves are invalid' using errcode = '22023';
  end if;

  v_old_item_index := case
    when coalesce(v_instance.state ->> 'i', '') ~ '^[1-9][0-9]*$' then (v_instance.state ->> 'i')::integer
    when not (v_instance.state ? 'i') then 0
    else -1
  end;
  if v_old_item_index < 0 or (v_old_item_index > 0 and not exists (
    select 1 from public.catalog_item
    where catalog_release_id = v_instance.catalog_release_id and item_index = v_old_item_index
  )) then
    raise exception 'canonical held item is invalid' using errcode = '22023';
  end if;

  select * into v_item
  from public.catalog_item
  where catalog_release_id = v_instance.catalog_release_id and item_index = p_item_index;
  if not found then
    raise exception 'item is missing from the Pokemon catalog release' using errcode = 'P0002';
  end if;

  perform 1
  from public.player_inventory_item
  where auth_user_id = v_auth_user_id
  order by item_index
  for update;

  select * into v_inventory
  from public.player_inventory_item
  where auth_user_id = v_auth_user_id and item_index = p_item_index
  for update;
  if p_operation <> 'remove_held' and (not found or v_inventory.catalog_release_id <> v_instance.catalog_release_id or v_inventory.quantity <= 0) then
    raise exception 'item is not available in inventory' using errcode = '22023';
  end if;

  if p_operation = 'assign_held' then
    if v_item.category_key not in ('HeldItem', 'Berry') then
      raise exception 'item cannot be held' using errcode = '22023';
    end if;
    if (v_item.rules ? 'allowedSpeciesKeys' and jsonb_typeof(v_item.rules -> 'allowedSpeciesKeys') <> 'array')
      or (v_item.rules ? 'allowedSpeciesNames' and jsonb_typeof(v_item.rules -> 'allowedSpeciesNames') <> 'array')
      or (v_item.rules ? 'requiredType' and jsonb_typeof(v_item.rules -> 'requiredType') <> 'string')
      or (v_item.rules ? 'requiredMonoType' and jsonb_typeof(v_item.rules -> 'requiredMonoType') <> 'string') then
      raise exception 'held item compatibility rules are malformed' using errcode = '22023';
    end if;
    select array_agg(type_key order by type_order) into v_types
    from public.catalog_species_type
    where catalog_release_id = v_instance.catalog_release_id and species_key = v_instance.species_key;
    if coalesce(array_length(v_types, 1), 0) = 0
      or (jsonb_typeof(v_item.rules -> 'allowedSpeciesKeys') = 'array'
        and jsonb_array_length(v_item.rules -> 'allowedSpeciesKeys') > 0
        and not (v_item.rules -> 'allowedSpeciesKeys' ? v_instance.species_key))
      or (jsonb_typeof(v_item.rules -> 'allowedSpeciesNames') = 'array'
        and jsonb_array_length(v_item.rules -> 'allowedSpeciesNames') > 0
        and not (v_item.rules -> 'allowedSpeciesNames' ? (select display_name from public.catalog_species where catalog_release_id = v_instance.catalog_release_id and species_key = v_instance.species_key)))
      or (v_item.rules ? 'requiredType' and not ((v_item.rules ->> 'requiredType') = any(v_types)))
      or (v_item.rules ? 'requiredMonoType' and not (array_length(v_types, 1) = 1 and v_types[1] = v_item.rules ->> 'requiredMonoType')) then
      raise exception 'Pokemon is not compatible with the held item' using errcode = '22023';
    end if;
    if v_old_item_index = p_item_index then
      raise exception 'Pokemon already holds this item' using errcode = '22023';
    end if;
    if (select count(*)
      from public.player_pokemon_placement placement
      join public.player_pokemon_instance pokemon on pokemon.id = placement.pokemon_instance_id
      where placement.auth_user_id = v_auth_user_id and placement.placement_type = 'team'
        and pokemon.id <> p_pokemon_instance_id
        and coalesce(pokemon.state ->> 'i', '') ~ '^[1-9][0-9]*$'
        and (pokemon.state ->> 'i')::integer = p_item_index) >= 2 then
      raise exception 'team cannot contain more than two Pokemon holding the same item' using errcode = '22023';
    end if;

    if v_inventory.quantity = 1 then
      delete from public.player_inventory_item where auth_user_id = v_auth_user_id and item_index = p_item_index;
    else
      update public.player_inventory_item set quantity = quantity - 1, updated_at = now()
      where auth_user_id = v_auth_user_id and item_index = p_item_index;
    end if;
    if v_old_item_index > 0 then
      insert into public.player_inventory_item(auth_user_id, catalog_release_id, item_index, quantity, updated_at)
      values (v_auth_user_id, v_instance.catalog_release_id, v_old_item_index, 1, now())
      on conflict (auth_user_id, item_index) do update
        set quantity = player_inventory_item.quantity + 1, updated_at = now();
    end if;
    v_instance.state := jsonb_set(v_instance.state, '{i}', to_jsonb(p_item_index), true);

  elsif p_operation = 'remove_held' then
    if v_old_item_index <> p_item_index then
      raise exception 'item index does not match the held item' using errcode = '22023';
    end if;
    if v_item.category_key not in ('HeldItem', 'Berry') then
      raise exception 'canonical held item category is invalid' using errcode = '22023';
    end if;
    insert into public.player_inventory_item(auth_user_id, catalog_release_id, item_index, quantity, updated_at)
    values (v_auth_user_id, v_instance.catalog_release_id, p_item_index, 1, now())
    on conflict (auth_user_id, item_index) do update
      set quantity = player_inventory_item.quantity + 1, updated_at = now();
    v_instance.state := v_instance.state - 'i';

  elsif p_operation = 'use_vitamin' then
    if v_item.category_key <> 'Vitamin'
      or v_item.rules ->> 'effect' is null
      or v_item.rules ->> 'effect' not in ('max_hp', 'move_power')
      or coalesce(v_item.rules ->> 'value', '') !~ '^[1-9][0-9]*$' then
      raise exception 'vitamin catalog rules are unsupported or incomplete' using errcode = '22023';
    end if;
    v_item_value := (v_item.rules ->> 'value')::integer;
    if v_item.rules ->> 'effect' = 'max_hp' then
      if p_replacement_slot is not null or (v_instance.state ->> 'hp')::integer >= (case when v_instance.debug_created then 999 else v_level_rule.max_hp end) then
        raise exception 'vitamin would have no valid effect' using errcode = '22023';
      end if;
      v_instance.state := jsonb_set(v_instance.state, '{hp}',
        to_jsonb(least((v_instance.state ->> 'hp')::integer + v_item_value, (case when v_instance.debug_created then 999 else v_level_rule.max_hp end))), true);
    else
      if p_replacement_slot is null or p_replacement_slot < 0 or p_replacement_slot >= v_move_count then
        raise exception 'valid move slot is required for this vitamin' using errcode = '22023';
      end if;
      v_move_power := (v_moves -> p_replacement_slot ->> 1)::integer;
      v_move_stats := (v_moves -> p_replacement_slot ->> 2)::integer;
      if v_move_power >= (case when v_instance.debug_created then 999 else v_level_rule.max_power end) and v_move_stats >= (case when v_instance.debug_created then 999 else v_level_rule.max_stats end) then
        raise exception 'vitamin would have no effect on the selected move' using errcode = '22023';
      end if;
      v_moves := jsonb_set(v_moves, array[p_replacement_slot::text], jsonb_build_array(
        (v_moves -> p_replacement_slot ->> 0)::integer,
        least(v_move_power + v_item_value, (case when v_instance.debug_created then 999 else v_level_rule.max_power end)),
        least(v_move_stats + v_item_value, (case when v_instance.debug_created then 999 else v_level_rule.max_stats end))
      ), false);
      v_instance.state := jsonb_set(v_instance.state, '{m}', v_moves, true);
    end if;
    if v_inventory.quantity = 1 then
      delete from public.player_inventory_item where auth_user_id = v_auth_user_id and item_index = p_item_index;
    else
      update public.player_inventory_item set quantity = quantity - 1, updated_at = now()
      where auth_user_id = v_auth_user_id and item_index = p_item_index;
    end if;

  elsif p_operation = 'teach_mt' then
    if v_item.category_key <> 'Mt' or v_item.move_index is null then
      raise exception 'MT catalog rules are unsupported or incomplete' using errcode = '22023';
    end if;
    if not exists (
      select 1 from public.catalog_species_machine_move
      where catalog_release_id = v_instance.catalog_release_id
        and species_key = v_instance.species_key and move_index = v_item.move_index
    ) or exists (
      select 1 from jsonb_array_elements(v_moves) known where (known ->> 0)::integer = v_item.move_index
    ) then
      raise exception 'Pokemon cannot learn this MT' using errcode = '22023';
    end if;
    select coalesce(max((known ->> 1)::integer), v_level_rule.base_power),
      coalesce(max((known ->> 2)::integer), v_level_rule.base_stats)
    into v_move_power, v_move_stats from jsonb_array_elements(v_moves) known;
    if v_move_power is null or v_move_stats is null then
      raise exception 'base move stats are missing for the Pokemon level' using errcode = 'P0002';
    end if;
    if v_move_count < 4 then
      if p_replacement_slot is not null then
        raise exception 'replacement slot is not allowed while fewer than four moves are known' using errcode = '22023';
      end if;
      v_moves := v_moves || jsonb_build_array(jsonb_build_array(v_item.move_index, v_move_power, v_move_stats));
    else
      if p_replacement_slot is null or p_replacement_slot not between 0 and 3 then
        raise exception 'replacement slot must be between 0 and 3' using errcode = '22023';
      end if;
      v_moves := jsonb_set(v_moves, array[p_replacement_slot::text],
        jsonb_build_array(v_item.move_index, v_move_power, v_move_stats), false);
    end if;
    v_instance.state := jsonb_set(v_instance.state, '{m}', v_moves, true);
    -- MTs are reusable in the current game rules, so quantity is validated but not consumed.

  else
    if not ((v_item.category_key = 'Item' and v_item.subcategory_key = 'EvoStone')
      or v_item.category_key = 'HeldItem') then
      raise exception 'item category cannot trigger evolution' using errcode = '22023';
    end if;
    if not exists (
      select 1 from public.catalog_species_evolution evolution
      where evolution.catalog_release_id = v_instance.catalog_release_id
        and evolution.species_key = v_instance.species_key
        and evolution.target_species_key = v_target_species_key
        and evolution.trigger_key = 'item'
        and coalesce(evolution.trigger_rules -> 'item' ->> 'itemIndex', '') ~ '^[1-9][0-9]*$'
        and (evolution.trigger_rules -> 'item' ->> 'itemIndex')::integer = p_item_index
    ) then
      raise exception 'selected evolution target is not valid for this Pokemon and item' using errcode = '22023';
    end if;
    if (select count(*)
      from public.player_pokemon_placement placement
      join public.player_pokemon_instance pokemon on pokemon.id = placement.pokemon_instance_id
      where placement.auth_user_id = v_auth_user_id and placement.placement_type = 'team'
        and pokemon.id <> p_pokemon_instance_id
        and pokemon.species_key = v_target_species_key) >= 2 then
      raise exception 'resulting team cannot contain more than two Pokemon of the same species' using errcode = '22023';
    end if;
    if v_inventory.quantity = 1 then
      delete from public.player_inventory_item where auth_user_id = v_auth_user_id and item_index = p_item_index;
    else
      update public.player_inventory_item set quantity = quantity - 1, updated_at = now()
      where auth_user_id = v_auth_user_id and item_index = p_item_index;
    end if;
    v_instance.species_key := v_target_species_key;
    v_instance.state := jsonb_set(v_instance.state, '{s}', to_jsonb(v_target_species_key), true);
    insert into public.player_dex_entry(auth_user_id, catalog_release_id, species_key)
    values (v_auth_user_id, v_instance.catalog_release_id, v_target_species_key)
    on conflict do nothing;
  end if;

  update public.player_pokemon_instance set
    species_key = v_instance.species_key,
    state = v_instance.state,
    revision = revision + 1,
    updated_at = now()
  where id = p_pokemon_instance_id and auth_user_id = v_auth_user_id;

  update public.player_state_revision set revision = revision + 1, updated_at = now()
  where auth_user_id = v_auth_user_id returning revision into v_current_revision;

  v_result := server_authority_private.player_state_projection(v_auth_user_id) || jsonb_build_object(
    'command_id', p_command_id,
    'command_type', 'pokemon_center_' || p_operation,
    'pokemon_instance_id', p_pokemon_instance_id,
    'item_index', p_item_index,
    'replacement_slot', p_replacement_slot,
    'evolution_target_species_key', v_target_species_key
  );
  insert into public.player_command_receipt(
    auth_user_id, command_id, command_type, request_hash, result, resulting_revision
  ) values (
    v_auth_user_id, p_command_id, 'pokemon_center_' || p_operation,
    v_request_hash, v_result, v_current_revision
  );
  return v_result;
end;
$_$;


