--

CREATE FUNCTION "public"."finalize_expired_edge_capture"("p_auth_user_id" "uuid", "p_battle_id" "uuid" DEFAULT NULL::"uuid", "p_command_id" "uuid" DEFAULT NULL::"uuid", "p_command_type" "text" DEFAULT NULL::"text", "p_command_hash" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
begin
  if coalesce(auth.role(),'')<>'service_role' then
    raise exception 'E richiesto il ruolo di servizio.' using errcode='42501';
  end if;
  return jsonb_build_object('capture_expired',false);
end;
$$;


