--
-- Name: list_edge_admin_gym_battles("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."list_edge_admin_gym_battles"("p_admin_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_result jsonb;
begin
  if coalesce(auth.role(),'')<>'service_role' or not server_authority_private.user_has_server_role(p_admin_user_id,'admin') then
    raise exception 'admin service authority required' using errcode='42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('battle_id',b.id,'auth_user_id',b.auth_user_id,
    'player_username',coalesce(r.username,''),'battle_type',case
      when b.contract_key='debug_training' then 'training_debug'
      when b.contract_key='league' then case when b.league_member_index=4 then 'kanto_league_champion' else 'kanto_league_'||(b.league_member_index+1)::text end
      else 'gym_'||b.gym_key end,'contract_key',b.contract_key,'league_member_index',b.league_member_index,
    'waiting_for',b.waiting_for,'status',b.status,'battle_version',b.battle_version,'created_at',b.created_at) order by b.created_at),'[]'::jsonb)
    into v_result from public.authoritative_battle b left join public.player_auth_recovery r on r.auth_user_id=b.auth_user_id
    where b.contract_key in ('admin_gym','league','debug_training') and b.status in ('active','needs_player_switch');
  return v_result;
end;
$$;


ALTER FUNCTION "public"."list_edge_admin_gym_battles"("p_admin_user_id" "uuid") OWNER TO "postgres";

--
-- Name: list_global_activity_feed(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."list_global_activity_feed"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'ok', true,
    'events', coalesce(jsonb_agg(jsonb_build_object(
      'id', feed.id,
      'player_username', feed.player_username,
      'event_type', feed.event_type,
      'subject_name', feed.subject_name,
      'secondary_subject_name', feed.secondary_subject_name
    ) order by feed.created_at desc, feed.id desc), '[]'::jsonb)
  )
  from (
    select id, player_username, event_type, subject_name, secondary_subject_name, created_at
    from public.global_activity_feed
    order by created_at desc, id desc limit 10
  ) feed;
$$;


