begin
  v_conflict:=server_authority_private.player_command_revision_conflict(p_command_id,p_expected_revision);
  if v_conflict is not null then return v_conflict; end if;
  begin
    return public.move_box_pokemon_to_team_before_revision_guard(
      p_command_id,p_expected_revision,p_pokemon_instance_id,p_target_slot
    );
  exception when serialization_failure then
    v_conflict:=server_authority_private.player_command_revision_conflict(p_command_id,p_expected_revision);
    if v_conflict is not null then return v_conflict; end if;
    raise;
  end;
end;
$$;


