--
-- Name: prepare_edge_admin_gym_battle("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."prepare_edge_admin_gym_battle"("p_admin_user_id" "uuid", "p_battle_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_owner uuid; v_result jsonb; v_username text;
begin
  if coalesce(auth.role(),'')<>'service_role' or not server_authority_private.user_has_server_role(p_admin_user_id,'admin') then
    raise exception 'admin service authority required' using errcode='42501'; end if;
  select auth_user_id into strict v_owner from public.authoritative_battle where id=p_battle_id
    and contract_key in ('admin_gym','league','debug_training');
  v_result:=server_authority_private.prepare_edge_battle_command_core(v_owner,p_battle_id);
  select username into v_username from public.player_auth_recovery where auth_user_id=v_owner;
  v_result:=jsonb_set(v_result,'{battle,auth_user_id}',to_jsonb(v_owner),true);
  v_result:=jsonb_set(v_result,'{battle,player_username}',to_jsonb(coalesce(v_username,'')),true);
  return v_result;
end;
$$;


