CREATE FUNCTION "public"."read_edge_battle_tower_terminal_state"("p_auth_user_id" "uuid", "p_battle_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_battle public.authoritative_battle%rowtype; v_run public.authoritative_battle_tower_run%rowtype;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'service role required' using errcode='42501'; end if;
  select * into strict v_battle from public.authoritative_battle where id=p_battle_id and auth_user_id=p_auth_user_id
    and contract_key='battle_tower' and status in ('concluded','abandoned');
  select * into strict v_run from public.authoritative_battle_tower_run where id=v_battle.tower_run_id;
  return jsonb_build_object('tower_run',jsonb_build_object('run_id',v_run.id,'wins',v_run.wins,'next_challenge',v_run.next_challenge,
    'status',v_run.status,'battle_points',v_run.reward_battle_points),
    'tower_reward',case when v_run.reward_claimed then jsonb_build_object('battle_points',v_run.reward_battle_points,'wins',v_run.wins) else null end,
    'player_state',server_authority_private.player_state_projection(p_auth_user_id));
end;
$$;


