--
-- Name: read_edge_capture_terminal_state("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."read_edge_capture_terminal_state"("p_auth_user_id" "uuid", "p_battle_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_battle public.authoritative_battle%rowtype; v_place text;
begin
  if coalesce(auth.role(),'')<>'service_role' then
    raise exception 'E richiesto il ruolo di servizio.' using errcode='42501';
  end if;
  select * into v_battle from public.authoritative_battle where id=p_battle_id and auth_user_id=p_auth_user_id;
  if not found or v_battle.contract_key<>'capture' or v_battle.status not in ('concluded','abandoned') then
    raise exception 'La battaglia di cattura conclusa non e stata trovata.' using errcode='P0002';
  end if;
  select p.placement_type into v_place from public.player_encounter e join public.player_pokemon_placement p
    on p.pokemon_instance_id=e.captured_pokemon_instance_id and p.auth_user_id=e.auth_user_id where e.id=v_battle.encounter_id;
  return jsonb_build_object('capture_success',v_battle.result_key='pokemon_captured',
    'result_key',v_battle.result_key,'placement',v_place,
    'player_state',server_authority_private.player_state_projection(p_auth_user_id));
end;
$$;


