--
-- Name: reject_immutable_catalog_content(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."reject_immutable_catalog_content"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_status text;
begin
  if tg_op <> 'INSERT' then
    select status into v_status from public.catalog_release where id = old.catalog_release_id;
    if v_status in ('published', 'retired') then
      raise exception 'catalog release content is immutable: %', old.catalog_release_id;
    end if;
  end if;
  if tg_op <> 'DELETE' then
    select status into v_status from public.catalog_release where id = new.catalog_release_id;
    if v_status in ('published', 'retired') then
      raise exception 'catalog release content is immutable: %', new.catalog_release_id;
    end if;
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."reject_immutable_catalog_content"() OWNER TO "postgres";

--
-- Name: release_box_pokemon_authoritative("uuid", bigint, "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."release_box_pokemon_authoritative"("p_command_id" "uuid", "p_expected_revision" bigint, "p_pokemon_instance_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_conflict jsonb;
begin
  v_conflict:=server_authority_private.player_command_revision_conflict(p_command_id,p_expected_revision);
  if v_conflict is not null then return v_conflict; end if;
  begin
    return public.release_box_pokemon_before_revision_guard(p_command_id,p_expected_revision,p_pokemon_instance_id);
  exception when serialization_failure then
    v_conflict:=server_authority_private.player_command_revision_conflict(p_command_id,p_expected_revision);
    if v_conflict is not null then return v_conflict; end if;
    raise;
  end;
end;
$$;


