--
-- Name: replay_edge_admin_gym_command("uuid", "uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."replay_edge_admin_gym_command"("p_admin_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_receipt public.authoritative_admin_gym_command_receipt%rowtype;
begin
  if coalesce(auth.role(), '') <> 'service_role'
    or not server_authority_private.user_has_server_role(p_admin_user_id, 'admin') then
    raise exception 'admin service authority required' using errcode = '42501';
  end if;
  select * into v_receipt from public.authoritative_admin_gym_command_receipt
    where admin_auth_user_id = p_admin_user_id and command_id = p_command_id;
  if not found then return null; end if;
  if v_receipt.command_type <> p_command_type or v_receipt.command_hash <> p_command_hash then
    raise exception 'admin command id was reused with a different payload' using errcode = '22023';
  end if;
  return v_receipt.result;
end;
$$;


ALTER FUNCTION "public"."replay_edge_admin_gym_command"("p_admin_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text") OWNER TO "postgres";

--
-- Name: replay_edge_battle_command("uuid", "uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."replay_edge_battle_command"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_receipt public.authoritative_battle_command_receipt%rowtype;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'service role required' using errcode = '42501';
  end if;
  select * into v_receipt
  from public.authoritative_battle_command_receipt
  where auth_user_id = p_auth_user_id and command_id = p_command_id;
  if not found then
    return null;
  end if;
  if v_receipt.command_type <> p_command_type or v_receipt.command_hash <> p_command_hash then
    raise exception 'command id was already used with a different payload' using errcode = '22023';
  end if;
  return v_receipt.result;
end;
$$;


ALTER FUNCTION "public"."replay_edge_battle_command"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text") OWNER TO "postgres";

--
-- Name: require_complete_catalog_chunks_for_manifest(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."require_complete_catalog_chunks_for_manifest"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_loaded integer;
  v_total integer;
  v_total_variants integer;
  v_checksum_variants integer;
begin
  select count(*)::integer,
         max(chunk_total),
         count(distinct chunk_total)::integer,
         count(distinct source_set_checksum)::integer
  into v_loaded, v_total, v_total_variants, v_checksum_variants
  from public.catalog_import_chunk
  where catalog_release_id = new.catalog_release_id
    and family_key = new.family_key;

  if v_loaded > 0 and (
    v_total_variants <> 1
    or v_checksum_variants <> 1
    or v_loaded <> v_total
  ) then
    raise exception 'catalog family chunk import is incomplete: % (%/% chunks)', new.family_key, v_loaded, v_total;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."require_complete_catalog_chunks_for_manifest"() OWNER TO "postgres";

--
-- Name: resolve_daycare_withdrawal_authoritative("uuid", bigint, "uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."resolve_daycare_withdrawal_authoritative"("p_command_id" "uuid", "p_expected_revision" bigint, "p_pending_resolution_id" "uuid", "p_choices" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_conflict jsonb;
begin
  v_conflict:=server_authority_private.player_command_revision_conflict(p_command_id,p_expected_revision);
  if v_conflict is not null then return v_conflict; end if;
  begin
    return public.resolve_daycare_withdrawal_before_revision_guard(
      p_command_id,p_expected_revision,p_pending_resolution_id,p_choices
    );
  exception when serialization_failure then
    v_conflict:=server_authority_private.player_command_revision_conflict(p_command_id,p_expected_revision);
    if v_conflict is not null then return v_conflict; end if;
    raise;
  end;
end;
$$;


ALTER FUNCTION "public"."resolve_daycare_withdrawal_authoritative"("p_command_id" "uuid", "p_expected_revision" bigint, "p_pending_resolution_id" "uuid", "p_choices" "jsonb") OWNER TO "postgres";

