--
-- Name: authoritative_battle_append_event("uuid", "text", "jsonb", "uuid", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."authoritative_battle_append_event"("p_battle_id" "uuid", "p_event_type" "text", "p_event_data" "jsonb", "p_command_id" "uuid" DEFAULT NULL::"uuid", "p_rng_audit" "jsonb" DEFAULT '[]'::"jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
begin
  return server_authority_private.authoritative_battle_append_event_before_ordinary_terminal_metadata(
    p_battle_id,p_event_type,p_event_data,
    case when p_event_type in ('battle_money_penalty','ordinary_exp_awarded') then null else p_command_id end,
    p_rng_audit);
end;
$$;


ALTER FUNCTION "server_authority_private"."authoritative_battle_append_event"("p_battle_id" "uuid", "p_event_type" "text", "p_event_data" "jsonb", "p_command_id" "uuid", "p_rng_audit" "jsonb") OWNER TO "postgres";

--
-- Name: authoritative_battle_append_event_before_ordinary_terminal_meta("uuid", "text", "jsonb", "uuid", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."authoritative_battle_append_event_before_ordinary_terminal_meta"("p_battle_id" "uuid", "p_event_type" "text", "p_event_data" "jsonb", "p_command_id" "uuid" DEFAULT NULL::"uuid", "p_rng_audit" "jsonb" DEFAULT '[]'::"jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_data jsonb:=p_event_data; v_contract text;
begin
  if p_event_type in ('battle_started','engine_initialized') or coalesce(p_event_data?'reward_status',false) then
    select contract_key into v_contract from public.authoritative_battle where id=p_battle_id;
    v_data:=coalesce(v_data,'{}'::jsonb)||jsonb_build_object(
      'reward_status',server_authority_private.authoritative_battle_reward_status(v_contract));
  end if;
  return server_authority_private.authoritative_battle_append_event_before_reward_status(
    p_battle_id,p_event_type,v_data,p_command_id,p_rng_audit);
end;
$$;


ALTER FUNCTION "server_authority_private"."authoritative_battle_append_event_before_ordinary_terminal_meta"("p_battle_id" "uuid", "p_event_type" "text", "p_event_data" "jsonb", "p_command_id" "uuid", "p_rng_audit" "jsonb") OWNER TO "postgres";

--
-- Name: authoritative_battle_append_event_before_reward_status("uuid", "text", "jsonb", "uuid", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."authoritative_battle_append_event_before_reward_status"("p_battle_id" "uuid", "p_event_type" "text", "p_event_data" "jsonb", "p_command_id" "uuid" DEFAULT NULL::"uuid", "p_rng_audit" "jsonb" DEFAULT '[]'::"jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare
  v_seq bigint;
  v_version bigint;
begin
  update public.authoritative_battle
  set next_event_seq = next_event_seq + 1
  where id = p_battle_id
  returning next_event_seq - 1, battle_version into v_seq, v_version;
  if not found then
    raise exception 'authoritative battle does not exist' using errcode = 'P0002';
  end if;
  insert into public.authoritative_battle_event (
    battle_id, seq, battle_version, event_type, event_data, command_id, rng_audit
  ) values (
    p_battle_id, v_seq, v_version, p_event_type, coalesce(p_event_data, '{}'::jsonb),
    p_command_id, coalesce(p_rng_audit, '[]'::jsonb)
  );
  return v_seq;
end;
$$;


ALTER FUNCTION "server_authority_private"."authoritative_battle_append_event_before_reward_status"("p_battle_id" "uuid", "p_event_type" "text", "p_event_data" "jsonb", "p_command_id" "uuid", "p_rng_audit" "jsonb") OWNER TO "postgres";

--
-- Name: authoritative_battle_apply_azione("uuid", "text", integer); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."authoritative_battle_apply_azione"("p_battle_id" "uuid", "p_attacker_side" "text", "p_move_slot" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare
  v_battle public.authoritative_battle%rowtype;
  v_attacker public.authoritative_battle_participant%rowtype;
  v_defender public.authoritative_battle_participant%rowtype;
  v_move jsonb;
  v_multiplier numeric;
  v_damage integer;
  v_hp_after integer;
  v_defender_side text := case when p_attacker_side = 'player' then 'npc' else 'player' end;
begin
  if p_attacker_side not in ('player', 'npc') then
    raise exception 'battle action side is invalid' using errcode = '22023';
  end if;
  select * into strict v_battle from public.authoritative_battle where id = p_battle_id;
  select * into strict v_attacker
  from public.authoritative_battle_participant
  where battle_id = p_battle_id and side = p_attacker_side
    and slot_index = case when p_attacker_side = 'player' then v_battle.player_active_slot else v_battle.npc_active_slot end;
  select * into strict v_defender
  from public.authoritative_battle_participant
  where battle_id = p_battle_id and side = v_defender_side
    and slot_index = case when v_defender_side = 'player' then v_battle.player_active_slot else v_battle.npc_active_slot end;

  if v_attacker.current_hp <= 0 or v_defender.current_hp <= 0 then
    raise exception 'a fainted participant cannot resolve an action' using errcode = '22023';
  end if;
  if p_move_slot is null or p_move_slot < 0 or p_move_slot >= jsonb_array_length(v_attacker.moves) then
    raise exception 'move slot is not available' using errcode = '22023';
  end if;
  v_move := v_attacker.moves -> p_move_slot;
  if (v_move ->> 'move_index')::integer <> 25 or v_move ->> 'rules_contract' <> 'simple_damage' then
    raise exception 'move is unsupported by authoritative battle v1' using errcode = '0A000';
  end if;

  -- Engine parity: the attacker's Pokemon types drive effectiveness (not the
  -- move type), there is no STAB, and this slice has no stat/held/weather mods.
  v_multiplier := server_authority_private.authoritative_battle_type_multiplier(
    v_battle.catalog_release_id, v_attacker.type_keys, v_defender.type_keys
  );
  v_damage := greatest(1, floor((v_move ->> 'power')::integer * v_multiplier)::integer);
  v_hp_after := greatest(0, v_defender.current_hp - v_damage);
  update public.authoritative_battle_participant
  set current_hp = v_hp_after
  where battle_id = p_battle_id and side = v_defender.side and slot_index = v_defender.slot_index;

  perform server_authority_private.authoritative_battle_append_event(
    p_battle_id,
    'move_resolved',
    jsonb_build_object(
      'turn_number', v_battle.turn_number,
      'attacker_side', p_attacker_side,
      'attacker_slot', v_attacker.slot_index,
      'defender_side', v_defender.side,
      'defender_slot', v_defender.slot_index,
      'move_slot', p_move_slot,
      'move_index', 25,
      'move_name', 'Azione',
      'power', (v_move ->> 'power')::integer,
      'attacker_types', v_attacker.type_keys,
      'type_multiplier', v_multiplier,
      'damage', v_damage,
      'hp_before', v_defender.current_hp,
      'hp_after', v_hp_after,
      'ko', v_hp_after = 0
    )
  );
  return jsonb_build_object('defender_side', v_defender.side, 'defender_slot', v_defender.slot_index,
    'damage', v_damage, 'hp_after', v_hp_after, 'ko', v_hp_after = 0);
end;
$$;


ALTER FUNCTION "server_authority_private"."authoritative_battle_apply_azione"("p_battle_id" "uuid", "p_attacker_side" "text", "p_move_slot" integer) OWNER TO "postgres";

--
-- Name: authoritative_battle_projection("uuid", "uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."authoritative_battle_projection"("p_auth_user_id" "uuid", "p_battle_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_result jsonb;
begin
  v_result:=server_authority_private.authoritative_battle_projection_before_reward_status(p_auth_user_id,p_battle_id);
  if v_result is null then return null; end if;
  return jsonb_set(v_result,'{reward_status}',to_jsonb(server_authority_private.authoritative_battle_reward_status(
    v_result->>'contract_key')),true);
end;
$$;


ALTER FUNCTION "server_authority_private"."authoritative_battle_projection"("p_auth_user_id" "uuid", "p_battle_id" "uuid") OWNER TO "postgres";

--
-- Name: authoritative_battle_projection_before_reward_status("uuid", "uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."authoritative_battle_projection_before_reward_status"("p_auth_user_id" "uuid", "p_battle_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
  with selected as (
    select battle.*
    from public.authoritative_battle battle
    where battle.auth_user_id = p_auth_user_id
      and (p_battle_id is null or battle.id = p_battle_id)
    order by
      case when battle.status in ('active', 'needs_player_switch') then 0 else 1 end,
      battle.created_at desc
    limit 1
  )
  select case when not exists (select 1 from selected) then null else (
    select jsonb_build_object(
      'mode', 'authoritative',
      'battle_id', battle.id,
      'contract_key', battle.contract_key,
      'catalog_release_id', battle.catalog_release_id,
      'status', battle.status,
      'result_key', battle.result_key,
      'reward_status', 'disabled_first_slice',
      'turn_number', battle.turn_number,
      'first_actor', battle.first_actor,
      'player_active_slot', battle.player_active_slot,
      'npc_active_slot', battle.npc_active_slot,
      'battle_version', battle.battle_version,
      'runtime_owner_id', battle.runtime_owner_id,
      'runtime_lock_version', battle.runtime_lock_version,
      'rng_state', battle.rng_state,
      'created_at', battle.created_at,
      'updated_at', battle.updated_at,
      'concluded_at', battle.concluded_at,
      'participants', coalesce((
        select jsonb_agg(jsonb_build_object(
          'side', participant.side,
          'slot_index', participant.slot_index,
          'pokemon_instance_id', participant.pokemon_instance_id,
          'species_key', participant.species_key,
          'display_name', participant.display_name,
          'level', participant.level,
          'max_hp', participant.max_hp,
          'current_hp', participant.current_hp,
          'type_keys', participant.type_keys,
          'moves', participant.moves
        ) order by case participant.side when 'player' then 0 else 1 end, participant.slot_index)
        from public.authoritative_battle_participant participant
        where participant.battle_id = battle.id
      ), '[]'::jsonb),
      'events', coalesce((
        select jsonb_agg(jsonb_build_object(
          'seq', event.seq,
          'battle_version', event.battle_version,
          'event_type', event.event_type,
          'event_data', event.event_data,
          'command_id', event.command_id,
          'rng_audit', event.rng_audit,
          'created_at', event.created_at
        ) order by event.seq)
        from public.authoritative_battle_event event
        where event.battle_id = battle.id
      ), '[]'::jsonb)
    )
    from selected battle
  ) end;
$$;


ALTER FUNCTION "server_authority_private"."authoritative_battle_projection_before_reward_status"("p_auth_user_id" "uuid", "p_battle_id" "uuid") OWNER TO "postgres";

--
-- Name: authoritative_battle_reward_status("text"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."authoritative_battle_reward_status"("p_contract_key" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
  select case p_contract_key
    when 'training' then 'training_authoritative'
    when 'debug_training' then 'none'
    when 'gym' then 'gym_authoritative'
    when 'admin_gym' then 'gym_authoritative'
    when 'league' then 'league_authoritative'
    when 'capture' then 'capture_authoritative'
    else 'none'
  end
$$;


ALTER FUNCTION "server_authority_private"."authoritative_battle_reward_status"("p_contract_key" "text") OWNER TO "postgres";

--
-- Name: authoritative_battle_type_multiplier("uuid", "jsonb", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."authoritative_battle_type_multiplier"("p_catalog_release_id" "uuid", "p_attacker_types" "jsonb", "p_defender_types" "jsonb") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare
  v_attacker_type text;
  v_defender_type text;
  v_multiplier numeric := 1.0;
  v_pair_multiplier numeric;
begin
  for v_attacker_type in select jsonb_array_elements_text(p_attacker_types) loop
    for v_defender_type in select jsonb_array_elements_text(p_defender_types) loop
      select effectiveness.multiplier into v_pair_multiplier
      from public.catalog_type_effectiveness effectiveness
      where effectiveness.catalog_release_id = p_catalog_release_id
        and effectiveness.attacker_type_key = v_attacker_type
        and effectiveness.defender_type_key = v_defender_type;
      v_multiplier := v_multiplier * coalesce(v_pair_multiplier, 1.0);
    end loop;
  end loop;
  if v_multiplier > 1 then return 2.0; end if;
  if v_multiplier < 1 then return 0.5; end if;
  return 1.0;
end;
$$;


ALTER FUNCTION "server_authority_private"."authoritative_battle_type_multiplier"("p_catalog_release_id" "uuid", "p_attacker_types" "jsonb", "p_defender_types" "jsonb") OWNER TO "postgres";

--
-- Name: award_terminal_admin_gym_victory("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."award_terminal_admin_gym_victory"("p_auth_user_id" "uuid", "p_battle_id" "uuid", "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare
  v_battle public.authoritative_battle%rowtype;
  v_profile public.player_profile_state%rowtype;
  v_opponent public.catalog_opponent%rowtype;
  v_existing public.player_gym_victory%rowtype;
  v_receipt public.player_command_receipt%rowtype;
  v_reward jsonb;
  v_items jsonb;
  v_item record;
  v_money bigint;
  v_badge_index integer;
  v_revision bigint;
  v_hash text;
  v_result jsonb;
  v_ordinal integer := 3;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'service role required' using errcode = '42501';
  end if;
  select * into strict v_battle from public.authoritative_battle
    where id = p_battle_id and auth_user_id = p_auth_user_id for update;
  if v_battle.contract_key <> 'admin_gym' or v_battle.status <> 'concluded'
    or v_battle.result_key <> 'player_win_no_reward' then return null; end if;
  select * into v_existing from public.player_gym_victory where battle_id = p_battle_id;
  if found then
    return jsonb_build_object('gym_reward', v_existing.reward,
      'player_state', server_authority_private.player_state_projection(p_auth_user_id));
  end if;
  select * into strict v_opponent from public.catalog_opponent
    where catalog_release_id = v_battle.catalog_release_id
      and opponent_key = 'gym_' || v_battle.gym_key for share;
  select * into strict v_profile from public.player_profile_state
    where auth_user_id = p_auth_user_id for update;
  if v_opponent.opponent_kind <> 'gym' or v_opponent.badge_index <> v_profile.badges then
    raise exception 'gym victory no longer matches canonical badge progression' using errcode = '40001';
  end if;
  if (select count(*) from public.catalog_opponent_reward
      where catalog_release_id = v_battle.catalog_release_id and opponent_key = v_opponent.opponent_key) <> 4
    or (select count(*) from public.catalog_opponent_reward
      where catalog_release_id = v_battle.catalog_release_id and opponent_key = v_opponent.opponent_key
        and reward_kind = 'money' and quantity > 0 and item_index is null) <> 1
    or (select count(*) from public.catalog_opponent_reward
      where catalog_release_id = v_battle.catalog_release_id and opponent_key = v_opponent.opponent_key
        and reward_kind = 'item' and quantity = 1 and item_index is not null) <> 2
    or (select count(*) from public.catalog_opponent_reward
      where catalog_release_id = v_battle.catalog_release_id and opponent_key = v_opponent.opponent_key
        and reward_kind = 'badge' and quantity = 1 and item_index is null
        and (rules ->> 'badgeIndex')::integer = v_opponent.badge_index) <> 1 then
    raise exception 'canonical gym reward shape is unsupported' using errcode = '0A000';
  end if;
  select quantity::bigint into strict v_money from public.catalog_opponent_reward
    where catalog_release_id = v_battle.catalog_release_id and opponent_key = v_opponent.opponent_key
      and reward_kind = 'money';
  v_badge_index := v_opponent.badge_index;
  select jsonb_agg(jsonb_build_object('itemIndex', item_index, 'quantity', quantity)
    order by reward_order) into v_items from public.catalog_opponent_reward
    where catalog_release_id = v_battle.catalog_release_id and opponent_key = v_opponent.opponent_key
      and reward_kind = 'item';
  v_reward := jsonb_build_object('rewardKind', 'gym', 'gymKey', v_battle.gym_key,
    'opponentKey', v_opponent.opponent_key, 'badgeIndex', v_badge_index,
    'money', v_money, 'items', coalesce(v_items, '[]'::jsonb), 'already', false);

  update public.player_profile_state set pokedollars = pokedollars + v_money,
    badges = badges + 1, updated_at = now() where auth_user_id = p_auth_user_id;
  for v_item in select item_index, quantity from public.catalog_opponent_reward
    where catalog_release_id = v_battle.catalog_release_id and opponent_key = v_opponent.opponent_key
      and reward_kind = 'item' order by reward_order
  loop
    insert into public.player_inventory_item(auth_user_id, catalog_release_id, item_index, quantity, updated_at)
    values(p_auth_user_id, v_battle.catalog_release_id, v_item.item_index, v_item.quantity, now())
    on conflict (auth_user_id, item_index) do update
      set quantity = public.player_inventory_item.quantity + excluded.quantity, updated_at = now();
  end loop;
  insert into public.player_gym_victory(auth_user_id, opponent_key, battle_id,
    catalog_release_id, badge_index, terminal_command_id, reward)
  values(p_auth_user_id, v_opponent.opponent_key, p_battle_id,
    v_battle.catalog_release_id, v_badge_index, p_command_id, v_reward);
  update public.player_state_revision set revision = revision + 1, updated_at = now()
    where auth_user_id = p_auth_user_id returning revision into v_revision;
  v_result := server_authority_private.player_state_projection(p_auth_user_id)
    || jsonb_build_object('command_id', p_command_id, 'command_type', 'gym_terminal_reward',
      'battle_id', p_battle_id, 'gym_reward', v_reward);
  v_hash := encode(digest(convert_to(jsonb_build_object('battle_id', p_battle_id,
    'result_key', v_battle.result_key, 'opponent_key', v_opponent.opponent_key)::text, 'UTF8'), 'sha256'), 'hex');
  insert into public.player_command_receipt(auth_user_id, command_id, command_type,
    request_hash, result, resulting_revision)
  values(p_auth_user_id, p_command_id, 'gym_terminal_reward', v_hash, v_result, v_revision)
  returning * into v_receipt;
  perform server_authority_private.authoritative_battle_append_event(p_battle_id, 'gym_reward_awarded',
    v_reward, null, '[]'::jsonb);
  v_result := jsonb_build_object('gym_reward', v_reward,
    'player_state', server_authority_private.player_state_projection(p_auth_user_id));
  update public.player_command_receipt set result = result || v_result
    where auth_user_id = p_auth_user_id and command_id = p_command_id;
  return v_result;
end;
$$;


ALTER FUNCTION "server_authority_private"."award_terminal_admin_gym_victory"("p_auth_user_id" "uuid", "p_battle_id" "uuid", "p_command_id" "uuid") OWNER TO "postgres";

--
-- Name: award_terminal_gym_victory("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."award_terminal_gym_victory"("p_auth_user_id" "uuid", "p_battle_id" "uuid", "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare
  v_battle public.authoritative_battle%rowtype;
  v_profile public.player_profile_state%rowtype;
  v_opponent public.catalog_opponent%rowtype;
  v_existing public.player_gym_victory%rowtype;
  v_receipt public.player_command_receipt%rowtype;
  v_reward jsonb;
  v_items jsonb;
  v_item record;
  v_money bigint;
  v_badge_index integer;
  v_revision bigint;
  v_hash text;
  v_result jsonb;
  v_ordinal integer := 3;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'service role required' using errcode = '42501';
  end if;
  select * into strict v_battle from public.authoritative_battle
    where id = p_battle_id and auth_user_id = p_auth_user_id for update;
  if v_battle.contract_key <> 'gym' or v_battle.status <> 'concluded'
    or v_battle.result_key <> 'player_win_no_reward' then return null; end if;
  select * into v_existing from public.player_gym_victory where battle_id = p_battle_id;
  if found then
    return jsonb_build_object('gym_reward', v_existing.reward,
      'player_state', server_authority_private.player_state_projection(p_auth_user_id));
  end if;
  select * into strict v_opponent from public.catalog_opponent
    where catalog_release_id = v_battle.catalog_release_id
      and opponent_key = 'gym_' || v_battle.gym_key for share;
  select * into strict v_profile from public.player_profile_state
    where auth_user_id = p_auth_user_id for update;
  if v_opponent.opponent_kind <> 'gym' or v_opponent.badge_index <> v_profile.badges then
    raise exception 'gym victory no longer matches canonical badge progression' using errcode = '40001';
  end if;
  if (select count(*) from public.catalog_opponent_reward
      where catalog_release_id = v_battle.catalog_release_id and opponent_key = v_opponent.opponent_key) <> 4
    or (select count(*) from public.catalog_opponent_reward
      where catalog_release_id = v_battle.catalog_release_id and opponent_key = v_opponent.opponent_key
        and reward_kind = 'money' and quantity > 0 and item_index is null) <> 1
    or (select count(*) from public.catalog_opponent_reward
      where catalog_release_id = v_battle.catalog_release_id and opponent_key = v_opponent.opponent_key
        and reward_kind = 'item' and quantity = 1 and item_index is not null) <> 2
    or (select count(*) from public.catalog_opponent_reward
      where catalog_release_id = v_battle.catalog_release_id and opponent_key = v_opponent.opponent_key
        and reward_kind = 'badge' and quantity = 1 and item_index is null
        and (rules ->> 'badgeIndex')::integer = v_opponent.badge_index) <> 1 then
    raise exception 'canonical gym reward shape is unsupported' using errcode = '0A000';
  end if;
  select quantity::bigint into strict v_money from public.catalog_opponent_reward
    where catalog_release_id = v_battle.catalog_release_id and opponent_key = v_opponent.opponent_key
      and reward_kind = 'money';
  v_badge_index := v_opponent.badge_index;
  select jsonb_agg(jsonb_build_object('itemIndex', item_index, 'quantity', quantity)
    order by reward_order) into v_items from public.catalog_opponent_reward
    where catalog_release_id = v_battle.catalog_release_id and opponent_key = v_opponent.opponent_key
      and reward_kind = 'item';
  v_reward := jsonb_build_object('rewardKind', 'gym', 'gymKey', v_battle.gym_key,
    'opponentKey', v_opponent.opponent_key, 'badgeIndex', v_badge_index,
    'money', v_money, 'items', coalesce(v_items, '[]'::jsonb), 'already', false);

  update public.player_profile_state set pokedollars = pokedollars + v_money,
    badges = badges + 1, updated_at = now() where auth_user_id = p_auth_user_id;
  for v_item in select item_index, quantity from public.catalog_opponent_reward
    where catalog_release_id = v_battle.catalog_release_id and opponent_key = v_opponent.opponent_key
      and reward_kind = 'item' order by reward_order
  loop
    insert into public.player_inventory_item(auth_user_id, catalog_release_id, item_index, quantity, updated_at)
    values(p_auth_user_id, v_battle.catalog_release_id, v_item.item_index, v_item.quantity, now())
    on conflict (auth_user_id, item_index) do update
      set quantity = public.player_inventory_item.quantity + excluded.quantity, updated_at = now();
  end loop;
  insert into public.player_gym_victory(auth_user_id, opponent_key, battle_id,
    catalog_release_id, badge_index, terminal_command_id, reward)
  values(p_auth_user_id, v_opponent.opponent_key, p_battle_id,
    v_battle.catalog_release_id, v_badge_index, p_command_id, v_reward);
  update public.player_state_revision set revision = revision + 1, updated_at = now()
    where auth_user_id = p_auth_user_id returning revision into v_revision;
  v_result := server_authority_private.player_state_projection(p_auth_user_id)
    || jsonb_build_object('command_id', p_command_id, 'command_type', 'gym_terminal_reward',
      'battle_id', p_battle_id, 'gym_reward', v_reward);
  v_hash := encode(digest(convert_to(jsonb_build_object('battle_id', p_battle_id,
    'result_key', v_battle.result_key, 'opponent_key', v_opponent.opponent_key)::text, 'UTF8'), 'sha256'), 'hex');
  insert into public.player_command_receipt(auth_user_id, command_id, command_type,
    request_hash, result, resulting_revision)
  values(p_auth_user_id, p_command_id, 'gym_terminal_reward', v_hash, v_result, v_revision)
  returning * into v_receipt;
  perform server_authority_private.authoritative_battle_append_event(p_battle_id, 'gym_reward_awarded',
    v_reward, null, '[]'::jsonb);
  v_result := jsonb_build_object('gym_reward', v_reward,
    'player_state', server_authority_private.player_state_projection(p_auth_user_id));
  update public.player_command_receipt set result = result || v_result
    where auth_user_id = p_auth_user_id and command_id = p_command_id;
  return v_result;
end;
$$;


ALTER FUNCTION "server_authority_private"."award_terminal_gym_victory"("p_auth_user_id" "uuid", "p_battle_id" "uuid", "p_command_id" "uuid") OWNER TO "postgres";

--
-- Name: award_terminal_training_progression("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."award_terminal_training_progression"("p_auth_user_id" "uuid", "p_battle_id" "uuid", "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare
  v_battle public.authoritative_battle%rowtype;
  v_profile public.player_profile_state%rowtype;
  v_rule public.catalog_training_reward_rule%rowtype;
  v_progression public.player_training_progression%rowtype;
  v_revision bigint;
  v_today date := (statement_timestamp() at time zone 'Europe/Rome')::date;
  v_daily boolean;
  v_battle_points integer;
  v_levels integer;
  v_capacity integer;
  v_result jsonb;
  v_hash text;
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'service role required' using errcode = '42501'; end if;
  select * into strict v_battle from public.authoritative_battle
    where id = p_battle_id and auth_user_id = p_auth_user_id for update;
  if v_battle.contract_key <> 'training' or v_battle.status <> 'concluded'
    or v_battle.result_key <> 'player_win_no_reward' then return null; end if;
  select * into v_progression from public.player_training_progression where battle_id = p_battle_id;
  if found then return server_authority_private.player_state_projection(p_auth_user_id); end if;
  if exists (select 1 from public.player_training_progression
    where auth_user_id = p_auth_user_id and status <> 'completed') then
    raise exception 'another training progression is pending' using errcode = '55000';
  end if;
  select * into strict v_profile from public.player_profile_state
    where auth_user_id = p_auth_user_id for update;
  select * into strict v_rule from public.catalog_training_reward_rule
    where catalog_release_id = v_battle.catalog_release_id
      and badge_count = least(8, greatest(0, v_profile.badges))
      and difficulty = v_battle.training_difficulty;
  perform 1 from public.player_training_daily_claim
    where auth_user_id = p_auth_user_id and difficulty = v_battle.training_difficulty for update;
  v_daily := not exists (select 1 from public.player_training_daily_claim
    where auth_user_id = p_auth_user_id and difficulty = v_battle.training_difficulty
      and last_claimed_day = v_today);
  -- Published catalogs predating this migration retain money rows. The fallback
  -- keeps their in-flight battles on the new fixed reward contract until the
  -- staged catalog cutover binds the dedicated Battle Point columns.
  if v_rule.daily_money > 0 then
    v_battle_points := case v_battle.training_difficulty when 'easy' then 1 when 'medium' then 2 else 3 end;
    v_levels := case when v_daily then case v_battle.training_difficulty when 'easy' then 4 when 'medium' then 8 else 12 end
      else case v_battle.training_difficulty when 'easy' then 1 when 'medium' then 2 else 3 end end;
  else
    v_battle_points := case when v_daily then v_rule.daily_battle_points else v_rule.repeat_battle_points end;
    v_levels := case when v_daily then v_rule.daily_levels else v_rule.repeat_levels end;
  end if;
  if v_daily then
    insert into public.player_training_daily_claim(auth_user_id, difficulty, last_claimed_day, last_claimed_at)
    values (p_auth_user_id, v_battle.training_difficulty, v_today, statement_timestamp())
    on conflict (auth_user_id, difficulty) do update
      set last_claimed_day = excluded.last_claimed_day, last_claimed_at = excluded.last_claimed_at;
  end if;
  update public.player_profile_state set battle_points = battle_points + v_battle_points, updated_at = now()
    where auth_user_id = p_auth_user_id;
  select coalesce(sum(least(v_rule.max_levels_per_pokemon,
    greatest(0, v_rule.level_cap - (pokemon.state ->> 'l')::integer),
    greatest(0, 100 - (pokemon.state ->> 'l')::integer))), 0)::integer
  into v_capacity
  from public.authoritative_battle_participant participant
  join public.player_pokemon_instance pokemon on pokemon.id = participant.pokemon_instance_id
    and pokemon.auth_user_id = p_auth_user_id
  join public.player_pokemon_placement placement on placement.pokemon_instance_id = pokemon.id
    and placement.auth_user_id = p_auth_user_id and placement.placement_type = 'team'
  where participant.battle_id = p_battle_id and participant.side = 'player';
  insert into public.player_training_progression(
    auth_user_id,battle_id,catalog_release_id,difficulty,reward_kind,money_awarded,battle_points_awarded,
    levels_awarded,assignable_levels,forfeited_levels,max_levels_per_pokemon,
    level_cap,badge_count,status,terminal_command_id,completed_at
  ) values (
    p_auth_user_id,p_battle_id,v_battle.catalog_release_id,v_battle.training_difficulty,
    case when v_daily then 'daily' else 'repeat' end,0,v_battle_points,v_levels,
    least(v_levels,v_capacity),v_levels-least(v_levels,v_capacity),v_rule.max_levels_per_pokemon,
    v_rule.level_cap,least(8,greatest(0,v_profile.badges)),
    case when least(v_levels,v_capacity)=0 then 'completed' else 'awaiting_allocation' end,
    p_command_id,case when least(v_levels,v_capacity)=0 then now() else null end
  ) returning * into v_progression;
  insert into public.player_training_progression_pokemon(
    progression_id,auth_user_id,pokemon_instance_id,team_slot,battle_instance_revision,
    frozen_instance_revision,starting_species_key,starting_level,max_assignable
  ) select v_progression.id,p_auth_user_id,pokemon.id,participant.slot_index,
    coalesce((participant.source_snapshot ->> 'instance_revision')::bigint,0),pokemon.revision,
    pokemon.species_key,(pokemon.state ->> 'l')::integer,
    least(v_rule.max_levels_per_pokemon,greatest(0,v_rule.level_cap-(pokemon.state ->> 'l')::integer),
      greatest(0,100-(pokemon.state ->> 'l')::integer))
  from public.authoritative_battle_participant participant
  join public.player_pokemon_instance pokemon on pokemon.id=participant.pokemon_instance_id
    and pokemon.auth_user_id=p_auth_user_id
  join public.player_pokemon_placement placement on placement.pokemon_instance_id=pokemon.id
    and placement.auth_user_id=p_auth_user_id and placement.placement_type='team'
    and placement.slot_index=participant.slot_index
  where participant.battle_id=p_battle_id and participant.side='player'
  order by participant.slot_index;
  update public.player_state_revision set revision=revision+1,updated_at=now()
    where auth_user_id=p_auth_user_id returning revision into v_revision;
  v_result := server_authority_private.player_state_projection(p_auth_user_id)
    || jsonb_build_object('command_id',p_command_id,'command_type','training_terminal_reward',
      'battle_id',p_battle_id,'training_victory',true,'training_difficulty',v_battle.training_difficulty,
      'training_team_size',(select count(*) from public.authoritative_battle_participant where battle_id=p_battle_id and side='player'),
      'battle_points_awarded',v_battle_points,'levels_awarded',v_levels);
  v_hash := encode(digest(convert_to(jsonb_build_object('battle_id',p_battle_id,'result_key',v_battle.result_key)::text,'UTF8'),'sha256'),'hex');
  insert into public.player_command_receipt(auth_user_id,command_id,command_type,request_hash,result,resulting_revision)
  values(p_auth_user_id,p_command_id,'training_terminal_reward',v_hash,v_result,v_revision);
  perform server_authority_private.authoritative_battle_append_event(p_battle_id,'training_reward_awarded',
    jsonb_build_object('reward_kind',case when v_daily then 'daily' else 'repeat' end,
      'battle_points',v_battle_points,'levels',v_levels,'assignable_levels',least(v_levels,v_capacity),
      'progression_id',v_progression.id),null,'[]'::jsonb);
  v_result := server_authority_private.player_state_projection(p_auth_user_id)
    || (v_result - 'revision' - 'profile' - 'team' - 'box' - 'daycare' - 'pending_resolutions'
      - 'items' - 'dex' - 'starter' - 'shop_purchases' - 'garden' - 'daily_berry'
      - 'flute_daily' - 'active_encounter' - 'missions' - 'training_progression' - 'training_daily');
  update public.player_command_receipt set result=v_result where auth_user_id=p_auth_user_id and command_id=p_command_id;
  return v_result;
end;
$$;


ALTER FUNCTION "server_authority_private"."award_terminal_training_progression"("p_auth_user_id" "uuid", "p_battle_id" "uuid", "p_command_id" "uuid") OWNER TO "postgres";

--
-- Name: battle_shop_offers_projection("uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."battle_shop_offers_projection"("p_auth_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_catalog_release_id uuid; v_badges integer; v_level integer;
begin
  select catalog_release_id,badges into v_catalog_release_id,v_badges
  from public.player_profile_state where auth_user_id=p_auth_user_id;
  if v_catalog_release_id is null then return '[]'::jsonb; end if;
  select (rules->>'level')::integer into v_level from public.catalog_progression_rule
  where catalog_release_id=v_catalog_release_id and rule_family='badge-level-limit'
    and rule_key=least(8,greatest(0,coalesce(v_badges,0)))::text;
  return coalesce((
    select jsonb_agg(row_json order by sort_order,stable_order) from (
      select offer.sort_order,offer.offer_key stable_order,
        jsonb_build_object('offer_key',offer.offer_key,'offer_kind','item','item_index',offer.item_index,
          'battle_point_price',offer.battle_point_price,'eligible',true) row_json
      from public.catalog_battle_shop_offer offer
      where offer.catalog_release_id=v_catalog_release_id and offer.offer_kind='item'
        and coalesce(offer.rules->>'group','') not in ('Bacca a crescita veloce','Bacca a crescita lenta','MT',
          'Strumenti evolutivi','Aromi','Strumenti potenziatore Tipo')
      union all
      select min(offer.sort_order),choice_key,
        jsonb_build_object('offer_key',choice_key,'offer_kind','item_choice',
          'battle_point_price',min(offer.battle_point_price),'eligible',count(*)>0,
          'choices',jsonb_agg(jsonb_build_object('offer_key',offer.offer_key,'item_index',item.item_index)
            order by item.item_index)) row_json
      from (
        select offer.*,case offer.rules->>'group'
          when 'Bacca a crescita veloce' then 'choice-berry-fast'
          when 'Bacca a crescita lenta' then 'choice-berry-slow'
          when 'MT' then 'choice-mt'
          when 'Strumenti evolutivi' then 'choice-evolution'
          when 'Aromi' then 'choice-aroma'
          else 'choice-type-booster' end choice_key,
          offer.rules->>'group' group_name
        from public.catalog_battle_shop_offer offer
        where offer.catalog_release_id=v_catalog_release_id and offer.offer_kind='item'
          and coalesce(offer.rules->>'group','') in ('Bacca a crescita veloce','Bacca a crescita lenta','MT',
            'Strumenti evolutivi','Aromi','Strumenti potenziatore Tipo')
      ) offer
      join public.catalog_item item on item.catalog_release_id=offer.catalog_release_id and item.item_index=offer.item_index
      where offer.group_name<>'MT' or v_badges>=case coalesce((item.rules->>'tier')::integer,3)
        when 0 then 7 when 1 then 6 when 2 then 4 else 0 end
      group by group_name,choice_key
      union all
      select offer.sort_order,offer.offer_key,
        jsonb_build_object('offer_key',offer.offer_key,'offer_kind','pokemon_choice',
          'battle_point_price',offer.battle_point_price,'eligible',true,
          'choices',jsonb_agg(jsonb_build_object('offer_key',offer.offer_key||':'||species.species_key,
            'species_key',species.species_key,'level',v_level) order by species.species_key)) row_json
      from public.catalog_battle_shop_offer offer
      join lateral server_authority_private.battle_shop_pokemon_candidates(
        v_catalog_release_id,offer.offer_key,v_level) candidate on true
      join public.catalog_species species on species.catalog_release_id=v_catalog_release_id
        and species.species_key=candidate.species_key
      where offer.catalog_release_id=v_catalog_release_id and offer.offer_kind='pokemon'
      group by offer.offer_key,offer.sort_order,offer.battle_point_price
    ) offers
  ),'[]'::jsonb);
end;
$$;


ALTER FUNCTION "server_authority_private"."battle_shop_offers_projection"("p_auth_user_id" "uuid") OWNER TO "postgres";

--
-- Name: battle_shop_pokemon_candidates("uuid", "text", integer); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."battle_shop_pokemon_candidates"("p_catalog_release_id" "uuid", "p_pool_key" "text", "p_level" integer) RETURNS TABLE("species_key" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
  with recursive lineage(root_species_key, species_key, minimum_level) as (
    select species.species_key, species.species_key, 5
    from public.catalog_species species where species.catalog_release_id=p_catalog_release_id
    union all
    select lineage.root_species_key, evolution.species_key,
      greatest(lineage.minimum_level, case when evolution.trigger_key='level'
        then coalesce((evolution.trigger_rules->>'level')::integer, 101)
        else coalesce(parent.encounter_min_level, 5) end)
    from lineage
    join public.catalog_species_evolution evolution on evolution.catalog_release_id=p_catalog_release_id
      and evolution.target_species_key=lineage.species_key
    join public.catalog_species parent on parent.catalog_release_id=p_catalog_release_id
      and parent.species_key=evolution.species_key
  ), minimums as (
    select root_species_key, max(minimum_level) as minimum_level from lineage group by root_species_key
  )
  select species.species_key
  from public.catalog_battle_shop_offer offer
  join public.catalog_species species on species.catalog_release_id=offer.catalog_release_id
  join minimums on minimums.root_species_key=species.species_key
  where offer.catalog_release_id=p_catalog_release_id and offer.offer_key=p_pool_key and offer.offer_kind='pokemon'
    and p_level between 5 and 100 and minimums.minimum_level<=p_level
    and species.encounter_rarity_key<>'l'
    and (coalesce((offer.rules->>'excludeFossils')::boolean,false)=false or species.encounter_rarity_key<>'f');
$$;


ALTER FUNCTION "server_authority_private"."battle_shop_pokemon_candidates"("p_catalog_release_id" "uuid", "p_pool_key" "text", "p_level" integer) OWNER TO "postgres";

--
-- Name: capture_battle_inventory("uuid", "uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."capture_battle_inventory"("p_auth_user_id" "uuid", "p_catalog_release_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_array(i.item_index,i.quantity) order by i.item_index),'[]'::jsonb)
  from public.player_inventory_item i join public.catalog_item c
    on c.catalog_release_id=i.catalog_release_id and c.item_index=i.item_index
  where i.auth_user_id=p_auth_user_id and i.catalog_release_id=p_catalog_release_id and i.quantity>0
    and (c.category_key='Ball' or c.category_key='BattleItem'
      or (c.category_key='Berry' and c.item_index between 300 and 308));
$$;


ALTER FUNCTION "server_authority_private"."capture_battle_inventory"("p_auth_user_id" "uuid", "p_catalog_release_id" "uuid") OWNER TO "postgres";

--
-- Name: capture_mission_consumed_item_fact(); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."capture_mission_consumed_item_fact"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare
  v_consumed integer;
begin
  if not exists (select 1 from auth.users where id = old.auth_user_id) then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  v_consumed := old.quantity - case when tg_op = 'DELETE' then 0 else new.quantity end;
  if v_consumed > 0 then
    insert into public.player_mission_pending_item_fact(
      auth_user_id, transaction_id, item_index, consumed_quantity
    ) values (
      old.auth_user_id, txid_current(), old.item_index, v_consumed
    ) on conflict (auth_user_id, transaction_id, item_index) do update
      set consumed_quantity = public.player_mission_pending_item_fact.consumed_quantity + excluded.consumed_quantity;
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "server_authority_private"."capture_mission_consumed_item_fact"() OWNER TO "postgres";

--
-- Name: catalog_base_hp_for_level("uuid", integer); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."catalog_base_hp_for_level"("p_catalog_release_id" "uuid", "p_level" integer) RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
  select coalesce(
    (select rule.base_hp from public.catalog_level_rule rule
      where rule.catalog_release_id = p_catalog_release_id and rule.level = p_level),
    (select rule.base_hp + (p_level - 60) * 3 from public.catalog_level_rule rule
      where p_level > 60 and rule.catalog_release_id = p_catalog_release_id and rule.level = 60)
  )
$$;


ALTER FUNCTION "server_authority_private"."catalog_base_hp_for_level"("p_catalog_release_id" "uuid", "p_level" integer) OWNER TO "postgres";

--
-- Name: catalog_base_power_for_level("uuid", integer); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."catalog_base_power_for_level"("p_catalog_release_id" "uuid", "p_level" integer) RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
  select coalesce(
    (select rule.base_power from public.catalog_level_rule rule
      where rule.catalog_release_id = p_catalog_release_id and rule.level = p_level),
    (select rule.base_power + (p_level - 60) * 2 from public.catalog_level_rule rule
      where p_level > 60 and rule.catalog_release_id = p_catalog_release_id and rule.level = 60)
  )
$$;


ALTER FUNCTION "server_authority_private"."catalog_base_power_for_level"("p_catalog_release_id" "uuid", "p_level" integer) OWNER TO "postgres";

