--
-- Name: cleanup_authoritative_terminal_battles(integer); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."cleanup_authoritative_terminal_battles"("p_batch_limit" integer DEFAULT 500) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare
  v_batch_limit integer := least(greatest(coalesce(p_batch_limit, 500), 1), 500);
  v_deleted_battles integer;
begin
  -- Delete terminal battle roots and the other bounded event families first.
  -- This removes the restrictive battle -> tower-run references before the
  -- terminal run itself is considered.
  v_deleted_battles := server_authority_private.cleanup_authoritative_terminal_battles_core(
    v_batch_limit
  );

  with candidates as (
    select tower_run.id
    from public.authoritative_battle_tower_run tower_run
    where tower_run.status in ('lost', 'abandoned')
      and coalesce(tower_run.concluded_at, tower_run.updated_at, tower_run.created_at)
        < now() - interval '24 hours'
      and not exists (
        select 1
        from public.authoritative_battle battle
        where battle.tower_run_id = tower_run.id
      )
    order by coalesce(tower_run.concluded_at, tower_run.updated_at, tower_run.created_at), tower_run.id
    limit v_batch_limit
    for update of tower_run skip locked
  )
  delete from public.authoritative_battle_tower_run tower_run
  using candidates
  where tower_run.id = candidates.id;

  -- Preserve the historical return contract: callers receive the number of
  -- deleted battle roots. The scheduled job ignores the value.
  return v_deleted_battles;
end;
$$;


ALTER FUNCTION "server_authority_private"."cleanup_authoritative_terminal_battles"("p_batch_limit" integer) OWNER TO "postgres";

--
-- Name: cleanup_authoritative_terminal_battles_core(integer); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."cleanup_authoritative_terminal_battles_core"("p_batch_limit" integer DEFAULT 500) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare
  v_batch_limit integer := least(greatest(coalesce(p_batch_limit, 500), 1), 500);
  v_battle_ids uuid[];
  v_deleted_count integer := 0;
begin
  select array_agg(candidate.id order by candidate.concluded_at, candidate.id)
  into v_battle_ids
  from (
    select battle.id, battle.concluded_at
    from public.authoritative_battle battle
    where battle.status in ('concluded', 'abandoned')
      and battle.concluded_at < now() - interval '24 hours'
      and not exists (select 1 from public.player_training_progression progression
        where progression.battle_id = battle.id and progression.status <> 'completed')
      and not exists (select 1 from public.player_ordinary_progression progression
        where progression.battle_id = battle.id and progression.status <> 'completed')
      and not exists (select 1 from public.player_training_progression progression
        join public.player_training_progression_pokemon pokemon on pokemon.progression_id = progression.id
        join public.player_pending_resolution resolution on resolution.id = pokemon.pending_resolution_id
        where progression.battle_id = battle.id and resolution.status = 'pending')
      and not exists (select 1 from public.player_ordinary_progression progression
        join public.player_ordinary_progression_pokemon pokemon on pokemon.progression_id = progression.id
        join public.player_pending_resolution resolution on resolution.id = pokemon.pending_resolution_id
        where progression.battle_id = battle.id and resolution.status = 'pending')
      and not (battle.contract_key = 'league' and exists (
        select 1 from public.authoritative_league_run league_run
        where league_run.id = battle.league_run_id and league_run.status in ('active', 'awaiting_battle')))
    order by battle.concluded_at, battle.id
    limit v_batch_limit
    for update of battle skip locked
  ) candidate;

  if coalesce(cardinality(v_battle_ids), 0) > 0 then
    delete from public.player_command_receipt receipt
    using unnest(v_battle_ids) selected(battle_id)
    where receipt.expires_at < now()
      and receipt.command_type in (
        'authoritative_battle_start', 'authoritative_training_start', 'authoritative_debug_training_start',
        'authoritative_capture_start', 'authoritative_gym_start', 'authoritative_admin_gym_start',
        'authoritative_admin_league_start', 'training_terminal_reward', 'gym_terminal_reward',
        'wild_capture_attempt', 'authoritative_battle_item', 'ordinary_terminal_effect',
        'authoritative_battle_move', 'authoritative_battle_switch', 'authoritative_battle_abandon'
      )
      and (receipt.result #>> '{battle,battle_id}' = selected.battle_id::text
        or receipt.result ->> 'battle_id' = selected.battle_id::text);

    delete from public.authoritative_battle battle where battle.id = any(v_battle_ids);
    get diagnostics v_deleted_count = row_count;
  end if;

  with candidates as (
    select receipt.auth_user_id, receipt.command_id
    from public.player_command_receipt receipt
    where receipt.expires_at < now()
      and not exists (select 1 from public.authoritative_battle battle
        where battle.auth_user_id = receipt.auth_user_id and battle.status in ('active', 'needs_player_switch'))
      and not exists (select 1 from public.player_encounter encounter
        where encounter.auth_user_id = receipt.auth_user_id and encounter.status = 'active')
      and not exists (select 1 from public.authoritative_league_run league_run
        where league_run.auth_user_id = receipt.auth_user_id and league_run.status in ('active', 'awaiting_battle'))
      and not exists (select 1 from public.player_training_progression progression
        where progression.auth_user_id = receipt.auth_user_id and progression.status <> 'completed')
      and not exists (select 1 from public.player_ordinary_progression progression
        where progression.auth_user_id = receipt.auth_user_id and progression.status <> 'completed')
      and not exists (select 1 from public.player_pending_resolution resolution
        where resolution.auth_user_id = receipt.auth_user_id and resolution.status = 'pending')
      and not exists (select 1 from public.player_daycare_state daycare
        where daycare.auth_user_id = receipt.auth_user_id and daycare.status = 'withdraw_pending')
    order by receipt.expires_at, receipt.auth_user_id, receipt.command_id
    limit v_batch_limit
    for update of receipt skip locked
  )
  delete from public.player_command_receipt receipt
  using candidates
  where receipt.auth_user_id = candidates.auth_user_id and receipt.command_id = candidates.command_id;

  with candidates as (
    select encounter.id from public.player_encounter encounter
    where encounter.status <> 'active'
      and encounter.terminal_at < now() - interval '24 hours'
      and not exists (select 1 from public.authoritative_battle battle where battle.encounter_id = encounter.id)
    order by encounter.terminal_at, encounter.id limit v_batch_limit
    for update of encounter skip locked
  )
  delete from public.player_encounter encounter using candidates where encounter.id = candidates.id;

  with candidates as (
    select resolution.id from public.player_pending_resolution resolution
    where resolution.status in ('resolved', 'cancelled')
      and resolution.resolved_at < now() - interval '24 hours'
      and not exists (select 1 from public.player_daycare_state daycare where daycare.pending_resolution_id = resolution.id)
      and not exists (select 1 from public.player_training_progression_pokemon pokemon where pokemon.pending_resolution_id = resolution.id)
      and not exists (select 1 from public.player_ordinary_progression_pokemon pokemon where pokemon.pending_resolution_id = resolution.id)
    order by resolution.resolved_at, resolution.id limit v_batch_limit
    for update of resolution skip locked
  )
  delete from public.player_pending_resolution resolution using candidates where resolution.id = candidates.id;

  with candidates as (
    select league_run.id from public.authoritative_league_run league_run
    where league_run.status in ('completed', 'failed')
      and league_run.concluded_at < now() - interval '24 hours'
      and not exists (select 1 from public.authoritative_battle battle where battle.league_run_id = league_run.id)
    order by league_run.concluded_at, league_run.id limit v_batch_limit
    for update of league_run skip locked
  )
  delete from public.authoritative_league_run league_run using candidates where league_run.id = candidates.id;

  with candidates as (
    select flute.auth_user_id, flute.usage_date, flute.flute_key
    from public.player_flute_daily_usage flute
    where flute.usage_date < ((now() at time zone 'Europe/Rome')::date - 7)
    order by flute.usage_date, flute.auth_user_id, flute.flute_key limit v_batch_limit
    for update of flute skip locked
  )
  delete from public.player_flute_daily_usage flute using candidates
  where flute.auth_user_id = candidates.auth_user_id
    and flute.usage_date = candidates.usage_date and flute.flute_key = candidates.flute_key;

  with candidates as (
    select bucket.category, bucket.subject_hash
    from server_authority_private.edge_request_rate_bucket bucket
    where bucket.updated_at < now() - interval '24 hours'
    order by bucket.updated_at, bucket.category, bucket.subject_hash limit v_batch_limit
    for update of bucket skip locked
  )
  delete from server_authority_private.edge_request_rate_bucket bucket using candidates
  where bucket.category = candidates.category and bucket.subject_hash = candidates.subject_hash;

  return v_deleted_count;
end;
$$;


ALTER FUNCTION "server_authority_private"."cleanup_authoritative_terminal_battles_core"("p_batch_limit" integer) OWNER TO "postgres";

--
-- Name: commit_edge_battle_command("uuid", "uuid", "text", "text", bigint, "uuid", bigint, "uuid", "text", "text", "text", "jsonb", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."commit_edge_battle_command"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
begin
  return server_authority_private.commit_edge_battle_command_before_revision_conflict_response(
    p_auth_user_id,p_command_id,p_command_type,p_command_hash,p_expected_player_revision,p_battle_id,p_expected_battle_version,
    p_runtime_owner_id,p_engine_version,p_engine_checksum,p_input_snapshot_hash,p_next_snapshot,p_events,p_projection,p_terminal_effects
  );
exception when serialization_failure then
  if SQLERRM = 'player revision conflict' then
    return jsonb_build_object('ok', false, 'conflict', 'player_revision');
  end if;
  raise;
end;
$$;


ALTER FUNCTION "server_authority_private"."commit_edge_battle_command"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") OWNER TO "postgres";

--
-- Name: commit_edge_battle_command_before_admin_gyms("uuid", "uuid", "text", "text", bigint, "uuid", bigint, "uuid", "text", "text", "text", "jsonb", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."commit_edge_battle_command_before_admin_gyms"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_result jsonb; v_reward jsonb; v_replay boolean;
begin
  select exists(select 1 from public.authoritative_battle_command_receipt
    where auth_user_id = p_auth_user_id and command_id = p_command_id) into v_replay;
  v_result := server_authority_private.commit_edge_battle_command_before_gyms(
    p_auth_user_id,p_command_id,p_command_type,p_command_hash,p_expected_player_revision,
    p_battle_id,p_expected_battle_version,p_runtime_owner_id,p_engine_version,p_engine_checksum,
    p_input_snapshot_hash,p_next_snapshot,p_events,p_projection,p_terminal_effects);
  if not v_replay and p_projection ->> 'status' = 'concluded'
    and p_projection ->> 'result_key' = 'player_win_no_reward'
    and exists(select 1 from public.authoritative_battle where id = p_battle_id
      and auth_user_id = p_auth_user_id and contract_key = 'gym') then
    v_reward := server_authority_private.award_terminal_gym_victory(p_auth_user_id, p_battle_id, p_command_id);
    if v_reward is not null then
      v_result := jsonb_set(v_result, '{player_revision}', v_reward #> '{player_state,revision}', true)
        || v_reward;
      update public.authoritative_battle_command_receipt set result = v_result,
        resulting_player_revision = (v_reward #>> '{player_state,revision}')::bigint
      where auth_user_id = p_auth_user_id and command_id = p_command_id;
    end if;
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION "server_authority_private"."commit_edge_battle_command_before_admin_gyms"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") OWNER TO "postgres";

--
-- Name: commit_edge_battle_command_before_battle_tower("uuid", "uuid", "text", "text", bigint, "uuid", bigint, "uuid", "text", "text", "text", "jsonb", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."commit_edge_battle_command_before_battle_tower"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_contract text; v_waiting text; v_result jsonb; v_terminal jsonb; v_replay boolean;
begin
  select contract_key,waiting_for into strict v_contract,v_waiting from public.authoritative_battle
    where id=p_battle_id and auth_user_id=p_auth_user_id;
  if v_contract in ('league','debug_training') then
    if p_next_snapshot#>>'{manager,adminControlled}'<>'true' or p_projection->>'admin_controlled'<>'true'
      or (p_projection->>'status' not in ('concluded','abandoned') and (p_projection->>'waiting_for' is distinct from p_next_snapshot#>>'{manager,waitingFor}'
        or p_projection->>'waiting_for' not in ('player','admin'))) then raise exception 'admin battle turn ownership is invalid' using errcode='22023'; end if;
    if p_command_type<>'initialize' and ((v_waiting<>'player' and p_command_type<>'abandon') or p_command_type not in ('move','switch','item','abandon')) then
      raise exception 'admin battle is not waiting for this player command' using errcode='40001'; end if;
  end if;
  select exists(select 1 from public.authoritative_battle_command_receipt where auth_user_id=p_auth_user_id and command_id=p_command_id) into v_replay;
  v_result:=server_authority_private.commit_edge_battle_command_before_held_item_state_repair(p_auth_user_id,p_command_id,p_command_type,p_command_hash,
    p_expected_player_revision,p_battle_id,p_expected_battle_version,p_runtime_owner_id,p_engine_version,p_engine_checksum,
    p_input_snapshot_hash,p_next_snapshot,p_events,p_projection,p_terminal_effects);
  if v_contract in ('league','debug_training') then
    update public.authoritative_battle set waiting_for=case when status in ('concluded','abandoned') then null else p_projection->>'waiting_for' end,
      admin_items=coalesce(p_projection->'admin_items',admin_items) where id=p_battle_id;
    if v_contract='league' and not v_replay and p_projection->>'status' in ('concluded','abandoned') then
      v_terminal:=server_authority_private.finalize_terminal_admin_league(p_auth_user_id,p_battle_id,p_command_id,p_projection);
      if v_terminal is not null then
        v_result:=jsonb_set(v_result,'{player_revision}',v_terminal#>'{player_state,revision}',true)||v_terminal;
        update public.authoritative_battle_command_receipt set result=v_result,
          resulting_player_revision=(v_terminal#>>'{player_state,revision}')::bigint where auth_user_id=p_auth_user_id and command_id=p_command_id;
      end if;
    end if;
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION "server_authority_private"."commit_edge_battle_command_before_battle_tower"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") OWNER TO "postgres";

--
-- Name: commit_edge_battle_command_before_battle_tower_record("uuid", "uuid", "text", "text", bigint, "uuid", bigint, "uuid", "text", "text", "text", "jsonb", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."commit_edge_battle_command_before_battle_tower_record"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_battle public.authoritative_battle%rowtype; v_run public.authoritative_battle_tower_run%rowtype; v_result jsonb;
  v_replay boolean; v_wins integer; v_points bigint;
begin
  select * into strict v_battle from public.authoritative_battle where id=p_battle_id and auth_user_id=p_auth_user_id;
  if v_battle.contract_key='battle_tower' and p_command_type in ('item','ball') then
    raise exception 'Battle Tower does not allow inventory actions' using errcode='22023';
  end if;
  select exists(select 1 from public.authoritative_battle_command_receipt where auth_user_id=p_auth_user_id and command_id=p_command_id) into v_replay;
  v_result:=server_authority_private.commit_edge_battle_command_before_battle_tower(p_auth_user_id,p_command_id,p_command_type,p_command_hash,
    p_expected_player_revision,p_battle_id,p_expected_battle_version,p_runtime_owner_id,p_engine_version,p_engine_checksum,p_input_snapshot_hash,
    p_next_snapshot,p_events,p_projection,p_terminal_effects);
  if v_battle.contract_key<>'battle_tower' or v_replay or p_projection->>'status' not in ('concluded','abandoned') then return v_result; end if;
  select * into strict v_run from public.authoritative_battle_tower_run where id=v_battle.tower_run_id for update;
  -- Keep the frozen roster revision aligned when a held Berry/item transition
  -- was canonically persisted during the finished round.
  update public.authoritative_battle_tower_run_pokemon roster
  set state=case when coalesce(server_authority_private.edge_jsonb_bigint(pokemon.state->'i'),0)>0
      then roster.state||jsonb_build_object('i',server_authority_private.edge_jsonb_bigint(pokemon.state->'i')) else roster.state-'i' end,
    instance_revision=pokemon.revision
  from public.player_pokemon_instance pokemon
  where roster.run_id=v_run.id and pokemon.id=roster.pokemon_instance_id and pokemon.auth_user_id=p_auth_user_id;
  if p_projection->>'status'='concluded' and p_projection->>'result_key'='player_win_no_reward' then
    update public.authoritative_battle_tower_run set wins=wins+1,next_challenge=next_challenge+1,status='awaiting_next',updated_at=now()
      where id=v_run.id returning * into v_run;
  else
    v_wins:=v_run.wins;
    v_points:=v_wins + case when v_wins>=7 then 20 else 0 end + case when v_wins>=10 then 50 else 0 end;
    update public.authoritative_battle_tower_run set status=case when p_projection->>'status'='abandoned' then 'abandoned' else 'lost' end,
      reward_battle_points=v_points,reward_claimed=true,concluded_at=now(),updated_at=now() where id=v_run.id returning * into v_run;
    update public.player_profile_state set battle_points=battle_points+v_points,updated_at=now() where auth_user_id=p_auth_user_id;
    v_result:=v_result||jsonb_build_object('tower_reward',jsonb_build_object('battle_points',v_points,'wins',v_wins));
  end if;
  v_result:=v_result||jsonb_build_object('tower_run',jsonb_build_object('run_id',v_run.id,'wins',v_run.wins,
    'next_challenge',v_run.next_challenge,'status',v_run.status,'battle_points',v_run.reward_battle_points),
    'player_state',server_authority_private.player_state_projection(p_auth_user_id));
  update public.authoritative_battle_command_receipt set result=v_result where auth_user_id=p_auth_user_id and command_id=p_command_id;
  return v_result;
end;
$$;


ALTER FUNCTION "server_authority_private"."commit_edge_battle_command_before_battle_tower_record"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") OWNER TO "postgres";

--
-- Name: commit_edge_battle_command_before_capture("uuid", "uuid", "text", "text", bigint, "uuid", bigint, "uuid", "text", "text", "text", "jsonb", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."commit_edge_battle_command_before_capture"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_contract text; v_waiting text; v_result jsonb; v_terminal jsonb; v_replay boolean;
begin
  select contract_key,waiting_for into strict v_contract,v_waiting from public.authoritative_battle
    where id=p_battle_id and auth_user_id=p_auth_user_id;
  if v_contract='league' then
    if p_next_snapshot#>>'{manager,adminControlled}'<>'true' or p_projection->>'admin_controlled'<>'true'
      or (p_projection->>'status' not in ('concluded','abandoned') and (p_projection->>'waiting_for' is distinct from p_next_snapshot#>>'{manager,waitingFor}'
        or p_projection->>'waiting_for' not in ('player','admin'))) then raise exception 'admin League turn ownership is invalid' using errcode='22023'; end if;
    if p_command_type<>'initialize' and (v_waiting<>'player' or p_command_type not in ('move','switch','abandon')) then
      raise exception 'admin League is not waiting for this player command' using errcode='40001'; end if;
  end if;
  select exists(select 1 from public.authoritative_battle_command_receipt where auth_user_id=p_auth_user_id and command_id=p_command_id) into v_replay;
  v_result:=server_authority_private.commit_edge_battle_command_before_league(p_auth_user_id,p_command_id,p_command_type,p_command_hash,
    p_expected_player_revision,p_battle_id,p_expected_battle_version,p_runtime_owner_id,p_engine_version,p_engine_checksum,
    p_input_snapshot_hash,p_next_snapshot,p_events,p_projection,p_terminal_effects);
  if v_contract='league' then
    update public.authoritative_battle set waiting_for=case when status in ('concluded','abandoned') then null else p_projection->>'waiting_for' end,
      admin_items=coalesce(p_projection->'admin_items',admin_items) where id=p_battle_id;
    if not v_replay and p_projection->>'status' in ('concluded','abandoned') then
      v_terminal:=server_authority_private.finalize_terminal_admin_league(p_auth_user_id,p_battle_id,p_command_id,p_projection);
      if v_terminal is not null then
        v_result:=jsonb_set(v_result,'{player_revision}',v_terminal#>'{player_state,revision}',true)||v_terminal;
        update public.authoritative_battle_command_receipt set result=v_result,
          resulting_player_revision=(v_terminal#>>'{player_state,revision}')::bigint where auth_user_id=p_auth_user_id and command_id=p_command_id;
      end if;
    end if;
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION "server_authority_private"."commit_edge_battle_command_before_capture"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") OWNER TO "postgres";

--
-- Name: commit_edge_battle_command_before_gyms("uuid", "uuid", "text", "text", bigint, "uuid", bigint, "uuid", "text", "text", "text", "jsonb", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."commit_edge_battle_command_before_gyms"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare
  v_battle public.authoritative_battle%rowtype;
  v_receipt public.authoritative_battle_command_receipt%rowtype;
  v_player_receipt public.player_command_receipt%rowtype;
  v_revision bigint;
  v_current_hash text;
  v_expected_items jsonb;
  v_inventory_effect jsonb;
  v_item public.catalog_item%rowtype;
  v_item_index integer;
  v_before integer;
  v_after integer;
  v_db_quantity integer;
  v_prior_uses integer;
  v_snapshot_uses integer;
  v_next_uses integer;
  v_consumed boolean;
  v_result jsonb;
  v_player jsonb;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'service role required' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_auth_user_id::text || ':' || p_command_id::text, 0));
  select * into v_receipt from public.authoritative_battle_command_receipt
    where auth_user_id = p_auth_user_id and command_id = p_command_id;
  if found then
    if v_receipt.battle_id <> p_battle_id or v_receipt.command_type <> p_command_type
      or v_receipt.command_hash <> p_command_hash then
      raise exception 'command id was already used with a different payload' using errcode = '22023';
    end if;
    return v_receipt.result;
  end if;

  if p_command_type = 'initialize' then
    select * into strict v_battle from public.authoritative_battle
      where id = p_battle_id and auth_user_id = p_auth_user_id;
    if v_battle.contract_key in ('training','gym','admin_gym','league','debug_training') then
      v_expected_items := server_authority_private.training_battle_inventory(p_auth_user_id, v_battle.catalog_release_id);
      if p_next_snapshot -> 'playerItems' is distinct from v_expected_items
        or p_projection -> 'player_items' is distinct from v_expected_items then
        raise exception 'training initialization inventory is not canonical' using errcode = '22023';
      end if;
    end if;
  end if;

  if p_command_type <> 'item' then
    return server_authority_private.commit_edge_battle_command_without_items(
      p_auth_user_id,p_command_id,p_command_type,p_command_hash,p_expected_player_revision,
      p_battle_id,p_expected_battle_version,p_runtime_owner_id,p_engine_version,p_engine_checksum,
      p_input_snapshot_hash,p_next_snapshot,p_events,p_projection,p_terminal_effects);
  end if;

  -- Reject stale/foreign commands before locking or changing inventory. The
  -- wrapped commit repeats these checks immediately before snapshot adoption.
  select revision into v_revision from public.player_state_revision
    where auth_user_id = p_auth_user_id for update;
  if not found then raise exception 'player state does not exist' using errcode = 'P0002'; end if;
  select * into v_battle from public.authoritative_battle
    where id = p_battle_id and auth_user_id = p_auth_user_id for update;
  if not found then raise exception 'authoritative battle was not found' using errcode = 'P0002'; end if;
  if v_revision <> p_expected_player_revision or v_battle.battle_version <> p_expected_battle_version
    or v_battle.engine_runtime_state <> 'ready'
    or v_battle.engine_version is distinct from p_engine_version
    or v_battle.engine_checksum is distinct from p_engine_checksum then
    raise exception 'battle item revision/version conflict' using errcode = '40001';
  end if;
  if v_battle.runtime_owner_id <> p_runtime_owner_id then
    raise exception 'runtime lock is owned by another client' using errcode = '55P03';
  end if;
  if v_battle.status <> 'active' or v_battle.contract_key not in ('training','gym','admin_gym','league','debug_training')
    or coalesce(server_authority_private.edge_jsonb_boolean(v_battle.engine_snapshot #> '{manager,playerNeedsSwitch}'),false)
    or coalesce(server_authority_private.edge_jsonb_boolean(v_battle.engine_snapshot #> '{manager,playerPostMoveSwitch}'),false) then
    raise exception 'battle contract does not accept persistent items' using errcode = '22023';
  end if;
  v_current_hash := server_authority_private.prepare_edge_battle_command_core(p_auth_user_id,p_battle_id)->>'input_snapshot_hash';
  if v_current_hash <> p_input_snapshot_hash then
    raise exception 'engine snapshot/version conflict' using errcode = '40001';
  end if;

  if p_events #>> '{0,type}' <> 'command_resolved'
    or p_events #>> '{0,data,command_type}' <> 'item'
    or server_authority_private.edge_jsonb_bigint(p_events #> '{0,data,item_index}') is null
    or server_authority_private.edge_jsonb_boolean(p_events #> '{0,data,item_consumed}') is null
    or server_authority_private.edge_jsonb_boolean(p_events #> '{0,data,action_skipped}') is null then
    raise exception 'battle item journal fact is invalid' using errcode = '22023';
  end if;
  v_item_index := server_authority_private.edge_jsonb_bigint(p_events #> '{0,data,item_index}');

  if jsonb_typeof(p_terminal_effects) is distinct from 'object'
    or p_terminal_effects - array['reward','inventory','team'] <> '{}'::jsonb
    or p_terminal_effects ->> 'reward' <> 'none' or p_terminal_effects ->> 'team' <> 'unchanged' then
    raise exception 'battle item consumption descriptor is invalid' using errcode = '22023';
  end if;
  v_inventory_effect := p_terminal_effects -> 'inventory';
  v_consumed := jsonb_typeof(v_inventory_effect) = 'object';
  if v_consumed then
    if v_inventory_effect - array['kind','itemIndex','quantity','beforeQuantity','afterQuantity'] <> '{}'::jsonb
      or v_inventory_effect ->> 'kind' <> 'battle_item_consumption'
      or server_authority_private.edge_jsonb_bigint(v_inventory_effect -> 'quantity') <> 1
      or server_authority_private.edge_jsonb_bigint(v_inventory_effect -> 'itemIndex') <> v_item_index
      or not server_authority_private.edge_jsonb_boolean(p_events #> '{0,data,item_consumed}')
      or server_authority_private.edge_jsonb_boolean(p_events #> '{0,data,action_skipped}') then
      raise exception 'exactly one battle item must be consumed' using errcode = '22023';
    end if;
    v_before := server_authority_private.edge_jsonb_bigint(v_inventory_effect -> 'beforeQuantity');
    v_after := server_authority_private.edge_jsonb_bigint(v_inventory_effect -> 'afterQuantity');
    if coalesce(v_before,0) <= 0 or v_after <> v_before - 1 then
      raise exception 'battle item quantity delta is invalid' using errcode = '22023';
    end if;
  elsif v_inventory_effect is distinct from to_jsonb('unchanged'::text)
    or server_authority_private.edge_jsonb_boolean(p_events #> '{0,data,item_consumed}')
    or not server_authority_private.edge_jsonb_boolean(p_events #> '{0,data,action_skipped}') then
    raise exception 'non-consumed battle item transition is invalid' using errcode = '22023';
  end if;
  select * into v_item from public.catalog_item where catalog_release_id = v_battle.catalog_release_id
    and item_index = v_item_index;
  if not found or not (
      (v_item.category_key = 'BattleItem' and v_item.subcategory_key in ('HealHp','HealFull','HealKo','HealStatus','Meteo'))
      or (v_item.category_key = 'Berry' and v_item.item_index between 300 and 308
        and v_item.subcategory_key in ('HealHp','HealStatus'))
    ) then
    raise exception 'catalog item is not supported for authoritative training' using errcode = '22023';
  end if;

  if jsonb_typeof(v_battle.engine_snapshot -> 'playerItems') is distinct from 'array'
    or jsonb_typeof(p_next_snapshot -> 'playerItems') is distinct from 'array'
    or jsonb_typeof(p_projection -> 'player_items') is distinct from 'array'
    or p_projection -> 'player_items' is distinct from p_next_snapshot -> 'playerItems'
    or exists (select 1 from jsonb_array_elements(v_battle.engine_snapshot -> 'playerItems') entry(value)
      where jsonb_typeof(value) <> 'array' or jsonb_array_length(value) <> 2
        or server_authority_private.edge_jsonb_bigint(value -> 0) is null
        or coalesce(server_authority_private.edge_jsonb_bigint(value -> 1),-1) < 0)
    or exists (select 1 from jsonb_array_elements(p_next_snapshot -> 'playerItems') entry(value)
      where jsonb_typeof(value) <> 'array' or jsonb_array_length(value) <> 2
        or server_authority_private.edge_jsonb_bigint(value -> 0) is null
        or coalesce(server_authority_private.edge_jsonb_bigint(value -> 1),-1) < 0)
    or (select count(*) from jsonb_array_elements(v_battle.engine_snapshot -> 'playerItems')) <>
       (select count(distinct server_authority_private.edge_jsonb_bigint(value -> 0)) from jsonb_array_elements(v_battle.engine_snapshot -> 'playerItems'))
    or (select count(*) from jsonb_array_elements(p_next_snapshot -> 'playerItems')) <>
       (select count(distinct server_authority_private.edge_jsonb_bigint(value -> 0)) from jsonb_array_elements(p_next_snapshot -> 'playerItems')) then
    raise exception 'battle-local inventory snapshot is invalid' using errcode = '22023';
  end if;
  select server_authority_private.edge_jsonb_bigint(value -> 1) into v_snapshot_uses
    from jsonb_array_elements(v_battle.engine_snapshot -> 'playerItems') where server_authority_private.edge_jsonb_bigint(value -> 0)=v_item_index;
  select server_authority_private.edge_jsonb_bigint(value -> 1) into v_next_uses
    from jsonb_array_elements(p_next_snapshot -> 'playerItems') where server_authority_private.edge_jsonb_bigint(value -> 0)=v_item_index;
  if p_projection -> 'weather' is distinct from p_next_snapshot #> '{manager,weather}'
    or p_projection -> 'weather_move_used_last_action' is distinct from p_next_snapshot #> '{manager,weatherMoveUsedLastAction}' then
    raise exception 'battle weather projection diverges from the trusted snapshot' using errcode='22023';
  end if;
  if v_consumed then
    if v_snapshot_uses is distinct from v_before or v_next_uses is distinct from v_after
      or exists (
        select 1 from jsonb_array_elements(v_battle.engine_snapshot -> 'playerItems') old_entry(value)
        full join jsonb_array_elements(p_next_snapshot -> 'playerItems') new_entry(value)
          on server_authority_private.edge_jsonb_bigint(old_entry.value -> 0)=server_authority_private.edge_jsonb_bigint(new_entry.value -> 0)
        where coalesce(server_authority_private.edge_jsonb_bigint(old_entry.value -> 0),server_authority_private.edge_jsonb_bigint(new_entry.value -> 0))<>v_item_index
          and old_entry.value is distinct from new_entry.value
      ) then raise exception 'battle-local inventory changed outside the trusted consumption' using errcode = '22023'; end if;
  elsif coalesce(v_snapshot_uses,0) <= 0 or v_next_uses is distinct from v_snapshot_uses
    or p_next_snapshot -> 'playerItems' is distinct from v_battle.engine_snapshot -> 'playerItems' then
    raise exception 'skipped battle item changed battle-local inventory' using errcode='22023';
  end if;
  if not v_consumed then v_before:=v_snapshot_uses; v_after:=v_next_uses; end if;

  if exists (
    with snapshot_combatants as (
      select 'player'::text side,
        server_authority_private.edge_jsonb_bigint(pokemon.value #> '{state,authoritativeSlot}') slot,
        combatant.value #> '{state,status}' status,
        coalesce(server_authority_private.edge_jsonb_bigint(combatant.value #> '{state,sleepCounter}'),0) sleep_counter,
        coalesce(server_authority_private.edge_jsonb_bigint(combatant.value #> '{state,sleepDuration}'),0) sleep_duration,
        coalesce(server_authority_private.edge_jsonb_bigint(combatant.value #> '{state,confCounter}'),0) confusion_counter
      from jsonb_array_elements(p_next_snapshot #> '{playerTeam,pokemon}') with ordinality pokemon(value,ordinality)
      join jsonb_array_elements(p_next_snapshot #> '{playerTeam,combatants}') with ordinality combatant(value,ordinality) using(ordinality)
      union all
      select 'npc'::text,
        server_authority_private.edge_jsonb_bigint(pokemon.value #> '{state,authoritativeSlot}'),
        combatant.value #> '{state,status}',
        coalesce(server_authority_private.edge_jsonb_bigint(combatant.value #> '{state,sleepCounter}'),0),
        coalesce(server_authority_private.edge_jsonb_bigint(combatant.value #> '{state,sleepDuration}'),0),
        coalesce(server_authority_private.edge_jsonb_bigint(combatant.value #> '{state,confCounter}'),0)
      from jsonb_array_elements(p_next_snapshot #> '{enemyTeam,pokemon}') with ordinality pokemon(value,ordinality)
      join jsonb_array_elements(p_next_snapshot #> '{enemyTeam,combatants}') with ordinality combatant(value,ordinality) using(ordinality)
    )
    select 1 from snapshot_combatants snapshot
    left join jsonb_array_elements(p_projection -> 'participants') projected(value)
      on projected.value->>'side'=snapshot.side
      and server_authority_private.edge_jsonb_bigint(projected.value->'slot_index')=snapshot.slot
    where projected.value is null or projected.value->'status' is distinct from snapshot.status
      or server_authority_private.edge_jsonb_bigint(projected.value->'sleep_counter')<>snapshot.sleep_counter
      or server_authority_private.edge_jsonb_bigint(projected.value->'sleep_duration')<>snapshot.sleep_duration
      or server_authority_private.edge_jsonb_bigint(projected.value->'confusion_counter')<>snapshot.confusion_counter
  ) then raise exception 'battle HP/status projection diverges from the trusted snapshot' using errcode='22023'; end if;

  select count(*) into v_prior_uses from public.authoritative_battle_event event
    where event.battle_id=p_battle_id and event.event_type='command_resolved'
      and event.event_data->>'command_type'='item'
      and coalesce(server_authority_private.edge_jsonb_boolean(event.event_data->'item_consumed'),false)
      and server_authority_private.edge_jsonb_bigint(event.event_data->'item_index')=v_item_index;
  v_snapshot_uses := coalesce(server_authority_private.edge_jsonb_bigint(v_battle.engine_snapshot #> array['manager','usedItems',v_item.display_name]),0);
  v_next_uses := coalesce(server_authority_private.edge_jsonb_bigint(p_next_snapshot #> array['manager','usedItems',v_item.display_name]),0);
  if v_snapshot_uses <> v_prior_uses or v_snapshot_uses >= 3
    or (v_consumed and v_next_uses <> v_prior_uses + 1)
    or (not v_consumed and v_next_uses <> v_prior_uses)
    or (v_consumed and (v_battle.engine_snapshot #> '{manager,usedItems}') - v_item.display_name
      is distinct from (p_next_snapshot #> '{manager,usedItems}') - v_item.display_name)
    or (not v_consumed and v_battle.engine_snapshot #> '{manager,usedItems}'
      is distinct from p_next_snapshot #> '{manager,usedItems}')
    or p_projection -> 'used_items' is distinct from p_next_snapshot #> '{manager,usedItems}' then
    raise exception 'battle item use count or journal fact is invalid' using errcode = '22023';
  end if;

  select quantity into v_db_quantity from public.player_inventory_item
    where auth_user_id=p_auth_user_id and catalog_release_id=v_battle.catalog_release_id
      and item_index=v_item_index for update;
  if not found or v_db_quantity <> v_before then
    raise exception 'canonical battle item quantity is insufficient or stale' using errcode = '40001';
  end if;
  if not v_consumed then
    v_result := server_authority_private.commit_edge_battle_command_without_items(
      p_auth_user_id,p_command_id,p_command_type,p_command_hash,p_expected_player_revision,
      p_battle_id,p_expected_battle_version,p_runtime_owner_id,p_engine_version,p_engine_checksum,
      p_input_snapshot_hash,p_next_snapshot,p_events,p_projection,
      jsonb_build_object('reward','none','inventory','unchanged','team','unchanged'));
    return v_result;
  end if;
  update public.player_inventory_item set quantity=quantity-1,updated_at=now()
    where auth_user_id=p_auth_user_id and item_index=v_item_index;
  delete from public.player_inventory_item where auth_user_id=p_auth_user_id
    and item_index=v_item_index and quantity=0;

  v_result := server_authority_private.commit_edge_battle_command_without_items(
    p_auth_user_id,p_command_id,p_command_type,p_command_hash,p_expected_player_revision,
    p_battle_id,p_expected_battle_version,p_runtime_owner_id,p_engine_version,p_engine_checksum,
    p_input_snapshot_hash,p_next_snapshot,p_events,p_projection,
    jsonb_build_object('reward','none','inventory','unchanged','team','unchanged'));
  v_player := server_authority_private.player_state_projection(p_auth_user_id);
  v_result := v_result || jsonb_build_object('player_state',v_player);
  update public.authoritative_battle_command_receipt set result=v_result,
    resulting_player_revision=(v_result->>'player_revision')::bigint
    where auth_user_id=p_auth_user_id and command_id=p_command_id;

  insert into public.player_command_receipt(auth_user_id,command_id,command_type,request_hash,result,resulting_revision)
  values(p_auth_user_id,p_command_id,'authoritative_battle_item',p_command_hash,
    jsonb_build_object('item_index',v_item_index,'battle_id',p_battle_id),
    (v_result->>'player_revision')::bigint) returning * into v_player_receipt;
  perform server_authority_private.apply_mission_fact(v_player_receipt.auth_user_id,'battle-item-used',
    jsonb_build_object('itemIndex',v_item_index,'battleId',p_battle_id,'contract','training'),v_player_receipt.created_at);
  v_player := server_authority_private.player_state_projection(p_auth_user_id);
  v_result := v_result || jsonb_build_object('player_state',v_player);
  update public.authoritative_battle_command_receipt set result=v_result
    where auth_user_id=p_auth_user_id and command_id=p_command_id;
  update public.player_command_receipt set result=jsonb_build_object(
    'item_index',v_item_index,'battle_id',p_battle_id,'player_state',v_player)
    where auth_user_id=p_auth_user_id and command_id=p_command_id;
  return v_result;
end;
$$;


ALTER FUNCTION "server_authority_private"."commit_edge_battle_command_before_gyms"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") OWNER TO "postgres";

--
-- Name: commit_edge_battle_command_before_held_item_state_repair("uuid", "uuid", "text", "text", bigint, "uuid", bigint, "uuid", "text", "text", "text", "jsonb", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."commit_edge_battle_command_before_held_item_state_repair"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $_$
declare v_battle public.authoritative_battle%rowtype; v_receipt public.authoritative_battle_command_receipt%rowtype;
  v_item public.catalog_item%rowtype; v_index integer; v_before integer; v_after integer; v_db integer;
  v_consumed boolean; v_success boolean; v_result jsonb; v_core_projection jsonb; v_revision bigint; v_player_receipt public.player_command_receipt%rowtype;
  v_rate numeric; v_expected_rate numeric;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'service role required' using errcode='42501'; end if;
  select * into v_battle from public.authoritative_battle where id=p_battle_id and auth_user_id=p_auth_user_id;
  if not found or v_battle.contract_key<>'capture' then
    return server_authority_private.commit_edge_battle_command_before_capture(p_auth_user_id,p_command_id,p_command_type,p_command_hash,
      p_expected_player_revision,p_battle_id,p_expected_battle_version,p_runtime_owner_id,p_engine_version,p_engine_checksum,
      p_input_snapshot_hash,p_next_snapshot,p_events,p_projection,p_terminal_effects);
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_auth_user_id::text||':'||p_command_id::text,0));
  select * into v_receipt from public.authoritative_battle_command_receipt where auth_user_id=p_auth_user_id and command_id=p_command_id;
  if found then
    if v_receipt.battle_id<>p_battle_id or v_receipt.command_type<>p_command_type or v_receipt.command_hash<>p_command_hash then
      raise exception 'command id was reused with a different payload' using errcode='22023'; end if;
    return v_receipt.result;
  end if;
  if p_command_type='initialize' then
    if p_next_snapshot->'playerItems' is distinct from server_authority_private.capture_battle_inventory(p_auth_user_id,v_battle.catalog_release_id)
      or p_projection->'player_items' is distinct from p_next_snapshot->'playerItems' then
      raise exception 'capture initialization inventory is not canonical' using errcode='22023'; end if;
    return server_authority_private.commit_edge_battle_command_before_capture(p_auth_user_id,p_command_id,p_command_type,p_command_hash,
      p_expected_player_revision,p_battle_id,p_expected_battle_version,p_runtime_owner_id,p_engine_version,p_engine_checksum,
      p_input_snapshot_hash,p_next_snapshot,p_events,p_projection,p_terminal_effects);
  end if;
  if p_command_type in ('item','ball') then
    if v_battle.status<>'active' or v_battle.battle_version<>p_expected_battle_version or v_battle.runtime_owner_id<>p_runtime_owner_id
      or v_battle.engine_version is distinct from p_engine_version or v_battle.engine_checksum is distinct from p_engine_checksum then
      raise exception 'capture item version conflict' using errcode='40001'; end if;
    select revision into strict v_revision from public.player_state_revision where auth_user_id=p_auth_user_id for update;
    if v_revision<>p_expected_player_revision then raise exception 'player revision conflict' using errcode='40001'; end if;
    if p_command_type='ball' then
      if p_events#>>'{0,type}'<>'ball_resolved' or p_events#>>'{0,data,command_type}'<>'ball' then
        raise exception 'ball journal fact is invalid' using errcode='22023'; end if;
      v_index:=server_authority_private.edge_jsonb_bigint(p_events#>'{0,data,item_index}');
      v_consumed:=coalesce(server_authority_private.edge_jsonb_boolean(p_events#>'{0,data,item_consumed}'),false);
      v_success:=coalesce(server_authority_private.edge_jsonb_boolean(p_events#>'{0,data,capture_success}'),false);
      if not exists(select 1 from public.player_encounter where id=v_battle.encounter_id and status='active') then
        raise exception 'L''incontro di cattura non e piu attivo prima della conferma della Ball.' using errcode='40001'; end if;
      if server_authority_private.edge_jsonb_bigint(p_events#>'{0,data,target_slot}')<>0
        or p_projection->>'capture_success' is distinct from v_success::text
        or (v_success and not v_consumed) then raise exception 'ball outcome descriptor is invalid' using errcode='22023'; end if;
    else
      if p_events#>>'{0,type}'<>'command_resolved' or p_events#>>'{0,data,command_type}'<>'item' then
        raise exception 'capture item journal fact is invalid' using errcode='22023'; end if;
      v_index:=server_authority_private.edge_jsonb_bigint(p_events#>'{0,data,item_index}');
      v_consumed:=coalesce(server_authority_private.edge_jsonb_boolean(p_events#>'{0,data,item_consumed}'),false);
      v_success:=false;
    end if;
    select * into v_item from public.catalog_item where catalog_release_id=v_battle.catalog_release_id and item_index=v_index;
    if not found or (p_command_type='ball' and v_item.category_key<>'Ball')
      or (p_command_type='item' and not ((v_item.category_key='BattleItem' and v_item.subcategory_key in ('HealHp','HealFull','HealKo','HealStatus','Meteo'))
        or (v_item.category_key='Berry' and v_item.item_index between 300 and 308 and v_item.subcategory_key in ('HealHp','HealStatus')))) then
      raise exception 'item class is unsupported by capture' using errcode='22023'; end if;
    if p_command_type='ball' then
      if jsonb_typeof(p_events#>'{0,data,catch_rate}')<>'number'
        or p_events#>>'{0,data,catch_rate}' !~ '^[0-9]+([.][0-9]+)?$' then
        raise exception 'capture rate audit is invalid' using errcode='22023'; end if;
      v_rate:=(p_events#>>'{0,data,catch_rate}')::numeric;
      select least(100,greatest(0,(v_item.rules->>'value')::numeric*r.catch_multiplier*h.catch_multiplier))
        into v_expected_rate from public.player_encounter e
        join public.catalog_rarity_rule r on r.catalog_release_id=e.catalog_release_id and r.rarity_key=e.rarity_key
        join lateral (select catch_multiplier from public.catalog_capture_hp_threshold t
          where t.catalog_release_id=e.catalog_release_id
            and (select current_hp from public.authoritative_battle_participant where battle_id=p_battle_id and side='npc' and slot_index=0)::numeric
              / e.max_hp<=t.max_hp_fraction order by t.threshold_order limit 1) h on true
        where e.id=v_battle.encounter_id and jsonb_typeof(v_item.rules->'value')='number';
      if v_expected_rate is null or abs(v_rate-v_expected_rate)>0.000000001 then
        raise exception 'trusted JS capture rate diverges from the exact catalog/encounter state' using errcode='22023'; end if;
    end if;
    select server_authority_private.edge_jsonb_bigint(value->1) into v_before from jsonb_array_elements(v_battle.engine_snapshot->'playerItems')
      where server_authority_private.edge_jsonb_bigint(value->0)=v_index;
    select server_authority_private.edge_jsonb_bigint(value->1) into v_after from jsonb_array_elements(p_next_snapshot->'playerItems')
      where server_authority_private.edge_jsonb_bigint(value->0)=v_index;
    if p_projection->'player_items' is distinct from p_next_snapshot->'playerItems'
      or (v_consumed and (v_before<=0 or v_after<>v_before-1))
      or (not v_consumed and (v_before<=0 or v_after is distinct from v_before))
      or exists(select 1 from jsonb_array_elements(v_battle.engine_snapshot->'playerItems') old(value)
        full join jsonb_array_elements(p_next_snapshot->'playerItems') new(value)
          on server_authority_private.edge_jsonb_bigint(old.value->0)=server_authority_private.edge_jsonb_bigint(new.value->0)
        where coalesce(server_authority_private.edge_jsonb_bigint(old.value->0),server_authority_private.edge_jsonb_bigint(new.value->0))<>v_index
          and old.value is distinct from new.value) then raise exception 'battle-local inventory delta is invalid' using errcode='22023'; end if;
    if p_command_type='item' and coalesce(server_authority_private.edge_jsonb_bigint(p_next_snapshot#>array['manager','usedItems',v_item.display_name]),0)>3 then
      raise exception 'capture battle item use limit exceeded' using errcode='22023'; end if;
    if v_consumed then
      select quantity into v_db from public.player_inventory_item where auth_user_id=p_auth_user_id
        and catalog_release_id=v_battle.catalog_release_id and item_index=v_index for update;
      if not found or v_db<>v_before then raise exception 'canonical item quantity is stale' using errcode='40001'; end if;
      update public.player_inventory_item set quantity=quantity-1,updated_at=now() where auth_user_id=p_auth_user_id and item_index=v_index;
      delete from public.player_inventory_item where auth_user_id=p_auth_user_id and item_index=v_index and quantity=0;
    end if;
    v_core_projection:=p_projection;
    if p_command_type='ball' and v_success then
      v_core_projection:=jsonb_set(v_core_projection,'{result_key}',to_jsonb('player_win_no_reward'::text),true);
    end if;
    v_result:=server_authority_private.commit_edge_battle_command_without_items(p_auth_user_id,p_command_id,'item',p_command_hash,
      p_expected_player_revision,p_battle_id,p_expected_battle_version,p_runtime_owner_id,p_engine_version,p_engine_checksum,
      p_input_snapshot_hash,p_next_snapshot,p_events,v_core_projection,jsonb_build_object('reward','none','inventory','unchanged','team','unchanged'));
    update public.authoritative_battle_command_receipt set command_type=p_command_type where auth_user_id=p_auth_user_id and command_id=p_command_id;
    if p_command_type='ball' and v_success then
      return server_authority_private.finish_capture_success(p_auth_user_id,p_battle_id,p_command_id,p_command_hash,v_index,v_result);
    end if;
    if p_projection->>'status' in ('concluded','abandoned') then
      update public.player_encounter set status='cancelled'
        where id=v_battle.encounter_id and status='active';
    end if;
    if p_command_type='ball' then
      select revision into v_revision from public.player_state_revision where auth_user_id=p_auth_user_id;
      insert into public.player_command_receipt(auth_user_id,command_id,command_type,request_hash,result,resulting_revision)
        values(p_auth_user_id,p_command_id,'wild_capture_attempt',p_command_hash,
          jsonb_build_object('capture_success',false,'item_index',v_index,'battle_id',p_battle_id),v_revision)
        returning * into v_player_receipt;
    elsif v_consumed then
      select revision into v_revision from public.player_state_revision where auth_user_id=p_auth_user_id;
      insert into public.player_command_receipt(auth_user_id,command_id,command_type,request_hash,result,resulting_revision)
        values(p_auth_user_id,p_command_id,'authoritative_battle_item',p_command_hash,
          jsonb_build_object('item_index',v_index,'battle_id',p_battle_id),v_revision) returning * into v_player_receipt;
      perform server_authority_private.apply_mission_fact(v_player_receipt.auth_user_id,'battle-item-used',
        jsonb_build_object('itemIndex',v_index,'battleId',p_battle_id,'contract','capture'),v_player_receipt.created_at);
    end if;
    v_result:=v_result||jsonb_build_object('capture_success',false,'player_state',server_authority_private.player_state_projection(p_auth_user_id));
    update public.authoritative_battle_command_receipt set result=v_result where auth_user_id=p_auth_user_id and command_id=p_command_id;
    return v_result;
  end if;
  v_result:=server_authority_private.commit_edge_battle_command_before_capture(p_auth_user_id,p_command_id,p_command_type,p_command_hash,
    p_expected_player_revision,p_battle_id,p_expected_battle_version,p_runtime_owner_id,p_engine_version,p_engine_checksum,
    p_input_snapshot_hash,p_next_snapshot,p_events,p_projection,p_terminal_effects);
  if p_projection->>'status' in ('concluded','abandoned') then
    update public.player_encounter set status='cancelled'
      where id=v_battle.encounter_id and status='active';
    v_result:=v_result||jsonb_build_object('player_state',server_authority_private.player_state_projection(p_auth_user_id));
    update public.authoritative_battle_command_receipt set result=v_result where auth_user_id=p_auth_user_id and command_id=p_command_id;
  end if;
  return v_result;
end;
$_$;


ALTER FUNCTION "server_authority_private"."commit_edge_battle_command_before_held_item_state_repair"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") OWNER TO "postgres";

--
-- Name: commit_edge_battle_command_before_league("uuid", "uuid", "text", "text", bigint, "uuid", bigint, "uuid", "text", "text", "text", "jsonb", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."commit_edge_battle_command_before_league"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_contract text; v_waiting text; v_result jsonb; v_reward jsonb;
begin
  select contract_key, waiting_for into strict v_contract, v_waiting
    from public.authoritative_battle where id = p_battle_id and auth_user_id = p_auth_user_id;
  if v_contract = 'admin_gym' then
    if p_next_snapshot #>> '{manager,adminControlled}' <> 'true'
      or p_projection ->> 'admin_controlled' <> 'true'
      or (p_projection ->> 'status' not in ('concluded', 'abandoned') and (
        p_projection ->> 'waiting_for' is distinct from p_next_snapshot #>> '{manager,waitingFor}'
        or p_projection ->> 'waiting_for' not in ('player', 'admin'))) then
      raise exception 'admin gym snapshot turn ownership is invalid' using errcode = '22023';
    end if;
    if p_command_type <> 'initialize' and ((v_waiting <> 'player' and p_command_type <> 'abandon') or p_command_type not in ('move', 'switch', 'item', 'abandon')) then
      raise exception 'admin gym is not waiting for this player command' using errcode = '40001';
    end if;
  end if;
  v_result := server_authority_private.commit_edge_battle_command_before_admin_gyms(
    p_auth_user_id,p_command_id,p_command_type,p_command_hash,p_expected_player_revision,
    p_battle_id,p_expected_battle_version,p_runtime_owner_id,p_engine_version,p_engine_checksum,
    p_input_snapshot_hash,p_next_snapshot,p_events,p_projection,p_terminal_effects);
  if v_contract = 'admin_gym' then
    update public.authoritative_battle set waiting_for = case when status in ('concluded','abandoned') then null
      else p_projection ->> 'waiting_for' end,
      admin_items = coalesce(p_projection -> 'admin_items', admin_items)
      where id = p_battle_id;
    if p_projection ->> 'status' = 'concluded' and p_projection ->> 'result_key' = 'player_win_no_reward' then
      v_reward := server_authority_private.award_terminal_admin_gym_victory(p_auth_user_id,p_battle_id,p_command_id);
      if v_reward is not null then
        v_result := jsonb_set(v_result, '{player_revision}', v_reward #> '{player_state,revision}', true) || v_reward;
        update public.authoritative_battle_command_receipt set result = v_result,
          resulting_player_revision = (v_reward #>> '{player_state,revision}')::bigint
          where auth_user_id = p_auth_user_id and command_id = p_command_id;
      end if;
    end if;
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION "server_authority_private"."commit_edge_battle_command_before_league"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") OWNER TO "postgres";

--
-- Name: commit_edge_battle_command_before_revision_conflict_response("uuid", "uuid", "text", "text", bigint, "uuid", bigint, "uuid", "text", "text", "text", "jsonb", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."commit_edge_battle_command_before_revision_conflict_response"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare v_legacy_snapshot jsonb; v_result jsonb; v_hash text;
begin
  if server_authority_private.edge_jsonb_bigint(p_next_snapshot->'snapshotVersion')<>2 then
    return server_authority_private.commit_edge_battle_command_before_snapshot(
      p_auth_user_id,p_command_id,p_command_type,p_command_hash,p_expected_player_revision,p_battle_id,p_expected_battle_version,
      p_runtime_owner_id,p_engine_version,p_engine_checksum,p_input_snapshot_hash,p_next_snapshot,p_events,p_projection,p_terminal_effects
    );
  end if;
  v_legacy_snapshot:=jsonb_set(p_next_snapshot,'{snapshotVersion}','1'::jsonb,false);
  v_result:=server_authority_private.commit_edge_battle_command_before_snapshot(
    p_auth_user_id,p_command_id,p_command_type,p_command_hash,p_expected_player_revision,p_battle_id,p_expected_battle_version,
    p_runtime_owner_id,p_engine_version,p_engine_checksum,p_input_snapshot_hash,v_legacy_snapshot,p_events,p_projection,p_terminal_effects
  );
  v_hash:=encode(digest(convert_to(p_next_snapshot::text,'UTF8'),'sha256'),'hex');
  update public.authoritative_battle set engine_snapshot=p_next_snapshot,engine_snapshot_hash=v_hash,rng_state=p_next_snapshot->'rng'
    where id=p_battle_id and engine_version=p_engine_version and engine_checksum=p_engine_checksum;
  return v_result;
end;
$$;


ALTER FUNCTION "server_authority_private"."commit_edge_battle_command_before_revision_conflict_response"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") OWNER TO "postgres";

--
-- Name: commit_edge_battle_command_before_snapshot("uuid", "uuid", "text", "text", bigint, "uuid", bigint, "uuid", "text", "text", "text", "jsonb", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."commit_edge_battle_command_before_snapshot"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_battle public.authoritative_battle%rowtype; v_result jsonb; v_replay boolean; v_wins integer; v_record integer;
begin
  select * into strict v_battle from public.authoritative_battle where id=p_battle_id and auth_user_id=p_auth_user_id;
  select exists(select 1 from public.authoritative_battle_command_receipt where auth_user_id=p_auth_user_id and command_id=p_command_id) into v_replay;
  v_result:=server_authority_private.commit_edge_battle_command_before_battle_tower_record(
    p_auth_user_id,p_command_id,p_command_type,p_command_hash,p_expected_player_revision,p_battle_id,p_expected_battle_version,
    p_runtime_owner_id,p_engine_version,p_engine_checksum,p_input_snapshot_hash,p_next_snapshot,p_events,p_projection,p_terminal_effects);
  if v_battle.contract_key<>'battle_tower' or v_replay or p_projection->>'status'<>'concluded'
    or p_projection->>'result_key'<>'player_win_no_reward' then return v_result; end if;
  select wins into v_wins from public.authoritative_battle_tower_run where id=v_battle.tower_run_id;
  update public.player_profile_state set battle_tower_record=greatest(battle_tower_record,coalesce(v_wins,0)),updated_at=now()
    where auth_user_id=p_auth_user_id returning battle_tower_record into v_record;
  v_result:=v_result||jsonb_build_object('tower_record',coalesce(v_record,0),'player_state',server_authority_private.player_state_projection(p_auth_user_id));
  update public.authoritative_battle_command_receipt set result=v_result where auth_user_id=p_auth_user_id and command_id=p_command_id;
  return v_result;
end;
$$;


ALTER FUNCTION "server_authority_private"."commit_edge_battle_command_before_snapshot"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") OWNER TO "postgres";

--
-- Name: commit_edge_battle_command_core("uuid", "uuid", "text", "text", bigint, "uuid", bigint, "uuid", "text", "text", "text", "jsonb", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."commit_edge_battle_command_core"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $_$
declare
  v_battle public.authoritative_battle%rowtype;
  v_receipt public.authoritative_battle_command_receipt%rowtype;
  v_player_revision bigint;
  v_battle_version bigint;
  v_snapshot_hash text;
  v_event jsonb;
  v_participant jsonb;
  v_event_index integer := 0;
  v_status text;
  v_result_key text;
  v_result jsonb;
  v_expected_participants integer;
  v_projected_participants integer;
  v_current_input_hash text;
  v_turn_number bigint;
  v_player_active_slot bigint;
  v_npc_active_slot bigint;
  v_player_active_index bigint;
  v_npc_active_index bigint;
  v_snapshot_roster_count integer;
  v_snapshot_roster_matches boolean;
  v_rng_start jsonb;
  v_rng_end jsonb;
  v_rng_start_draws bigint;
  v_rng_end_draws bigint;
  v_rng_audit jsonb;
  v_global_seq bigint;
  v_committed_events jsonb := '[]'::jsonb;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'service role required' using errcode = '42501';
  end if;
  if p_auth_user_id is null or p_command_id is null or p_battle_id is null or p_runtime_owner_id is null then
    raise exception 'required command identity is missing' using errcode = '22023';
  end if;
  if p_command_type is null or p_command_hash is null or p_input_snapshot_hash is null
    or p_engine_version is null or p_engine_checksum is null
    or p_command_type not in ('initialize', 'move', 'switch', 'entry_choice', 'item', 'abandon')
    or p_command_hash !~ '^[0-9a-f]{64}$'
    or p_input_snapshot_hash !~ '^[0-9a-f]{64}$'
    or p_engine_checksum !~ '^[0-9a-f]{64}$'
    or length(p_engine_version) not between 1 and 80 then
    raise exception 'command metadata is invalid' using errcode = '22023';
  end if;
  if p_expected_player_revision is null or p_expected_battle_version is null
    or p_expected_player_revision < 0 or p_expected_battle_version < 1 then
    raise exception 'expected revisions are invalid' using errcode = '22023';
  end if;
  if p_terminal_effects is distinct from jsonb_build_object('reward', 'none', 'inventory', 'unchanged', 'team', 'unchanged') then
    raise exception 'first Edge slice permits no terminal rewards or persistent mutations' using errcode = '0A000';
  end if;
  if jsonb_typeof(p_next_snapshot) is distinct from 'object' then
    raise exception 'next engine snapshot must be an object' using errcode = '22023';
  end if;
  if octet_length(p_next_snapshot::text) > 524288
    or not (p_next_snapshot ?& array['snapshotVersion', 'engineVersion', 'manager', 'playerTeam', 'enemyTeam', 'rng'])
    or server_authority_private.edge_jsonb_bigint(p_next_snapshot -> 'snapshotVersion') is null
    or server_authority_private.edge_jsonb_bigint(p_next_snapshot -> 'snapshotVersion') <> 1
    or p_next_snapshot ->> 'engineVersion' <> p_engine_version
    or jsonb_typeof(p_next_snapshot -> 'manager') is distinct from 'object'
    or jsonb_typeof(p_next_snapshot -> 'playerTeam') is distinct from 'object'
    or jsonb_typeof(p_next_snapshot -> 'enemyTeam') is distinct from 'object'
    or jsonb_typeof(p_next_snapshot -> 'rng') is distinct from 'object'
    or p_next_snapshot ->> 'engineVersion' is null
    or p_next_snapshot #>> '{rng,algorithm}' is null
    or p_next_snapshot #>> '{rng,algorithm}' <> 'xorshift32-v1'
    or server_authority_private.edge_jsonb_bigint(p_next_snapshot #> '{rng,state}') is null
    or coalesce(server_authority_private.edge_jsonb_bigint(p_next_snapshot #> '{rng,draws}'), -1) < 0 then
    raise exception 'next engine snapshot is invalid' using errcode = '22023';
  end if;
  if jsonb_typeof(p_events) is distinct from 'array' or jsonb_typeof(p_projection) is distinct from 'object' then
    raise exception 'events/projection root schema is invalid' using errcode = '22023';
  end if;
  if jsonb_typeof(p_projection -> 'participants') is distinct from 'array' then
    raise exception 'projection participants must be an array' using errcode = '22023';
  end if;
  if jsonb_array_length(p_events) not between 1 and 128 or octet_length(p_events::text) > 131072
    or octet_length(p_projection::text) > 131072
    or not (p_projection ?& array['status', 'reward_status', 'turn_number', 'first_actor', 'player_active_slot', 'npc_active_slot', 'participants'])
    or jsonb_array_length(p_projection -> 'participants') not between 2 and 12 then
    raise exception 'transition output exceeds its schema bounds' using errcode = '22023';
  end if;
  v_status := p_projection ->> 'status';
  v_result_key := p_projection ->> 'result_key';
  v_turn_number := server_authority_private.edge_jsonb_bigint(p_projection -> 'turn_number');
  v_player_active_slot := server_authority_private.edge_jsonb_bigint(p_projection -> 'player_active_slot');
  v_npc_active_slot := server_authority_private.edge_jsonb_bigint(p_projection -> 'npc_active_slot');
  if v_status is null or v_status not in ('active', 'needs_player_switch', 'concluded', 'abandoned')
    or (v_status in ('concluded', 'abandoned')) <> (v_result_key is not null)
    or (v_result_key is not null and v_result_key not in ('player_win_no_reward', 'player_loss_no_reward', 'abandoned_no_reward'))
    or p_projection ->> 'reward_status' is null
    or p_projection ->> 'reward_status' <> 'disabled_edge_first_slice'
    or p_projection ->> 'first_actor' is null
    or p_projection ->> 'first_actor' not in ('player', 'npc')
    or coalesce(v_turn_number, 0) < 1
    or coalesce(v_player_active_slot, -1) not between 0 and 5
    or coalesce(v_npc_active_slot, -1) not between 0 and 5 then
    raise exception 'battle projection is invalid' using errcode = '22023';
  end if;
  if jsonb_typeof(p_next_snapshot #> '{playerTeam,pokemon}') is distinct from 'array'
    or jsonb_typeof(p_next_snapshot #> '{playerTeam,combatants}') is distinct from 'array'
    or jsonb_typeof(p_next_snapshot #> '{enemyTeam,pokemon}') is distinct from 'array'
    or jsonb_typeof(p_next_snapshot #> '{enemyTeam,combatants}') is distinct from 'array' then
    raise exception 'snapshot roster arrays are missing' using errcode = '22023';
  end if;
  if jsonb_array_length(p_next_snapshot #> '{playerTeam,pokemon}') <> jsonb_array_length(p_next_snapshot #> '{playerTeam,combatants}')
    or jsonb_array_length(p_next_snapshot #> '{enemyTeam,pokemon}') <> jsonb_array_length(p_next_snapshot #> '{enemyTeam,combatants}') then
    raise exception 'snapshot roster arrays are invalid' using errcode = '22023';
  end if;
  v_player_active_index := server_authority_private.edge_jsonb_bigint(p_next_snapshot #> '{playerTeam,state,activeIndex}');
  v_npc_active_index := server_authority_private.edge_jsonb_bigint(p_next_snapshot #> '{enemyTeam,state,activeIndex}');
  if v_player_active_index is null or v_npc_active_index is null
    or v_player_active_index not between 0 and jsonb_array_length(p_next_snapshot #> '{playerTeam,pokemon}') - 1
    or v_npc_active_index not between 0 and jsonb_array_length(p_next_snapshot #> '{enemyTeam,pokemon}') - 1 then
    raise exception 'snapshot active indexes are invalid' using errcode = '22023';
  end if;
  if server_authority_private.edge_jsonb_bigint(
      ((p_next_snapshot #> '{playerTeam,pokemon}') -> v_player_active_index::integer) #> '{state,authoritativeSlot}'
    ) <> v_player_active_slot
    or server_authority_private.edge_jsonb_bigint(
      ((p_next_snapshot #> '{enemyTeam,pokemon}') -> v_npc_active_index::integer) #> '{state,authoritativeSlot}'
    ) <> v_npc_active_slot
    or server_authority_private.edge_jsonb_bigint(p_next_snapshot #> '{manager,turn}') is null
    or server_authority_private.edge_jsonb_bigint(p_next_snapshot #> '{manager,turn}') <> v_turn_number
    or p_next_snapshot #>> '{manager,firstActor}' is null
    or p_next_snapshot #>> '{manager,firstActor}' <> p_projection ->> 'first_actor'
    or server_authority_private.edge_jsonb_boolean(p_next_snapshot #> '{manager,battleOver}') is null
    or server_authority_private.edge_jsonb_boolean(p_next_snapshot #> '{manager,playerNeedsSwitch}') is null
    or server_authority_private.edge_jsonb_boolean(p_next_snapshot #> '{manager,playerPostMoveSwitch}') is null then
    raise exception 'snapshot and projection metadata diverge' using errcode = '22023';
  end if;
  if (v_status in ('concluded', 'abandoned')) <> server_authority_private.edge_jsonb_boolean(p_next_snapshot #> '{manager,battleOver}')
    or (v_status = 'active' and (
      server_authority_private.edge_jsonb_boolean(p_next_snapshot #> '{manager,playerNeedsSwitch}')
      or server_authority_private.edge_jsonb_boolean(p_next_snapshot #> '{manager,playerPostMoveSwitch}')
    ))
    or (v_status = 'needs_player_switch' and not (
      server_authority_private.edge_jsonb_boolean(p_next_snapshot #> '{manager,playerNeedsSwitch}')
      or server_authority_private.edge_jsonb_boolean(p_next_snapshot #> '{manager,playerPostMoveSwitch}')
    )) then
    raise exception 'snapshot and projection phase diverge' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_auth_user_id::text || ':' || p_command_id::text, 0));
  select * into v_receipt from public.authoritative_battle_command_receipt
  where auth_user_id = p_auth_user_id and command_id = p_command_id;
  if found then
    if v_receipt.battle_id <> p_battle_id or v_receipt.command_type <> p_command_type or v_receipt.command_hash <> p_command_hash then
      raise exception 'command id was already used with a different payload' using errcode = '22023';
    end if;
    return v_receipt.result;
  end if;

  select revision into v_player_revision from public.player_state_revision
  where auth_user_id = p_auth_user_id for update;
  if not found then raise exception 'player state does not exist' using errcode = 'P0002'; end if;
  if v_player_revision <> p_expected_player_revision then raise exception 'player revision conflict' using errcode = '40001'; end if;
  select * into v_battle from public.authoritative_battle
  where id = p_battle_id and auth_user_id = p_auth_user_id for update;
  if not found then raise exception 'authoritative battle was not found' using errcode = 'P0002'; end if;
  if v_battle.battle_version <> p_expected_battle_version then raise exception 'battle version conflict' using errcode = '40001'; end if;
  if v_battle.runtime_owner_id <> p_runtime_owner_id then raise exception 'runtime lock is owned by another client' using errcode = '55P03'; end if;
  if v_battle.status not in ('active', 'needs_player_switch') then raise exception 'battle no longer accepts commands' using errcode = '22023'; end if;
  if not exists (
    select 1 from public.catalog_engine_runtime_binding binding
    where binding.catalog_release_id = v_battle.catalog_release_id and binding.enabled
      and binding.engine_version = p_engine_version and binding.engine_checksum = p_engine_checksum
  ) then raise exception 'incompatible active battle engine binding' using errcode = '0A000'; end if;
  v_current_input_hash := server_authority_private.prepare_edge_battle_command_core(p_auth_user_id, p_battle_id) ->> 'input_snapshot_hash';
  if v_current_input_hash <> p_input_snapshot_hash
    or (v_battle.engine_version is not null and v_battle.engine_version <> p_engine_version)
    or (v_battle.engine_checksum is not null and v_battle.engine_checksum <> p_engine_checksum)
    or (v_battle.engine_runtime_state = 'pending') <> (p_command_type = 'initialize') then
    raise exception 'engine snapshot/version conflict' using errcode = '40001';
  end if;

  select count(*) into v_expected_participants from public.authoritative_battle_participant where battle_id = p_battle_id;
  select count(*) into v_projected_participants from (
    select distinct value ->> 'side' as side, value ->> 'slot_index' as slot
    from jsonb_array_elements(p_projection -> 'participants')
  ) projected;
  if jsonb_array_length(p_projection -> 'participants') <> v_expected_participants
    or v_projected_participants <> v_expected_participants then
    raise exception 'projection participant count changed' using errcode = '22023';
  end if;
  for v_participant in select value from jsonb_array_elements(p_projection -> 'participants') loop
    if jsonb_typeof(v_participant) is distinct from 'object'
      or v_participant ->> 'side' not in ('player', 'npc')
      or coalesce(server_authority_private.edge_jsonb_bigint(v_participant -> 'slot_index'), -1) not between 0 and 5
      or coalesce(server_authority_private.edge_jsonb_bigint(v_participant -> 'current_hp'), -1) < 0
      or server_authority_private.edge_jsonb_bigint(v_participant -> 'level') is null
      or server_authority_private.edge_jsonb_bigint(v_participant -> 'max_hp') is null
      or not exists (
        select 1 from public.authoritative_battle_participant participant
        where participant.battle_id = p_battle_id
          and participant.side = v_participant ->> 'side'
          and participant.slot_index = server_authority_private.edge_jsonb_bigint(v_participant -> 'slot_index')
          and participant.species_key = v_participant ->> 'species_key'
          and participant.level = server_authority_private.edge_jsonb_bigint(v_participant -> 'level')
          and participant.max_hp = server_authority_private.edge_jsonb_bigint(v_participant -> 'max_hp')
          and server_authority_private.edge_jsonb_bigint(v_participant -> 'current_hp') <= participant.max_hp
      ) then raise exception 'participant projection is invalid' using errcode = '22023'; end if;
  end loop;
  with snapshot_roster as (
    select 'player'::text as side,
      server_authority_private.edge_jsonb_bigint(pokemon.value #> '{state,authoritativeSlot}') as slot,
      server_authority_private.edge_jsonb_bigint(combatant.value #> '{state,hp}') as hp,
      pokemon.value #>> '{state,speciesKey}' as species_key,
      server_authority_private.edge_jsonb_bigint(pokemon.value #> '{state,level}') as level,
      server_authority_private.edge_jsonb_bigint(pokemon.value #> '{state,maxHp}') as max_hp
    from jsonb_array_elements(p_next_snapshot #> '{playerTeam,pokemon}') with ordinality pokemon(value, ordinality)
    join jsonb_array_elements(p_next_snapshot #> '{playerTeam,combatants}') with ordinality combatant(value, ordinality) using (ordinality)
    union all
    select 'npc'::text,
      server_authority_private.edge_jsonb_bigint(pokemon.value #> '{state,authoritativeSlot}'),
      server_authority_private.edge_jsonb_bigint(combatant.value #> '{state,hp}'),
      pokemon.value #>> '{state,speciesKey}',
      server_authority_private.edge_jsonb_bigint(pokemon.value #> '{state,level}'),
      server_authority_private.edge_jsonb_bigint(pokemon.value #> '{state,maxHp}')
    from jsonb_array_elements(p_next_snapshot #> '{enemyTeam,pokemon}') with ordinality pokemon(value, ordinality)
    join jsonb_array_elements(p_next_snapshot #> '{enemyTeam,combatants}') with ordinality combatant(value, ordinality) using (ordinality)
  )
  select count(*), coalesce(bool_and(roster.slot is not null and roster.hp is not null
    and roster.species_key is not null and roster.level is not null and roster.max_hp is not null and exists (
    select 1 from jsonb_array_elements(p_projection -> 'participants') projected(value)
    where projected.value ->> 'side' = roster.side
      and server_authority_private.edge_jsonb_bigint(projected.value -> 'slot_index') = roster.slot
      and server_authority_private.edge_jsonb_bigint(projected.value -> 'current_hp') = roster.hp
      and projected.value ->> 'species_key' = roster.species_key
      and server_authority_private.edge_jsonb_bigint(projected.value -> 'level') = roster.level
      and server_authority_private.edge_jsonb_bigint(projected.value -> 'max_hp') = roster.max_hp
  )), false)
  into v_snapshot_roster_count, v_snapshot_roster_matches from snapshot_roster roster;
  if v_snapshot_roster_count <> v_expected_participants or not v_snapshot_roster_matches then
    raise exception 'snapshot and participant projection diverge' using errcode = '22023';
  end if;
  for v_event in select value from jsonb_array_elements(p_events) loop
    if jsonb_typeof(v_event) is distinct from 'object'
      or server_authority_private.edge_jsonb_bigint(v_event -> 'sequence') is null
      or server_authority_private.edge_jsonb_bigint(v_event -> 'sequence') <> v_event_index
      or coalesce(v_event ->> 'type', '') !~ '^[a-z][a-z0-9_]{0,47}$'
      or jsonb_typeof(v_event -> 'data') is distinct from 'object' or octet_length((v_event -> 'data')::text) > 8192 then
      raise exception 'display event sequence/schema is invalid' using errcode = '22023';
    end if;
    v_event_index := v_event_index + 1;
  end loop;

  v_snapshot_hash := encode(digest(convert_to(p_next_snapshot::text, 'UTF8'), 'sha256'), 'hex');
  v_rng_start := coalesce(v_battle.engine_snapshot -> 'rng', p_next_snapshot -> 'rng');
  v_rng_end := p_next_snapshot -> 'rng';
  v_rng_start_draws := server_authority_private.edge_jsonb_bigint(v_rng_start -> 'draws');
  v_rng_end_draws := server_authority_private.edge_jsonb_bigint(v_rng_end -> 'draws');
  if v_rng_start_draws is null or v_rng_end_draws is null or v_rng_end_draws < v_rng_start_draws then
    raise exception 'RNG draw counter regressed' using errcode = '22023';
  end if;
  v_rng_audit := jsonb_build_array(jsonb_build_object(
    'start', v_rng_start,
    'end', v_rng_end,
    'draw_delta', v_rng_end_draws - v_rng_start_draws
  ));
  update public.authoritative_battle set
    engine_version = p_engine_version,
    engine_checksum = p_engine_checksum,
    engine_snapshot = p_next_snapshot,
    engine_snapshot_hash = v_snapshot_hash,
    engine_runtime_state = 'ready',
    rng_state = p_next_snapshot -> 'rng',
    status = v_status,
    result_key = v_result_key,
    turn_number = v_turn_number,
    first_actor = p_projection ->> 'first_actor',
    player_active_slot = v_player_active_slot,
    npc_active_slot = v_npc_active_slot,
    battle_version = battle_version + 1,
    concluded_at = case when v_status in ('concluded', 'abandoned') then now() else null end,
    updated_at = now()
  where id = p_battle_id returning battle_version into v_battle_version;
  for v_participant in select value from jsonb_array_elements(p_projection -> 'participants') loop
    update public.authoritative_battle_participant set current_hp = server_authority_private.edge_jsonb_bigint(v_participant -> 'current_hp')
    where battle_id = p_battle_id and side = v_participant ->> 'side'
      and slot_index = server_authority_private.edge_jsonb_bigint(v_participant -> 'slot_index');
  end loop;
  for v_event in select value from jsonb_array_elements(p_events) loop
    v_global_seq := server_authority_private.authoritative_battle_append_event(
      p_battle_id, v_event ->> 'type', v_event -> 'data',
      case when server_authority_private.edge_jsonb_bigint(v_event -> 'sequence') = 0 and p_command_type <> 'initialize' then p_command_id else null end,
      v_rng_audit
    );
    v_committed_events := v_committed_events || jsonb_build_array(v_event || jsonb_build_object(
      'seq', v_global_seq,
      'battle_version', v_battle_version,
      'rng_audit', v_rng_audit
    ));
  end loop;
  update public.player_state_revision set revision = revision + 1, updated_at = now()
  where auth_user_id = p_auth_user_id returning revision into v_player_revision;
  v_result := jsonb_build_object(
    'ok', true,
    'player_revision', v_player_revision,
    'battle_version', v_battle_version,
    'engine_snapshot_hash', v_snapshot_hash,
    'battle', p_projection || jsonb_build_object(
      'mode', 'authoritative_edge',
      'battle_id', p_battle_id,
      'battle_version', v_battle_version,
      'engine_version', p_engine_version,
      'engine_checksum', p_engine_checksum,
      'engine_snapshot_hash', v_snapshot_hash
    ),
    'events', v_committed_events
  );
  insert into public.authoritative_battle_command_receipt(
    auth_user_id, command_id, battle_id, command_type, command_hash, result,
    resulting_player_revision, resulting_battle_version
  ) values (
    p_auth_user_id, p_command_id, p_battle_id, p_command_type, p_command_hash, v_result,
    v_player_revision, v_battle_version
  );
  return v_result;
end;
$_$;


ALTER FUNCTION "server_authority_private"."commit_edge_battle_command_core"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") OWNER TO "postgres";

--
-- Name: commit_edge_battle_command_with_initialization("uuid", "uuid", "text", "text", bigint, "uuid", bigint, "uuid", "text", "text", "text", "jsonb", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."commit_edge_battle_command_with_initialization"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_contract text; v_requested_version text; v_requested_checksum text;
  v_commit_input_hash text := p_input_snapshot_hash;
  v_receipt public.authoritative_battle_command_receipt%rowtype;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_auth_user_id::text || ':' || p_command_id::text, 0));
  select * into v_receipt from public.authoritative_battle_command_receipt
    where auth_user_id = p_auth_user_id and command_id = p_command_id;
  if found then
    if v_receipt.battle_id <> p_battle_id or v_receipt.command_type <> p_command_type
      or v_receipt.command_hash <> p_command_hash then
      raise exception 'command id was already used with a different payload' using errcode = '22023';
    end if;
    return v_receipt.result;
  end if;
  select contract_key, requested_engine_version, requested_engine_checksum
    into v_contract, v_requested_version, v_requested_checksum
  from public.authoritative_battle where id = p_battle_id and auth_user_id = p_auth_user_id;
  if v_contract = 'training' and p_command_type = 'initialize' then
    if v_requested_version <> p_engine_version or v_requested_checksum <> p_engine_checksum then
      raise exception 'training initialization engine identity changed' using errcode = '40001';
    end if;
    perform server_authority_private.adopt_edge_training_initialization(p_auth_user_id, p_battle_id, p_next_snapshot, p_projection);
    v_commit_input_hash := server_authority_private.prepare_edge_battle_command_core(p_auth_user_id, p_battle_id) ->> 'input_snapshot_hash';
  end if;
  perform server_authority_private.validate_edge_battle_roster_bijection(p_battle_id, p_next_snapshot, p_projection);
  return server_authority_private.commit_edge_battle_command_core(p_auth_user_id, p_command_id, p_command_type,
    p_command_hash, p_expected_player_revision, p_battle_id, p_expected_battle_version,
    p_runtime_owner_id, p_engine_version, p_engine_checksum, v_commit_input_hash,
    p_next_snapshot, p_events, p_projection, p_terminal_effects);
end;
$$;


ALTER FUNCTION "server_authority_private"."commit_edge_battle_command_with_initialization"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") OWNER TO "postgres";

--
-- Name: commit_edge_battle_command_without_items("uuid", "uuid", "text", "text", bigint, "uuid", bigint, "uuid", "text", "text", "text", "jsonb", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."commit_edge_battle_command_without_items"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_result jsonb; v_player jsonb; v_replay boolean;
begin
  select exists(select 1 from public.authoritative_battle_command_receipt
    where auth_user_id=p_auth_user_id and command_id=p_command_id) into v_replay;
  v_result:=server_authority_private.commit_edge_battle_command_with_initialization(p_auth_user_id,p_command_id,p_command_type,p_command_hash,
    p_expected_player_revision,p_battle_id,p_expected_battle_version,p_runtime_owner_id,p_engine_version,p_engine_checksum,
    p_input_snapshot_hash,p_next_snapshot,p_events,p_projection,p_terminal_effects);
  if not v_replay and p_projection->>'status'='concluded' and p_projection->>'result_key'='player_win_no_reward'
    and exists(select 1 from public.authoritative_battle where id=p_battle_id and auth_user_id=p_auth_user_id and contract_key='training') then
    v_player:=server_authority_private.award_terminal_training_progression(p_auth_user_id,p_battle_id,p_command_id);
    if v_player is not null then
      v_result:=jsonb_set(v_result,'{player_revision}',v_player->'revision',true)
        || jsonb_build_object('player_state',v_player,'training_progression',v_player->'training_progression');
      update public.authoritative_battle_command_receipt set result=v_result,
        resulting_player_revision=(v_player->>'revision')::bigint
      where auth_user_id=p_auth_user_id and command_id=p_command_id;
    end if;
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION "server_authority_private"."commit_edge_battle_command_without_items"("p_auth_user_id" "uuid", "p_command_id" "uuid", "p_command_type" "text", "p_command_hash" "text", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_engine_version" "text", "p_engine_checksum" "text", "p_input_snapshot_hash" "text", "p_next_snapshot" "jsonb", "p_events" "jsonb", "p_projection" "jsonb", "p_terminal_effects" "jsonb") OWNER TO "postgres";

--
-- Name: create_terminal_ordinary_progression("uuid", "uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."create_terminal_ordinary_progression"("p_auth_user_id" "uuid", "p_battle_id" "uuid", "p_command_id" "uuid", "p_awards" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare v_battle public.authoritative_battle%rowtype; v_profile public.player_profile_state%rowtype; v_progression public.player_ordinary_progression%rowtype;
  v_award jsonb; v_instance public.player_pokemon_instance%rowtype; v_revision bigint; v_badges integer; v_order integer:=0;
  v_receipt public.player_command_receipt%rowtype; v_hash text;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'service role required' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_auth_user_id::text||':ordinary_progression',0));
  select * into strict v_battle from public.authoritative_battle where id=p_battle_id and auth_user_id=p_auth_user_id for update;
  if v_battle.contract_key not in ('gym','admin_gym','league','capture') or v_battle.status<>'concluded'
    or v_battle.result_key<>'player_win_no_reward' then return null; end if;
  if jsonb_typeof(p_awards)<>'array' then raise exception 'ordinary EXP awards must be an array' using errcode='22023'; end if;
  select * into v_progression from public.player_ordinary_progression where battle_id=p_battle_id;
  if found then return server_authority_private.player_state_projection(p_auth_user_id); end if;
  if jsonb_array_length(p_awards)=0 then return null; end if;
  if exists(select 1 from public.player_ordinary_progression where auth_user_id=p_auth_user_id and status<>'completed') then
    raise exception 'another ordinary progression is pending' using errcode='55000'; end if;
  select * into strict v_profile from public.player_profile_state where auth_user_id=p_auth_user_id for update;
  v_badges:=least(8,greatest(0,v_profile.badges-case when v_battle.contract_key in ('gym','admin_gym')
    and exists(select 1 from public.player_gym_victory where battle_id=p_battle_id) then 1 else 0 end));
  select revision into strict v_revision from public.player_state_revision where auth_user_id=p_auth_user_id for update;
  insert into public.player_ordinary_progression(auth_user_id,battle_id,catalog_release_id,contract_key,badge_count,level_cap,status,terminal_command_id)
  values(p_auth_user_id,p_battle_id,v_battle.catalog_release_id,v_battle.contract_key,v_badges,
    (array[14,20,30,40,50,60,70,80,100])[v_badges+1],'awaiting_choices',p_command_id) returning * into v_progression;
  for v_award in select value from jsonb_array_elements(p_awards) loop
    if jsonb_typeof(v_award)<>'object' or v_award-'pokemon_instance_id'-'team_slot'-'exp'-'ko_count'<>'{}'::jsonb
      or server_authority_private.edge_jsonb_bigint(v_award->'exp')<=0 or server_authority_private.edge_jsonb_bigint(v_award->'ko_count')<=0 then
      raise exception 'ordinary EXP award shape is invalid' using errcode='22023'; end if;
    select * into strict v_instance from public.player_pokemon_instance where id=(v_award->>'pokemon_instance_id')::uuid and auth_user_id=p_auth_user_id for update;
    if not exists(select 1 from public.authoritative_battle_participant where battle_id=p_battle_id and side='player'
      and pokemon_instance_id=v_instance.id and slot_index=server_authority_private.edge_jsonb_bigint(v_award->'team_slot')) then
      raise exception 'ordinary EXP target is not a canonical battle participant' using errcode='22023'; end if;
    update public.player_pokemon_instance set state=jsonb_set(state,'{xp}',to_jsonb(coalesce(server_authority_private.edge_jsonb_bigint(state->'xp'),0)
      +server_authority_private.edge_jsonb_bigint(v_award->'exp')),true),revision=revision+1,updated_at=now() where id=v_instance.id;
    insert into public.player_ordinary_progression_pokemon(progression_id,auth_user_id,pokemon_instance_id,award_order,team_slot,
      exp_awarded,ko_count,starting_species_key,starting_level,frozen_instance_revision,status)
    values(v_progression.id,p_auth_user_id,v_instance.id,v_order,server_authority_private.edge_jsonb_bigint(v_award->'team_slot'),
      server_authority_private.edge_jsonb_bigint(v_award->'exp'),server_authority_private.edge_jsonb_bigint(v_award->'ko_count'),
      v_instance.species_key,server_authority_private.edge_jsonb_bigint(v_instance.state->'l'),v_instance.revision+1,'pending');
    v_order:=v_order+1;
  end loop;
  perform server_authority_private.advance_ordinary_progression(p_auth_user_id,v_progression.id,v_revision+1);
  update public.player_state_revision set revision=revision+1,updated_at=now() where auth_user_id=p_auth_user_id returning revision into v_revision;
  select * into v_receipt from public.player_command_receipt where auth_user_id=p_auth_user_id and command_id=p_command_id;
  if not found then
    v_hash:=encode(digest(convert_to(jsonb_build_object('battle_id',p_battle_id,'ordinary_exp_awards',p_awards)::text,'UTF8'),'sha256'),'hex');
    insert into public.player_command_receipt(auth_user_id,command_id,command_type,request_hash,result,resulting_revision)
    values(p_auth_user_id,p_command_id,'ordinary_terminal_effect',v_hash,
      jsonb_build_object('battle_id',p_battle_id,'progression_id',v_progression.id,'awards',p_awards),v_revision);
  end if;
  perform server_authority_private.emit_ordinary_level_events(p_auth_user_id,v_progression.id,p_command_id);
  perform server_authority_private.authoritative_battle_append_event(p_battle_id,'ordinary_exp_awarded',
    jsonb_build_object('progression_id',v_progression.id,'awards',p_awards),p_command_id,'[]'::jsonb);
  return server_authority_private.player_state_projection(p_auth_user_id);
end;
$$;


ALTER FUNCTION "server_authority_private"."create_terminal_ordinary_progression"("p_auth_user_id" "uuid", "p_battle_id" "uuid", "p_command_id" "uuid", "p_awards" "jsonb") OWNER TO "postgres";

--
-- Name: daycare_projection("uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."daycare_projection"("p_auth_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'slot_index', placement.slot_index,
      'pokemon', pokemon.state || jsonb_build_object(
        'instance_id', pokemon.id,
        'instance_revision', pokemon.revision,
        'catalog_release_id', pokemon.catalog_release_id
      ),
      'deposited_at', daycare.deposited_at,
      'starting_level', daycare.starting_level,
      'status', daycare.status,
      'pending_levels', calculated.levels,
      'cost', case when daycare.status = 'withdraw_pending' then daycare.pending_cost
        else rule.withdraw_base_cost + calculated.levels * rule.withdraw_level_cost end,
      'elapsed_intervals', calculated.elapsed_intervals,
      'level_cap', calculated.level_cap,
      'server_time', statement_timestamp(),
      'pending_resolution_id', daycare.pending_resolution_id
    ) order by placement.slot_index
  ), '[]'::jsonb)
  from public.player_pokemon_placement placement
  join public.player_pokemon_instance pokemon
    on pokemon.id = placement.pokemon_instance_id
   and pokemon.auth_user_id = placement.auth_user_id
  join public.player_daycare_state daycare
    on daycare.pokemon_instance_id = pokemon.id
   and daycare.auth_user_id = pokemon.auth_user_id
  join public.player_profile_state profile on profile.auth_user_id = pokemon.auth_user_id
  join public.catalog_daycare_rule rule on rule.catalog_release_id = pokemon.catalog_release_id
  cross join lateral (
    select
      greatest(0, floor(extract(epoch from (statement_timestamp() - daycare.deposited_at)) / rule.level_interval_seconds))::integer as elapsed_intervals,
      rule.badge_level_limits[least(8, greatest(0, profile.badges)) + 1] as level_cap
  ) elapsed
  cross join lateral (
    select elapsed.elapsed_intervals,
      elapsed.level_cap,
      case when daycare.status = 'withdraw_pending' then daycare.pending_levels::integer
      else least(
        elapsed.elapsed_intervals,
        rule.max_pending_levels,
        greatest(0, elapsed.level_cap - coalesce((pokemon.state ->> 'l')::integer, daycare.starting_level))
      ) end as levels
  ) calculated
  where placement.auth_user_id = p_auth_user_id
    and placement.placement_type = 'daycare';
$$;


ALTER FUNCTION "server_authority_private"."daycare_projection"("p_auth_user_id" "uuid") OWNER TO "postgres";

--
-- Name: edge_jsonb_bigint("jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."edge_jsonb_bigint"("p_value" "jsonb") RETURNS bigint
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $_$
begin
  if jsonb_typeof(p_value) <> 'number' or p_value::text !~ '^-?(0|[1-9][0-9]*)$' then return null; end if;
  return p_value::text::bigint;
exception when numeric_value_out_of_range or invalid_text_representation then
  return null;
end;
$_$;


ALTER FUNCTION "server_authority_private"."edge_jsonb_bigint"("p_value" "jsonb") OWNER TO "postgres";

--
-- Name: edge_jsonb_boolean("jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."edge_jsonb_boolean"("p_value" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
  select case when jsonb_typeof(p_value) = 'boolean' then p_value::text::boolean else null end
$$;


ALTER FUNCTION "server_authority_private"."edge_jsonb_boolean"("p_value" "jsonb") OWNER TO "postgres";

--
-- Name: emit_ordinary_level_events("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."emit_ordinary_level_events"("p_auth_user_id" "uuid", "p_progression_id" "uuid", "p_command_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_receipt public.player_command_receipt%rowtype; v_entry record; v_species text;
begin
  select * into v_receipt from public.player_command_receipt where auth_user_id=p_auth_user_id and command_id=p_command_id;
  if not found then return; end if;
  for v_entry in select * from public.player_ordinary_progression_pokemon where progression_id=p_progression_id
    and levels_gained>levels_reported order by award_order for update loop
    select species_key into v_species from public.player_pokemon_instance where id=v_entry.pokemon_instance_id;
    perform server_authority_private.apply_mission_fact(v_receipt.auth_user_id,'pokemon-level-up',
      jsonb_build_object('speciesKey',v_species,'levels',v_entry.levels_gained-v_entry.levels_reported,'source','ordinary'),
      v_receipt.created_at);
    update public.player_ordinary_progression_pokemon set levels_reported=levels_gained
      where progression_id=p_progression_id and pokemon_instance_id=v_entry.pokemon_instance_id;
  end loop;
end;
$$;


ALTER FUNCTION "server_authority_private"."emit_ordinary_level_events"("p_auth_user_id" "uuid", "p_progression_id" "uuid", "p_command_id" "uuid") OWNER TO "postgres";

--
-- Name: enforce_username_server_role(); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."enforce_username_server_role"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'server_authority_private', 'pg_temp'
    AS $$
declare v_username_normalized text;
begin
  select username_normalized into v_username_normalized
  from public.player_auth_recovery
  where auth_user_id = new.auth_user_id;

  if (new.role_key = 'admin' and v_username_normalized is distinct from 'admin')
    or (new.role_key = 'debug' and v_username_normalized is distinct from 'aaa') then
    raise exception 'server role does not match canonical username' using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "server_authority_private"."enforce_username_server_role"() OWNER TO "postgres";

--
-- Name: execute_authoritative_battle_command("text", "uuid", bigint, "uuid", bigint, "uuid", integer); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."execute_authoritative_battle_command"("p_command_type" "text", "p_command_id" "uuid", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_semantic_slot" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare
  v_auth_user_id uuid := auth.uid();
  v_request jsonb;
  v_hash text;
  v_receipt public.player_command_receipt%rowtype;
  v_player_revision bigint;
  v_battle public.authoritative_battle%rowtype;
  v_hit jsonb;
  v_phase text;
  v_forced_switch boolean;
  v_result jsonb;
begin
  if v_auth_user_id is null then raise exception 'authentication required' using errcode = '28000'; end if;
  if p_command_type not in ('authoritative_battle_move', 'authoritative_battle_switch', 'authoritative_battle_abandon') then
    raise exception 'authoritative battle command is unsupported' using errcode = '0A000';
  end if;
  if p_command_id is null or p_battle_id is null or p_runtime_owner_id is null then
    raise exception 'command, battle, and runtime owner ids are required' using errcode = '22023';
  end if;
  if p_expected_player_revision is null or p_expected_player_revision < 0
    or p_expected_battle_version is null or p_expected_battle_version < 1 then
    raise exception 'expected versions are invalid' using errcode = '22023';
  end if;
  if p_command_type in ('authoritative_battle_move', 'authoritative_battle_switch')
    and (p_semantic_slot is null or p_semantic_slot < 0 or p_semantic_slot > 5) then
    raise exception 'semantic slot is invalid' using errcode = '22023';
  end if;
  if p_command_type = 'authoritative_battle_abandon' and p_semantic_slot is not null then
    raise exception 'abandon does not accept a slot' using errcode = '22023';
  end if;
  v_request := jsonb_build_object('command_type', p_command_type,
    'expected_player_revision', p_expected_player_revision, 'battle_id', p_battle_id,
    'expected_battle_version', p_expected_battle_version, 'runtime_owner_id', p_runtime_owner_id,
    'semantic_slot', p_semantic_slot);
  v_hash := encode(digest(convert_to(v_request::text, 'UTF8'), 'sha256'), 'hex');
  perform pg_advisory_xact_lock(hashtextextended(v_auth_user_id::text || ':' || p_command_id::text, 0));
  select * into v_receipt from public.player_command_receipt
  where auth_user_id = v_auth_user_id and command_id = p_command_id;
  if found then
    if v_receipt.command_type <> p_command_type or v_receipt.request_hash <> v_hash then
      raise exception 'command id was already used with a different payload' using errcode = '22023';
    end if;
    return v_receipt.result;
  end if;
  select revision into v_player_revision from public.player_state_revision
  where auth_user_id = v_auth_user_id for update;
  if not found or v_player_revision <> p_expected_player_revision then
    raise exception 'player revision conflict' using errcode = '40001';
  end if;
  select * into v_battle from public.authoritative_battle
  where id = p_battle_id and auth_user_id = v_auth_user_id for update;
  if not found then raise exception 'authoritative battle was not found' using errcode = 'P0002'; end if;
  if v_battle.battle_version <> p_expected_battle_version then
    raise exception 'battle version conflict: expected %, current %', p_expected_battle_version, v_battle.battle_version using errcode = '40001';
  end if;
  if v_battle.runtime_owner_id <> p_runtime_owner_id then
    raise exception 'runtime lock is owned by another client' using errcode = '55P03';
  end if;
  if v_battle.status not in ('active', 'needs_player_switch') then
    raise exception 'battle no longer accepts commands' using errcode = '22023';
  end if;

  update public.authoritative_battle set battle_version = battle_version + 1, updated_at = now()
  where id = p_battle_id;
  perform server_authority_private.authoritative_battle_append_event(p_battle_id, 'command_accepted',
    jsonb_build_object('command_type', p_command_type, 'semantic_slot', p_semantic_slot), p_command_id);

  if p_command_type = 'authoritative_battle_abandon' then
    update public.authoritative_battle set status = 'abandoned', result_key = 'abandoned_no_reward',
      concluded_at = now(), updated_at = now() where id = p_battle_id;
    perform server_authority_private.authoritative_battle_append_event(p_battle_id, 'battle_abandoned',
      jsonb_build_object('result_key', 'abandoned_no_reward', 'reward_status', 'disabled_first_slice'));
  elsif p_command_type = 'authoritative_battle_move' then
    if v_battle.status <> 'active' then
      raise exception 'a replacement Pokemon must be selected before moving' using errcode = '22023';
    end if;
    if p_semantic_slot > 3 then raise exception 'move slot is invalid' using errcode = '22023'; end if;
    if v_battle.first_actor = 'npc' then
      v_hit := server_authority_private.authoritative_battle_apply_azione(p_battle_id, 'npc', 0);
      v_phase := server_authority_private.authoritative_battle_advance_after_hit(p_battle_id, v_hit);
    end if;
    if coalesce(v_phase, 'active') = 'active' then
      v_hit := server_authority_private.authoritative_battle_apply_azione(p_battle_id, 'player', p_semantic_slot);
      v_phase := server_authority_private.authoritative_battle_advance_after_hit(p_battle_id, v_hit);
    end if;
    if coalesce(v_phase, 'active') = 'active' and v_battle.first_actor = 'player' then
      v_hit := server_authority_private.authoritative_battle_apply_azione(p_battle_id, 'npc', 0);
      v_phase := server_authority_private.authoritative_battle_advance_after_hit(p_battle_id, v_hit);
    end if;
    update public.authoritative_battle set turn_number = turn_number + 1, updated_at = now()
    where id = p_battle_id;
  else
    v_forced_switch := v_battle.status = 'needs_player_switch';
    if p_semantic_slot = v_battle.player_active_slot then
      raise exception 'selected Pokemon is already active' using errcode = '22023';
    end if;
    if not exists (select 1 from public.authoritative_battle_participant
      where battle_id = p_battle_id and side = 'player' and slot_index = p_semantic_slot and current_hp > 0) then
      raise exception 'switch target is missing or fainted' using errcode = '22023';
    end if;
    if not v_forced_switch and v_battle.first_actor = 'npc' then
      v_hit := server_authority_private.authoritative_battle_apply_azione(p_battle_id, 'npc', 0);
      v_phase := server_authority_private.authoritative_battle_advance_after_hit(p_battle_id, v_hit);
    end if;
    if coalesce(v_phase, 'active') = 'active' then
      update public.authoritative_battle set player_active_slot = p_semantic_slot,
        status = 'active', updated_at = now() where id = p_battle_id;
      perform server_authority_private.authoritative_battle_append_event(p_battle_id, 'player_switched',
        jsonb_build_object('from_slot', v_battle.player_active_slot, 'to_slot', p_semantic_slot,
          'forced', v_forced_switch));
      if not v_forced_switch and v_battle.first_actor = 'player' then
        v_hit := server_authority_private.authoritative_battle_apply_azione(p_battle_id, 'npc', 0);
        v_phase := server_authority_private.authoritative_battle_advance_after_hit(p_battle_id, v_hit);
      end if;
    end if;
    if not v_forced_switch then
      update public.authoritative_battle set turn_number = turn_number + 1, updated_at = now()
      where id = p_battle_id;
    end if;
  end if;

  update public.player_state_revision set revision = revision + 1, updated_at = now()
  where auth_user_id = v_auth_user_id returning revision into v_player_revision;
  v_result := jsonb_build_object('player_revision', v_player_revision,
    'battle', server_authority_private.authoritative_battle_projection(v_auth_user_id, p_battle_id));
  insert into public.player_command_receipt(auth_user_id, command_id, command_type, request_hash,
    result, resulting_revision) values (v_auth_user_id, p_command_id, p_command_type, v_hash,
      v_result, v_player_revision);
  return v_result;
end;
$$;


ALTER FUNCTION "server_authority_private"."execute_authoritative_battle_command"("p_command_type" "text", "p_command_id" "uuid", "p_expected_player_revision" bigint, "p_battle_id" "uuid", "p_expected_battle_version" bigint, "p_runtime_owner_id" "uuid", "p_semantic_slot" integer) OWNER TO "postgres";

--
-- Name: execute_daycare_command("text", "uuid", bigint, "uuid", integer); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."execute_daycare_command"("p_command_type" "text", "p_command_id" "uuid", "p_expected_revision" bigint, "p_pokemon_instance_id" "uuid", "p_slot_index" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
begin
  perform server_authority_private.assert_no_pending_ordinary_progression(auth.uid(),p_command_id);
  return server_authority_private.execute_daycare_command_before_ordinary_guard(
    p_command_type,p_command_id,p_expected_revision,p_pokemon_instance_id,p_slot_index);
end;
$$;


ALTER FUNCTION "server_authority_private"."execute_daycare_command"("p_command_type" "text", "p_command_id" "uuid", "p_expected_revision" bigint, "p_pokemon_instance_id" "uuid", "p_slot_index" integer) OWNER TO "postgres";

--
-- Name: execute_daycare_command_before_ordinary_guard("text", "uuid", bigint, "uuid", integer); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."execute_daycare_command_before_ordinary_guard"("p_command_type" "text", "p_command_id" "uuid", "p_expected_revision" bigint, "p_pokemon_instance_id" "uuid", "p_slot_index" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $_$
declare
  v_auth_user_id uuid := auth.uid();
  v_request jsonb;
  v_request_hash text;
  v_receipt_type text;
  v_receipt_hash text;
  v_receipt_result jsonb;
  v_current_revision bigint;
  v_profile public.player_profile_state%rowtype;
  v_instance public.player_pokemon_instance%rowtype;
  v_placement public.player_pokemon_placement%rowtype;
  v_daycare public.player_daycare_state%rowtype;
  v_rule public.catalog_daycare_rule%rowtype;
  v_team_count integer;
  v_level integer;
  v_level_cap integer;
  v_elapsed integer;
  v_levels integer;
  v_target_level integer;
  v_cost bigint;
  v_same_species_count integer;
  v_same_item_count integer;
  v_held_item_index integer;
  v_has_move_choice boolean;
  v_has_evolution_choice boolean;
  v_resolution_id uuid;
  v_resolution_options jsonb;
  v_moves jsonb;
  v_level_rule public.catalog_level_rule%rowtype;
  v_shift_slot integer;
  v_result jsonb;
begin
  if v_auth_user_id is null then
    raise exception 'authentication required' using errcode = '28000';
  end if;
  if p_command_type not in ('daycare_deposit', 'daycare_withdraw') then
    raise exception 'daycare command type is not allowed' using errcode = '22023';
  end if;
  if p_command_id is null or p_pokemon_instance_id is null then
    raise exception 'command id and Pokemon instance id are required' using errcode = '22023';
  end if;
  if p_expected_revision is null or p_expected_revision < 0 then
    raise exception 'expected revision must be non-negative' using errcode = '22023';
  end if;
  if p_command_type = 'daycare_deposit' and (p_slot_index is null or p_slot_index not between 0 and 1) then
    raise exception 'daycare slot must be between 0 and 1' using errcode = '22023';
  end if;
  if p_command_type = 'daycare_withdraw' and p_slot_index is not null then
    raise exception 'daycare slot is not accepted for withdrawal' using errcode = '22023';
  end if;

  v_request := jsonb_build_object(
    'command_type', p_command_type,
    'expected_revision', p_expected_revision,
    'pokemon_instance_id', p_pokemon_instance_id,
    'slot_index', p_slot_index
  );
  v_request_hash := encode(digest(convert_to(v_request::text, 'UTF8'), 'sha256'), 'hex');
  perform pg_advisory_xact_lock(hashtextextended(v_auth_user_id::text || ':' || p_command_id::text, 0));

  select command_type, request_hash, result
  into v_receipt_type, v_receipt_hash, v_receipt_result
  from public.player_command_receipt
  where auth_user_id = v_auth_user_id and command_id = p_command_id;
  if found then
    if v_receipt_type <> p_command_type or v_receipt_hash <> v_request_hash then
      raise exception 'command id was already used with a different payload' using errcode = '22023';
    end if;
    return v_receipt_result;
  end if;

  select revision into v_current_revision
  from public.player_state_revision
  where auth_user_id = v_auth_user_id
  for update;
  if not found then
    raise exception 'player state does not exist' using errcode = 'P0002';
  end if;
  if v_current_revision <> p_expected_revision then
    raise exception 'revision conflict: expected %, current %', p_expected_revision, v_current_revision using errcode = '40001';
  end if;

  select * into v_profile from public.player_profile_state
  where auth_user_id = v_auth_user_id for update;
  if not found then
    raise exception 'player profile does not exist' using errcode = 'P0002';
  end if;

  -- Every team and daycare placement/instance is locked in UUID order so team
  -- compaction and composition checks share the team/box command lock order.
  perform 1
  from public.player_pokemon_placement placement
  join public.player_pokemon_instance pokemon
    on pokemon.id = placement.pokemon_instance_id and pokemon.auth_user_id = placement.auth_user_id
  where placement.auth_user_id = v_auth_user_id
    and (placement.placement_type in ('team', 'daycare') or placement.pokemon_instance_id = p_pokemon_instance_id)
  order by placement.pokemon_instance_id
  for update of placement, pokemon;

  perform 1 from public.player_daycare_state daycare
  where daycare.auth_user_id = v_auth_user_id
  order by daycare.pokemon_instance_id for update;

  select * into v_instance from public.player_pokemon_instance
  where id = p_pokemon_instance_id and auth_user_id = v_auth_user_id;
  if not found then
    raise exception 'Pokemon instance is not owned by the current player' using errcode = '22023';
  end if;
  select * into v_placement from public.player_pokemon_placement
  where pokemon_instance_id = p_pokemon_instance_id and auth_user_id = v_auth_user_id;
  if not found then
    raise exception 'Pokemon placement was not found' using errcode = 'P0002';
  end if;
  select * into v_rule from public.catalog_daycare_rule
  where catalog_release_id = v_instance.catalog_release_id;
  if not found then
    raise exception 'daycare rules are missing for the Pokemon catalog release' using errcode = 'P0002';
  end if;

  v_level := case when coalesce(v_instance.state ->> 'l', '') ~ '^[1-9][0-9]*$'
    then (v_instance.state ->> 'l')::integer else 0 end;
  if v_level not between 1 and 100 then
    raise exception 'canonical Pokemon level is invalid' using errcode = '22023';
  end if;
  v_level_cap := v_rule.badge_level_limits[least(8, greatest(0, v_profile.badges)) + 1];
  select count(*) into v_team_count from public.player_pokemon_placement
  where auth_user_id = v_auth_user_id and placement_type = 'team';

  if p_command_type = 'daycare_deposit' then
    if v_placement.placement_type <> 'team' then
      raise exception 'Pokemon is not currently in the team' using errcode = '22023';
    end if;
    if v_team_count <= 1 then
      raise exception 'at least one Pokemon must remain in the team' using errcode = '22023';
    end if;
    if v_level >= 100 or v_level >= v_level_cap then
      raise exception 'Pokemon is already at the current daycare level cap' using errcode = '22023';
    end if;
    if exists (select 1 from public.player_pokemon_placement where auth_user_id = v_auth_user_id and placement_type = 'daycare' and slot_index = p_slot_index) then
      raise exception 'daycare slot is already occupied' using errcode = '23505';
    end if;

    insert into public.player_daycare_state (
      pokemon_instance_id, auth_user_id, catalog_release_id, deposited_at, starting_level
    ) values (
      p_pokemon_instance_id, v_auth_user_id, v_instance.catalog_release_id, clock_timestamp(), v_level
    );

    update public.player_pokemon_placement set
      placement_type = 'daycare', slot_index = p_slot_index, box_index = null, updated_at = now()
    where pokemon_instance_id = p_pokemon_instance_id;

    if v_placement.slot_index < v_team_count - 1 then
      for v_shift_slot in v_placement.slot_index + 1..v_team_count - 1 loop
        update public.player_pokemon_placement set slot_index = v_shift_slot - 1, updated_at = now()
        where auth_user_id = v_auth_user_id and placement_type = 'team' and slot_index = v_shift_slot;
      end loop;
    end if;
  else
    if v_placement.placement_type <> 'daycare' then
      raise exception 'Pokemon is not currently in daycare' using errcode = '22023';
    end if;
    select * into v_daycare from public.player_daycare_state
    where pokemon_instance_id = p_pokemon_instance_id and auth_user_id = v_auth_user_id;
    if not found then
      raise exception 'canonical daycare metadata was not found' using errcode = 'P0002';
    end if;
    if v_daycare.status = 'withdraw_pending' then
      raise exception 'daycare withdrawal already requires a pending resolution' using errcode = '55000';
    end if;
    if v_team_count >= 6 then
      raise exception 'team is full' using errcode = '22023';
    end if;

    select count(*) into v_same_species_count
    from public.player_pokemon_placement placement
    join public.player_pokemon_instance pokemon on pokemon.id = placement.pokemon_instance_id
    where placement.auth_user_id = v_auth_user_id and placement.placement_type = 'team'
      and pokemon.species_key = v_instance.species_key;
    if v_same_species_count >= 2 then
      raise exception 'team cannot contain more than two Pokemon of the same species' using errcode = '22023';
    end if;
    v_held_item_index := case when coalesce(v_instance.state ->> 'i', '') ~ '^[1-9][0-9]*$'
      then (v_instance.state ->> 'i')::integer else 0 end;
    if v_held_item_index > 0 then
      select count(*) into v_same_item_count
      from public.player_pokemon_placement placement
      join public.player_pokemon_instance pokemon on pokemon.id = placement.pokemon_instance_id
      where placement.auth_user_id = v_auth_user_id and placement.placement_type = 'team'
        and case when coalesce(pokemon.state ->> 'i', '') ~ '^[1-9][0-9]*$'
          then (pokemon.state ->> 'i')::integer else 0 end = v_held_item_index;
      if v_same_item_count >= 2 then
        raise exception 'team cannot contain more than two Pokemon holding the same item' using errcode = '22023';
      end if;
    end if;

    v_elapsed := greatest(0, floor(extract(epoch from (clock_timestamp() - v_daycare.deposited_at)) / v_rule.level_interval_seconds))::integer;
    v_levels := least(v_elapsed, v_rule.max_pending_levels, greatest(0, v_level_cap - v_level));
    v_target_level := v_level + v_levels;
    v_cost := v_rule.withdraw_base_cost::bigint + v_levels::bigint * v_rule.withdraw_level_cost::bigint;
    if v_profile.pokedollars < v_cost then
      raise exception 'insufficient Pokedollars for daycare withdrawal' using errcode = '22023';
    end if;

    select exists (
      select 1 from public.catalog_species_level_move move
      where move.catalog_release_id = v_instance.catalog_release_id
        and move.species_key = v_instance.species_key
        and move.level > v_level and move.level <= v_target_level
        and not exists (
          select 1 from jsonb_array_elements(coalesce(v_instance.state -> 'm', '[]'::jsonb)) known
          where (known ->> 0)::integer = move.move_index
        )
    ) into v_has_move_choice;
    select exists (
      select 1 from public.catalog_species_evolution evolution
      where evolution.catalog_release_id = v_instance.catalog_release_id
        and evolution.species_key = v_instance.species_key
        and evolution.trigger_key = 'level'
        and coalesce((evolution.trigger_rules ->> 'level')::integer, 101) <= v_target_level
    ) into v_has_evolution_choice;

    update public.player_profile_state set pokedollars = pokedollars - v_cost, updated_at = now()
    where auth_user_id = v_auth_user_id;

    if v_has_move_choice or v_has_evolution_choice then
      v_resolution_options := jsonb_build_object(
        'source', 'daycare_withdrawal',
        'daycare_slot_index', v_placement.slot_index,
        'starting_level', v_level,
        'target_level', v_target_level,
        'levels_gained', v_levels,
        'charged_cost', v_cost,
        'level_cap', v_level_cap,
        'level_moves', coalesce((
          select jsonb_agg(jsonb_build_object(
            'level', move.level, 'move_index', move.move_index,
            'move_order', move.move_order, 'name', catalog_move.display_name
          ) order by move.level, move.move_order)
          from public.catalog_species_level_move move
          join public.catalog_move catalog_move
            on catalog_move.catalog_release_id = move.catalog_release_id and catalog_move.move_index = move.move_index
          where move.catalog_release_id = v_instance.catalog_release_id
            and move.species_key = v_instance.species_key
            and move.level > v_level and move.level <= v_target_level
            and not exists (
              select 1 from jsonb_array_elements(coalesce(v_instance.state -> 'm', '[]'::jsonb)) known
              where (known ->> 0)::integer = move.move_index
            )
        ), '[]'::jsonb),
        'evolutions', coalesce((
          select jsonb_agg(jsonb_build_object(
            'target_species_key', evolution.target_species_key,
            'evolution_order', evolution.evolution_order,
            'trigger_level', (evolution.trigger_rules ->> 'level')::integer
          ) order by evolution.evolution_order)
          from public.catalog_species_evolution evolution
          where evolution.catalog_release_id = v_instance.catalog_release_id
            and evolution.species_key = v_instance.species_key
            and evolution.trigger_key = 'level'
            and coalesce((evolution.trigger_rules ->> 'level')::integer, 101) <= v_target_level
        ), '[]'::jsonb)
      );
      insert into public.player_pending_resolution (
        auth_user_id, pokemon_instance_id, resolution_type, options, expected_revision
      ) values (
        v_auth_user_id, p_pokemon_instance_id,
        case when v_has_evolution_choice then 'evolution' else 'move' end,
        v_resolution_options, v_current_revision + 1
      ) returning id into v_resolution_id;
      update public.player_daycare_state set
        status = 'withdraw_pending', pending_levels = v_levels, pending_cost = v_cost,
        pending_resolution_id = v_resolution_id, updated_at = now()
      where pokemon_instance_id = p_pokemon_instance_id;
    else
      select * into v_level_rule from public.catalog_level_rule
      where catalog_release_id = v_instance.catalog_release_id and level = v_target_level;
      if not found then
        raise exception 'level/stat rule is missing for target level %', v_target_level using errcode = 'P0002';
      end if;
      select coalesce(jsonb_agg(jsonb_build_array(
        (move ->> 0)::integer,
        least(coalesce((move ->> 1)::integer, 0) + 2 * v_levels, v_level_rule.max_power),
        least(coalesce((move ->> 2)::integer, 0) + 2 * v_levels, v_level_rule.max_stats)
      ) order by ordinality), '[]'::jsonb) into v_moves
      from jsonb_array_elements(coalesce(v_instance.state -> 'm', '[]'::jsonb)) with ordinality as moves(move, ordinality);

      update public.player_pokemon_instance set
        state = jsonb_set(
          jsonb_set(
            jsonb_set(
              jsonb_set(state, '{l}', to_jsonb(v_target_level), true),
              '{hp}', to_jsonb(least(coalesce((state ->> 'hp')::integer, 1) + 3 * v_levels, v_level_rule.max_hp)), true
            ),
            '{m}', v_moves, true
          ),
          '{xp}', to_jsonb(case when v_target_level = v_level_cap then 0 else coalesce((state ->> 'xp')::integer, 0) end), true
        ),
        revision = revision + 1,
        updated_at = now()
      where id = p_pokemon_instance_id and auth_user_id = v_auth_user_id;

      delete from public.player_daycare_state where pokemon_instance_id = p_pokemon_instance_id;
      update public.player_pokemon_placement set
        placement_type = 'team', slot_index = v_team_count, box_index = null, updated_at = now()
      where pokemon_instance_id = p_pokemon_instance_id;
    end if;
  end if;

  update public.player_state_revision set revision = revision + 1, updated_at = now()
  where auth_user_id = v_auth_user_id returning revision into v_current_revision;

  v_result := server_authority_private.player_state_projection(v_auth_user_id)
    || jsonb_build_object(
      'command_id', p_command_id,
      'command_type', p_command_type,
      'pokemon_instance_id', p_pokemon_instance_id,
      'daycare_slot_index', case when p_command_type = 'daycare_deposit' then p_slot_index else v_placement.slot_index end,
      'withdrawal_status', case when v_resolution_id is not null then 'resolution_required'
        when p_command_type = 'daycare_withdraw' then 'completed' else null end,
      'pending_resolution_id', v_resolution_id,
      'levels_gained', case when p_command_type = 'daycare_withdraw' then v_levels else null end,
      'charged_cost', case when p_command_type = 'daycare_withdraw' then v_cost else null end
    );

  insert into public.player_command_receipt (
    auth_user_id, command_id, command_type, request_hash, result, resulting_revision
  ) values (
    v_auth_user_id, p_command_id, p_command_type, v_request_hash, v_result, v_current_revision
  );
  return v_result;
end;
$_$;


ALTER FUNCTION "server_authority_private"."execute_daycare_command_before_ordinary_guard"("p_command_type" "text", "p_command_id" "uuid", "p_expected_revision" bigint, "p_pokemon_instance_id" "uuid", "p_slot_index" integer) OWNER TO "postgres";

--
-- Name: execute_garden_command("text", "uuid", bigint, integer, integer); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."execute_garden_command"("p_command_type" "text", "p_command_id" "uuid", "p_expected_revision" bigint, "p_plot_index" integer DEFAULT NULL::integer, "p_item_index" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $_$
declare
  v_auth_user_id uuid := auth.uid();
  v_request jsonb;
  v_request_hash text;
  v_receipt_type text;
  v_receipt_hash text;
  v_receipt_result jsonb;
  v_current_revision bigint;
  v_profile public.player_profile_state%rowtype;
  v_plot public.player_garden_plot_state%rowtype;
  v_daily public.player_daily_claim_state%rowtype;
  v_catalog_release_id uuid;
  v_catalog_status text;
  v_allow_draft boolean;
  v_engine_contract text;
  v_item public.catalog_item%rowtype;
  v_inventory_quantity integer := 0;
  v_growth_hours integer;
  v_harvest_quantity integer;
  v_reward_pool text;
  v_pool_count integer;
  v_random_bytes bytea;
  v_random_value bigint;
  v_reward_offset integer;
  v_local_date date;
  v_event_time timestamptz := now();
  v_result jsonb;
begin
  if v_auth_user_id is null then
    raise exception 'authentication required' using errcode = '28000';
  end if;
  if p_command_type not in ('garden_plant', 'garden_harvest', 'daily_berry_claim') then
    raise exception 'garden command type is not allowed' using errcode = '22023';
  end if;
  if p_command_id is null then
    raise exception 'command id is required' using errcode = '22023';
  end if;
  if p_expected_revision is null or p_expected_revision < 0 then
    raise exception 'expected revision must be non-negative' using errcode = '22023';
  end if;
  if p_command_type in ('garden_plant', 'garden_harvest')
     and (p_plot_index is null or p_plot_index not between 0 and 2) then
    raise exception 'plot index must be between 0 and 2' using errcode = '22023';
  end if;
  if p_command_type = 'garden_plant' and (p_item_index is null or p_item_index <= 0) then
    raise exception 'item index must be positive' using errcode = '22023';
  end if;
  if p_command_type <> 'garden_plant' and p_item_index is not null then
    raise exception 'item index is not accepted for this command' using errcode = '22023';
  end if;

  v_request := jsonb_build_object(
    'command_type', p_command_type,
    'expected_revision', p_expected_revision,
    'plot_index', p_plot_index,
    'item_index', p_item_index
  );
  v_request_hash := encode(digest(convert_to(v_request::text, 'UTF8'), 'sha256'), 'hex');

  perform pg_advisory_xact_lock(hashtextextended(v_auth_user_id::text || ':' || p_command_id::text, 0));
  select command_type, request_hash, result
  into v_receipt_type, v_receipt_hash, v_receipt_result
  from public.player_command_receipt
  where auth_user_id = v_auth_user_id and command_id = p_command_id;

  if found then
    if v_receipt_type <> p_command_type or v_receipt_hash <> v_request_hash then
      raise exception 'command id was already used with a different payload' using errcode = '22023';
    end if;
    return v_receipt_result;
  end if;

  select revision into v_current_revision
  from public.player_state_revision
  where auth_user_id = v_auth_user_id
  for update;
  if not found then
    raise exception 'player state does not exist' using errcode = 'P0002';
  end if;
  if v_current_revision <> p_expected_revision then
    raise exception 'revision conflict: expected %, current %', p_expected_revision, v_current_revision using errcode = '40001';
  end if;

  select * into v_profile
  from public.player_profile_state
  where auth_user_id = v_auth_user_id
  for update;
  if not found or v_profile.starter_status <> 'selected' then
    raise exception 'player profile is not ready' using errcode = '55000';
  end if;

  select config.catalog_release_id, release.status, config.allow_draft, config.engine_contract
  into v_catalog_release_id, v_catalog_status, v_allow_draft, v_engine_contract
  from server_authority_private.runtime_catalog_config config
  join public.catalog_release release on release.id = config.catalog_release_id
  where config.runtime_key = 'garden';
  if v_catalog_release_id is null
     or v_engine_contract <> 'garden'
     or (v_catalog_status <> 'published' and not (v_catalog_status = 'draft' and v_allow_draft)) then
    raise exception 'garden runtime catalog is not ready';
  end if;
  if v_profile.catalog_release_id <> v_catalog_release_id then
    raise exception 'player catalog is not bound to the garden runtime catalog' using errcode = '55000';
  end if;

  if p_command_type in ('garden_plant', 'garden_harvest') then
    insert into public.player_garden_plot_state(auth_user_id, plot_index)
    values (v_auth_user_id, p_plot_index)
    on conflict (auth_user_id, plot_index) do nothing;
    select * into v_plot
    from public.player_garden_plot_state
    where auth_user_id = v_auth_user_id and plot_index = p_plot_index
    for update;
  else
    insert into public.player_daily_claim_state(auth_user_id, claim_type)
    values (v_auth_user_id, 'berry')
    on conflict (auth_user_id, claim_type) do nothing;
    select * into v_daily
    from public.player_daily_claim_state
    where auth_user_id = v_auth_user_id and claim_type = 'berry'
    for update;
  end if;

  if p_command_type = 'garden_plant' then
    select * into v_item
    from public.catalog_item item
    where item.catalog_release_id = v_catalog_release_id and item.item_index = p_item_index;
    if not found or v_item.category_key <> 'Berry'
       or jsonb_typeof(v_item.rules -> 'berryGrowthHours') is distinct from 'number'
       or (v_item.rules ->> 'berryGrowthHours') not in ('36', '60') then
      raise exception 'item is not a plantable berry' using errcode = '22023';
    end if;
    if v_plot.berry_item_index is not null then
      raise exception 'garden plot is occupied' using errcode = '22023';
    end if;
    v_growth_hours := (v_item.rules ->> 'berryGrowthHours')::integer;

    select quantity into v_inventory_quantity
    from public.player_inventory_item
    where auth_user_id = v_auth_user_id and item_index = p_item_index
    for update;
    if not found or v_inventory_quantity < 1 then
      raise exception 'berry is not available in inventory' using errcode = '22023';
    end if;
    if v_inventory_quantity = 1 then
      delete from public.player_inventory_item
      where auth_user_id = v_auth_user_id and item_index = p_item_index;
    else
      update public.player_inventory_item
      set quantity = quantity - 1, updated_at = v_event_time
      where auth_user_id = v_auth_user_id and item_index = p_item_index;
    end if;
    update public.player_garden_plot_state
    set catalog_release_id = v_catalog_release_id,
        berry_item_index = p_item_index,
        planted_at = v_event_time,
        ready_at = v_event_time + make_interval(hours => v_growth_hours),
        updated_at = v_event_time
    where auth_user_id = v_auth_user_id and plot_index = p_plot_index;
  elsif p_command_type = 'garden_harvest' then
    if v_plot.berry_item_index is null then
      raise exception 'garden plot is empty' using errcode = '22023';
    end if;
    select * into v_item
    from public.catalog_item item
    where item.catalog_release_id = v_catalog_release_id
      and item.item_index = v_plot.berry_item_index;
    if v_plot.catalog_release_id <> v_catalog_release_id
       or not found
       or v_item.category_key <> 'Berry'
       or jsonb_typeof(v_item.rules -> 'berryGrowthHours') is distinct from 'number'
       or (v_item.rules ->> 'berryGrowthHours') not in ('36', '60') then
      raise exception 'planted berry is not valid for the garden runtime catalog' using errcode = '55000';
    end if;
    if v_plot.ready_at > v_event_time then
      raise exception 'garden plot is not ready' using errcode = '22023';
    end if;
    select (rules ->> 'value')::integer into v_harvest_quantity
    from public.catalog_progression_rule
    where catalog_release_id = v_catalog_release_id
      and rule_family = 'constant'
      and rule_key = 'garden-harvest-quantity'
      and jsonb_typeof(rules -> 'value') = 'number'
      and (rules ->> 'value') ~ '^[1-9][0-9]*$';
    if v_harvest_quantity is null or v_harvest_quantity > 1000000 then
      raise exception 'garden harvest quantity rule is invalid';
    end if;

    perform 1 from public.player_inventory_item
    where auth_user_id = v_auth_user_id and item_index = v_plot.berry_item_index
    for update;
    select coalesce((select quantity from public.player_inventory_item
      where auth_user_id = v_auth_user_id and item_index = v_plot.berry_item_index), 0)
    into v_inventory_quantity;
    if v_inventory_quantity::bigint + v_harvest_quantity > 2147483647 then
      raise exception 'inventory quantity limit exceeded' using errcode = '22003';
    end if;
    insert into public.player_inventory_item(auth_user_id, catalog_release_id, item_index, quantity, updated_at)
    values (v_auth_user_id, v_catalog_release_id, v_plot.berry_item_index, v_harvest_quantity, v_event_time)
    on conflict (auth_user_id, item_index) do update
      set quantity = public.player_inventory_item.quantity + excluded.quantity,
          updated_at = excluded.updated_at;
    update public.player_garden_plot_state
    set catalog_release_id = null, berry_item_index = null, planted_at = null, ready_at = null, updated_at = v_event_time
    where auth_user_id = v_auth_user_id and plot_index = p_plot_index;
  else
    v_local_date := (v_event_time at time zone 'Europe/Rome')::date;
    if v_daily.last_claim_local_date = v_local_date then
      raise exception 'daily berry was already claimed for Europe/Rome date %', v_local_date using errcode = '22023';
    end if;

    v_random_bytes := gen_random_bytes(4);
    v_random_value := get_byte(v_random_bytes, 0)::bigint * 16777216
      + get_byte(v_random_bytes, 1)::bigint * 65536
      + get_byte(v_random_bytes, 2)::bigint * 256
      + get_byte(v_random_bytes, 3)::bigint;
    v_reward_pool := case when mod(v_random_value, 100) < 90 then 'normal' else 'long' end;
    select count(*)::integer into v_pool_count
    from public.catalog_item item
    where item.catalog_release_id = v_catalog_release_id
      and item.category_key = 'Berry'
      and item.rules ->> 'berryGrowthHours' = case when v_reward_pool = 'normal' then '36' else '60' end;
    if v_pool_count <= 0 then
      raise exception 'daily berry reward pool is empty';
    end if;
    v_random_bytes := gen_random_bytes(4);
    v_random_value := get_byte(v_random_bytes, 0)::bigint * 16777216
      + get_byte(v_random_bytes, 1)::bigint * 65536
      + get_byte(v_random_bytes, 2)::bigint * 256
      + get_byte(v_random_bytes, 3)::bigint;
    v_reward_offset := mod(v_random_value, v_pool_count)::integer;
    select * into v_item
    from public.catalog_item item
    where item.catalog_release_id = v_catalog_release_id
      and item.category_key = 'Berry'
      and item.rules ->> 'berryGrowthHours' = case when v_reward_pool = 'normal' then '36' else '60' end
    order by item.item_index
    offset v_reward_offset limit 1;

    perform 1 from public.player_inventory_item
    where auth_user_id = v_auth_user_id and item_index = v_item.item_index
    for update;
    select coalesce((select quantity from public.player_inventory_item
      where auth_user_id = v_auth_user_id and item_index = v_item.item_index), 0)
    into v_inventory_quantity;
    if v_inventory_quantity = 2147483647 then
      raise exception 'inventory quantity limit exceeded' using errcode = '22003';
    end if;
    insert into public.player_inventory_item(auth_user_id, catalog_release_id, item_index, quantity, updated_at)
    values (v_auth_user_id, v_catalog_release_id, v_item.item_index, 1, v_event_time)
    on conflict (auth_user_id, item_index) do update
      set quantity = public.player_inventory_item.quantity + 1,
          updated_at = excluded.updated_at;
    update public.player_daily_claim_state
    set last_claim_local_date = v_local_date,
        claimed_at = v_event_time,
        catalog_release_id = v_catalog_release_id,
        reward_item_index = v_item.item_index,
        updated_at = v_event_time
    where auth_user_id = v_auth_user_id and claim_type = 'berry';
  end if;

  update public.player_state_revision
  set revision = revision + 1, updated_at = v_event_time
  where auth_user_id = v_auth_user_id
  returning revision into v_current_revision;

  v_result := server_authority_private.player_state_projection(v_auth_user_id)
    || jsonb_build_object(
      'command_id', p_command_id,
      'command_type', p_command_type,
      'plot_index', p_plot_index,
      'berry_index', case when p_command_type = 'garden_harvest' then v_plot.berry_item_index when p_command_type = 'garden_plant' then p_item_index else v_item.item_index end,
      'quantity', case when p_command_type = 'garden_harvest' then v_harvest_quantity when p_command_type = 'daily_berry_claim' then 1 else null end,
      'reward_item_index', case when p_command_type = 'daily_berry_claim' then v_item.item_index else null end,
      'reward_name', case when p_command_type = 'daily_berry_claim' then v_item.display_name else null end,
      'claimed_local_date', case when p_command_type = 'daily_berry_claim' then v_local_date else null end
    );
  insert into public.player_command_receipt(auth_user_id, command_id, command_type, request_hash, result, resulting_revision)
  values (v_auth_user_id, p_command_id, p_command_type, v_request_hash, v_result, v_current_revision);
  return v_result;
end;
$_$;


ALTER FUNCTION "server_authority_private"."execute_garden_command"("p_command_type" "text", "p_command_id" "uuid", "p_expected_revision" bigint, "p_plot_index" integer, "p_item_index" integer) OWNER TO "postgres";

--
-- Name: execute_shop_command("text", "uuid", bigint, integer, integer); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."execute_shop_command"("p_command_type" "text", "p_command_id" "uuid", "p_expected_revision" bigint, "p_item_index" integer, "p_quantity" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $_$
declare
  v_auth_user_id uuid := auth.uid();
  v_request jsonb;
  v_request_hash text;
  v_receipt_type text;
  v_receipt_hash text;
  v_receipt_result jsonb;
  v_current_revision bigint;
  v_profile public.player_profile_state%rowtype;
  v_catalog_release_id uuid;
  v_catalog_status text;
  v_allow_draft boolean;
  v_engine_contract text;
  v_offer public.catalog_shop_offer%rowtype;
  v_inventory_quantity integer := 0;
  v_purchased_quantity bigint := 0;
  v_unit_price bigint;
  v_total numeric;
  v_stock_limit bigint;
  v_result jsonb;
begin
  if v_auth_user_id is null then
    raise exception 'authentication required' using errcode = '28000';
  end if;
  if p_command_type not in ('shop_buy', 'shop_sell') then
    raise exception 'shop command type is not allowed' using errcode = '22023';
  end if;
  if p_command_id is null then
    raise exception 'command id is required' using errcode = '22023';
  end if;
  if p_expected_revision is null or p_expected_revision < 0 then
    raise exception 'expected revision must be non-negative' using errcode = '22023';
  end if;
  if p_item_index is null or p_item_index <= 0 then
    raise exception 'item index must be positive' using errcode = '22023';
  end if;
  if p_quantity is null or p_quantity <= 0 or p_quantity > 1000000 then
    raise exception 'quantity must be between 1 and 1000000' using errcode = '22023';
  end if;

  v_request := jsonb_build_object(
    'command_type', p_command_type,
    'expected_revision', p_expected_revision,
    'item_index', p_item_index,
    'quantity', p_quantity
  );
  v_request_hash := encode(digest(convert_to(v_request::text, 'UTF8'), 'sha256'), 'hex');

  perform pg_advisory_xact_lock(
    hashtextextended(v_auth_user_id::text || ':' || p_command_id::text, 0)
  );

  select command_type, request_hash, result
  into v_receipt_type, v_receipt_hash, v_receipt_result
  from public.player_command_receipt
  where auth_user_id = v_auth_user_id
    and command_id = p_command_id;

  if found then
    if v_receipt_type <> p_command_type or v_receipt_hash <> v_request_hash then
      raise exception 'command id was already used with a different payload' using errcode = '22023';
    end if;
    return v_receipt_result;
  end if;

  select revision into v_current_revision
  from public.player_state_revision
  where auth_user_id = v_auth_user_id
  for update;

  if not found then
    raise exception 'player state does not exist' using errcode = 'P0002';
  end if;
  if v_current_revision <> p_expected_revision then
    raise exception 'revision conflict: expected %, current %', p_expected_revision, v_current_revision
      using errcode = '40001';
  end if;

  select * into v_profile
  from public.player_profile_state
  where auth_user_id = v_auth_user_id
  for update;

  if not found or v_profile.starter_status <> 'selected' then
    raise exception 'player profile is not ready' using errcode = '55000';
  end if;

  select config.catalog_release_id, release.status, config.allow_draft, config.engine_contract
  into v_catalog_release_id, v_catalog_status, v_allow_draft, v_engine_contract
  from server_authority_private.runtime_catalog_config config
  join public.catalog_release release on release.id = config.catalog_release_id
  where config.runtime_key = 'shop';

  if v_catalog_release_id is null
     or v_engine_contract <> 'shop'
     or (v_catalog_status <> 'published' and not (v_catalog_status = 'draft' and v_allow_draft)) then
    raise exception 'shop runtime catalog is not ready';
  end if;
  if v_profile.catalog_release_id <> v_catalog_release_id then
    raise exception 'player catalog is not bound to the shop runtime catalog' using errcode = '55000';
  end if;

  select * into v_offer
  from public.catalog_shop_offer offer
  where offer.catalog_release_id = v_catalog_release_id
    and offer.item_index = p_item_index;

  if not found then
    raise exception 'shop offer was not found' using errcode = '22023';
  end if;

  perform 1 from public.player_inventory_item inventory
  where inventory.auth_user_id = v_auth_user_id
    and inventory.item_index = p_item_index
  for update;
  select coalesce((
    select inventory.quantity from public.player_inventory_item inventory
    where inventory.auth_user_id = v_auth_user_id
      and inventory.item_index = p_item_index
  ), 0) into v_inventory_quantity;

  perform 1 from public.player_shop_purchase_state purchase
  where purchase.auth_user_id = v_auth_user_id
    and purchase.item_index = p_item_index
  for update;
  select coalesce((
    select purchase.purchased_quantity from public.player_shop_purchase_state purchase
    where purchase.auth_user_id = v_auth_user_id
      and purchase.item_index = p_item_index
  ), 0) into v_purchased_quantity;

  if p_command_type = 'shop_buy' then
    if not v_offer.purchase_enabled or v_offer.price is null or v_offer.price < 0 then
      raise exception 'item is not available for purchase' using errcode = '22023';
    end if;
    if v_offer.unlock_rules <> '{}'::jsonb then
      if (v_offer.unlock_rules ->> 'kind') is distinct from 'badges'
         or jsonb_typeof(v_offer.unlock_rules -> 'value') is distinct from 'number'
         or (v_offer.unlock_rules ->> 'value') !~ '^[0-9]+$' then
        raise exception 'shop unlock rule is not supported';
      end if;
      if v_profile.badges < (v_offer.unlock_rules ->> 'value')::integer then
        raise exception 'item is locked by badge progression' using errcode = '22023';
      end if;
    end if;

    if v_offer.stock_rules <> '{}'::jsonb then
      if coalesce(v_offer.stock_rules ->> 'kind', '') not in ('fixed', 'single-owned')
         or jsonb_typeof(v_offer.stock_rules -> 'limit') is distinct from 'number'
         or (v_offer.stock_rules ->> 'limit') !~ '^[1-9][0-9]*$' then
        raise exception 'shop stock rule is not supported';
      end if;
      v_stock_limit := (v_offer.stock_rules ->> 'limit')::bigint;
      if v_purchased_quantity + p_quantity > v_stock_limit then
        raise exception 'requested quantity exceeds personal stock' using errcode = '22023';
      end if;
    end if;
    if v_offer.single_purchase and v_purchased_quantity + p_quantity > 1 then
      raise exception 'item can only be purchased once' using errcode = '22023';
    end if;
    if v_inventory_quantity::bigint + p_quantity > 2147483647 then
      raise exception 'inventory quantity limit exceeded' using errcode = '22003';
    end if;

    v_unit_price := v_offer.price;
    v_total := v_unit_price::numeric * p_quantity;
    if v_total > 9223372036854775807 or v_profile.pokedollars < v_total then
      raise exception 'insufficient pokedollars' using errcode = '22023';
    end if;

    update public.player_profile_state
    set pokedollars = pokedollars - v_total::bigint,
        updated_at = now()
    where auth_user_id = v_auth_user_id;

    insert into public.player_inventory_item (
      auth_user_id, catalog_release_id, item_index, quantity, updated_at
    ) values (
      v_auth_user_id, v_catalog_release_id, p_item_index, p_quantity, now()
    ) on conflict (auth_user_id, item_index) do update
      set quantity = public.player_inventory_item.quantity + excluded.quantity,
          updated_at = now();

    insert into public.player_shop_purchase_state (
      auth_user_id, catalog_release_id, item_index, purchased_quantity, updated_at
    ) values (
      v_auth_user_id, v_catalog_release_id, p_item_index, p_quantity, now()
    ) on conflict (auth_user_id, item_index) do update
      set purchased_quantity = public.player_shop_purchase_state.purchased_quantity + excluded.purchased_quantity,
          updated_at = now();
  else
    if not v_offer.sale_enabled
       or jsonb_typeof(v_offer.sale_rules -> 'price') is distinct from 'number'
       or (v_offer.sale_rules ->> 'price') !~ '^[0-9]+$' then
      raise exception 'item is not available for sale' using errcode = '22023';
    end if;
    if v_inventory_quantity < p_quantity then
      raise exception 'insufficient inventory quantity' using errcode = '22023';
    end if;

    v_unit_price := (v_offer.sale_rules ->> 'price')::bigint;
    v_total := v_unit_price::numeric * p_quantity;
    if v_total > 9223372036854775807 - v_profile.pokedollars then
      raise exception 'pokedollar limit exceeded' using errcode = '22003';
    end if;

    update public.player_profile_state
    set pokedollars = pokedollars + v_total::bigint,
        updated_at = now()
    where auth_user_id = v_auth_user_id;

    if v_inventory_quantity = p_quantity then
      delete from public.player_inventory_item
      where auth_user_id = v_auth_user_id
        and item_index = p_item_index;
    else
      update public.player_inventory_item
      set quantity = quantity - p_quantity,
          updated_at = now()
      where auth_user_id = v_auth_user_id
        and item_index = p_item_index;
    end if;
  end if;

  update public.player_state_revision
  set revision = revision + 1,
      updated_at = now()
  where auth_user_id = v_auth_user_id
  returning revision into v_current_revision;

  v_result := server_authority_private.player_state_projection(v_auth_user_id)
    || jsonb_build_object(
      'command_id', p_command_id,
      'command_type', p_command_type,
      'item_index', p_item_index,
      'quantity', p_quantity,
      'unit_price', v_unit_price,
      'total', v_total::bigint
    );

  insert into public.player_command_receipt (
    auth_user_id, command_id, command_type, request_hash, result, resulting_revision
  ) values (
    v_auth_user_id, p_command_id, p_command_type, v_request_hash, v_result, v_current_revision
  );

  return v_result;
end;
$_$;


ALTER FUNCTION "server_authority_private"."execute_shop_command"("p_command_type" "text", "p_command_id" "uuid", "p_expected_revision" bigint, "p_item_index" integer, "p_quantity" integer) OWNER TO "postgres";

--
-- Name: execute_team_box_command("text", "uuid", bigint, "uuid", integer); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."execute_team_box_command"("p_command_type" "text", "p_command_id" "uuid", "p_expected_revision" bigint, "p_pokemon_instance_id" "uuid", "p_target_slot" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
begin
  perform server_authority_private.assert_no_pending_ordinary_progression(auth.uid(),p_command_id);
  return server_authority_private.execute_team_box_command_before_ordinary_guard(
    p_command_type,p_command_id,p_expected_revision,p_pokemon_instance_id,p_target_slot);
end;
$$;


ALTER FUNCTION "server_authority_private"."execute_team_box_command"("p_command_type" "text", "p_command_id" "uuid", "p_expected_revision" bigint, "p_pokemon_instance_id" "uuid", "p_target_slot" integer) OWNER TO "postgres";

--
-- Name: execute_team_box_command_before_ordinary_guard("text", "uuid", bigint, "uuid", integer); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."execute_team_box_command_before_ordinary_guard"("p_command_type" "text", "p_command_id" "uuid", "p_expected_revision" bigint, "p_pokemon_instance_id" "uuid", "p_target_slot" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $_$
declare
  v_auth_user_id uuid := auth.uid();
  v_request jsonb;
  v_request_hash text;
  v_receipt_type text;
  v_receipt_hash text;
  v_receipt_result jsonb;
  v_current_revision bigint;
  v_primary_instance public.player_pokemon_instance%rowtype;
  v_primary_placement public.player_pokemon_placement%rowtype;
  v_other_placement public.player_pokemon_placement%rowtype;
  v_team_count integer;
  v_same_species_count integer;
  v_same_item_count integer;
  v_held_item_index integer;
  v_box_index bigint;
  v_shift_slot integer;
  v_result jsonb;
begin
  if v_auth_user_id is null then
    raise exception 'authentication required' using errcode = '28000';
  end if;
  if p_command_type not in ('team_to_box', 'box_to_team', 'team_swap', 'box_release') then
    raise exception 'team/box command type is not allowed' using errcode = '22023';
  end if;
  if p_command_id is null or p_pokemon_instance_id is null then
    raise exception 'command id and Pokemon instance id are required' using errcode = '22023';
  end if;
  if p_expected_revision is null or p_expected_revision < 0 then
    raise exception 'expected revision must be non-negative' using errcode = '22023';
  end if;
  if p_command_type in ('box_to_team', 'team_swap') and (p_target_slot is null or p_target_slot < 0 or p_target_slot > 5) then
    raise exception 'target team slot must be between 0 and 5' using errcode = '22023';
  end if;
  if p_command_type not in ('box_to_team', 'team_swap') and p_target_slot is not null then
    raise exception 'target team slot is not allowed' using errcode = '22023';
  end if;

  v_request := jsonb_build_object(
    'command_type', p_command_type,
    'expected_revision', p_expected_revision,
    'pokemon_instance_id', p_pokemon_instance_id,
    'target_slot', p_target_slot
  );
  v_request_hash := encode(digest(convert_to(v_request::text, 'UTF8'), 'sha256'), 'hex');

  perform pg_advisory_xact_lock(
    hashtextextended(v_auth_user_id::text || ':' || p_command_id::text, 0)
  );

  select command_type, request_hash, result
  into v_receipt_type, v_receipt_hash, v_receipt_result
  from public.player_command_receipt
  where auth_user_id = v_auth_user_id
    and command_id = p_command_id;

  if found then
    if v_receipt_type <> p_command_type or v_receipt_hash <> v_request_hash then
      raise exception 'command id was already used with a different payload' using errcode = '22023';
    end if;
    return v_receipt_result;
  end if;

  select revision into v_current_revision
  from public.player_state_revision
  where auth_user_id = v_auth_user_id
  for update;

  if not found then
    raise exception 'player state does not exist' using errcode = 'P0002';
  end if;
  if v_current_revision <> p_expected_revision then
    raise exception 'revision conflict: expected %, current %', p_expected_revision, v_current_revision
      using errcode = '40001';
  end if;

  -- Lock every team row because compaction and composition checks involve the
  -- complete team. UUID ordering is shared by every placement command.
  perform 1
  from public.player_pokemon_placement placement
  join public.player_pokemon_instance pokemon
    on pokemon.id = placement.pokemon_instance_id
   and pokemon.auth_user_id = placement.auth_user_id
  where placement.auth_user_id = v_auth_user_id
    and (
      placement.placement_type = 'team'
      or placement.pokemon_instance_id = p_pokemon_instance_id
    )
  order by placement.pokemon_instance_id
  for update of placement, pokemon;

  select * into v_primary_instance
  from public.player_pokemon_instance pokemon
  where pokemon.id = p_pokemon_instance_id
    and pokemon.auth_user_id = v_auth_user_id;
  if not found then
    raise exception 'Pokemon instance is not owned by the current player' using errcode = '22023';
  end if;

  select * into v_primary_placement
  from public.player_pokemon_placement placement
  where placement.pokemon_instance_id = p_pokemon_instance_id
    and placement.auth_user_id = v_auth_user_id;
  if not found then
    raise exception 'Pokemon placement was not found' using errcode = 'P0002';
  end if;

  select count(*) into v_team_count
  from public.player_pokemon_placement placement
  where placement.auth_user_id = v_auth_user_id
    and placement.placement_type = 'team';

  if p_command_type = 'team_to_box' then
    if v_primary_placement.placement_type <> 'team' then
      raise exception 'Pokemon is not currently in the team' using errcode = '22023';
    end if;
    if v_team_count <= 1 then
      raise exception 'at least one Pokemon must remain in the team' using errcode = '22023';
    end if;

    insert into public.player_box_index_state (auth_user_id, next_box_index)
    select v_auth_user_id, coalesce(max(placement.box_index), -1)::bigint + 1
    from public.player_pokemon_placement placement
    where placement.auth_user_id = v_auth_user_id
      and placement.placement_type = 'box'
    on conflict (auth_user_id) do nothing;

    select next_box_index into v_box_index
    from public.player_box_index_state
    where auth_user_id = v_auth_user_id
    for update;

    select greatest(
      v_box_index,
      coalesce(max(placement.box_index), -1)::bigint + 1
    ) into v_box_index
    from public.player_pokemon_placement placement
    where placement.auth_user_id = v_auth_user_id
      and placement.placement_type = 'box';

    if v_box_index > 2147483647 then
      raise exception 'box index limit exceeded' using errcode = '22003';
    end if;

    update public.player_box_index_state
    set next_box_index = v_box_index + 1,
        updated_at = now()
    where auth_user_id = v_auth_user_id;

    update public.player_pokemon_placement
    set placement_type = 'box',
        slot_index = null,
        box_index = v_box_index::integer,
        updated_at = now()
    where pokemon_instance_id = p_pokemon_instance_id;

    if v_primary_placement.slot_index < v_team_count - 1 then
      for v_shift_slot in v_primary_placement.slot_index + 1..v_team_count - 1 loop
        update public.player_pokemon_placement
        set slot_index = v_shift_slot - 1,
            updated_at = now()
        where auth_user_id = v_auth_user_id
          and placement_type = 'team'
          and slot_index = v_shift_slot;
      end loop;
    end if;

  elsif p_command_type = 'box_to_team' then
    if v_primary_placement.placement_type <> 'box' then
      raise exception 'Pokemon is not currently in the box' using errcode = '22023';
    end if;
    if v_team_count >= 6 then
      raise exception 'team is full' using errcode = '22023';
    end if;
    if p_target_slot <> v_team_count then
      raise exception 'target slot must be the next team slot: %', v_team_count using errcode = '22023';
    end if;

    select count(*) into v_same_species_count
    from public.player_pokemon_placement placement
    join public.player_pokemon_instance pokemon
      on pokemon.id = placement.pokemon_instance_id
     and pokemon.auth_user_id = placement.auth_user_id
    where placement.auth_user_id = v_auth_user_id
      and placement.placement_type = 'team'
      and pokemon.species_key = v_primary_instance.species_key;
    if v_same_species_count >= 2 then
      raise exception 'team cannot contain more than two Pokemon of the same species' using errcode = '22023';
    end if;

    v_held_item_index := case
      when coalesce(v_primary_instance.state ->> 'i', '') ~ '^[1-9][0-9]*$'
        then (v_primary_instance.state ->> 'i')::integer
      else 0
    end;
    if v_held_item_index > 0 then
      select count(*) into v_same_item_count
      from public.player_pokemon_placement placement
      join public.player_pokemon_instance pokemon
        on pokemon.id = placement.pokemon_instance_id
       and pokemon.auth_user_id = placement.auth_user_id
      where placement.auth_user_id = v_auth_user_id
        and placement.placement_type = 'team'
        and case
          when coalesce(pokemon.state ->> 'i', '') ~ '^[1-9][0-9]*$'
            then (pokemon.state ->> 'i')::integer
          else 0
        end = v_held_item_index;
      if v_same_item_count >= 2 then
        raise exception 'team cannot contain more than two Pokemon holding the same item' using errcode = '22023';
      end if;
    end if;

    update public.player_pokemon_placement
    set placement_type = 'team',
        slot_index = p_target_slot,
        box_index = null,
        updated_at = now()
    where pokemon_instance_id = p_pokemon_instance_id;

  elsif p_command_type = 'team_swap' then
    if v_primary_placement.placement_type <> 'team' then
      raise exception 'source Pokemon is not currently in the team' using errcode = '22023';
    end if;

    if v_primary_placement.slot_index = p_target_slot then
      raise exception 'source Pokemon already occupies the target slot' using errcode = '22023';
    end if;

    select * into v_other_placement
    from public.player_pokemon_placement placement
    where placement.auth_user_id = v_auth_user_id
      and placement.placement_type = 'team'
      and placement.slot_index = p_target_slot;
    if not found or v_other_placement.placement_type <> 'team' then
      raise exception 'target team slot is not occupied' using errcode = '22023';
    end if;

    delete from public.player_pokemon_placement
    where pokemon_instance_id in (p_pokemon_instance_id, v_other_placement.pokemon_instance_id);
    insert into public.player_pokemon_placement (
      pokemon_instance_id, auth_user_id, placement_type, slot_index, box_index, updated_at
    ) values
      (p_pokemon_instance_id, v_auth_user_id, 'team', v_other_placement.slot_index, null, now()),
      (v_other_placement.pokemon_instance_id, v_auth_user_id, 'team', v_primary_placement.slot_index, null, now());

  else
    if v_primary_placement.placement_type <> 'box' then
      raise exception 'only a boxed Pokemon can be released' using errcode = '22023';
    end if;
    if server_authority_private.pokemon_has_active_reference(v_auth_user_id, p_pokemon_instance_id) then
      raise exception 'Pokemon is referenced by an active encounter, battle, or pending resolution'
        using errcode = '55000';
    end if;

    delete from public.player_pokemon_instance
    where id = p_pokemon_instance_id
      and auth_user_id = v_auth_user_id;
  end if;

  update public.player_state_revision
  set revision = revision + 1,
      updated_at = now()
  where auth_user_id = v_auth_user_id
  returning revision into v_current_revision;

  v_result := server_authority_private.player_state_projection(v_auth_user_id)
    || jsonb_build_object(
      'command_id', p_command_id,
      'command_type', p_command_type,
      'pokemon_instance_id', p_pokemon_instance_id,
      'target_slot', p_target_slot,
      'allocated_box_index', case when p_command_type = 'team_to_box' then v_box_index else null end
    );

  insert into public.player_command_receipt (
    auth_user_id, command_id, command_type, request_hash, result, resulting_revision
  ) values (
    v_auth_user_id, p_command_id, p_command_type, v_request_hash, v_result, v_current_revision
  );

  return v_result;
end;
$_$;


ALTER FUNCTION "server_authority_private"."execute_team_box_command_before_ordinary_guard"("p_command_type" "text", "p_command_id" "uuid", "p_expected_revision" bigint, "p_pokemon_instance_id" "uuid", "p_target_slot" integer) OWNER TO "postgres";

--
-- Name: finalize_terminal_admin_league("uuid", "uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."finalize_terminal_admin_league"("p_auth_user_id" "uuid", "p_battle_id" "uuid", "p_command_id" "uuid", "p_projection" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare v_battle public.authoritative_battle%rowtype; v_run public.authoritative_league_run%rowtype;
  v_existing public.player_league_victory%rowtype; v_key text; v_money bigint; v_penalty bigint:=0;
  v_reward jsonb; v_state jsonb; v_revision bigint; v_receipt public.player_command_receipt%rowtype;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'service role required' using errcode='42501'; end if;
  select * into strict v_battle from public.authoritative_battle where id=p_battle_id and auth_user_id=p_auth_user_id for update;
  if v_battle.contract_key<>'league' or v_battle.status not in ('concluded','abandoned') then return null; end if;
  select * into strict v_run from public.authoritative_league_run where id=v_battle.league_run_id for update;
  if v_run.status in ('completed','failed') then
    select * into v_existing from public.player_league_victory where battle_id=p_battle_id;
    return jsonb_build_object('league_reward',case when found then v_existing.reward else null end,
      'league_state',jsonb_build_object('runId',v_run.id,'status',v_run.status,'nextMemberIndex',v_run.next_member_index,
        'completedMembers',v_run.completed_members),'player_state',server_authority_private.player_state_projection(p_auth_user_id));
  end if;
  if v_run.status<>'active' or v_run.next_member_index<>v_battle.league_member_index then
    raise exception 'League terminal does not match the active sequence member' using errcode='40001'; end if;
  if v_battle.result_key<>'player_win_no_reward' then
    select floor(pokedollars/5.0)::bigint into v_penalty from public.player_profile_state where auth_user_id=p_auth_user_id for update;
    update public.player_profile_state set pokedollars=pokedollars-v_penalty,updated_at=now() where auth_user_id=p_auth_user_id;
    update public.authoritative_league_run set status='failed',next_member_index=null,updated_at=now(),concluded_at=now() where id=v_run.id;
    update public.player_state_revision set revision=revision+1,updated_at=now() where auth_user_id=p_auth_user_id returning revision into v_revision;
    perform server_authority_private.authoritative_battle_append_event(p_battle_id,'league_run_failed',
      jsonb_build_object('member_index',v_battle.league_member_index,'money_penalty',v_penalty),null,'[]'::jsonb);
    return jsonb_build_object('player_state',server_authority_private.player_state_projection(p_auth_user_id),
      'league_state',jsonb_build_object('runId',v_run.id,'status','failed','nextMemberIndex',null,
        'completedMembers',v_run.completed_members,'moneyPenalty',v_penalty));
  end if;
  v_key:=case when v_battle.league_member_index=4 then 'kanto_league_champion' else 'kanto_league_'||(v_battle.league_member_index+1)::text end;
  if (select count(*) from public.catalog_opponent_reward where catalog_release_id=v_battle.catalog_release_id and opponent_key=v_key)<>1 then
    raise exception 'canonical League reward shape changed' using errcode='0A000'; end if;
  select quantity::bigint into strict v_money from public.catalog_opponent_reward where catalog_release_id=v_battle.catalog_release_id
    and opponent_key=v_key and reward_kind='money' and quantity>0 and item_index is null;
  v_reward:=jsonb_build_object('rewardKind','league','opponentKey',v_key,'memberIndex',v_battle.league_member_index,
    'money',v_money,'already',false);
  update public.player_profile_state set pokedollars=pokedollars+v_money,updated_at=now() where auth_user_id=p_auth_user_id;
  insert into public.player_league_victory(run_id,member_index,auth_user_id,battle_id,opponent_key,terminal_command_id,reward)
    values(v_run.id,v_battle.league_member_index,p_auth_user_id,p_battle_id,v_key,p_command_id,v_reward);
  update public.authoritative_league_run set completed_members=v_battle.league_member_index+1,
    status=case when v_battle.league_member_index=4 then 'completed' else 'awaiting_battle' end,
    next_member_index=case when v_battle.league_member_index=4 then null else v_battle.league_member_index+1 end,
    updated_at=now(),concluded_at=case when v_battle.league_member_index=4 then now() else null end where id=v_run.id;
  update public.player_state_revision set revision=revision+1,updated_at=now() where auth_user_id=p_auth_user_id returning revision into v_revision;
  perform server_authority_private.authoritative_battle_append_event(p_battle_id,'league_reward_awarded',v_reward,null,'[]'::jsonb);
  select * into v_run from public.authoritative_league_run where id=v_run.id;
  v_state:=jsonb_build_object('runId',v_run.id,'status',v_run.status,'nextMemberIndex',v_run.next_member_index,
    'completedMembers',v_run.completed_members);
  return jsonb_build_object('league_reward',v_reward,'league_state',v_state,
    'player_state',server_authority_private.player_state_projection(p_auth_user_id));
end;
$$;


ALTER FUNCTION "server_authority_private"."finalize_terminal_admin_league"("p_auth_user_id" "uuid", "p_battle_id" "uuid", "p_command_id" "uuid", "p_projection" "jsonb") OWNER TO "postgres";

--
-- Name: finish_capture_success("uuid", "uuid", "uuid", "text", integer, "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."finish_capture_success"("p_auth_user_id" "uuid", "p_battle_id" "uuid", "p_command_id" "uuid", "p_command_hash" "text", "p_item_index" integer, "p_result" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_battle public.authoritative_battle%rowtype; v_encounter public.player_encounter%rowtype; v_instance uuid:=gen_random_uuid();
  v_state jsonb; v_count integer; v_species_count integer; v_slot integer; v_box bigint; v_place text; v_revision bigint;
  v_receipt public.player_command_receipt%rowtype; v_player jsonb; v_result jsonb:=p_result;
begin
  select * into strict v_battle from public.authoritative_battle where id=p_battle_id and auth_user_id=p_auth_user_id for update;
  select * into strict v_encounter from public.player_encounter where id=v_battle.encounter_id and auth_user_id=p_auth_user_id for update;
  if v_encounter.status<>'active' then
    raise exception 'L''incontro associato non e piu attivo.' using errcode='40001'; end if;
  v_state:=jsonb_build_object('s',v_encounter.species_key,'g',case v_encounter.gender_key when 'Maschio' then 'M' when 'Femmina' then 'F' else null end,
    'l',v_encounter.level,'hp',v_encounter.max_hp,'m',v_encounter.moves,'xp',0);
  insert into public.player_pokemon_instance(id,auth_user_id,catalog_release_id,species_key,state_version,state,revision)
    values(v_instance,p_auth_user_id,v_encounter.catalog_release_id,v_encounter.species_key,1,v_state,1);
  select count(*) into v_count from public.player_pokemon_placement where auth_user_id=p_auth_user_id and placement_type='team';
  select count(*) into v_species_count from public.player_pokemon_placement p join public.player_pokemon_instance i on i.id=p.pokemon_instance_id
    where p.auth_user_id=p_auth_user_id and p.placement_type='team' and i.species_key=v_encounter.species_key;
  if v_count<6 and v_species_count<2 then
    select slot into v_slot from generate_series(0,5) slot where not exists(select 1 from public.player_pokemon_placement
      where auth_user_id=p_auth_user_id and placement_type='team' and slot_index=slot) order by slot limit 1;
    insert into public.player_pokemon_placement(pokemon_instance_id,auth_user_id,placement_type,slot_index,box_index)
      values(v_instance,p_auth_user_id,'team',v_slot,null); v_place:='team';
  else
    insert into public.player_box_index_state(auth_user_id,next_box_index)
      select p_auth_user_id,coalesce(max(box_index),-1)::bigint+1 from public.player_pokemon_placement
      where auth_user_id=p_auth_user_id and placement_type='box' on conflict(auth_user_id) do nothing;
    select next_box_index into v_box from public.player_box_index_state where auth_user_id=p_auth_user_id for update;
    select greatest(v_box,coalesce(max(box_index),-1)::bigint+1) into v_box from public.player_pokemon_placement
      where auth_user_id=p_auth_user_id and placement_type='box';
    if v_box>2147483647 then raise exception 'box index limit exceeded' using errcode='22003'; end if;
    update public.player_box_index_state set next_box_index=v_box+1,updated_at=now() where auth_user_id=p_auth_user_id;
    insert into public.player_pokemon_placement(pokemon_instance_id,auth_user_id,placement_type,slot_index,box_index)
      values(v_instance,p_auth_user_id,'box',null,v_box::integer); v_place:='box';
  end if;
  insert into public.player_dex_entry(auth_user_id,catalog_release_id,species_key)
    values(p_auth_user_id,v_encounter.catalog_release_id,v_encounter.species_key) on conflict do nothing;
  update public.player_encounter set status='consumed',consumed_at=now(),captured_pokemon_instance_id=v_instance where id=v_encounter.id;
  update public.authoritative_battle set result_key='pokemon_captured' where id=p_battle_id;
  select revision into v_revision from public.player_state_revision where auth_user_id=p_auth_user_id;
  v_player:=server_authority_private.player_state_projection(p_auth_user_id);
  v_result:=jsonb_set(v_result,'{battle,result_key}',to_jsonb('pokemon_captured'::text),true)
    ||jsonb_build_object('capture_success',true,'placement',v_place,'pokemon_instance_id',v_instance,'player_state',v_player);
  insert into public.player_command_receipt(auth_user_id,command_id,command_type,request_hash,result,resulting_revision)
    values(p_auth_user_id,p_command_id,'wild_capture_attempt',p_command_hash,
      jsonb_build_object('capture_success',true,'pokemon_instance_id',v_instance,'item_index',p_item_index,'battle_id',p_battle_id),v_revision)
    returning * into v_receipt;
  v_player:=server_authority_private.player_state_projection(p_auth_user_id);
  v_result:=jsonb_set(v_result,'{player_state}',v_player,true);
  update public.authoritative_battle_command_receipt set command_type='ball',result=v_result
    where auth_user_id=p_auth_user_id and command_id=p_command_id;
  return v_result;
end;
$$;


ALTER FUNCTION "server_authority_private"."finish_capture_success"("p_auth_user_id" "uuid", "p_battle_id" "uuid", "p_command_id" "uuid", "p_command_hash" "text", "p_item_index" integer, "p_result" "jsonb") OWNER TO "postgres";

