-- Name: force_active_encounter_no_expiry(); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."force_active_encounter_no_expiry"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
begin
  if new.status='active' then new.expires_at:='infinity'::timestamptz; end if;
  return new;
end;
$$;


ALTER FUNCTION "server_authority_private"."force_active_encounter_no_expiry"() OWNER TO "postgres";

--
-- Name: guard_bound_encounter_mutation(); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."guard_bound_encounter_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
begin
  if old.status='active' and new.status<>'active' and exists(
    select 1 from public.authoritative_battle b where b.encounter_id=old.id
      and b.status in ('active','needs_player_switch')
  ) then raise exception 'encounter is bound to an active capture battle' using errcode='55000'; end if;
  return new;
end;
$$;


