--
-- Name: held_item_is_compatible("uuid", "text", integer); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."held_item_is_compatible"("p_catalog_release_id" "uuid", "p_species_key" "text", "p_item_index" integer) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
  select coalesce((
    select item.category_key in ('HeldItem', 'Berry')
      and not (item.rules ? 'allowedSpeciesKeys'
        and jsonb_typeof(item.rules -> 'allowedSpeciesKeys') <> 'array')
      and not (item.rules ? 'allowedSpeciesNames'
        and jsonb_typeof(item.rules -> 'allowedSpeciesNames') <> 'array')
      and not (item.rules ? 'requiredType'
        and jsonb_typeof(item.rules -> 'requiredType') <> 'string')
      and not (item.rules ? 'requiredMonoType'
        and jsonb_typeof(item.rules -> 'requiredMonoType') <> 'string')
      and cardinality(species.types) > 0
      and not coalesce((jsonb_typeof(item.rules -> 'allowedSpeciesKeys') = 'array'
        and jsonb_array_length(item.rules -> 'allowedSpeciesKeys') > 0
        and not (item.rules -> 'allowedSpeciesKeys' ? p_species_key)), false)
      and not coalesce((jsonb_typeof(item.rules -> 'allowedSpeciesNames') = 'array'
        and jsonb_array_length(item.rules -> 'allowedSpeciesNames') > 0
        and not (item.rules -> 'allowedSpeciesNames' ? species.display_name)), false)
      and not (item.rules ? 'requiredType'
        and not ((item.rules ->> 'requiredType') = any(species.types)))
      and not (item.rules ? 'requiredMonoType'
        and not (cardinality(species.types) = 1
          and species.types[1] = item.rules ->> 'requiredMonoType'))
    from public.catalog_item item
    join lateral (select catalog_species.display_name,
      array_agg(species_type.type_key order by species_type.type_order)
        filter (where species_type.type_key is not null) types
      from public.catalog_species catalog_species
      left join public.catalog_species_type species_type
        on species_type.catalog_release_id = catalog_species.catalog_release_id
        and species_type.species_key = catalog_species.species_key
      where catalog_species.catalog_release_id = p_catalog_release_id
        and catalog_species.species_key = p_species_key
      group by catalog_species.display_name) species on true
    where item.catalog_release_id = p_catalog_release_id
      and item.item_index = p_item_index
  ), false);
$$;


ALTER FUNCTION "server_authority_private"."held_item_is_compatible"("p_catalog_release_id" "uuid", "p_species_key" "text", "p_item_index" integer) OWNER TO "postgres";

--
-- Name: initialize_debug_training_admin_control(); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."initialize_debug_training_admin_control"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
begin
  if new.contract_key = 'debug_training' and old.contract_key <> 'debug_training' then
    new.waiting_for := case when new.first_actor = 'npc' then 'admin' else 'player' end;
    select coalesce(jsonb_agg(jsonb_build_array(item_index,3) order by item_index),'[]'::jsonb)
      into new.admin_items
      from public.catalog_admin_battle_item
      where catalog_release_id=new.catalog_release_id;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "server_authority_private"."initialize_debug_training_admin_control"() OWNER TO "postgres";

--
-- Name: mission_is_active("uuid", integer); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."mission_is_active"("p_auth_user_id" "uuid", "p_mission_index" integer) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
  select coalesce((
    select state.claim_status = 'unclaimed' and case
      when mission.repeatable or mission.category_key in ('repeatable', 'daily') then true
      when mission.category_key = 'capture' then true
      when mission.category_key <> 'adventure' then false
      when coalesce(mission.phase, 0) < 1 then false
      when profile.badges < mission.phase - 1 then false
      when exists (
        select 1
        from public.catalog_mission previous
        join public.player_mission_state previous_state
          on previous_state.auth_user_id = p_auth_user_id
         and previous_state.mission_index = previous.mission_index
        where previous.catalog_release_id = mission.catalog_release_id
          and previous.category_key = 'adventure'
          and previous.phase < mission.phase
          and previous_state.claim_status not in ('claimed', 'skipped')
      ) then false
      else true
    end
    from public.player_mission_state state
    join public.catalog_mission mission
      on mission.catalog_release_id = state.catalog_release_id
     and mission.mission_index = state.mission_index
    join public.player_profile_state profile on profile.auth_user_id = state.auth_user_id
    where state.auth_user_id = p_auth_user_id and state.mission_index = p_mission_index
  ), false);
$$;


ALTER FUNCTION "server_authority_private"."mission_is_active"("p_auth_user_id" "uuid", "p_mission_index" integer) OWNER TO "postgres";

--
-- Name: mission_pokemon_reward_candidates("uuid", integer, boolean); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."mission_pokemon_reward_candidates"("p_catalog_release_id" "uuid", "p_level" integer, "p_exclude_fossils" boolean) RETURNS TABLE("species_key" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
  with recursive lineage(root_species_key,species_key,minimum_level) as (
    select species.species_key,species.species_key,5 from public.catalog_species species
    where species.catalog_release_id=p_catalog_release_id
    union all
    select lineage.root_species_key,evolution.species_key,
      greatest(lineage.minimum_level,case when evolution.trigger_key='level'
        then coalesce((evolution.trigger_rules->>'level')::integer,101)
        else coalesce(parent.encounter_min_level,5) end)
    from lineage join public.catalog_species_evolution evolution
      on evolution.catalog_release_id=p_catalog_release_id and evolution.target_species_key=lineage.species_key
    join public.catalog_species parent on parent.catalog_release_id=p_catalog_release_id
      and parent.species_key=evolution.species_key
  ), minimums as (
    select root_species_key,max(minimum_level) minimum_level from lineage group by root_species_key
  )
  select species.species_key from public.catalog_species species
  join minimums on minimums.root_species_key=species.species_key
  where species.catalog_release_id=p_catalog_release_id and p_level between 5 and 100
    and minimums.minimum_level<=p_level and species.encounter_rarity_key<>'l'
    and (not coalesce(p_exclude_fossils,false) or species.encounter_rarity_key<>'f');
$$;


ALTER FUNCTION "server_authority_private"."mission_pokemon_reward_candidates"("p_catalog_release_id" "uuid", "p_level" integer, "p_exclude_fossils" boolean) OWNER TO "postgres";

--
-- Name: ordinary_progression_projection("uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."ordinary_progression_projection"("p_auth_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
  select case when progression.id is null then null else jsonb_build_object(
    'id',progression.id,'battle_id',progression.battle_id,'contract_key',progression.contract_key,
    'level_cap',progression.level_cap,'status',progression.status,
    'pokemon',coalesce((select jsonb_agg(jsonb_build_object(
      'pokemon_instance_id',entry.pokemon_instance_id,'team_slot',entry.team_slot,'exp_awarded',entry.exp_awarded,
      'ko_count',entry.ko_count,'levels_gained',entry.levels_gained,'status',entry.status,
      'pending_resolution_id',entry.pending_resolution_id) order by entry.award_order)
      from public.player_ordinary_progression_pokemon entry where entry.progression_id=progression.id),'[]'::jsonb)) end
  from (select 1) singleton left join lateral(select * from public.player_ordinary_progression
    where auth_user_id=p_auth_user_id and status<>'completed' order by created_at limit 1) progression on true
$$;


ALTER FUNCTION "server_authority_private"."ordinary_progression_projection"("p_auth_user_id" "uuid") OWNER TO "postgres";

--
-- Name: pin_admin_gym_waiting(); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."pin_admin_gym_waiting"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  if new.contract_key = 'admin_gym' then
    if new.gym_key not in ('isola-cannella','smeraldopoli') then
      raise exception 'admin_gym is restricted to the two catalog admin gyms' using errcode = '22023';
    end if;
    new.waiting_for := case when new.first_actor = 'npc' then 'admin' else 'player' end;
  elsif new.contract_key = 'league' then
    if new.league_member_index not between 0 and 4 then
      raise exception 'league member is invalid' using errcode = '22023';
    end if;
    new.waiting_for := case when new.first_actor = 'npc' then 'admin' else 'player' end;
  elsif new.waiting_for is not null or new.admin_items <> '[]'::jsonb then
    raise exception 'admin turn state belongs only to an admin battle' using errcode = '22023';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "server_authority_private"."pin_admin_gym_waiting"() OWNER TO "postgres";

--
-- Name: pin_pending_battle_engine(); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."pin_pending_battle_engine"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
begin
  if new.engine_runtime_state = 'pending' and new.requested_engine_version is null then
    if not exists (
      select 1 from public.catalog_engine_runtime_binding binding
      where binding.catalog_release_id = new.catalog_release_id and binding.enabled
        and binding.engine_version = 'pokemon-game-revival'
        and binding.engine_checksum = 'b5ebe27b5acf55f4f318dec15d736ac4eac4bd3a1d35f39d9d223ed63aafaf71'
    ) then
      raise exception 'pending battle has no enabled engine binding' using errcode = '0A000';
    end if;
    new.requested_engine_version := 'pokemon-game-revival';
    new.requested_engine_checksum := 'b5ebe27b5acf55f4f318dec15d736ac4eac4bd3a1d35f39d9d223ed63aafaf71';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "server_authority_private"."pin_pending_battle_engine"() OWNER TO "postgres";

--
-- Name: player_command_revision_conflict("uuid", bigint); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."player_command_revision_conflict"("p_command_id" "uuid", "p_expected_revision" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare
  v_auth_user_id uuid := auth.uid();
  v_current_revision bigint;
begin
  -- Invalid envelopes and unauthenticated calls remain the responsibility of
  -- the canonical command implementation so their existing errors are kept.
  if v_auth_user_id is null or p_command_id is null or p_expected_revision is null
    or p_expected_revision < 0 then
    return null;
  end if;

  -- Receipt-first idempotency is mandatory: a replay of a committed command
  -- must return its receipt even though the player revision has since moved.
  if exists (
    select 1
    from public.player_command_receipt receipt
    where receipt.auth_user_id = v_auth_user_id
      and receipt.command_id = p_command_id
  ) then
    return null;
  end if;

  select revision into v_current_revision
  from public.player_state_revision
  where auth_user_id = v_auth_user_id;

  if v_current_revision is null or v_current_revision = p_expected_revision then
    return null;
  end if;

  return jsonb_build_object(
    'ok', false,
    'applied', false,
    'conflict', 'player_revision',
    'player_revision', v_current_revision
  );
end;
$$;


ALTER FUNCTION "server_authority_private"."player_command_revision_conflict"("p_command_id" "uuid", "p_expected_revision" bigint) OWNER TO "postgres";

--
-- Name: player_state_projection("uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."player_state_projection"("p_auth_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
  select server_authority_private.player_state_projection_before_battle_shop(p_auth_user_id)
$$;


ALTER FUNCTION "server_authority_private"."player_state_projection"("p_auth_user_id" "uuid") OWNER TO "postgres";

--
-- Name: player_state_projection_before_battle_points("uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."player_state_projection_before_battle_points"("p_auth_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'has_player', profile.auth_user_id is not null,
    'revision', coalesce(revision.revision, 0),
    'profile', case when profile.auth_user_id is null then null else jsonb_build_object(
      'auth_user_id', profile.auth_user_id,
      'trainer_index', profile.trainer_index,
      'pokedollars', profile.pokedollars,
      'badges', profile.badges,
      'starter_status', profile.starter_status,
      'catalog_release_id', profile.catalog_release_id
    ) end,
    'team', coalesce((
      select jsonb_agg(pokemon.state || jsonb_build_object(
        'instance_id', pokemon.id, 'instance_revision', pokemon.revision,
        'catalog_release_id', pokemon.catalog_release_id, 'debug_created', pokemon.debug_created
      ) order by placement.slot_index)
      from public.player_pokemon_placement placement
      join public.player_pokemon_instance pokemon
        on pokemon.id = placement.pokemon_instance_id and pokemon.auth_user_id = placement.auth_user_id
      where placement.auth_user_id = p_auth_user_id and placement.placement_type = 'team'
    ), '[]'::jsonb),
    'box', coalesce((
      select jsonb_agg(jsonb_build_object(
        'box_index', placement.box_index,
        'pokemon', pokemon.state || jsonb_build_object(
          'instance_id', pokemon.id, 'instance_revision', pokemon.revision,
          'catalog_release_id', pokemon.catalog_release_id, 'debug_created', pokemon.debug_created
        )
      ) order by placement.box_index)
      from public.player_pokemon_placement placement
      join public.player_pokemon_instance pokemon
        on pokemon.id = placement.pokemon_instance_id and pokemon.auth_user_id = placement.auth_user_id
      where placement.auth_user_id = p_auth_user_id and placement.placement_type = 'box'
    ), '[]'::jsonb),
    'daycare', server_authority_private.daycare_projection(p_auth_user_id),
    'pending_resolutions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', resolution.id, 'pokemon_instance_id', resolution.pokemon_instance_id,
        'resolution_type', resolution.resolution_type, 'options', resolution.options,
        'status', resolution.status, 'expected_revision', resolution.expected_revision,
        'created_at', resolution.created_at
      ) order by resolution.created_at)
      from public.player_pending_resolution resolution
      where resolution.auth_user_id = p_auth_user_id and resolution.status = 'pending'
    ), '[]'::jsonb),
    'items', coalesce((
      select jsonb_agg(jsonb_build_array(inventory.item_index, inventory.quantity)
        order by case inventory.item_index when 103 then 0 when 100 then 1 else 2 end, inventory.item_index)
      from public.player_inventory_item inventory
      where inventory.auth_user_id = p_auth_user_id
    ), '[]'::jsonb),
    'dex', coalesce((
      select jsonb_agg(species.dex_number order by species.dex_number)
      from public.player_dex_entry dex
      join public.catalog_species species
        on species.catalog_release_id = dex.catalog_release_id and species.species_key = dex.species_key
      where dex.auth_user_id = p_auth_user_id
    ), '[]'::jsonb),
    'starter', (
      select jsonb_build_object(
        'pokemon_instance_id', starter.pokemon_instance_id, 'species_key', starter.species_key,
        'gender', starter.gender_key, 'command_id', starter.command_id, 'selected_at', starter.selected_at
      )
      from public.player_starter_selection starter
      where starter.auth_user_id = p_auth_user_id
    ),
    'shop_purchases', coalesce((
      select jsonb_agg(jsonb_build_object(
        'item_index', purchase.item_index, 'purchased_quantity', purchase.purchased_quantity
      ) order by purchase.item_index)
      from public.player_shop_purchase_state purchase
      where purchase.auth_user_id = p_auth_user_id
    ), '[]'::jsonb),
    'garden', jsonb_build_object(
      'plant_1', garden.plant_1, 'plant_2', garden.plant_2, 'plant_3', garden.plant_3,
      'seed_time_1', garden.seed_time_1, 'seed_time_2', garden.seed_time_2, 'seed_time_3', garden.seed_time_3,
      'ready_at_1', garden.ready_at_1, 'ready_at_2', garden.ready_at_2, 'ready_at_3', garden.ready_at_3
    ),
    'daily_berry', (
      select jsonb_build_object(
        'last_claimed_at', daily.claimed_at, 'last_claim_local_date', daily.last_claim_local_date,
        'reward_item_index', daily.reward_item_index
      )
      from public.player_daily_claim_state daily
      where daily.auth_user_id = p_auth_user_id and daily.claim_type = 'berry'
    ),
    'active_encounter', server_authority_private.active_encounter_projection(p_auth_user_id),
    'flute_daily', coalesce((
      select jsonb_agg(jsonb_build_object(
        'limit_type', flute.flute_key, 'use_count', flute.use_count, 'last_claimed_at', flute.last_used_at
      ) order by flute.flute_key)
      from public.player_flute_daily_usage flute
      where flute.auth_user_id = p_auth_user_id
        and flute.usage_date = (now() at time zone 'Europe/Rome')::date
    ), '[]'::jsonb),
    'missions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'mission_index', mission.mission_index, 'counter', mission.counter,
        'claim_status', mission.claim_status, 'tracked_keys', to_jsonb(mission.tracked_keys),
        'last_counted_day', mission.last_counted_day, 'claim_count', mission.claim_count,
        'last_claimed_at', mission.last_claimed_at, 'daily_reset_date', mission.daily_reset_date, 'updated_at', mission.updated_at
      ) order by mission.mission_index)
      from public.player_mission_state mission
      where mission.auth_user_id = p_auth_user_id
    ), '[]'::jsonb),
    'training_progression', server_authority_private.training_progression_projection(p_auth_user_id),
    'training_daily', coalesce((
      select jsonb_agg(jsonb_build_object(
        'limit_type', 'training_' || claim.difficulty, 'last_claimed_at', claim.last_claimed_at
      ) order by claim.difficulty)
      from public.player_training_daily_claim claim
      where claim.auth_user_id = p_auth_user_id
    ), '[]'::jsonb),
    'ordinary_progression', server_authority_private.ordinary_progression_projection(p_auth_user_id)
  )
  from (select p_auth_user_id as auth_user_id) requested
  left join public.player_profile_state profile on profile.auth_user_id = requested.auth_user_id
  left join public.player_state_revision revision on revision.auth_user_id = requested.auth_user_id
  left join lateral (
    select
      max(berry_item_index) filter (where plot_index = 0) as plant_1,
      max(berry_item_index) filter (where plot_index = 1) as plant_2,
      max(berry_item_index) filter (where plot_index = 2) as plant_3,
      max(planted_at) filter (where plot_index = 0) as seed_time_1,
      max(planted_at) filter (where plot_index = 1) as seed_time_2,
      max(planted_at) filter (where plot_index = 2) as seed_time_3,
      max(ready_at) filter (where plot_index = 0) as ready_at_1,
      max(ready_at) filter (where plot_index = 1) as ready_at_2,
      max(ready_at) filter (where plot_index = 2) as ready_at_3
    from public.player_garden_plot_state plot
    where plot.auth_user_id = requested.auth_user_id
  ) garden on true;
$$;


ALTER FUNCTION "server_authority_private"."player_state_projection_before_battle_points"("p_auth_user_id" "uuid") OWNER TO "postgres";

--
-- Name: player_state_projection_before_battle_shop("uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."player_state_projection_before_battle_shop"("p_auth_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_result jsonb; v_tower jsonb;
begin
  v_result:=server_authority_private.player_state_projection_before_battle_tower_attempt(p_auth_user_id);
  select jsonb_build_object(
    'run_id',run.id,
    'wins',run.wins,
    'next_challenge',run.next_challenge,
    'status',run.status,
    'attempted_today',true
  ) into v_tower
  from public.authoritative_battle_tower_run run
  where run.auth_user_id=p_auth_user_id
    and run.attempt_date=(now() at time zone 'Europe/Rome')::date
  order by run.created_at desc limit 1;
  return jsonb_set(v_result,'{battle_tower}',coalesce(v_tower,jsonb_build_object(
    'run_id',null,'wins',0,'next_challenge',1,'attempted_today',false
  )),true);
end;
$$;


