--
-- Name: player_state_projection_before_battle_tower_record("uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."player_state_projection_before_battle_tower_record"("p_auth_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_result jsonb; v_points bigint; v_run jsonb;
begin
  v_result:=server_authority_private.player_state_projection_before_battle_points(p_auth_user_id);
  select battle_points into v_points from public.player_profile_state where auth_user_id=p_auth_user_id;
  select jsonb_build_object('run_id',id,'wins',wins,'next_challenge',next_challenge,'status',status)
    into v_run from public.authoritative_battle_tower_run
    where auth_user_id=p_auth_user_id and status in ('active','awaiting_next') order by created_at desc limit 1;
  v_result:=jsonb_set(v_result,'{profile,battle_points}',to_jsonb(coalesce(v_points,0)),true);
  return jsonb_set(v_result,'{battle_tower}',coalesce(v_run,'null'::jsonb),true);
end;
$$;


