        'ready_at_1', (select ready_at from public.player_garden_plot_state where auth_user_id = p_auth_user_id and plot_index = 0),
        'ready_at_2', (select ready_at from public.player_garden_plot_state where auth_user_id = p_auth_user_id and plot_index = 1),
        'ready_at_3', (select ready_at from public.player_garden_plot_state where auth_user_id = p_auth_user_id and plot_index = 2)
      ),
      'daily_berry', (
        select jsonb_build_object(
