--
-- Name: player_state_projection_without_shop("uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."player_state_projection_without_shop"("p_auth_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'has_player', profile.auth_user_id is not null,
    'revision', coalesce(revision.revision, 0),
    'profile', case when profile.auth_user_id is null then null else jsonb_build_object(
      'auth_user_id', profile.auth_user_id,
      'trainer_index', profile.trainer_index,
      'pokedollars', profile.pokedollars,
      'badges', profile.badges,
      'starter_status', profile.starter_status,
      'catalog_release_id', profile.catalog_release_id
    ) end,
    'team', coalesce((
      select jsonb_agg(
        pokemon.state || jsonb_build_object(
          'instance_id', pokemon.id,
          'instance_revision', pokemon.revision,
          'catalog_release_id', pokemon.catalog_release_id
        )
        order by placement.slot_index
      )
      from public.player_pokemon_placement placement
      join public.player_pokemon_instance pokemon
        on pokemon.id = placement.pokemon_instance_id
       and pokemon.auth_user_id = placement.auth_user_id
      where placement.auth_user_id = p_auth_user_id
        and placement.placement_type = 'team'
    ), '[]'::jsonb),
    'box', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'box_index', placement.box_index,
          'pokemon', pokemon.state || jsonb_build_object(
            'instance_id', pokemon.id,
            'instance_revision', pokemon.revision,
            'catalog_release_id', pokemon.catalog_release_id
          )
        )
        order by placement.box_index
      )
      from public.player_pokemon_placement placement
      join public.player_pokemon_instance pokemon
        on pokemon.id = placement.pokemon_instance_id
       and pokemon.auth_user_id = placement.auth_user_id
      where placement.auth_user_id = p_auth_user_id
        and placement.placement_type = 'box'
    ), '[]'::jsonb),
    'daycare', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'slot_index', placement.slot_index,
          'pokemon', pokemon.state || jsonb_build_object(
            'instance_id', pokemon.id,
            'instance_revision', pokemon.revision,
            'catalog_release_id', pokemon.catalog_release_id
          )
        )
        order by placement.slot_index
      )
      from public.player_pokemon_placement placement
      join public.player_pokemon_instance pokemon
        on pokemon.id = placement.pokemon_instance_id
       and pokemon.auth_user_id = placement.auth_user_id
      where placement.auth_user_id = p_auth_user_id
        and placement.placement_type = 'daycare'
    ), '[]'::jsonb),
    'items', coalesce((
      select jsonb_agg(
        jsonb_build_array(inventory.item_index, inventory.quantity)
        order by case inventory.item_index when 103 then 0 when 100 then 1 else 2 end,
                 inventory.item_index
      )
      from public.player_inventory_item inventory
      where inventory.auth_user_id = p_auth_user_id
    ), '[]'::jsonb),
    'dex', coalesce((
      select jsonb_agg(species.dex_number order by species.dex_number)
      from public.player_dex_entry dex
      join public.catalog_species species
        on species.catalog_release_id = dex.catalog_release_id
       and species.species_key = dex.species_key
      where dex.auth_user_id = p_auth_user_id
    ), '[]'::jsonb),
    'starter', (
      select jsonb_build_object(
        'pokemon_instance_id', starter.pokemon_instance_id,
        'species_key', starter.species_key,
        'gender', starter.gender_key,
        'command_id', starter.command_id,
        'selected_at', starter.selected_at
      )
      from public.player_starter_selection starter
      where starter.auth_user_id = p_auth_user_id
    )
  )
  from (select p_auth_user_id as auth_user_id) requested
  left join public.player_profile_state profile
    on profile.auth_user_id = requested.auth_user_id
  left join public.player_state_revision revision
    on revision.auth_user_id = requested.auth_user_id;
$$;


ALTER FUNCTION "server_authority_private"."player_state_projection_without_shop"("p_auth_user_id" "uuid") OWNER TO "postgres";

--
-- Name: pokemon_has_active_reference("uuid", "uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."pokemon_has_active_reference"("p_auth_user_id" "uuid", "p_pokemon_instance_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $_$
  select exists (
    select 1
    from public.player_pending_resolution resolution
    where resolution.auth_user_id = p_auth_user_id
      and resolution.pokemon_instance_id = p_pokemon_instance_id
      and resolution.status = 'pending'
  ) or exists (
    select 1
    from public.player_encounter encounter
    where encounter.auth_user_id = p_auth_user_id
      and encounter.status = 'active'
      and encounter.encounter_state::text like '%' || p_pokemon_instance_id::text || '%'
  ) or exists (
    select 1
    from public.authoritative_battle_participant participant
    join public.authoritative_battle battle on battle.id = participant.battle_id
    where battle.auth_user_id = p_auth_user_id
      and battle.status in ('active', 'needs_player_switch')
      and participant.pokemon_instance_id = p_pokemon_instance_id
  ) or exists (
    select 1
    from public.authoritative_league_run_pokemon pokemon
    join public.authoritative_league_run run on run.id = pokemon.run_id
    where run.auth_user_id = p_auth_user_id
      and run.status in ('active', 'awaiting_battle')
      and pokemon.pokemon_instance_id = p_pokemon_instance_id
  ) or exists (
    select 1
    from public.authoritative_battle_tower_run_pokemon pokemon
    join public.authoritative_battle_tower_run run on run.id = pokemon.run_id
    where run.auth_user_id = p_auth_user_id
      and run.status in ('active', 'awaiting_next')
      and pokemon.pokemon_instance_id = p_pokemon_instance_id
  );
$_$;


ALTER FUNCTION "server_authority_private"."pokemon_has_active_reference"("p_auth_user_id" "uuid", "p_pokemon_instance_id" "uuid") OWNER TO "postgres";

--
-- Name: prepare_edge_battle_command("uuid", "uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."prepare_edge_battle_command"("p_auth_user_id" "uuid", "p_battle_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare v_result jsonb; v_battle public.authoritative_battle%rowtype; v_run public.authoritative_battle_tower_run%rowtype; v_seed_hash text;
begin
  v_result:=server_authority_private.prepare_edge_battle_command_with_inventory(p_auth_user_id,p_battle_id);
  if v_result->'battle'='null'::jsonb then return v_result; end if;
  select * into v_battle from public.authoritative_battle where id=(v_result#>>'{battle,battle_id}')::uuid;
  if v_battle.contract_key='battle_tower' then
    select * into v_run from public.authoritative_battle_tower_run where id=v_battle.tower_run_id;
    v_result:=jsonb_set(v_result,'{battle,player_items}','[]'::jsonb,true);
    v_result:=jsonb_set(v_result,'{battle,tower_run_id}',to_jsonb(v_battle.tower_run_id),true);
    v_result:=jsonb_set(v_result,'{battle,tower_challenge}',to_jsonb(v_battle.tower_challenge),true);
    v_result:=jsonb_set(v_result,'{battle,tower_wins}',to_jsonb(v_run.wins),true);
    v_seed_hash:=encode(digest(convert_to(jsonb_build_object('contract','battle_tower','run',v_battle.tower_run_id,
      'challenge',v_battle.tower_challenge,'entropy',v_battle.rng_state)::text,'UTF8'),'sha256'),'hex');
    v_result:=jsonb_set(v_result,'{initialization_seed_hash}',to_jsonb(v_seed_hash),true);
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION "server_authority_private"."prepare_edge_battle_command"("p_auth_user_id" "uuid", "p_battle_id" "uuid") OWNER TO "postgres";

--
-- Name: prepare_edge_battle_command_core("uuid", "uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."prepare_edge_battle_command_core"("p_auth_user_id" "uuid", "p_battle_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare v_result jsonb; v_battle public.authoritative_battle%rowtype; v_run public.authoritative_battle_tower_run%rowtype; v_seed_hash text;
begin
  v_result:=server_authority_private.prepare_edge_battle_command_with_inventory(p_auth_user_id,p_battle_id);
  if v_result->'battle'='null'::jsonb then return v_result; end if;
  select * into v_battle from public.authoritative_battle where id=(v_result#>>'{battle,battle_id}')::uuid;
  if v_battle.contract_key='battle_tower' then
    select * into v_run from public.authoritative_battle_tower_run where id=v_battle.tower_run_id;
    v_result:=jsonb_set(v_result,'{battle,player_items}','[]'::jsonb,true);
    v_result:=jsonb_set(v_result,'{battle,tower_run_id}',to_jsonb(v_battle.tower_run_id),true);
    v_result:=jsonb_set(v_result,'{battle,tower_challenge}',to_jsonb(v_battle.tower_challenge),true);
    v_result:=jsonb_set(v_result,'{battle,tower_wins}',to_jsonb(v_run.wins),true);
    v_seed_hash:=encode(digest(convert_to(jsonb_build_object('contract','battle_tower','run',v_battle.tower_run_id,
      'challenge',v_battle.tower_challenge,'entropy',v_battle.rng_state)::text,'UTF8'),'sha256'),'hex');
    v_result:=jsonb_set(v_result,'{initialization_seed_hash}',to_jsonb(v_seed_hash),true);
  end if;
  return v_result;
end;
$$;


