--
-- Name: prepare_edge_battle_command_with_admin_context("uuid", "uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."prepare_edge_battle_command_with_admin_context"("p_auth_user_id" "uuid", "p_battle_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare v_result jsonb; v_catalog uuid; v_contract text; v_battle_id uuid; v_gym_key text;
  v_seed_hash text; v_rng_state jsonb; v_admin_items jsonb; v_run uuid; v_member integer;
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'service role required' using errcode='42501'; end if;
  v_result := server_authority_private.prepare_edge_battle_command_with_roster(p_auth_user_id,p_battle_id);
  if v_result -> 'battle' = 'null'::jsonb then return v_result; end if;
  v_catalog := (v_result #>> '{battle,catalog_release_id}')::uuid;
  v_contract := v_result #>> '{battle,contract_key}';
  v_battle_id := (v_result #>> '{battle,battle_id}')::uuid;
  v_result := jsonb_set(v_result,'{battle,player_items}',case when v_contract='training'
    then server_authority_private.training_battle_inventory(p_auth_user_id,v_catalog) else '[]'::jsonb end,true);
  if v_contract in ('gym','admin_gym','league') then
    select gym_key,rng_state,league_run_id,league_member_index into v_gym_key,v_rng_state,v_run,v_member
      from public.authoritative_battle where id=v_battle_id;
    v_seed_hash := encode(digest(convert_to(jsonb_build_object('input_hash',v_result->>'input_snapshot_hash',
      'context',coalesce(v_gym_key,v_run::text||':'||v_member::text),'entropy',v_rng_state)::text,'UTF8'),'sha256'),'hex');
    v_result := jsonb_set(v_result,'{initialization_seed_hash}',to_jsonb(v_seed_hash),true);
    v_result := jsonb_set(v_result,'{battle,gym_key}',coalesce(to_jsonb(v_gym_key),'null'::jsonb),true);
    v_result := jsonb_set(v_result,'{battle,league_run_id}',coalesce(to_jsonb(v_run),'null'::jsonb),true);
    v_result := jsonb_set(v_result,'{battle,league_member_index}',coalesce(to_jsonb(v_member),'null'::jsonb),true);
    v_result := jsonb_set(v_result,'{battle,presentation}',coalesce((select presentation from public.authoritative_battle where id=v_battle_id),'{}'::jsonb),true);
  end if;
  if v_contract in ('admin_gym','league') then
    select coalesce(jsonb_agg(jsonb_build_array(item_index,quantity) order by item_index),'[]'::jsonb)
      into v_admin_items from public.catalog_admin_battle_item where catalog_release_id=v_catalog;
    v_result := jsonb_set(v_result,'{battle,admin_items}',v_admin_items,true);
    v_result := jsonb_set(v_result,'{battle,waiting_for}',coalesce(to_jsonb((select waiting_for from public.authoritative_battle where id=v_battle_id)),'null'::jsonb),true);
  else v_result := jsonb_set(v_result,'{battle,admin_items}','[]'::jsonb,true); end if;
  return v_result;
end;
$$;


ALTER FUNCTION "server_authority_private"."prepare_edge_battle_command_with_admin_context"("p_auth_user_id" "uuid", "p_battle_id" "uuid") OWNER TO "postgres";

--
-- Name: prepare_edge_battle_command_with_contract_items("uuid", "uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."prepare_edge_battle_command_with_contract_items"("p_auth_user_id" "uuid", "p_battle_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare v_result jsonb; v_catalog uuid; v_contract text; v_battle_id uuid; v_gym_key text;
  v_seed_hash text; v_rng_state jsonb; v_admin_items jsonb; v_run uuid; v_member integer;
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'service role required' using errcode='42501'; end if;
  v_result := server_authority_private.prepare_edge_battle_command_with_roster(p_auth_user_id,p_battle_id);
  if v_result -> 'battle' = 'null'::jsonb then return v_result; end if;
  v_catalog := (v_result #>> '{battle,catalog_release_id}')::uuid;
  v_contract := v_result #>> '{battle,contract_key}';
  v_battle_id := (v_result #>> '{battle,battle_id}')::uuid;
  v_result := jsonb_set(v_result,'{battle,player_items}',case when v_contract='training'
    then server_authority_private.training_battle_inventory(p_auth_user_id,v_catalog) else '[]'::jsonb end,true);
  if v_contract in ('gym','admin_gym','league') then
    select gym_key,rng_state,league_run_id,league_member_index into v_gym_key,v_rng_state,v_run,v_member
      from public.authoritative_battle where id=v_battle_id;
    v_seed_hash := encode(digest(convert_to(jsonb_build_object('input_hash',v_result->>'input_snapshot_hash',
      'context',coalesce(v_gym_key,v_run::text||':'||v_member::text),'entropy',v_rng_state)::text,'UTF8'),'sha256'),'hex');
    v_result := jsonb_set(v_result,'{initialization_seed_hash}',to_jsonb(v_seed_hash),true);
    v_result := jsonb_set(v_result,'{battle,gym_key}',coalesce(to_jsonb(v_gym_key),'null'::jsonb),true);
    v_result := jsonb_set(v_result,'{battle,league_run_id}',coalesce(to_jsonb(v_run),'null'::jsonb),true);
    v_result := jsonb_set(v_result,'{battle,league_member_index}',coalesce(to_jsonb(v_member),'null'::jsonb),true);
    v_result := jsonb_set(v_result,'{battle,presentation}',coalesce((select presentation from public.authoritative_battle where id=v_battle_id),'{}'::jsonb),true);
  end if;
  if v_contract='debug_training' then
    select rng_state into v_rng_state from public.authoritative_battle where id=v_battle_id;
    v_seed_hash := encode(digest(convert_to(jsonb_build_object('input_hash',v_result->>'input_snapshot_hash',
      'contract','debug_training','entropy',v_rng_state)::text,'UTF8'),'sha256'),'hex');
    v_result := jsonb_set(v_result,'{initialization_seed_hash}',to_jsonb(v_seed_hash),true);
    v_result := jsonb_set(v_result,'{battle,presentation}',coalesce((select presentation from public.authoritative_battle where id=v_battle_id),'{}'::jsonb),true);
  end if;
  if v_contract in ('admin_gym','league','debug_training') then
    select coalesce(jsonb_agg(jsonb_build_array(item_index,case when v_contract='debug_training' then 3 else least(3,quantity) end) order by item_index),'[]'::jsonb)
      into v_admin_items
      from public.catalog_admin_battle_item
      where catalog_release_id=v_catalog;
    v_result := jsonb_set(v_result,'{battle,admin_items}',v_admin_items,true);
    if v_contract in ('admin_gym','league') then
      v_result := jsonb_set(v_result,'{battle,waiting_for}',coalesce(to_jsonb((select waiting_for from public.authoritative_battle where id=v_battle_id)),'null'::jsonb),true);
    end if;
  else
    v_result := jsonb_set(v_result,'{battle,admin_items}','[]'::jsonb,true);
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION "server_authority_private"."prepare_edge_battle_command_with_contract_items"("p_auth_user_id" "uuid", "p_battle_id" "uuid") OWNER TO "postgres";

--
-- Name: prepare_edge_battle_command_with_inventory("uuid", "uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."prepare_edge_battle_command_with_inventory"("p_auth_user_id" "uuid", "p_battle_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare v_result jsonb; v_contract text; v_catalog uuid;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'service role required' using errcode='42501'; end if;
  v_result:=server_authority_private.prepare_edge_battle_command_with_contract_items(p_auth_user_id,p_battle_id);
  if v_result->'battle'='null'::jsonb then return v_result; end if;
  v_contract:=v_result#>>'{battle,contract_key}';
  v_catalog:=(v_result#>>'{battle,catalog_release_id}')::uuid;
  v_result:=jsonb_set(v_result,'{battle,player_items}',case when v_contract='capture'
    then server_authority_private.capture_battle_inventory(p_auth_user_id,v_catalog)
    else server_authority_private.training_battle_inventory(p_auth_user_id,v_catalog) end,true);
  return v_result;
end;
$$;


ALTER FUNCTION "server_authority_private"."prepare_edge_battle_command_with_inventory"("p_auth_user_id" "uuid", "p_battle_id" "uuid") OWNER TO "postgres";

--
-- Name: prepare_edge_battle_command_with_roster("uuid", "uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."prepare_edge_battle_command_with_roster"("p_auth_user_id" "uuid", "p_battle_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $$
declare v_result jsonb; v_battle public.authoritative_battle%rowtype; v_seed_hash text; v_participants jsonb;
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'service role required' using errcode = '42501'; end if;
  v_result := server_authority_private.prepare_edge_battle_command_core(p_auth_user_id, p_battle_id);
  if v_result -> 'battle' = 'null'::jsonb then return v_result; end if;
  select * into v_battle from public.authoritative_battle where id = (v_result #>> '{battle,battle_id}')::uuid;
  select coalesce(jsonb_agg(jsonb_build_object(
    'side', participant.side, 'slot_index', participant.slot_index,
    'pokemon_instance_id', participant.pokemon_instance_id, 'species_key', participant.species_key,
    'display_name', participant.display_name, 'ndex', species.dex_number,
    'level', participant.level, 'max_hp', participant.max_hp, 'current_hp', participant.current_hp,
    'type_keys', participant.type_keys, 'moves', participant.moves,
    'instance_revision', coalesce(server_authority_private.edge_jsonb_bigint(participant.source_snapshot -> 'instance_revision'), 0),
    'held_item_index', coalesce(server_authority_private.edge_jsonb_bigint(participant.source_snapshot -> 'i'), 0),
    'gender', participant.source_snapshot ->> 'g',
    'is_shiny', coalesce(server_authority_private.edge_jsonb_bigint(participant.source_snapshot -> 'sh'), 0) = 1,
    'is_mega', coalesce(server_authority_private.edge_jsonb_bigint(participant.source_snapshot -> 'mg'), 0) = 1,
    'exp_current', coalesce(server_authority_private.edge_jsonb_bigint(participant.source_snapshot -> 'xp'), 0),
    'exp_cap', species.experience_reward
  ) order by case participant.side when 'player' then 0 else 1 end, participant.slot_index), '[]'::jsonb)
  into v_participants from public.authoritative_battle_participant participant
  join public.catalog_species species on species.catalog_release_id = v_battle.catalog_release_id
    and species.species_key = participant.species_key
  where participant.battle_id = v_battle.id;
  v_result := jsonb_set(v_result, '{battle,participants}', v_participants, true);
  if v_battle.engine_runtime_state = 'pending' and v_battle.requested_engine_version is not null then
    if not exists (select 1 from public.catalog_engine_runtime_binding where catalog_release_id = v_battle.catalog_release_id
      and enabled and engine_version = v_battle.requested_engine_version and engine_checksum = v_battle.requested_engine_checksum) then
      raise exception 'incompatible active battle engine binding' using errcode = '0A000';
    end if;
    v_result := jsonb_set(v_result, '{battle,bound_engine_version}', to_jsonb(v_battle.requested_engine_version), true);
    v_result := jsonb_set(v_result, '{battle,bound_engine_checksum}', to_jsonb(v_battle.requested_engine_checksum), true);
  end if;
  if v_battle.contract_key = 'training' then
    v_seed_hash := encode(digest(convert_to(jsonb_build_object('input_hash', v_result ->> 'input_snapshot_hash',
      'difficulty', v_battle.training_difficulty, 'entropy', v_battle.rng_state)::text, 'UTF8'), 'sha256'), 'hex');
    v_result := jsonb_set(v_result, '{initialization_seed_hash}', to_jsonb(v_seed_hash), true);
    v_result := jsonb_set(v_result, '{battle,training_difficulty}', to_jsonb(v_battle.training_difficulty), true);
    v_result := jsonb_set(v_result, '{battle,presentation}', coalesce(v_battle.presentation, 'null'::jsonb), true);
    v_result := jsonb_set(v_result, '{battle,runtime_owner_id}', to_jsonb(v_battle.runtime_owner_id), true);
    v_result := jsonb_set(v_result, '{battle,bound_engine_version}', to_jsonb(v_battle.requested_engine_version), true);
    v_result := jsonb_set(v_result, '{battle,bound_engine_checksum}', to_jsonb(v_battle.requested_engine_checksum), true);
  end if;
  return v_result;
end;
$$;


