--
-- Name: preserve_pending_resolution_resolved_at(); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."preserve_pending_resolution_resolved_at"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'server_authority_private', 'pg_temp'
    AS $$
begin
  if new.status = 'pending' then
    new.resolved_at := null;
  elsif new.resolved_at is null then
    new.resolved_at := statement_timestamp();
  end if;
  return new;
end;
$$;


