--
-- Name: process_mission_command_receipt(); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."process_mission_command_receipt"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $_$
declare
  v_species_key text;
  v_dex_number integer;
  v_types jsonb := '[]'::jsonb;
  v_badges integer := 0;
  v_source_species_key text;
  v_item_index integer;
begin
  perform server_authority_private.sync_player_missions(new.auth_user_id);
  select profile.badges into v_badges from public.player_profile_state profile
  where profile.auth_user_id = new.auth_user_id;

  if new.command_type = 'choose_starter' then
    v_dex_number := case when coalesce(new.result ->> 'starter_dex_number', '') ~ '^[1-9][0-9]*$'
      then (new.result ->> 'starter_dex_number')::integer else null end;
    v_species_key := new.result -> 'starter' ->> 'species_key';
    if v_dex_number is null or v_species_key is null then
      raise exception 'starter receipt is missing canonical mission species data';
    end if;
    perform server_authority_private.apply_mission_fact(new.auth_user_id, 'pokedex-species-registered',
      jsonb_build_object('dexNumber', v_dex_number, 'speciesKey', v_species_key), new.created_at);
  elsif new.command_type = 'garden_harvest' then
    perform server_authority_private.apply_mission_fact(new.auth_user_id, 'berries-harvested',
      jsonb_build_object('itemIndex', new.result -> 'berry_index', 'quantity', new.result -> 'quantity'), new.created_at);
  elsif new.command_type in ('daycare_withdraw', 'resolve_daycare_withdrawal')
    and new.result ->> 'withdrawal_status' = 'completed' then
    select pokemon.species_key into v_species_key
    from public.player_pokemon_instance pokemon
    where pokemon.auth_user_id = new.auth_user_id
      and pokemon.id = (new.result ->> 'pokemon_instance_id')::uuid;
    if v_species_key is null then
      raise exception 'completed daycare receipt is missing its canonical Pokemon';
    end if;
    perform server_authority_private.apply_mission_fact(new.auth_user_id, 'daycare-cycle-completed',
      jsonb_build_object('speciesKey', v_species_key), new.created_at);
    if coalesce((new.result ->> 'levels_gained')::integer, 0) > 0 then
      perform server_authority_private.apply_mission_fact(new.auth_user_id, 'pokemon-level-up',
        jsonb_build_object('speciesKey', v_species_key), new.created_at);
    end if;
  elsif new.command_type = 'wild_capture_attempt' then
    select fact.item_index into v_item_index
    from public.player_mission_pending_item_fact fact
    join public.player_profile_state profile on profile.auth_user_id = fact.auth_user_id
    join public.catalog_item item
      on item.catalog_release_id = profile.catalog_release_id
     and item.item_index = fact.item_index
    where fact.auth_user_id = new.auth_user_id
      and fact.transaction_id = txid_current()
      and item.category_key = 'Ball'
    order by fact.item_index limit 1;
    if v_item_index is not null then
      perform server_authority_private.apply_mission_fact(new.auth_user_id, 'battle-item-used',
        jsonb_build_object('itemIndex', v_item_index), new.created_at);
    end if;
    if coalesce((new.result ->> 'capture_success')::boolean, false) then
      select pokemon.species_key, species.dex_number,
        coalesce((select jsonb_agg(species_type.type_key order by species_type.type_order)
          from public.catalog_species_type species_type
          where species_type.catalog_release_id = pokemon.catalog_release_id
            and species_type.species_key = pokemon.species_key), '[]'::jsonb)
      into v_species_key, v_dex_number, v_types
      from public.player_pokemon_instance pokemon
      join public.catalog_species species
        on species.catalog_release_id = pokemon.catalog_release_id and species.species_key = pokemon.species_key
      where pokemon.auth_user_id = new.auth_user_id
        and pokemon.id = (new.result ->> 'pokemon_instance_id')::uuid;
      if v_species_key is null or v_dex_number is null then
        raise exception 'successful capture receipt is missing canonical species data';
      end if;
      perform server_authority_private.apply_mission_fact(new.auth_user_id, 'pokemon-captured', jsonb_build_object(
        'speciesKey', v_species_key, 'dexNumber', v_dex_number, 'types', v_types, 'badges', v_badges), new.created_at);
      perform server_authority_private.apply_mission_fact(new.auth_user_id, 'pokedex-species-registered',
        jsonb_build_object('speciesKey', v_species_key, 'dexNumber', v_dex_number), new.created_at);
    end if;
  elsif new.command_type = 'pokemon_center_assign_held' then
    perform server_authority_private.apply_mission_fact(new.auth_user_id, 'held-item-assigned',
      jsonb_build_object('itemIndex', new.result -> 'item_index'), new.created_at);
  elsif new.command_type = 'pokemon_center_evolve' then
    select evolution.species_key into v_source_species_key
    from public.catalog_species_evolution evolution
    join public.player_profile_state profile on profile.catalog_release_id = evolution.catalog_release_id
    where profile.auth_user_id = new.auth_user_id
      and evolution.target_species_key = new.result ->> 'evolution_target_species_key'
      and evolution.trigger_key = 'item'
      and evolution.trigger_rules -> 'item' ->> 'itemIndex' = new.result ->> 'item_index'
    order by evolution.species_key limit 1;
    perform server_authority_private.apply_mission_fact(new.auth_user_id, 'pokemon-evolved', jsonb_build_object(
      'speciesKey', coalesce(v_source_species_key, new.result ->> 'evolution_target_species_key'),
      'targetSpeciesKey', new.result ->> 'evolution_target_species_key'), new.created_at);
  elsif new.command_type = 'mission_claim' then
    perform server_authority_private.apply_mission_fact(new.auth_user_id, 'mission-claimed',
      jsonb_build_object('missionIndex', new.result -> 'mission_index'), new.created_at);
  end if;
  delete from public.player_mission_pending_item_fact
  where auth_user_id = new.auth_user_id and transaction_id = txid_current();
  return new;
end;
$_$;


ALTER FUNCTION "server_authority_private"."process_mission_command_receipt"() OWNER TO "postgres";

--
-- Name: process_training_command_receipt(); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."process_training_command_receipt"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare v_entry jsonb; v_ordinal integer:=0; v_species text;
begin
  if new.command_type='training_terminal_reward' then
    perform server_authority_private.emit_mission_source_event(new,0,'training-victory',jsonb_build_object(
      'difficulty',new.result->>'training_difficulty','teamSizeAtStart',new.result->'training_team_size'));
    perform server_authority_private.apply_training_victory_missions(new.auth_user_id,new.command_id,0);
  elsif new.command_type='training_allocate' then
    for v_entry in select value from jsonb_array_elements(new.result->'level_events') loop
      select species_key into v_species from public.player_pokemon_instance where auth_user_id=new.auth_user_id
        and id=(v_entry->>'pokemonInstanceId')::uuid;
      perform server_authority_private.emit_mission_source_event(new,v_ordinal,'pokemon-level-up',jsonb_build_object(
        'speciesKey',v_species,'levels',v_entry->'levels','source','training'));
      v_ordinal:=v_ordinal+1;
    end loop;
  elsif new.command_type='training_resolve' and new.result->>'evolved_to_species_key' is not null then
    perform server_authority_private.emit_mission_source_event(new,0,'pokemon-evolved',jsonb_build_object(
      'speciesKey',new.result->>'evolved_from_species_key','targetSpeciesKey',new.result->>'evolved_to_species_key','source','training'));
  end if;
  return new;
end;
$$;


ALTER FUNCTION "server_authority_private"."process_training_command_receipt"() OWNER TO "postgres";

--
-- Name: protect_open_league_pokemon_delete(); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."protect_open_league_pokemon_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
begin
  if exists (select 1 from auth.users where id = old.auth_user_id)
    and exists (
      select 1
      from public.authoritative_league_run_pokemon frozen
      join public.authoritative_league_run run on run.id = frozen.run_id
      where frozen.pokemon_instance_id = old.id
        and run.status in ('awaiting_battle','active')
    ) then
    raise exception 'Pokemon belongs to an open authoritative League run'
      using errcode = '55000';
  end if;
  return old;
end;
$$;


ALTER FUNCTION "server_authority_private"."protect_open_league_pokemon_delete"() OWNER TO "postgres";

--
-- Name: read_edge_battle_events("uuid", "uuid", bigint, integer); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."read_edge_battle_events"("p_auth_user_id" "uuid", "p_battle_id" "uuid", "p_after_seq" bigint DEFAULT 0, "p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare
  v_result jsonb;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'service role required' using errcode = '42501';
  end if;
  if p_auth_user_id is null or p_battle_id is null or p_after_seq is null or p_after_seq < 0
    or p_limit is null or p_limit not between 1 and 100 then
    raise exception 'event pagination parameters are invalid' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.authoritative_battle battle
    where battle.id = p_battle_id and battle.auth_user_id = p_auth_user_id
  ) then raise exception 'authoritative battle was not found' using errcode = 'P0002'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'seq', page.seq,
    'battle_version', page.battle_version,
    'event_type', page.event_type,
    'event_data', page.event_data,
    'command_id', page.command_id,
    'rng_audit', page.rng_audit,
    'created_at', page.created_at
  ) order by page.seq), '[]'::jsonb)
  into v_result from (
    select event.* from public.authoritative_battle_event event
    where event.battle_id = p_battle_id and event.seq > p_after_seq
    order by event.seq limit p_limit
  ) page;
  return v_result;
end;
$$;


ALTER FUNCTION "server_authority_private"."read_edge_battle_events"("p_auth_user_id" "uuid", "p_battle_id" "uuid", "p_after_seq" bigint, "p_limit" integer) OWNER TO "postgres";

--
-- Name: reject_active_encounter_during_battle(); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."reject_active_encounter_during_battle"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
begin
  if new.status='active' and exists(select 1 from public.authoritative_battle battle
    where battle.auth_user_id=new.auth_user_id and battle.status in ('active','needs_player_switch')) then
    raise exception 'Completa l''attivitÃ  in corso prima di cercare PokÃ©mon' using errcode='P0001';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "server_authority_private"."reject_active_encounter_during_battle"() OWNER TO "postgres";

--
-- Name: reject_persisted_zero_inventory(); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."reject_persisted_zero_inventory"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
begin
  if exists (
    select 1
    from public.player_inventory_item inventory
    where inventory.auth_user_id = new.auth_user_id
      and inventory.item_index = new.item_index
      and inventory.quantity <= 0
  ) then
    raise exception 'inventory quantity must be positive at commit' using errcode = '23514';
  end if;
  return null;
end;
$$;


ALTER FUNCTION "server_authority_private"."reject_persisted_zero_inventory"() OWNER TO "postgres";

--
-- Name: resolve_daycare_withdrawal("uuid", bigint, "uuid", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."resolve_daycare_withdrawal"("p_command_id" "uuid", "p_expected_revision" bigint, "p_pending_resolution_id" "uuid", "p_choices" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
begin
  perform server_authority_private.assert_no_pending_ordinary_progression(auth.uid(),p_command_id);
  return server_authority_private.resolve_daycare_withdrawal_before_ordinary_guard(
    p_command_id,p_expected_revision,p_pending_resolution_id,p_choices);
end;
$$;


ALTER FUNCTION "server_authority_private"."resolve_daycare_withdrawal"("p_command_id" "uuid", "p_expected_revision" bigint, "p_pending_resolution_id" "uuid", "p_choices" "jsonb") OWNER TO "postgres";

--
-- Name: resolve_daycare_withdrawal_before_ordinary_guard("uuid", bigint, "uuid", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."resolve_daycare_withdrawal_before_ordinary_guard"("p_command_id" "uuid", "p_expected_revision" bigint, "p_pending_resolution_id" "uuid", "p_choices" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'extensions', 'pg_temp'
    AS $_$
declare
  v_auth_user_id uuid := auth.uid();
  v_request jsonb;
  v_request_hash text;
  v_receipt_type text;
  v_receipt_hash text;
  v_receipt_result jsonb;
  v_current_revision bigint;
  v_resolution public.player_pending_resolution%rowtype;
  v_daycare public.player_daycare_state%rowtype;
  v_instance public.player_pokemon_instance%rowtype;
  v_placement public.player_pokemon_placement%rowtype;
  v_level_rule public.catalog_level_rule%rowtype;
  v_starting_level integer;
  v_target_level integer;
  v_levels_gained integer;
  v_level_cap integer;
  v_team_count integer;
  v_move_count integer;
  v_offer_count integer;
  v_offer_index integer;
  v_move_index integer;
  v_replacement_slot integer;
  v_new_move_power integer;
  v_new_move_stats integer;
  v_offer jsonb;
  v_choice jsonb;
  v_moves jsonb;
  v_catalog_level_moves jsonb;
  v_catalog_evolutions jsonb;
  v_evolution_target text;
  v_result_species_key text;
  v_held_item_index integer;
  v_result jsonb;
begin
  if v_auth_user_id is null then
    raise exception 'authentication required' using errcode = '28000';
  end if;
  if p_command_id is null or p_pending_resolution_id is null then
    raise exception 'command id and pending resolution id are required' using errcode = '22023';
  end if;
  if p_expected_revision is null or p_expected_revision < 0 then
    raise exception 'expected revision must be non-negative' using errcode = '22023';
  end if;
  if p_choices is null or jsonb_typeof(p_choices) <> 'object'
    or not (p_choices ? 'moves') or not (p_choices ? 'evolution_target_species_key')
    or p_choices - 'moves' - 'evolution_target_species_key' <> '{}'::jsonb
    or jsonb_typeof(p_choices -> 'moves') <> 'array'
    or jsonb_typeof(p_choices -> 'evolution_target_species_key') not in ('string', 'null') then
    raise exception 'daycare resolution choices have an invalid shape' using errcode = '22023';
  end if;

  v_request := jsonb_build_object(
    'command_type', 'resolve_daycare_withdrawal',
    'expected_revision', p_expected_revision,
    'pending_resolution_id', p_pending_resolution_id,
    'choices', p_choices
  );
  v_request_hash := encode(digest(convert_to(v_request::text, 'UTF8'), 'sha256'), 'hex');
  perform pg_advisory_xact_lock(hashtextextended(v_auth_user_id::text || ':' || p_command_id::text, 0));

  select command_type, request_hash, result
  into v_receipt_type, v_receipt_hash, v_receipt_result
  from public.player_command_receipt
  where auth_user_id = v_auth_user_id and command_id = p_command_id;
  if found then
    if v_receipt_type <> 'resolve_daycare_withdrawal' or v_receipt_hash <> v_request_hash then
      raise exception 'command id was already used with a different payload' using errcode = '22023';
    end if;
    return v_receipt_result;
  end if;

  select revision into v_current_revision
  from public.player_state_revision
  where auth_user_id = v_auth_user_id
  for update;
  if not found then
    raise exception 'player state does not exist' using errcode = 'P0002';
  end if;
  if v_current_revision <> p_expected_revision then
    raise exception 'revision conflict: expected %, current %', p_expected_revision, v_current_revision using errcode = '40001';
  end if;

  select * into v_resolution
  from public.player_pending_resolution
  where id = p_pending_resolution_id and auth_user_id = v_auth_user_id
  for update;
  if not found then
    raise exception 'pending resolution was not found for the current player' using errcode = 'P0002';
  end if;
  if v_resolution.status <> 'pending' then
    raise exception 'daycare resolution is not pending' using errcode = '22023';
  end if;
  if v_resolution.expected_revision <> p_expected_revision then
    raise exception 'pending resolution revision does not match the player revision' using errcode = '40001';
  end if;
  if v_resolution.resolution_type not in ('move', 'evolution')
    or v_resolution.pokemon_instance_id is null
    or jsonb_typeof(v_resolution.options) <> 'object'
    or not (v_resolution.options ? 'source')
    or not (v_resolution.options ? 'daycare_slot_index')
    or not (v_resolution.options ? 'starting_level')
    or not (v_resolution.options ? 'target_level')
    or not (v_resolution.options ? 'levels_gained')
    or not (v_resolution.options ? 'charged_cost')
    or not (v_resolution.options ? 'level_cap')
    or not (v_resolution.options ? 'level_moves')
    or not (v_resolution.options ? 'evolutions')
    or v_resolution.options - 'source' - 'daycare_slot_index' - 'starting_level'
      - 'target_level' - 'levels_gained' - 'charged_cost' - 'level_cap'
      - 'level_moves' - 'evolutions' <> '{}'::jsonb
    or v_resolution.options ->> 'source' is distinct from 'daycare_withdrawal' then
    raise exception 'pending resolution is not a daycare withdrawal' using errcode = '22023';
  end if;

  select * into v_daycare
  from public.player_daycare_state
  where auth_user_id = v_auth_user_id
    and pokemon_instance_id = v_resolution.pokemon_instance_id
  for update;
  if not found or v_daycare.status <> 'withdraw_pending'
    or v_daycare.pending_resolution_id <> v_resolution.id then
    raise exception 'pending daycare metadata does not match the resolution' using errcode = '22023';
  end if;

  -- Match the lock order used by team/box and daycare commands.
  perform 1
  from public.player_pokemon_placement placement
  join public.player_pokemon_instance pokemon
    on pokemon.id = placement.pokemon_instance_id and pokemon.auth_user_id = placement.auth_user_id
  where placement.auth_user_id = v_auth_user_id
    and (placement.placement_type in ('team', 'daycare')
      or placement.pokemon_instance_id = v_resolution.pokemon_instance_id)
  order by placement.pokemon_instance_id
  for update of placement, pokemon;

  select * into v_instance
  from public.player_pokemon_instance
  where id = v_resolution.pokemon_instance_id and auth_user_id = v_auth_user_id;
  if not found then
    raise exception 'Pokemon instance is not owned by the current player' using errcode = '22023';
  end if;
  select * into v_placement
  from public.player_pokemon_placement
  where pokemon_instance_id = v_instance.id and auth_user_id = v_auth_user_id;
  if not found or v_placement.placement_type <> 'daycare'
    or v_placement.slot_index <> (v_resolution.options ->> 'daycare_slot_index')::integer then
    raise exception 'Pokemon is not in the frozen daycare slot' using errcode = '22023';
  end if;
  if v_instance.catalog_release_id <> v_daycare.catalog_release_id then
    raise exception 'daycare and Pokemon catalog releases do not match' using errcode = '22023';
  end if;
  if v_instance.state ->> 's' is distinct from v_instance.species_key then
    raise exception 'canonical Pokemon species state is inconsistent' using errcode = '22023';
  end if;

  if coalesce(v_resolution.options ->> 'starting_level', '') !~ '^[1-9][0-9]*$'
    or coalesce(v_resolution.options ->> 'target_level', '') !~ '^[1-9][0-9]*$'
    or coalesce(v_resolution.options ->> 'levels_gained', '') !~ '^[0-9]+$'
    or coalesce(v_resolution.options ->> 'level_cap', '') !~ '^[1-9][0-9]*$'
    or coalesce(v_resolution.options ->> 'charged_cost', '') !~ '^[0-9]+$'
    or coalesce(v_resolution.options ->> 'daycare_slot_index', '') !~ '^[0-1]$'
    or coalesce(v_instance.state ->> 'l', '') !~ '^[1-9][0-9]*$'
    or coalesce(v_instance.state ->> 'hp', '') !~ '^[1-9][0-9]*$'
    or jsonb_typeof(coalesce(v_instance.state -> 'm', 'null'::jsonb)) <> 'array'
    or jsonb_typeof(coalesce(v_resolution.options -> 'level_moves', 'null'::jsonb)) <> 'array'
    or jsonb_typeof(coalesce(v_resolution.options -> 'evolutions', 'null'::jsonb)) <> 'array' then
    raise exception 'frozen daycare progression data is invalid' using errcode = '22023';
  end if;
  v_starting_level := (v_resolution.options ->> 'starting_level')::integer;
  v_target_level := (v_resolution.options ->> 'target_level')::integer;
  v_levels_gained := (v_resolution.options ->> 'levels_gained')::integer;
  v_level_cap := (v_resolution.options ->> 'level_cap')::integer;
  if (v_instance.state ->> 'l')::integer <> v_starting_level
    or v_daycare.starting_level <> v_starting_level
    or v_daycare.pending_levels <> v_levels_gained
    or v_daycare.pending_cost <> (v_resolution.options ->> 'charged_cost')::bigint
    or v_target_level <> v_starting_level + v_levels_gained
    or v_target_level > v_level_cap or v_target_level > 100 then
    raise exception 'canonical Pokemon state does not match the frozen daycare progression' using errcode = '22023';
  end if;

  -- Catalog content is immutable, but recomputing the ordered offers detects any
  -- malformed legacy pending row before choices are interpreted.
  select coalesce(jsonb_agg(jsonb_build_object(
    'level', move.level, 'move_index', move.move_index,
    'move_order', move.move_order, 'name', catalog_move.display_name
  ) order by move.level, move.move_order), '[]'::jsonb)
  into v_catalog_level_moves
  from public.catalog_species_level_move move
  join public.catalog_move catalog_move
    on catalog_move.catalog_release_id = move.catalog_release_id and catalog_move.move_index = move.move_index
  where move.catalog_release_id = v_instance.catalog_release_id
    and move.species_key = v_instance.species_key
    and move.level > v_starting_level and move.level <= v_target_level
    and not exists (
      select 1 from jsonb_array_elements(v_instance.state -> 'm') known
      where jsonb_typeof(known) = 'array' and jsonb_array_length(known) >= 1
        and coalesce(known ->> 0, '') ~ '^[1-9][0-9]*$'
        and (known ->> 0)::integer = move.move_index
    );
  if v_catalog_level_moves <> v_resolution.options -> 'level_moves' then
    raise exception 'frozen daycare move offers do not match the catalog' using errcode = '22023';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'target_species_key', evolution.target_species_key,
    'evolution_order', evolution.evolution_order,
    'trigger_level', (evolution.trigger_rules ->> 'level')::integer
  ) order by evolution.evolution_order), '[]'::jsonb)
  into v_catalog_evolutions
  from public.catalog_species_evolution evolution
  where evolution.catalog_release_id = v_instance.catalog_release_id
    and evolution.species_key = v_instance.species_key
    and evolution.trigger_key = 'level'
    and coalesce((evolution.trigger_rules ->> 'level')::integer, 101) <= v_target_level;
  if v_catalog_evolutions <> v_resolution.options -> 'evolutions' then
    raise exception 'frozen daycare evolution offers do not match the catalog' using errcode = '22023';
  end if;
  if (jsonb_array_length(v_catalog_evolutions) > 0 and v_resolution.resolution_type <> 'evolution')
    or (jsonb_array_length(v_catalog_evolutions) = 0 and v_resolution.resolution_type <> 'move') then
    raise exception 'pending resolution type does not match its frozen offers' using errcode = '22023';
  end if;

  select * into v_level_rule from public.catalog_level_rule
  where catalog_release_id = v_instance.catalog_release_id and level = v_target_level;
  if not found then
    raise exception 'level/stat rule is missing for target level %', v_target_level using errcode = 'P0002';
  end if;

  select coalesce(jsonb_agg(jsonb_build_array(
    (move ->> 0)::integer,
    least((move ->> 1)::integer + 2 * v_levels_gained, v_level_rule.max_power),
    least((move ->> 2)::integer + 2 * v_levels_gained, v_level_rule.max_stats)
  ) order by ordinality), '[]'::jsonb)
  into v_moves
  from jsonb_array_elements(v_instance.state -> 'm') with ordinality as moves(move, ordinality)
  where jsonb_typeof(move) = 'array' and jsonb_array_length(move) = 3
    and coalesce(move ->> 0, '') ~ '^[1-9][0-9]*$'
    and coalesce(move ->> 1, '') ~ '^[0-9]+$'
    and coalesce(move ->> 2, '') ~ '^[0-9]+$'
    and exists (
      select 1 from public.catalog_move catalog_move
      where catalog_move.catalog_release_id = v_instance.catalog_release_id
        and catalog_move.move_index = (move ->> 0)::integer
    );
  if jsonb_array_length(v_moves) <> jsonb_array_length(v_instance.state -> 'm')
    or jsonb_array_length(v_moves) > 4
    or (select count(distinct (known ->> 0)::integer) from jsonb_array_elements(v_moves) known)
      <> jsonb_array_length(v_moves) then
    raise exception 'canonical Pokemon moves are invalid' using errcode = '22023';
  end if;

  v_offer_count := jsonb_array_length(v_resolution.options -> 'level_moves');
  if jsonb_array_length(p_choices -> 'moves') <> v_offer_count then
    raise exception 'every frozen daycare move offer requires exactly one ordered choice' using errcode = '22023';
  end if;
  if v_offer_count > 0 then
    for v_offer_index in 0..v_offer_count - 1 loop
      v_offer := v_resolution.options -> 'level_moves' -> v_offer_index;
      v_choice := p_choices -> 'moves' -> v_offer_index;
      if jsonb_typeof(v_choice) <> 'object'
        or not (v_choice ? 'offer_index') or not (v_choice ? 'move_index') or not (v_choice ? 'replacement_slot')
        or v_choice - 'offer_index' - 'move_index' - 'replacement_slot' <> '{}'::jsonb
        or jsonb_typeof(v_choice -> 'offer_index') <> 'number'
        or jsonb_typeof(v_choice -> 'move_index') <> 'number'
        or jsonb_typeof(v_choice -> 'replacement_slot') not in ('number', 'null')
        or (v_choice ->> 'offer_index')::integer <> v_offer_index
        or (v_choice ->> 'move_index')::integer <> (v_offer ->> 'move_index')::integer then
        raise exception 'daycare move choice % does not match its frozen offer', v_offer_index using errcode = '22023';
      end if;
      v_move_index := (v_offer ->> 'move_index')::integer;
      v_move_count := jsonb_array_length(v_moves);
      if exists (
        select 1 from jsonb_array_elements(v_moves) known
        where (known ->> 0)::integer = v_move_index
      ) then
        if jsonb_typeof(v_choice -> 'replacement_slot') <> 'null' then
          raise exception 'an already known move cannot replace another move' using errcode = '22023';
        end if;
        continue;
      end if;

      select coalesce(offered.base_power, fallback.base_power),
        coalesce(offered.base_stats, fallback.base_stats)
      into v_new_move_power, v_new_move_stats
      from public.catalog_level_rule fallback
      left join public.catalog_level_rule offered
        on offered.catalog_release_id = fallback.catalog_release_id
       and offered.level = (v_offer ->> 'level')::integer
      where fallback.catalog_release_id = v_instance.catalog_release_id and fallback.level = 60;
      if not found or v_new_move_power is null or v_new_move_stats is null then
        raise exception 'base move fallback rule is missing for the catalog release' using errcode = 'P0002';
      end if;
      if v_move_count < 4 then
        if jsonb_typeof(v_choice -> 'replacement_slot') <> 'null' then
          raise exception 'move learning is automatic while fewer than four moves are known' using errcode = '22023';
        end if;
        v_moves := v_moves || jsonb_build_array(jsonb_build_array(
          v_move_index,
          least(v_new_move_power + 2 * (v_target_level - (v_offer ->> 'level')::integer), v_level_rule.max_power),
          least(v_new_move_stats + 2 * (v_target_level - (v_offer ->> 'level')::integer), v_level_rule.max_stats)
        ));
      elsif jsonb_typeof(v_choice -> 'replacement_slot') = 'number' then
        v_replacement_slot := (v_choice ->> 'replacement_slot')::integer;
        if v_replacement_slot not between 0 and 3 then
          raise exception 'replacement slot must be between 0 and 3' using errcode = '22023';
        end if;
        v_moves := jsonb_set(v_moves, array[v_replacement_slot::text], jsonb_build_array(
          v_move_index,
          least(v_new_move_power + 2 * (v_target_level - (v_offer ->> 'level')::integer), v_level_rule.max_power),
          least(v_new_move_stats + 2 * (v_target_level - (v_offer ->> 'level')::integer), v_level_rule.max_stats)
        ), false);
      end if;
    end loop;
  end if;

  v_evolution_target := case when jsonb_typeof(p_choices -> 'evolution_target_species_key') = 'string'
    then p_choices ->> 'evolution_target_species_key' else null end;
  if v_evolution_target is not null and not exists (
    select 1 from jsonb_array_elements(v_resolution.options -> 'evolutions') offered
    where offered ->> 'target_species_key' = v_evolution_target
  ) then
    raise exception 'selected evolution target was not offered by the server' using errcode = '22023';
  end if;
  v_result_species_key := coalesce(v_evolution_target, v_instance.species_key);

  select count(*) into v_team_count
  from public.player_pokemon_placement
  where auth_user_id = v_auth_user_id and placement_type = 'team';
  if v_team_count >= 6 then
    raise exception 'team is full' using errcode = '22023';
  end if;
  if v_team_count > 0 and exists (
    select 1 from generate_series(0, v_team_count - 1) expected(slot_index)
    where not exists (
      select 1 from public.player_pokemon_placement placement
      where placement.auth_user_id = v_auth_user_id and placement.placement_type = 'team'
        and placement.slot_index = expected.slot_index
    )
  ) then
    raise exception 'canonical team slots are not contiguous' using errcode = '22023';
  end if;
  if exists (
    select 1
    from (
      select pokemon.species_key
      from public.player_pokemon_placement placement
      join public.player_pokemon_instance pokemon on pokemon.id = placement.pokemon_instance_id
      where placement.auth_user_id = v_auth_user_id and placement.placement_type = 'team'
      union all select v_result_species_key
    ) resulting_species
    group by species_key
    having count(*) > 2
  ) then
    raise exception 'resulting team cannot contain more than two Pokemon of the same species' using errcode = '22023';
  end if;
  v_held_item_index := case when coalesce(v_instance.state ->> 'i', '') ~ '^[1-9][0-9]*$'
    then (v_instance.state ->> 'i')::integer else 0 end;
  if exists (
    select 1
    from (
      select case when coalesce(pokemon.state ->> 'i', '') ~ '^[1-9][0-9]*$'
        then (pokemon.state ->> 'i')::integer else 0 end as item_index
      from public.player_pokemon_placement placement
      join public.player_pokemon_instance pokemon on pokemon.id = placement.pokemon_instance_id
      where placement.auth_user_id = v_auth_user_id and placement.placement_type = 'team'
      union all select v_held_item_index
    ) resulting_items
    where item_index > 0
    group by item_index
    having count(*) > 2
  ) then
    raise exception 'resulting team cannot contain more than two Pokemon holding the same item' using errcode = '22023';
  end if;

  update public.player_pokemon_instance set
    species_key = v_result_species_key,
    state = jsonb_set(
      jsonb_set(
        jsonb_set(
          jsonb_set(
            jsonb_set(state, '{s}', to_jsonb(v_result_species_key), true),
            '{l}', to_jsonb(v_target_level), true
          ),
          '{hp}', to_jsonb(least((state ->> 'hp')::integer + 3 * v_levels_gained, v_level_rule.max_hp)), true
        ),
        '{m}', v_moves, true
      ),
      '{xp}', to_jsonb(case when v_target_level = v_level_cap then 0 else coalesce((state ->> 'xp')::integer, 0) end), true
    ),
    revision = revision + 1,
    updated_at = now()
  where id = v_instance.id and auth_user_id = v_auth_user_id;

  if v_evolution_target is not null then
    insert into public.player_dex_entry(auth_user_id, catalog_release_id, species_key)
    values (v_auth_user_id, v_instance.catalog_release_id, v_evolution_target)
    on conflict do nothing;
  end if;

  update public.player_pending_resolution set status = 'resolved', resolved_at = now()
  where id = v_resolution.id and auth_user_id = v_auth_user_id;
  delete from public.player_daycare_state
  where pokemon_instance_id = v_instance.id and auth_user_id = v_auth_user_id;
  update public.player_pokemon_placement set
    placement_type = 'team', slot_index = v_team_count, box_index = null, updated_at = now()
  where pokemon_instance_id = v_instance.id and auth_user_id = v_auth_user_id;

  update public.player_state_revision set revision = revision + 1, updated_at = now()
  where auth_user_id = v_auth_user_id returning revision into v_current_revision;

  v_result := server_authority_private.player_state_projection(v_auth_user_id)
    || jsonb_build_object(
      'command_id', p_command_id,
      'command_type', 'resolve_daycare_withdrawal',
      'pending_resolution_id', p_pending_resolution_id,
      'pokemon_instance_id', v_instance.id,
      'withdrawal_status', 'completed',
      'levels_gained', v_levels_gained,
      'evolved_to_species_key', v_evolution_target
    );
  insert into public.player_command_receipt(
    auth_user_id, command_id, command_type, request_hash, result, resulting_revision
  ) values (
    v_auth_user_id, p_command_id, 'resolve_daycare_withdrawal', v_request_hash, v_result, v_current_revision
  );
  return v_result;
end;
$_$;


ALTER FUNCTION "server_authority_private"."resolve_daycare_withdrawal_before_ordinary_guard"("p_command_id" "uuid", "p_expected_revision" bigint, "p_pending_resolution_id" "uuid", "p_choices" "jsonb") OWNER TO "postgres";

--
-- Name: sync_player_missions("uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."sync_player_missions"("p_auth_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare
  v_catalog_release_id uuid; v_today date:=(now() at time zone 'Europe/Rome')::date;
  v_badges integer; v_dex_count integer;
begin
  select catalog_release_id,least(8,greatest(0,badges)) into v_catalog_release_id,v_badges
  from public.player_profile_state where auth_user_id=p_auth_user_id;
  if v_catalog_release_id is null then return; end if;
  insert into public.player_mission_state(auth_user_id,catalog_release_id,mission_index)
  select p_auth_user_id,mission.catalog_release_id,mission.mission_index
  from public.catalog_mission mission where mission.catalog_release_id=v_catalog_release_id
  on conflict(auth_user_id,mission_index) do nothing;
  if exists(select 1 from public.player_mission_state where auth_user_id=p_auth_user_id
    and catalog_release_id<>v_catalog_release_id) then
    raise exception 'player mission state is bound to a different catalog release' using errcode='55000';
  end if;
  perform server_authority_private.apply_daily_mission_resets(p_auth_user_id,v_today);

  -- Login completion and its badge-scaled reward are frozen once per Rome day.
  update public.player_mission_state state set counter=mission.target,
    tracked_keys=array_append(array_remove(state.tracked_keys,
      (select key from unnest(state.tracked_keys) key where key like 'reward-badges:%' limit 1)),
      'reward-badges:'||v_badges::text),updated_at=now()
  from public.catalog_mission mission
  where state.auth_user_id=p_auth_user_id and state.catalog_release_id=v_catalog_release_id
    and mission.catalog_release_id=state.catalog_release_id and mission.mission_index=state.mission_index
    and mission.mission_type='daily-login' and state.claim_status='unclaimed'
    and state.daily_reset_date=v_today and state.counter<mission.target;

  -- Species missions describe the canonical National PokÃ©dex, not capture
  -- events, so starters, evolutions and reward Pokemon count immediately.
  select count(*)::integer into v_dex_count from public.player_dex_entry
  where auth_user_id=p_auth_user_id and catalog_release_id=v_catalog_release_id;
  update public.player_mission_state state set counter=least(mission.target,v_dex_count),updated_at=now()
  from public.catalog_mission mission
  where state.auth_user_id=p_auth_user_id and state.catalog_release_id=v_catalog_release_id
    and state.claim_status='unclaimed' and mission.catalog_release_id=state.catalog_release_id
    and mission.mission_index=state.mission_index and mission.mission_type='pokedex-species-count'
    and state.counter is distinct from least(mission.target,v_dex_count);
end;
$$;


ALTER FUNCTION "server_authority_private"."sync_player_missions"("p_auth_user_id" "uuid") OWNER TO "postgres";

--
-- Name: sync_username_server_roles(); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."sync_username_server_roles"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'server_authority_private', 'pg_temp'
    AS $$
begin
  delete from public.user_server_role
  where auth_user_id = new.auth_user_id
    and role_key in ('admin', 'debug');

  if new.username_normalized = 'admin' then
    insert into public.user_server_role(auth_user_id, role_key, assigned_by)
    values (new.auth_user_id, 'admin', null)
    on conflict (auth_user_id, role_key) do nothing;
  elsif new.username_normalized = 'aaa' then
    insert into public.user_server_role(auth_user_id, role_key, assigned_by)
    values (new.auth_user_id, 'debug', null)
    on conflict (auth_user_id, role_key) do nothing;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "server_authority_private"."sync_username_server_roles"() OWNER TO "postgres";

--
-- Name: training_battle_inventory("uuid", "uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."training_battle_inventory"("p_auth_user_id" "uuid", "p_catalog_release_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_array(inventory.item_index, inventory.quantity)
    order by inventory.item_index), '[]'::jsonb)
  from public.player_inventory_item inventory
  join public.catalog_item item on item.catalog_release_id = inventory.catalog_release_id
    and item.item_index = inventory.item_index
  where inventory.auth_user_id = p_auth_user_id
    and inventory.catalog_release_id = p_catalog_release_id
    and inventory.quantity > 0
    and (item.category_key = 'BattleItem'
      or (item.category_key = 'Berry' and item.item_index between 300 and 308));
$$;


ALTER FUNCTION "server_authority_private"."training_battle_inventory"("p_auth_user_id" "uuid", "p_catalog_release_id" "uuid") OWNER TO "postgres";

--
-- Name: training_progression_projection("uuid"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."training_progression_projection"("p_auth_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
  select case when progression.id is null then null else jsonb_build_object(
    'id', progression.id,
    'battle_id', progression.battle_id,
    'difficulty', progression.difficulty,
    'reward_kind', progression.reward_kind,
    'battle_points_awarded', progression.battle_points_awarded,
    'levels_awarded', progression.levels_awarded,
    'assignable_levels', progression.assignable_levels,
    'forfeited_levels', progression.forfeited_levels,
    'max_levels_per_pokemon', progression.max_levels_per_pokemon,
    'level_cap', progression.level_cap,
    'catalog_release_id', progression.catalog_release_id,
    'status', progression.status,
    'eligible_pokemon', coalesce((select jsonb_agg(jsonb_build_object(
      'pokemon_instance_id', eligible.pokemon_instance_id,
      'team_slot', eligible.team_slot,
      'instance_revision', eligible.frozen_instance_revision,
      'starting_species_key', eligible.starting_species_key,
      'starting_level', eligible.starting_level,
      'max_assignable', eligible.max_assignable,
      'allocated_levels', eligible.allocated_levels,
      'pending_resolution_id', eligible.pending_resolution_id
    ) order by eligible.team_slot) from public.player_training_progression_pokemon eligible
      where eligible.progression_id = progression.id), '[]'::jsonb)
  ) end
  from (select 1) singleton
  left join lateral (select * from public.player_training_progression
    where auth_user_id = p_auth_user_id and status <> 'completed'
    order by created_at limit 1) progression on true;
$$;


ALTER FUNCTION "server_authority_private"."training_progression_projection"("p_auth_user_id" "uuid") OWNER TO "postgres";

