--
-- Name: validate_edge_battle_roster_bijection("uuid", "jsonb", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."validate_edge_battle_roster_bijection"("p_battle_id" "uuid", "p_next_snapshot" "jsonb", "p_projection" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare
  v_validation_projection jsonb := p_projection;
  v_participants jsonb;
begin
  if jsonb_typeof(p_projection -> 'participants') = 'array' then
    select coalesce(jsonb_agg(
      case
        when jsonb_typeof(participant.value) = 'object'
          and jsonb_typeof(participant.value -> 'moves') = 'array' then
          jsonb_set(participant.value, '{moves}', (
            select coalesce(jsonb_agg(
              case when jsonb_typeof(move.value) = 'object'
                then move.value - 'available'
                else move.value
              end order by move.ordinality
            ), '[]'::jsonb)
            from jsonb_array_elements(participant.value -> 'moves')
              with ordinality move(value, ordinality)
          ), false)
        else participant.value
      end order by participant.ordinality
    ), '[]'::jsonb)
    into v_participants
    from jsonb_array_elements(p_projection -> 'participants')
      with ordinality participant(value, ordinality);
    v_validation_projection := jsonb_set(p_projection, '{participants}', v_participants, false);
  end if;

  perform server_authority_private.validate_edge_battle_roster_bijection_before_move_availability(
    p_battle_id, p_next_snapshot, v_validation_projection);
end;
$$;


ALTER FUNCTION "server_authority_private"."validate_edge_battle_roster_bijection"("p_battle_id" "uuid", "p_next_snapshot" "jsonb", "p_projection" "jsonb") OWNER TO "postgres";

--
-- Name: validate_edge_battle_roster_bijection_before_move_availability("uuid", "jsonb", "jsonb"); Type: FUNCTION; Schema: server_authority_private; Owner: postgres
--

CREATE FUNCTION "server_authority_private"."validate_edge_battle_roster_bijection_before_move_availability"("p_battle_id" "uuid", "p_next_snapshot" "jsonb", "p_projection" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'server_authority_private', 'pg_temp'
    AS $$
declare
  v_expected integer;
  v_snapshot_count integer;
  v_snapshot_unique integer;
  v_projection_count integer;
  v_projection_unique integer;
begin
  select count(*) into v_expected from public.authoritative_battle_participant where battle_id = p_battle_id;
  if jsonb_array_length(p_next_snapshot #> '{playerTeam,pokemon}')
      <> jsonb_array_length(p_next_snapshot #> '{playerTeam,combatants}')
    or jsonb_array_length(p_next_snapshot #> '{enemyTeam,pokemon}')
      <> jsonb_array_length(p_next_snapshot #> '{enemyTeam,combatants}') then
    raise exception 'snapshot Pokemon/combatant ordinality is invalid' using errcode = '22023';
  end if;
  with snapshot_roster as (
    select 'player'::text side,
      server_authority_private.edge_jsonb_bigint(pokemon.value #> '{state,authoritativeSlot}') slot,
      pokemon.value #>> '{state,speciesKey}' species_key,
      server_authority_private.edge_jsonb_bigint(pokemon.value #> '{state,level}') level,
      server_authority_private.edge_jsonb_bigint(pokemon.value #> '{state,maxHp}') max_hp,
      pokemon.value #>> '{state,instanceId}' instance_id
    from jsonb_array_elements(p_next_snapshot #> '{playerTeam,pokemon}') with ordinality pokemon(value, ordinality)
    join jsonb_array_elements(p_next_snapshot #> '{playerTeam,combatants}') with ordinality combatant(value, ordinality) using (ordinality)
    union all
    select 'npc'::text,
      server_authority_private.edge_jsonb_bigint(pokemon.value #> '{state,authoritativeSlot}'),
      pokemon.value #>> '{state,speciesKey}',
      server_authority_private.edge_jsonb_bigint(pokemon.value #> '{state,level}'),
      server_authority_private.edge_jsonb_bigint(pokemon.value #> '{state,maxHp}'),
      pokemon.value #>> '{state,instanceId}'
    from jsonb_array_elements(p_next_snapshot #> '{enemyTeam,pokemon}') with ordinality pokemon(value, ordinality)
    join jsonb_array_elements(p_next_snapshot #> '{enemyTeam,combatants}') with ordinality combatant(value, ordinality) using (ordinality)
  )
  select count(*), count(distinct (side, slot)) into v_snapshot_count, v_snapshot_unique from snapshot_roster;
  if v_snapshot_count <> v_expected or v_snapshot_unique <> v_expected then
    raise exception 'snapshot roster cardinality/slots are not bijective' using errcode = '22023';
  end if;
  if exists (
    with snapshot_roster as (
      select 'player'::text side, server_authority_private.edge_jsonb_bigint(value #> '{state,authoritativeSlot}') slot,
        value #>> '{state,speciesKey}' species_key, server_authority_private.edge_jsonb_bigint(value #> '{state,level}') level,
        server_authority_private.edge_jsonb_bigint(value #> '{state,maxHp}') max_hp, value #>> '{state,instanceId}' instance_id
      from jsonb_array_elements(p_next_snapshot #> '{playerTeam,pokemon}')
      union all
      select 'npc'::text, server_authority_private.edge_jsonb_bigint(value #> '{state,authoritativeSlot}'),
        value #>> '{state,speciesKey}', server_authority_private.edge_jsonb_bigint(value #> '{state,level}'),
        server_authority_private.edge_jsonb_bigint(value #> '{state,maxHp}'), value #>> '{state,instanceId}'
      from jsonb_array_elements(p_next_snapshot #> '{enemyTeam,pokemon}')
    )
    select 1 from snapshot_roster roster
    left join public.authoritative_battle_participant participant
      on participant.battle_id = p_battle_id and participant.side = roster.side and participant.slot_index = roster.slot
    where participant.battle_id is null or participant.species_key <> roster.species_key
      or participant.level <> roster.level or participant.max_hp <> roster.max_hp
      or (roster.side = 'player' and participant.pokemon_instance_id::text is distinct from roster.instance_id)
      or (roster.side = 'npc' and roster.instance_id is not null)
  ) or exists (
    select 1 from public.authoritative_battle_participant participant
    where participant.battle_id = p_battle_id and not exists (
      select 1 from (
        select 'player'::text side, server_authority_private.edge_jsonb_bigint(value #> '{state,authoritativeSlot}') slot
        from jsonb_array_elements(p_next_snapshot #> '{playerTeam,pokemon}')
        union all
        select 'npc'::text, server_authority_private.edge_jsonb_bigint(value #> '{state,authoritativeSlot}')
        from jsonb_array_elements(p_next_snapshot #> '{enemyTeam,pokemon}')
      ) roster where roster.side = participant.side and roster.slot = participant.slot_index
    )
  ) then raise exception 'snapshot roster differs from canonical participants' using errcode = '22023'; end if;

  select count(*), count(distinct (value ->> 'side', server_authority_private.edge_jsonb_bigint(value -> 'slot_index')))
    into v_projection_count, v_projection_unique from jsonb_array_elements(p_projection -> 'participants');
  if v_projection_count <> v_expected or v_projection_unique <> v_expected then
    raise exception 'projection roster cardinality/slots are not bijective' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_projection -> 'participants') projected(value)
    left join public.authoritative_battle_participant participant on participant.battle_id = p_battle_id
      and participant.side = projected.value ->> 'side'
      and participant.slot_index = server_authority_private.edge_jsonb_bigint(projected.value -> 'slot_index')
    where participant.battle_id is null or participant.species_key <> projected.value ->> 'species_key'
      or participant.level <> server_authority_private.edge_jsonb_bigint(projected.value -> 'level')
      or participant.max_hp <> server_authority_private.edge_jsonb_bigint(projected.value -> 'max_hp')
  ) or exists (
    select 1 from public.authoritative_battle_participant participant
    where participant.battle_id = p_battle_id and not exists (
      select 1 from jsonb_array_elements(p_projection -> 'participants') projected(value)
      where projected.value ->> 'side' = participant.side
        and server_authority_private.edge_jsonb_bigint(projected.value -> 'slot_index') = participant.slot_index
    )
  ) then raise exception 'projection roster differs from canonical participants' using errcode = '22023'; end if;
end;
$$;


ALTER FUNCTION "server_authority_private"."validate_edge_battle_roster_bijection_before_move_availability"("p_battle_id" "uuid", "p_next_snapshot" "jsonb", "p_projection" "jsonb") OWNER TO "postgres";

