--
-- Name: authoritative_admin_gym_command_receipt; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE "public"."authoritative_admin_gym_command_receipt" (
    "admin_auth_user_id" "uuid" NOT NULL,
    "command_id" "uuid" NOT NULL,
    "battle_id" "uuid" NOT NULL,
    "command_type" "text" NOT NULL,
    "command_hash" "text" NOT NULL,
    "result" "jsonb" NOT NULL,
    "resulting_battle_version" bigint NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "authoritative_admin_gym_command__resulting_battle_version_check" CHECK (("resulting_battle_version" > 0)),
    CONSTRAINT "authoritative_admin_gym_command_receipt_command_hash_check" CHECK (("command_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "authoritative_admin_gym_command_receipt_command_type_check" CHECK (("command_type" = ANY (ARRAY['move'::"text", 'switch'::"text", 'item'::"text"]))),
    CONSTRAINT "authoritative_admin_gym_command_receipt_result_check" CHECK ((("jsonb_typeof"("result") = 'object'::"text") AND ("octet_length"(("result")::"text") <= 1048576)))
);


ALTER TABLE "public"."authoritative_admin_gym_command_receipt" OWNER TO "postgres";

--
-- Name: authoritative_battle; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE "public"."authoritative_battle" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "auth_user_id" "uuid" NOT NULL,
    "catalog_release_id" "uuid" NOT NULL,
    "contract_key" "text" NOT NULL,
    "status" "text" NOT NULL,
    "result_key" "text",
    "turn_number" integer DEFAULT 1 NOT NULL,
    "first_actor" "text" NOT NULL,
    "player_active_slot" smallint NOT NULL,
    "npc_active_slot" smallint DEFAULT 0 NOT NULL,
    "battle_version" bigint DEFAULT 1 NOT NULL,
    "runtime_owner_id" "uuid" NOT NULL,
    "runtime_lock_version" bigint DEFAULT 1 NOT NULL,
    "rng_state" "jsonb" NOT NULL,
    "next_event_seq" bigint DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "concluded_at" timestamp with time zone,
    "engine_version" "text",
    "engine_checksum" "text",
    "engine_snapshot" "jsonb",
    "engine_snapshot_hash" "text",
    "engine_runtime_state" "text" DEFAULT 'pending'::"text" NOT NULL,
    "training_difficulty" "text",
    "presentation" "jsonb",
    "requested_engine_version" "text",
    "requested_engine_checksum" "text",
    "gym_key" "text",
    "waiting_for" "text",
    "admin_items" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "league_run_id" "uuid",
    "league_member_index" smallint,
    "encounter_id" "uuid",
    "tower_run_id" "uuid",
    "tower_challenge" integer,
    CONSTRAINT "authoritative_battle_admin_items_check" CHECK ((("jsonb_typeof"("admin_items") = 'array'::"text") AND ("octet_length"(("admin_items")::"text") <= 32768))),
    CONSTRAINT "authoritative_battle_battle_version_check" CHECK (("battle_version" > 0)),
    CONSTRAINT "authoritative_battle_capture_encounter_check" CHECK (((("contract_key" = 'capture'::"text") AND ("encounter_id" IS NOT NULL)) OR (("contract_key" <> 'capture'::"text") AND ("encounter_id" IS NULL)))),
    CONSTRAINT "authoritative_battle_check" CHECK ((("status" = ANY (ARRAY['concluded'::"text", 'abandoned'::"text"])) = ("result_key" IS NOT NULL))),
    CONSTRAINT "authoritative_battle_check1" CHECK ((("status" = ANY (ARRAY['concluded'::"text", 'abandoned'::"text"])) = ("concluded_at" IS NOT NULL))),
    CONSTRAINT "authoritative_battle_contract_key_check" CHECK (("contract_key" = ANY (ARRAY['training'::"text", 'debug_training'::"text", 'gym'::"text", 'admin_gym'::"text", 'league'::"text", 'capture'::"text", 'battle_tower'::"text"]))),
    CONSTRAINT "authoritative_battle_engine_runtime_state_check" CHECK (("engine_runtime_state" = ANY (ARRAY['pending'::"text", 'ready'::"text"]))),
    CONSTRAINT "authoritative_battle_engine_snapshot_shape" CHECK (((("engine_runtime_state" = 'pending'::"text") AND ("engine_snapshot" IS NULL) AND ("engine_snapshot_hash" IS NULL) AND ("engine_version" IS NULL) AND ("engine_checksum" IS NULL)) OR (("engine_runtime_state" = 'ready'::"text") AND ("jsonb_typeof"("engine_snapshot") = 'object'::"text") AND ("engine_snapshot_hash" ~ '^[0-9a-f]{64}$'::"text") AND ("engine_version" IS NOT NULL) AND ("engine_checksum" ~ '^[0-9a-f]{64}$'::"text") AND ("octet_length"(("engine_snapshot")::"text") <= 524288)))),
    CONSTRAINT "authoritative_battle_first_actor_check" CHECK (("first_actor" = ANY (ARRAY['player'::"text", 'npc'::"text"]))),
    CONSTRAINT "authoritative_battle_gym_context_check" CHECK (((("contract_key" = ANY (ARRAY['gym'::"text", 'admin_gym'::"text"])) AND ("gym_key" IS NOT NULL) AND ("gym_key" ~ '^[a-z0-9-]{1,40}$'::"text")) OR (("contract_key" <> ALL (ARRAY['gym'::"text", 'admin_gym'::"text"])) AND ("gym_key" IS NULL)))),
    CONSTRAINT "authoritative_battle_league_context_check" CHECK (((("contract_key" = 'league'::"text") AND ("league_run_id" IS NOT NULL) AND ("league_member_index" IS NOT NULL)) OR (("contract_key" <> 'league'::"text") AND ("league_run_id" IS NULL) AND ("league_member_index" IS NULL)))),
    CONSTRAINT "authoritative_battle_league_member_index_check" CHECK ((("league_member_index" >= 0) AND ("league_member_index" <= 4))),
    CONSTRAINT "authoritative_battle_next_event_seq_check" CHECK (("next_event_seq" > 0)),
    CONSTRAINT "authoritative_battle_npc_active_slot_check" CHECK ((("npc_active_slot" >= 0) AND ("npc_active_slot" <= 5))),
    CONSTRAINT "authoritative_battle_player_active_slot_check" CHECK ((("player_active_slot" >= 0) AND ("player_active_slot" <= 5))),
    CONSTRAINT "authoritative_battle_presentation_check" CHECK ((("presentation" IS NULL) OR (("jsonb_typeof"("presentation") = 'object'::"text") AND ("octet_length"(("presentation")::"text") <= 4096)))),
    CONSTRAINT "authoritative_battle_requested_engine_check" CHECK (((("requested_engine_version" IS NULL) AND ("requested_engine_checksum" IS NULL)) OR (("length"("requested_engine_version") >= 1) AND ("length"("requested_engine_version") <= 80) AND ("requested_engine_checksum" ~ '^[0-9a-f]{64}$'::"text")))),
    CONSTRAINT "authoritative_battle_result_key_check" CHECK ((("result_key" IS NULL) OR ("result_key" = ANY (ARRAY['player_win_no_reward'::"text", 'player_loss_no_reward'::"text", 'abandoned_no_reward'::"text", 'pokemon_captured'::"text", 'encounter_expired_no_reward'::"text"])))),
    CONSTRAINT "authoritative_battle_rng_state_check" CHECK (("jsonb_typeof"("rng_state") = 'object'::"text")),
    CONSTRAINT "authoritative_battle_runtime_lock_version_check" CHECK (("runtime_lock_version" > 0)),
    CONSTRAINT "authoritative_battle_status_check" CHECK (("status" = ANY (ARRAY['prepared'::"text", 'active'::"text", 'needs_player_switch'::"text", 'concluded'::"text", 'abandoned'::"text"]))),
    CONSTRAINT "authoritative_battle_tower_context_check" CHECK (((("contract_key" = 'battle_tower'::"text") AND ("tower_run_id" IS NOT NULL) AND ("tower_challenge" > 0)) OR (("contract_key" <> 'battle_tower'::"text") AND ("tower_run_id" IS NULL) AND ("tower_challenge" IS NULL)))),
    CONSTRAINT "authoritative_battle_training_context_check" CHECK (((("contract_key" = 'training'::"text") AND ("training_difficulty" = ANY (ARRAY['easy'::"text", 'medium'::"text", 'hard'::"text"]))) OR (("contract_key" <> 'training'::"text") AND ("training_difficulty" IS NULL)))),
    CONSTRAINT "authoritative_battle_turn_number_check" CHECK (("turn_number" > 0)),
    CONSTRAINT "authoritative_battle_waiting_for_check" CHECK ((("waiting_for" IS NULL) OR ("waiting_for" = ANY (ARRAY['player'::"text", 'admin'::"text"]))))
);


