    CONSTRAINT "player_encounter_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'consumed'::"text", 'expired'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "player_encounter_terminal_at_check" CHECK ((("status" = 'active'::"text") = ("terminal_at" IS NULL)))
);


