-- Name: authoritative_battle; Type: ROW SECURITY; Schema: public; Owner: postgres
--

ALTER TABLE "public"."authoritative_battle" ENABLE ROW LEVEL SECURITY;

--
-- Name: authoritative_battle authoritative_battle_admin_realtime_select; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "authoritative_battle_admin_realtime_select" ON "public"."authoritative_battle" FOR SELECT TO "authenticated" USING ((("contract_key" = ANY (ARRAY['admin_gym'::"text", 'league'::"text", 'debug_training'::"text"])) AND "public"."current_user_has_server_role"('admin'::"text")));


--
-- Name: authoritative_battle_command_receipt; Type: ROW SECURITY; Schema: public; Owner: postgres
--

ALTER TABLE "public"."authoritative_battle_command_receipt" ENABLE ROW LEVEL SECURITY;

--
-- Name: authoritative_battle_event; Type: ROW SECURITY; Schema: public; Owner: postgres
--

ALTER TABLE "public"."authoritative_battle_event" ENABLE ROW LEVEL SECURITY;

--
-- Name: authoritative_battle_event authoritative_battle_event_admin_realtime_select; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "authoritative_battle_event_admin_realtime_select" ON "public"."authoritative_battle_event" FOR SELECT TO "authenticated" USING (("public"."current_user_has_server_role"('admin'::"text") AND (EXISTS ( SELECT 1
   FROM "public"."authoritative_battle" "battle"
  WHERE (("battle"."id" = "authoritative_battle_event"."battle_id") AND ("battle"."contract_key" = ANY (ARRAY['admin_gym'::"text", 'league'::"text", 'debug_training'::"text"])))))));


--
-- Name: authoritative_battle_event authoritative_battle_event_realtime_select; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "authoritative_battle_event_realtime_select" ON "public"."authoritative_battle_event" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."authoritative_battle" "battle"
  WHERE (("battle"."id" = "authoritative_battle_event"."battle_id") AND (("battle"."auth_user_id" = ( SELECT "auth"."uid"() AS "uid")) OR (("battle"."contract_key" = ANY (ARRAY['admin_gym'::"text", 'league'::"text"])) AND ( SELECT "public"."current_user_has_server_role"('admin'::"text") AS "current_user_has_server_role")))))));


