--
-- Name: authoritative_battle authoritative_battle_realtime_select; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "authoritative_battle_realtime_select" ON "public"."authoritative_battle" FOR SELECT TO "authenticated" USING ((("auth_user_id" = ( SELECT "auth"."uid"() AS "uid")) OR (("contract_key" = ANY (ARRAY['admin_gym'::"text", 'league'::"text"])) AND ( SELECT "public"."current_user_has_server_role"('admin'::"text") AS "current_user_has_server_role"))));


