DO $$
DECLARE
  existing_job bigint;
BEGIN
  SELECT jobid INTO existing_job
  FROM cron.job
  WHERE jobname = 'revival-terminal-retention-hourly';

  IF existing_job IS NOT NULL THEN
    PERFORM cron.unschedule(existing_job);
  END IF;

  PERFORM cron.schedule(
    'revival-terminal-retention-hourly',
    '17 * * * *',
    'select server_authority_private.cleanup_authoritative_terminal_battles(500);'
  );
END;
$$;

